\title{InvestAlign: Overcoming Data Scarcity in Aligning Large Language Models with Investor Decision-Making Processes under Herd Behavior}

\author{\textbf{Huisheng Wang\thanks{Equal contribution.}\quad Zhuoshi Pan$^*$\quad Hangjing Zhang$^*$} \\
  \textbf{Mingxiao Liu$^*$\quad Hanqing Gao\quad H. Vicky Zhao\thanks{Corresponding author.}} \\
