\subsection{Statistical Tests' Results of the Differences and Correlation Coefficients}
\label{sec:statistical}
We define the difference $d_i$ and correlation coefficient $\rho_i$ between $\{\tilde{P}_1^i(t)\}_{t\in\mathcal{T}}$ and $\{\hat{P}_1^i(t)\}_{t\in\mathcal{T}}$ as
\begin{equation}
    d_i=\sum_{t\in\mathcal{T}}[\tilde{P}_1^i(t)-\hat{P}_1^i(t)],
\end{equation}
and 
\begin{equation}
    \rho_i=\frac{\sum_{t\in\mathcal{T}}[\tilde{P}_1^i(t)-\bar{\tilde{P}}_1^i][\hat{P}_1^i(t)-\bar{\hat{P}}_1^i]}{\sqrt{\sum_{t\in\mathcal{T}}[\tilde{P}_1^i(t)-\bar{\tilde{P}}_1^i]^2\sum_{t\in\mathcal{T}}[\hat{P}_1^i(t)-\bar{\hat{P}}_1^i]^2}},
\end{equation}
where $\bar{\tilde{P}}_1^i=\frac{1}{T}\sum_{t\in\mathcal{T}}\tilde{P}_1^i(t)$ and $\bar{\hat{P}}_1^i=\frac{1}{T}\sum_{t\in\mathcal{T}}\hat{P}_1^i(t)$, respectively.

For the differences $\{d_i\}_{i\in\mathcal{I}}$, the results show that their mean does not significantly deviate from $0$ at the $1\%$ significance level, with a $t\text{-statistic}=-1.075$. For the correlation coefficients $\{\rho_i\}_{i\in\mathcal{I}}$, the results show that their mean does not significantly deviate from $0.85$ at the $1\%$ significance level, with a $t\text{-statistic}=-0.843$. Since a mean difference close to $0$ indicates minimal discrepancy and a correlation coefficient close to $0.85$ reflects a strong positive relationship, we show that there exists significant consistency between the theoretical solution and real-user data. 

\subsection{Probability Distribution Function of \texorpdfstring{$\mathsf{A_1}$}{A1}'s Optimal Investment Decision of \texorpdfstring{$\mathsf{P_3}$}{P3}}
\label{sec:probability}
We assume the parameters $\alpha_1$ and $\theta_1$ satisfy two uniform distributions, denoted by $U(\underline{\alpha},\overline{\alpha})$ and $U(\underline{\theta},\overline{\theta})$, respectively. Therefore, their probability distribution functions are
\begin{equation}
    f_{\alpha_1}(x)=\frac{1}{\overline{\alpha}-\underline{\alpha}},\ x\in[\underline{\alpha},\overline{\alpha}], \ \text{and}\ f_{\theta_1}(x)=\frac{1}{\overline{\theta}-\underline{\theta}},\ x\in[\underline{\theta},\overline{\theta}].
\end{equation}
From (\ref{eq:theoretical}), using the convolution formula \cite{renyi2007probability}, we have
\begin{align}
    f_{\hat{P}_1(t)}(x)&=\frac{1}{\overline{\theta}-\underline{\theta}}\int_{\underline{\theta}}^{\overline{\theta}}f_{\alpha_1}\left(\frac{1}{\sigma^2\eta\exp[2r(T-t)]}\right.\notag\\
    &\left.\cdot\left\{\frac{\alpha_2\sigma^2\eta\exp[2r(T-t)]+y}{x}\cdot\frac{v}{\alpha_2\sigma^2}\exp[r(t-T)]-y\right\}\right)\notag\\
    &\cdot\frac{\alpha_2\sigma^2\eta\exp[2r(T-t)]+y}{\sigma^2\eta\exp[2r(T-t)]x^2}\cdot\frac{v}{\alpha_2\sigma^2}\exp[r(t-T)]\dif y.\label{equ: fhatP}
\end{align}
Here, following the work in \cite{wang2024optimal}, we assume that $\eta$ approximately remains constant when $\alpha_1$ and $\theta_1$ change slightly. Because $\hat{P}_1(t)\in\hat{\mathcal{P}}_1(t)$, we can rewrite (\ref{equ: fhatP}) as
\begin{equation}
    f_{\hat{P}_1(t)}(x)\approx\frac{\min[\hat{\mathcal{P}}_1(t)]\cdot\max[\hat{\mathcal{P}}_1(t)]}{\max[\hat{\mathcal{P}}_1(t)]-\min[\hat{\mathcal{P}}_1(t)]}\cdot\frac{1}{x^2},\ x\in\hat{\mathcal{P}}_1(t).
\end{equation}
That is, $\mathsf{A_1}$'s theoretical optimal decision $\hat{P}_1(t)$ approximately satisfies a Pareto distribution. To simplify the notation, we denote the normalization parameter as
\begin{equation}
    c=\frac{\min[\hat{\mathcal{P}}_1(t)]\cdot\max[\hat{\mathcal{P}}_1(t)]}{\max[\hat{\mathcal{P}}_1(t)]-\min[\hat{\mathcal{P}}_1(t)]}.
\end{equation}

\subsection{Gradient Norms of the Loss Function}
\label{sec:convergence}
First, we derive the expression of $f_{\tilde{P}_1(t)}(\cdot)$ from (\ref{equ: pdf}). Using the convolution formula in \cite{renyi2007probability}, we can obtain
\begin{align}
    f_{\tilde{P}_1(t)}(x)&\approx\frac{1}{2\varepsilon}\int_{-\varepsilon}^{\varepsilon}f_{\hat{P}_1(t)}(x-y)\dif y\notag\\
    &=\left\{\begin{aligned}
    &\frac{c}{2\varepsilon}\int_{\min[\hat{\mathcal{P}}_1(t)]-x}^{\varepsilon}\frac{1}{(x-y)^2}\dif y, &x\in[\min[\hat{\mathcal{P}}_1(t)]-\varepsilon,\min[\hat{\mathcal{P}}_1(t)]+\varepsilon)\\
    &\frac{c}{2\varepsilon}\int_{-\varepsilon}^{\varepsilon}\frac{1}{(x-y)^2}\dif y, &x\in[\min[\hat{\mathcal{P}}_1(t)]+\varepsilon,\max[\hat{\mathcal{P}}_1(t)]-\varepsilon)\\
    &\frac{c}{2\varepsilon}\int_{-\varepsilon}^{\max[\hat{\mathcal{P}}_1(t)]-x}\frac{1}{(x-y)^2}\dif y, &x\in[\max[\hat{\mathcal{P}}_1(t)]-\varepsilon,\max[\hat{\mathcal{P}}_1(t)]+\varepsilon]\\
    \end{aligned}\right.\notag\\
    &=\frac{c}{2\varepsilon}\left(\frac{1}{\max\{\min[\hat{\mathcal{P}}_1(t)],x-\varepsilon\}}-\frac{1}{\min\{\max[\hat{\mathcal{P}}_1(t)],x+\varepsilon\}}\right),\ x\in\tilde{\mathcal{P}}(t).\label{eq:pdftilde}
\end{align}
Next, we calculate the gradient norms. We have
\begin{align}
    \nabla\hat{L}(\mathbf{w})&=-\sum_{t\in\mathcal{T}}\int_{\hat{\mathcal{P}}_1(t)}f_{\hat{P}_1(t)}(x)\nabla\ln f_{P_1(t)}(x)\dif x\notag\\
    &=-\sum_{t\in\mathcal{T}}\int_{\hat{\mathcal{P}}_1(t)}\frac{f_{\hat{P}_1(t)}(x)}{f_{P_1(t)}(x)}\nabla\mathrm{Sigmoid}(\mathbf{z})\dif x\notag\\
    &=-\mathbf{z}\sum_{t\in\mathcal{T}}\int_{\hat{\mathcal{P}}_1(t)}f_{\hat{P}_1(t)}(x)[1-f_{P_1(t)}(x)]\dif x\notag\\
    &=-\mathbf{z}\sum_{t\in\mathcal{T}}\left[\int_{\hat{\mathcal{P}}_1(t)}f_{\hat{P}_1(t)}(x)\dif x-\int_{\hat{\mathcal{P}}_1(t)}f_{\hat{P}_1(t)}(x)f_{P_1(t)}(x)\dif x\right]\notag\\
    &=-\mathbf{z}\sum_{t\in\mathcal{T}}\left[1-\int_{\hat{\mathcal{P}}_1(t)}f_{\hat{P}_1(t)}(x)f_{P_1(t)}(x)\dif x\right].\label{eq: pdf'}
\end{align}
Therefore, the gradient norm is
\begin{equation}
    \Vert\nabla\hat{L}(\mathbf{w})\Vert=\Vert\mathbf{z}\Vert\sum_{t\in\mathcal{T}}\left[1-\int_{\hat{\mathcal{P}}_1(t)}f_{\hat{P}_1(t)}(x)f_{P_1(t)}(x)\dif x\right].\label{eq: grad}
\end{equation}
Using the same method as above, we can obtain
\begin{equation}
    \Vert\nabla\tilde{L}(\mathbf{w})\Vert=\Vert\mathbf{z}\Vert\sum_{t\in\mathcal{T}}\left[1-\int_{\tilde{\mathcal{P}}_1(t)}f_{\tilde{P}_1(t)}(x)f_{P_1(t)}(x)\dif x\right].\label{eq: grad'}
\end{equation}
Then, we compare the two gradient norms $\Vert\nabla\hat{L}(\mathbf{w})\Vert$ and $\Vert\nabla\tilde{L}(\mathbf{w})\Vert$. From (\ref{eq: grad}) and (\ref{eq: grad'}), we only need to compare the following two integrals: 
\begin{equation}
    \hat{I}=\int_{\hat{\mathcal{P}}_1(t)}f_{\hat{P}_1(t)}(x)f_{P_1(t)}(x)\dif x,
\end{equation}
and
\begin{equation}
    \tilde{I}=\int_{\tilde{\mathcal{P}}_1(t)}f_{\tilde{P}_1(t)}(x)f_{P_1(t)}(x)\dif x.
\end{equation}
Because the investment decisions of the pre-SFT LLM can be arbitrary due to the randomness of model parameters, we have
\begin{equation}
    \hat{\mathcal{P}}_1(t)\subset\tilde{\mathcal{P}}_1(t)\subset\mathcal{P}_1(t).
\end{equation}
Because $f_{P_1(t)}(\cdot)$ is monotonically decreasing, from (\ref{equ: pdf}) and (\ref{eq: pdf'}), we can prove that
\begin{equation}
    \hat{I}<\tilde{I}<1,
\end{equation}
and thus we have 
\begin{equation}
    \Vert\nabla\hat{L}(\mathbf{w})\Vert>\Vert\nabla\tilde{L}(\mathbf{w})\Vert.
\end{equation}

