\textbf{Notations.} $n,p \in \N_{>0}$ and $q \in \N_{\geq 0}$ are large dimensional parameters, possibly tending to infinity. $n$ is the number of observations and $p+q$ the number of independent variables in linear models. We use $C$ and $D$ (resp. $\tau$) for arbitrary large (resp. small) positive constants. Let $\langle \cdot, \cdot \rangle$ stand for the scalar product, i.e. for any vectors $u$, $v \in \R^p$, $\langle u, v \rangle = u'v$. Denote by $\| \cdot \| = \| \cdot \|_2$ the Euclidean norm of vectors. For any matrix $A \in \R^{p \times p}$ and any vector $v \in \R^p$, we denote by $\| v \|_A = \sqrt{v'Av}$, a reweighted version of the Euclidean norm. Similarly, for any matrix $A \in \R^{p \times p}$ and any vector $v,u \in \R^p$, define $\langle u, v \rangle_A = u'Av$. We use $\| \cdot \|_{\text{op}}$ to denote the Euclidean $2$-norm of a matrix, namely, for any matrix $A \in \R^{n \times p}$, $\| A \|_{\text{op}}$ is the largest singular value of $A$. 

\section{Theoretical grounding}
\label{sec:theo}

\subsection{Setup: misspecification \textit{and} posterior drift}
\label{subsec:baseline}

This paper pertains to large models which, as in most of the recent literature, are \textit{linear}, see, e.g., \cite{bartlett2020benign}, and \cite{kelly2023virtue}. \cite{hastie2022surprises} do cover some non-linear cases but the corresponding require very lengthy proofs which is why the present paper focuses on extending linear combinations of features. Henceforth, our modelling framework follows that of \cite{hastie2022surprises} closely. We assume a data generating process (DGP) of the form
\begin{align}
\label{eq:dgpmis}
\begin{split}
    ((x_i,w_i),e_i) &\sim P_{x,w} \times  P_e,  \quad i=1,\dots,n \\
    y_i &= x'_i\beta+ w'_i\theta + e_i,  \quad i=1,\dots,n, 
\end{split}
\end{align}
where the $n$ random draws are independent. $P_{x,w}$ is a distribution on $\R^{p+q}$ with $\E[x_i]=0$ and $\E[w_i]=0$ and 
\begin{align*}
    \mathbb{C}\text{ov}[(x_i,w_i)]=\Sigma=
    \begin{bmatrix}
        \Sigma_x & \Sigma_{xw} \\
        \Sigma'_{xw} & \Sigma_w
    \end{bmatrix}. \label{eq:covmis}
\end{align*}
$P_e$ is a distribution on $\R$ with zero mean and variance $\sigma^2$. In our empirical application, as in \cite{kelly2023virtue}, $y$ will be the equity premium and $x$ a set of macroeconomic predictors that are expected to have some predictive power over the premium. 


The agent has access to the $x_i$ but not to the $w_i$, and hence only sees an incomplete picture, this is why her model is labeled as \textit{misspecified}. This corresponds to the assumptions in Section 5 of \cite{hastie2022surprises} and, to some extent, to Section IV of \cite{kelly2023virtue}. We write
$(y_i, x_i)\in \R \times \R^p  $ for one observation in the training data, and $(y,X)$ for the corresponding aggregated vector (in $\R^n$) and matrix (in $\R^{n\times p}$). 

As in \cite{hastie2022surprises}, we define out-of-sample prediction risk of the well specified model, i.e. the model in which all the covariates are observed, as
\begin{equation}
\label{eq:R_X}
    R_X(\hat{\beta},\beta) := \E[(x_0'(\hat{\beta}-\beta))^2|X] = B_X(\hat{\beta}, \beta) + V_X(\hat{\beta}, \beta),
\end{equation}
where $x_0$ is a random draw of $P_x$ that is independent from the training data. In the equation, the \textbf{bias} is $B_X(\hat{\beta}, \beta) =\|\E[\hat{\beta}|X]-\beta \|_\Sigma^2$, and the \textbf{variance} is $V_X(\hat{\beta}, \beta)=\text{Tr}[\mathbb{C}\text{ov}(\hat{\beta}|X)\Sigma]$.

The main departure from existing results is that we now discriminate between the $(\beta',\theta')'$ vector that is used for the two data generating processes in Equation \eqref{eq:dgpmis}: one vector for the training data ($(\beta_{\text{is}}',\theta_{\text{is}}')'$) and another one for the testing data ($(\beta_{\text{oos}}',\theta_{\text{oos}}')'$). In doing so, we include \textbf{posterior drift} in the model: we postulate a change in the link between $y$ and $(x',w')'$. Empirical support for this assumption will be provided in Section \ref{sec:betas} below.

The estimator $\hat{\beta}$ is evaluated with the in-sample (is) or out-of-sample (oos) generated data: 
\begin{equation}
    \hat{\beta}_{u} := \hat{\beta}_{u}(z_n)= (X'X+ \alpha I)^{-1}X'(X\beta_{u}+e)=n^{-1}(\hat{\Sigma}+z_nI)^{-1}X'(X\beta_{u}+W \theta_u+e),
    \label{eq:estimator}
\end{equation}

where $\alpha > 0$ and $u \in \{\text{is}, \text{oos} \}$.
Crucially, the above estimator relies on shrinkage with intensity $z_n = \alpha / n$ towards the identity matrix. In the remainder of the paper, we omit the dependence of the regularization parameter on the sample size $n$ and set $z := z_n$. If $n<p$ and $z \to 0$, the pseudo-inverse is taken for the inverse matrix. We have also set $\hat{\Sigma}=X'X/n$. Below, we explicit the terms for the quadratic error \eqref{eq:R_X} that is made when using the estimator $\hat{\beta}_{\text{is}}$ (from the data generated with $\beta_{\text{is}}$) when compared to the changed (or realized) $\beta_{\text{oos}}$. We are interested in this subsection in results for ridgeless estimators (when $z \to 0^+$).

\begin{proposition}

\label{lem:2}
    Under model \eqref{eq:dgpmis} and with $z \to 0$, the prediction risk of the misspecified model is 
\begin{align*}
    R_X^m(\hat{\beta}_{\text{is}},\beta_{\text{oos}}, \theta_{oos}) & = \E[(x_0'(\hat{\beta}_{\text{is}}-\beta_{\text{oos}})-w_0'\theta_{oos})^2|X] \\
    & = R_X(\hat{\beta}_{\text{is}},\beta_{\text{oos}}) + M(\theta_{oos}),
\end{align*}
where $M(\theta_{oos}) =\E[(w_0'\theta_{oos}-\E[w_0'\theta_{oos}|x_0])^2]$ is the \textit{misspecification bias}, i.e., the signal embedded in the unobserved features (following the notation of \cite{hastie2022surprises}). Moreover, in the isotropic case $\Sigma = I$,
\begin{align}
    \underset{n,p \rightarrow \infty}{\lim}R_X^m(\hat{\beta}_{\text{is}},\beta_{\text{oos}},\theta_{oos}) &= \left\{ \begin{array}{c l}
    (\sigma^2 + \| \theta_{is} \|_2^2) \frac{c}{1-c} + \|{\beta}_{\text{oos}}-{\beta}_{\text{is}}\|_2^2 + \| \theta_{oos} \|_2^2 & \quad p/n \rightarrow c < 1 \\
    (\sigma^2 + \| \theta_{is} \|_2^2)(c-1)^{-1} +c^{-1}\|\beta_{\text{is}}-\beta_{\text{oos}} \|^2_2 &\quad p/n \rightarrow c > 1  \\+ (1-c^{-1}) \|\beta_{\text{oos}} \|_2^2 + \| \theta_{oos} \|_2^2 .
    \end{array} \right. 
\end{align}
\end{proposition}
The proof of the proposition is postponed to Appendix \ref{app:proof_l2}. The limiting expressions generalize Theorem 4 in \cite{hastie2022surprises} by adding the posterior drift component. Plainly, both expressions for the risk are increasing in the \textbf{misspecification risk} $\| \theta_{oos} \|_2^2$ due to the unobserved features \textit{and} in the \textbf{drift risk} $\|\beta_{\text{is}}-\beta_{\text{oos}} \|_2^2$ that comes from the change in loadings. 


\subsection{Portfolio performance under posterior drift}
\label{subsec:performance}

Proposition \ref{lem:2} quantifies the impact of the presence of posterior drift on the risk of out-of-sample prediction of linear (ridge) regressions in the over-parameterized setting. We now focus on the impact on the financial performance of a market timing strategy. As in \cite{kelly2023virtue}, we analyze the returns of the strategy which consists of adjusting the position in an asset according to its estimated expected returns. Formally, the strategy's return can be written as 

\begin{equation}
\label{eq:strat}
    r^{(s)}_{t+1}(z) = \hat{\pi}_t(z) r_{t+1},
\end{equation}
where $\hat{\pi}_t(z) = \sum_{k=1}^p \hat{\beta}_{\text{is}}^{(k)} (z)x_t^{(k)}$ is the adjusted position in the asset and $r_{t+1}$ is its realized monthly return (the superscript $^{(s)}$ in the notation stands for \textit{strategy}). The estimated loadings in this case can be shrunk as in the general case in Equation \eqref{eq:estimator}.

For brevity, we directly consider the misspecified framework described in \eqref{eq:dgpmis} and without loss of generality, we assume $\sigma^2 = 1$. We provide similar results within the well-specified framework in Appendix \ref{subsub:wellspecifiedridge} and \ref{subsub:wellspecifiedminnorm}.

The following assumption establishes the linear model from which the covariates are considered to be drawn.

\begin{assump}
\label{ass:iddistcov}
    The covariates have the form $x_i = \Sigma^{1/2} z_i$ with $z_i = (z_{i1}, z_{i2}, \dots, z_{ip})$ having independent and identically distributed entries. Moreover, for all $j \in \{1,\dots,p\}$, $\E[z_{ij}] = 0$, $\E[z_{ij}^2] = 1$ and $\E[|z_{ij}|^{4+a}] \leq C < \infty$ for $a > 0$.
\end{assump} 

The out-of-sample expected return of the timing strategy under posterior drift can be decomposed as follows. 

\begin{proposition}
\label{prop:expretmis}
Let $z > 0$, $\xi = (e_{1}, e_{2}, \dots , e_{n})'$ with $(e_i)_i$ as in \eqref{eq:dgpmis} and Assumption (\ref{ass:iddistcov}) hold. Furthermore, denote by $r^{(s,w)}_{t+1}(z)$ the return of the strategy if the model is well-specified, i.e. there are no unobserved features, $w_i$, in the DGP \eqref{eq:dgpmis}. Then,

    \begin{align}
    \label{eq:oosexpretnonasymp}
        \mathbb{E}\left[ r^{(s)}_{t+1}(z) \big| X  \right]  = \mathbb{E}\left[ r^{(s,w)}_{t+1}(z) \big| X  \right] + \mathcal{M}(z)
    \end{align}

    where 

    \begin{align*}
        \mathbb{E}\left[ r^{(s,w)}_{t+1}(z) \big| X  \right] &= \beta_{oos}' \Sigma_x (zI + \hat{\Sigma}_x)^{-1} \big( \hat{\Sigma}_x \beta_{is} + \frac{1}{n} X' \xi \big) \\
        \mathcal{M}(z) & = \big( \beta_{oos}' \Sigma_x + \theta_{oos}' \Sigma_{xw}' \big) (zI + \hat{\Sigma}_x)^{-1} \E \Big[\hat{\Sigma}_{xw}\Big| X \Big] \theta_{is} \\
        & \quad + \theta_{oos}' \Sigma_{xw}' (zI + \hat{\Sigma}_x)^{-1} \big( \hat{\Sigma}_x \beta_{is} +  \frac{1}{n} X' \xi \big) .
    \end{align*}

\end{proposition}

The proof is postponed to Section \ref{subsub:misspecifiedgeneral} in the Appendix. The proposition shows that the out-of-sample expected return of the timing strategy under posterior drift crucially depends on the interactions between the observed and the unobserved covariates. These complex relations are encapsulated in the quantity $\mathcal{M}(z)$. Therefore, in order to provide more qualitative qualitative insights and intuition, we study different models of interest that allow to make this term more explicit. 

In what follows, we study the simpler case of i.i.d. features with unit variance, which entails $\Sigma=I$. 

We consider the following dimensional ratios.  

\begin{assump}
\label{ass:complexity}
    For some $\tau > 0$, $\tau \leq c \phi \leq \tau^{-1}$, with $c = (p+q)/n$, $\phi = p/(p+q) \in (0,1]$. 
\end{assump}

This assumption is standard in statistical theory and characterizes the proportional regime in which our study takes place. The constant $c$ stands for the complexity of the true models while $\phi$ is the misspecification ratio. The product $c\phi$ is the complexity of the misspecified model. 

% \begin{proposition}
% \label{prop:nonasyboundsdriftmis}
%     Let $z > 0$, $\xi = (e_1, e_2, \dots , e_n)'$ with $(e_i)_i$ as in \eqref{eq:dgpmis} and Assumptions (\ref{ass:iddistcov}), (\ref{ass:complexity}), (\ref{ass:opbound}), (\ref{ass:accumulationzero}) hold.  \textcolor{red}{Besides, assume $\E [\lambda_{max}(n^{-1}Z'Z)] \leq K < \infty$, for any $n \in \N^*$ DOUBLE CHECK IF REMOVABLE}. Then, for any $D>0$, there exist $C := C(\tau,K,D)$ such that 

%     \begin{equation*}
%         \big| \mathbb{E}\left[ r^{(s)}_{t+1}(z) | X  \right] - \Big( 1 - \frac{z}{z(1+c\phi m(-z)) + 1 - c\phi } \Big) \langle \beta_{is}, \beta_{oos} \rangle \big| \leq \frac{2 \| \beta_{oos} \|^{1/2}}{z^{1/2}n^{1/5}}
