\title{Elliptic flow of charged hadrons in d+Au collisions at $\sqrt{s_{NN}} =$ 200 GeV using a multi-phase transport model}

\author{J. Tanwar\inst{1}, I. Aggarwal\inst{1}, V. Bairathi\inst{2}, L. Kumar\inst{1}, and S. Kabana\inst{2}}
\institute{Physics Department, Panjab University, Chandigarh, India \and Instituto de Alta Investigación, Universidad de Tarapacá, Casilla 7D Arica 1000000, Chile}
