 Chigo Okonkwo
 \vspace{-2mm}
}

\maketitle                  % Create title and author

%------------------------------------------ Description of Authors ----------------------------------------------%

\begin{strip}
    \begin{author_descr}

        Electro-Optical Communication Group, Department of Electrical Engineering,\\Eindhoven University of Technology, the Netherlands,
        \textcolor{blue}{\uline{v.v.vliet@tue.nl}} 
    \end{author_descr}
    \vspace*{-3mm}
