\section{Missing Proofs}\label{app:missingProofs}
\begin{proof}[Proof of Lemma~\ref{lemma:unbiasednessSingleNode}]
First we let $X_e$ be a Bernoulli random variable taking value 1 with probability $p= \sfrac{1}{m}$ and 0 otherwise for each edge $e\in \E$. Then it follows that $\mathbb{E}[X_e] = p$, hence applying the linearity of expectation to Equation~\eqref{eq:EstimatorQ} we get
\begin{align*}
	\mathbb{E}[X_q(v)] &= \mathbb{E}\left[\sum_{e \in E : v\in e} \frac{q |\Delta_e|X_e}{p} + (1-2q)\sum_{e \in \E  : v\in \neighborEdge{e}}\frac{X_e}{p}\right]\\
	&= \sum_{e \in E : v\in e} \frac{q |\Delta_e|\mathbb{E}[X_e]}{p} + (1-2q)\sum_{e \in \E  : v\in \neighborEdge{e}}\frac{\mathbb{E}[X_e]}{p} \\
	&= \sum_{e \in E : v\in e} q |\Delta_e| + (1-2q)\sum_{e \in \E  : v\in \neighborEdge{e}}1 \\
	= q& \left( \sum_{e \in E : v\in e} |\Delta_e| -  2\sum_{e=\{u,v\} : v\in \mathcal{N}_u \cap \mathcal{N}_v}1\right) + \sum_{e \in \E  : v\in \neighborEdge{e}}1\\
	&=  q\left(2|\Delta_v| - 2|\Delta_v|\right) + |\Delta_v| =  |\Delta_v|.
\end{align*}
Where we used the fact that $\sum_{e \in E : v\in e}|\Delta_e| = 2|\Delta_v|$ as each triangle $\singleTri \in \triSetNode{v}$ is counted twice and $\sum_{e\in \E : v\in \neighborEdge{e}} 1 = |\Delta_v|$ as the number of triangles containing $v\in \V$ corresponds to the number of edges connecting two neighbors of $v\in \V$.
\end{proof}

\begin{proof}[Proof of Lemma~\ref{lemma:unbiasedEdgePartition}]
	First observe that the function in Equation~\eqref{eq:SingleNodeWeightEdge} is deterministic for any edge $e\in \E$, i.e., the indicator functions are based on properties of the input graph $\G$, and clearly $\G$ is fixed.

	Taking the expectation of $\estFunc_i(e)$ we have 
	\begin{align*}
		\expectation[f_j(e)] &\stackrel{(A)}{=}\sum_{e\in \E} \frac{\expectation[X_e]}{p} \frac{1}{|V_j|}\sum_{v\in V_j} \frac{a_q(v,e)}{|\wedgNodeSetGeneral{v}|}\\
		&\stackrel{(B)}{=}  \frac{1}{|V_j|} \sum_{v\in V_j} \frac{1}{{|\wedgNodeSetGeneral{v}|}} \sum_{e\in \E}  a_q(v,e)\\
		&\stackrel{(C)}{=}  \frac{1}{|V_j|} \sum_{v\in V_i} \clustMetric_v  =\frac{1}{|V_j|}\sum_{v\in V_j}\clustMetric_v = \clustGenPartition_j. \\
	\end{align*}
	Where $(A)$ comes from the linearity of expectation, $(B)$ comes from  $\expectation[X_e]=p$, by swapping the summations, and the fact that $1/|\wedgNodeSetGeneral{v}|$ does not depend on $e\in \E$ for any of nodes $v\in \V_i, i=1,\dots,k$, and $(C)$ by noting that 
	\[
	\sum_{e\in \E}  a_q(v,e) =  \sum_{e \in E : v\in e} q |\Delta_e| + (1-2q)\sum_{e \in \E  : v\in \neighborEdge{e}}1 = |\triSetNode{v}|
	\]
	from the proof of Lemma~\ref{lemma:unbiasednessSingleNode}, concluding therefore the proof as $|\triSetNode{v}|/|\wedgNodeSetGeneral{v}| = \clustMetric_v$.
\end{proof}

\begin{proof}[Proof of~\Cref{lemma:unbiasedOutput}]
	From Lemma~\ref{lemma:unbiasedEdgePartition} it holds that for each edge $e\in E$ and 
	each function $\estFunc_j(e)$, % for $j\in[k]$, 
	it is $\expectation[\estFunc_j(e)] = \clustGenPartition_j$, \edit{where $\expectation[\cdot]$ is over a random edge $e\in E$}.
	After noting that \edit{by definition} $\estFunc_j = \tfrac{1}{s}\sum_{e\in \mathcal{S}} \estFunc_j (e)$,
	the result follows by the linearity of expectation \edit{and $|\sampleSet| =s$}.
\end{proof}

\begin{proof}[Proof of Lemma~\ref{lemma:varianceBoundOutput}]
	First note that $\estFunc_j$ in output to Algorithm~\ref{alg:adaptiveBucketSampling} is the sample average over $s$ \emph{i.i.d.}\ random variables 
	\begin{equation}\label{eq:VarProofSingleTerm}
		\estFunc_j(e) = \sum_{e\in \E} \frac{X_e}{p} \frac{1}{|V_i|}\sum_{v\in V_i} \frac{a_q(v,e)}{|\wedgNodeSetGeneral{v}|}.
	\end{equation}
	Therefore to bound the variance, note
	\begin{equation}\label{eq:VarProofCombiningRes}
		\Var\left[\tfrac{1}{s}\sum_{i=1}^s \estFunc_j(e)\right] = \tfrac{1}{s^2} \sum_i \Var[\estFunc_j(e)] \le \frac{\hat{\sigma}^2}{s}.
	\end{equation}
	Where $\hat{\sigma}^2$ is a bound on the variance on $\estFunc_j(e)$,  we used the fact that the variables are i.i.d.\ and that $\Var[cX] = c^2\Var[X]$ for a random variable $X$ and a constant $c$.
	We now bound the variance of $\estFunc_j(e)$. Recall that
	\begin{equation}\label{eq:varianceBySecondMoment}
		\Var[X] = \expectation[X^2] - (\expectation[X])^2,
	\end{equation}
	hence,
	\begin{align*}
		&\expectation[\estFunc_j(e)^2]  =\\
		&= \expectation\left[ \sum_{e_1\in \E} \sum_{e_2 \in \E} \frac{X_{e_1}X_{e_2}}{p^2} \frac{1}{|V_j|}\sum_{v_1\in V_j} \frac{a_q(v_1,e_1)}{|\wedgNodeSetGeneral{v_1}|} \frac{1}{|V_j|}\sum_{v_2\in V_j} \frac{a_q(v_2,e_2)}{|\wedgNodeSetGeneral{v_2}|} \right]\\
		&\stackrel{(A)}{=}\sum_{e_1\in \E} \sum_{e_2 \in \E} \frac{\expectation[X_{e_1}X_{e_2}]}{p^2} \frac{1}{|V_j|}\sum_{v_1\in V_j} \frac{a_q(v_1,e_1)}{|\wedgNodeSetGeneral{v_1}|} \frac{1}{|V_j|}\sum_{v_2\in V_j} \frac{a_q(v_2,e_2)}{|\wedgNodeSetGeneral{v_2}|}\\
		&\stackrel{(B)}{\le}  \frac{1}{p} \frac{1}{|V_j|^2} \sum_{e_1\in \E}  \sum_{v_1\in V_j} \frac{a_q(v_1,e_1)}{|\wedgNodeSetGeneral{v_1}|} \sum_{v_2\in V_j} \sum_{e_2 \in \E}  \frac{a_q(v_2,e_2)}{|\wedgNodeSetGeneral{v_2}|} \\
		&\stackrel{(C)}{=}  \frac{1}{p} \frac{1}{|\V_j|^2} \sum_{e_1\in \E}  \sum_{v_1\in \V_j} \frac{a_q(v_1,e_1)}{|\wedgNodeSetGeneral{v_1}|} \sum_{v_2\in \V_j} \clustMetric_{v_2} = \frac{1}{p}  \left(\frac{1}{|\V_j|}  \sum_{v\in \V_j} \clustMetric_{v}\right)^2.
	\end{align*}
	Step $(A)$ follows from the linearity of expectation, step $(B)$ from the fact that $\expectation[X_{e_1}X_{e_2}] \le \expectation[X_{e_1}] = p$ noting that such random variables are 0--1 variables and for the events $I \doteq$``$X_{e_1}=1$'', and $I' \doteq \text{``}X_{e_2}=1$'' it holds $I\subseteq I'$, and $(C)$ follows from the same argument used in the proof of Lemma~\ref{lemma:unbiasedEdgePartition}. The final claim follows by combining the above result with Equations~\eqref{eq:varianceBySecondMoment} and~\eqref{eq:VarProofCombiningRes}, and the fact that $\estFunc_j(e)$ is an unbiased estimator of the triadic measure over each partition $j\in[k]$ (Lemma~\ref{lemma:unbiasedEdgePartition}).
\end{proof}

\begin{proof}[Proof of Theorem~\ref{theo:PdimBound}]
	We now show that $\PD(\Fset) = \VC(\DomH\times[a,b], \Fset^+)$ is bounded by $\floor{\log_2 \bucketColorSup} + 1$. 
	Let $\mathsf{VC}(\mathcal{H}\times[a,b], \mathcal{F}^+)=\pdim$ be the size of the largest set of elements of the space $\mathcal{H}\times[a,b]$ that can be shattered by the range-set $\mathcal{F}^+$, and let $Q$ be the shattered set attaining such size, that is $0<|Q|=\pdim$. Without loss of generality $Q$ contains one element $a=(e,x)$ for some $e\in E$ and $x>0$ (note that $x$ needs to be strictly greater than 0 otherwise the set $Q$ cannot be shattered, see Lemma~\ref{lemma:RVNozeroElements}), and furthermore note that there cannot be another element in $Q$ of the form $a=(e,y)$ for $y\neq x$ (see Lemma~\ref{lemma:RVatmostoneEdge}). There exist therefore $2^{\pdim-1}$ distinct and non-empty subsets of $Q$ containing the element $a$ that we label as $Q_1,\dots,Q_{2^{\pdim-1}}$, since the set $Q$ is shattered by $\mathcal{F}^+$. This implies therefore that there are $R_1,\dots R_{2^{\pdim-1}}$ ranges for some partitions $V_j, j =1\dots, k$ for which it holds $Q_i = Q \cap R_i$ with $i=1,\dots,2^{\pdim-1}$, by the definition of $Q$.
	Given an edge $e$ from $\DomH=\E$, an element  of the form $(e,x)$ can belong to at most $\bucketColorSup$ distinct ranges, which is easy to see by the following argument: (1) for a function $f_j(e)$ of a partition $j=1,\dots,k$ to be non-zero it should hold that there exists a node $v\in V_j$ such that $v \in \singleTri, \singleTri\in\triSetEdge{e}$ and (2) for an edge $e=\{u,v\}$ it holds $|\triSetEdge{e}| \le \min\{\nodeDeg{u},\nodeDeg{v}\}$ and further $\triSetEdge{e} = \{\{u,v\} \cup \{w\} : (\neighborNode{u}\setminus\{v\})\cap(\neighborNode{v}\setminus\{u\}) \})$ implying that all the nodes forming a triangle with edge $e=\{u,v\}$ should be in the neighborhood of the node with minimum degree among $u$ and $v$. Therefore for a fixed edge $e=\{u,v\}$ at most $\bucketColor_z$ where $z= \arg\min\{\nodeDeg{u},\nodeDeg{v}\}$ distinct functions $f_j(e)$ can have non-zero values. Hence the element $a=(e,x) \in Q$  can be contained in at most $\bucketColorSup$ ranges, therefore
	\[
	2^{\pdim-1}\le \bucketColorSup \implies \pdim \le \floor{\log_2 \bucketColorSup} + 1.
	\]
\end{proof}

\begin{proof}[Proof of Corollary~\ref{coroll:pdimQvals}]
	First we consider the case where $q=0$. By a similar argument to the proof of Theorem~\ref{theo:PdimBound} consider an element of the form $e=(u,x)$ in the shattered set $Q$ such that $|Q|=\pdim$, then the two nodes forming the edge $e=\{u,v\}$ do not contribute to the functions $f_j(e)$ for the partitions they belong to, that is $2^{\pdim-1} \le \bucketColorSup'$, taking the logarithm yields the claim. While for $q=1/2$ it can only be that at most two partitions (if $k\ge 2$) have $f_j(e) > 0$ and hence $\bucketColorSup' \le 2$ implying that $\pdim \le 2$.
\end{proof}

\begin{proof}[Proof of~\Cref{coroll:pdimLima}]
	Consider a star graph $G=(V,E)$ over $n$ nodes, then in such case $\bucketColorSup = 1$ as \emph{for each} edge $e=\{u,v\}\in \E$ it holds that $ \min\{\nodeDeg{u},\nodeDeg{v}\} = 1$, hence \edit{by Proposition~\ref{theo:PdimBound}: $\zeta \le \floor{\log_2 1} + 1 = 1$.}
\end{proof}

\begin{proof}[Proof of~\Cref{theo:probGuarantees}]
	\edit{To prove the claim we bound  the probability of failure of~\mainAlg, that is let $F$ be the event that~\mainAlg's guarantees do not hold. We now show $\Prob[F]\le \eta$. Clearly if this is the case, then~\mainAlg succeeds with probability at least $1-\eta$.}

	Let us define the following events:
	\begin{itemize}
		\item $F_1=s\ge s_{\max}$ and there exists $j\in [k]$ such that $|f_j-\clustGenPartition_j| > \varepsilon_j$; and
		\item $F_2=s< s_{\max}$, $\widehat{\varepsilon}_j\le \varepsilon_j$, for each $j\in [k]$, and there exists $j\in [k]$ such that $|f_j-\clustGenPartition_j| > \varepsilon_j$.
	\end{itemize}
	These are the two conditions under which Algorithm~\ref{alg:adaptiveBucketSampling} fails to report sufficiently accurate estimate\edit{s}, and under which its guarantees do not hold for the confidence intervals built around $f_j$, for $j\in[k]$ \edit{as from the statement}. By the combination of Theorem~\ref{theo:PdimBound} and~\ref{theo:boundSSPDIM} 
	%for $s_{\max}$ 
	then for~\mainAlg  it holds that $\Prob[F_1] \le \eta/2$, next consider $\widehat{\varepsilon}_j$ to be computed through Theorem~\ref{theo:empiricalBern} at each iteration $i$ using $\eta'=\eta/2^{i+1}$ then by a union bound over the possible (infinite) iterations~\cite{Borassi2019Kadabra,Pellegrina2023Silvan} it holds that $\Prob[F_2]\le \eta/2$. Hence, the failure probability of~\mainAlg $\Prob[F_1\cup F_2] \le \Prob[F_1] + \Prob[F_2] \le \eta/2 + \eta/2 \le \eta$, yielding the claim.
\end{proof}

\begin{proof}[Proof of Lemma~\ref{lemma:unbiasedVarEst}]
	Clearly $\frac{1}{c-1} \sum_{e\in\sampleSet} (f_j(e)-f_j)^2$ is an unbiased estimator of the variance of each function $f_j$ for $|\sampleSet|=c$, then 
	notice that $f_j = \frac{m}{c|V_j|}(\sum_{e}a_j(e) + q\sum_e b_j(e))$ and therefore
	$(f_j(e) - f_j)^2 = \frac{m^2}{|V_j|^2}[\hat{a}_j(e)^2 +q\hat{a}_j(e)\hat{b}_j(e)+ q^2\hat{b}_j(e)^2 ]$, hence 
	\begin{align*}
		\widehat{V}_q(f_j) &= \frac{m^2}{(c-1)|V_j|^2} \left(\sum_{e\in \sampleSet}A_j + qB_j + C_j q^2\right)\\
		&= \frac{m^2}{(c-1)|V_j|^2} \left(\sum_{e\in \sampleSet}\hat{a}_j(e)^2 + q \sum_{e\in \sampleSet}\hat{a}_j(e)\hat{b}_j(e) + q^2\sum_{e\in \sampleSet}\hat{b}_j(e)^2 \right)\\
		&=  \frac{1}{(c-1)}\sum_{e\in \sampleSet} (\estFunc_j(e) - \estFunc_j)^2
	\end{align*}
\end{proof}

\begin{proof}[Proof of Lemma~\ref{lemma:varEpsilon}]
	First note that $\varEst_q(\estFunc_j)$ is an unbiased estimate of $\Var[f_j]$, additionally given that $\varEst_q(\estFunc_j)$ has bounded range, i.e., it is a finite sum over bounded terms. Hence, it exists a value $B_q$ for each value of $q$ such that $\varEst_q(\estFunc_j) \le B_q$ therefore by Hoeffding's inequality (i.e., Theorem~\ref{th:Hoeffding}) it holds $\varepsilon'=B_q\sqrt{\frac{\log(2k/\eta')}{2|\sampleSet'|}}$, for any bound on the error probability $\eta'$.
\end{proof}

\begin{proof}[Proof of Lemma~\ref{lemma:upperBounds}]
	Recall that for each partition $j=1,\dots, k$, and each edge $e\in \E$ it holds that 
	\[
	\estFunc_j(e) = \frac{1}{p} \frac{1}{|V_i|}\sum_{v\in V_i} \frac{a_q(v,e)}{|\wedgNodeSetGeneral{v}|}.
	\]
	First notice that for a fixed edge $e=\{u,v\}\in \E$ the only nodes that can form a triangle with edge $e\in \E$ are those nodes such that $w \in (\neighborNode{u} \cap \neighborNode{v})$ for which it clearly holds that $(\neighborNode{u} \cap \neighborNode{v}) \subseteq \neighborNode{z}$ where $z=\arg\min\{\nodeDeg{u}, \nodeDeg{v}\}$, and further $|\triSetEdge{e}| \le \nodeDeg{z}$. Then recall that by definition $a_q(v,e) =  q|\triSetEdge{e}|\mathbf{1}[v\in e] + (1-2q)\mathbf{1}[v\in \neighborEdge{e}]$, hence we have 
	$q|\triSetEdge{e}|\mathbf{1}[w\in e] \le qd_z$ for both the two nodes $u,v \in e$ and
	\[
	(1-2q)\mathbf{1}[w\in \neighborEdge{e}] \le (1-2q) \text{ for }w\in \neighborNode{z}.
	\]
	Therefore for each partition $V_j$ we have that
	\[
	f_j(e) \le \frac{1}{p} \frac{1}{|V_i|} \left(\sum_{v\in V_i, v\in e} \frac{q d_z}{|\wedgNodeSetGeneral{v}|} + \sum_{v\in V_i, v\in \neighborNode{z}} \frac{(1-2q)}{|\wedgNodeSetGeneral{v}|}\right).
	\]
	which follows by the fact that $f_j(e)$ is the sum of non-negative terms, clearly $f_j(e) \le \max_e \{f_j(e)\} = R_j$ as computed by the algorithm, the final result follows from the definition of $p=\sfrac{1}{m}$.
	Finally the fact that $\floor{\log_2 \bucketColorSup}+1$ is an upper bound to the pseudo-dimension associated to the functions $f_j$, for $j\in[k]$, follows from Proposition~\ref{theo:PdimBound}
\end{proof}

\section{Auxiliary theoretical results}\label{appsec:auxTheo}
\begin{lemma}
	[\cite{Chiba1985}]\label{lemma:ChibaN}
	Given a graph $\G=(\V,\E)$ with $n$ nodes and $m$ edges, then
	\begin{equation*}
		\sum_{\{u,v\}\in E} \min\{\nodeDeg{u},\nodeDeg{v}\} \le 2 \arb m,
	\end{equation*}
	where $\arb$ corresponds to the \emph{arboricity} of the graph $G$, i.e., the minimum number of edge disjoint spanning-forests required in which $G$ can be decomposed.
\end{lemma}

\begin{lemma}[\cite{Riondato2018MisoSoup}]\label{lemma:RVatmostoneEdge}
	If $B\subseteq\DomH\times [a,b]$ is shattered by $\Fset^+$, it may contain \emph{at most one} element $(e,x)\in \DomH\times [a,b]$ for each $e\in \DomH$.
\end{lemma}
\begin{lemma}[\cite{Riondato2018MisoSoup}]\label{lemma:RVNozeroElements}
	If $B\subseteq\DomH\times [a,b]$ is shattered by $\Fset^+$, it cannot contain \emph{any} element of the form $(e,a)\in \DomH\times [a,b]$ for any $e\in \DomH$.
\end{lemma}


\begin{algorithm}[t]
	\caption{\texttt{FindThreshold}}\label{alg:findbeta}
	\KwIn{$\G=(\V,\E)$ with $|\V|=n$.}
	\KwOut{Value of the small-node degree threshold $\beta$.}
	$D=(0,\dots,0)\in \mathbb{R}^{n-2}; \beta \gets 2; T\gets 0$\;
	\lFor{$v\in V$}{
		$D_{\nodeDeg{v}}\gets D_{\nodeDeg{v}}+1$}
	\While{$T < c |V|$}{
		$T \gets \beta^2 D_{\beta}$\;
		$\beta \gets \beta + 1$\;
	}
	\KwRet{$\beta-1$}\;

\end{algorithm}

\begin{theorem}[Hoeffding bound~\citep{Mitzenmacher2017PC}]\label{th:Hoeffding}
	Let $X_1,\dots,X_s$ be $s$ independent random variables such that for all $i=1,\dots,s$, $\expectation[X_i] = \mu$ and $\Prob[X_i\in [a,b]]=1$. Then,
	\[
	\Prob\left(\left|\frac{1}{s}\sum_{i=1}^s X_i - \mu \right| \ge \varepsilon\right) \le 2\exp(-2s\varepsilon^2/(b-a)^2).
	\]
\end{theorem}

\section{Missing subroutines}

\subsection{\edit{Upper-bounds computation}}\label{appsubsec:upperbounds}
\begin{algorithm}[t]
	\caption{$\mathtt{UpperBounds}$}\label{alg:upperBondRange}
	\KwIn{$G=(V,E), \nodesetPartition, |\wedgNodeSetGeneral{v}|_{v\in V}$, $q$.}
	\KwOut{Upper bounds: $\zeta, R_1,\dots,R_k$.}
	$\mathbf{r}_v \gets (0,\dots,0) \in \mathbb{R}^{k}$; $\bucketColor_v \gets 0$ for each $v\in V$\label{alglineRange:initVectors}\;
	\For{$v\in V$\label{alglineRange:forNodes}}{
		\ForEach{$w\in \mathcal{N}_v$\label{alglineRange:forNodesVects}}{
			$\mathbf{r}_v[j] \gets \mathbf{r}_v[j] + \frac{(1-2q)}{|\wedgNodeSetGeneral{w}|}$ such that $w\in V_j$\label{alglineRange:updateVectors}\;
		}
		$\bucketColor_v \gets |\{j : w\in V_j \text{ and } w\in (\neighborNode{v}\cup \{v\})\}|$\label{alglineRange:ubCols}\;
	}
	$R_i \gets 0$ for each $i=1\dots,k$; $\bucketColorSup \gets 0$\label{alglineRange:initRanges}\;
	\ForEach{$e=(u,v) \in E$\label{alglineRange:forEdges}}{
		$z\gets \arg\min \{d_u,d_v\}$\label{alglineRange:minDeg}\;
		\ForEach{$r_j \in \mathbf{r}_z$\label{alglineRange:forVect}}{
			$\widehat{R}_j \gets r_j  + q \tfrac{\nodeDeg{z}}{|\wedgNodeSetGeneral{u}|} \mathbf{1}[u\in V_j] +  q\tfrac{\nodeDeg{z}}{|\wedgNodeSetGeneral{v}|} \mathbf{1}[v\in V_j] $\label{alglineRange:ubPart}\;
			$R_j \gets \max\left\{R_j, \widehat{R}_j\frac{m}{|V_j|}\right\}$\label{alglineRange:ubRange}\;
		}
		$\bucketColorSup \gets \max\{\bucketColorSup, \zeta_z\}$\label{alglineRange:ubPdim}\;
	}
	\KwRet{$\floor{\log_2 \bucketColorSup}+1, R_1,\dots,R_k$\label{alglineRange:return}}\;
\end{algorithm}

Algorithm~\ref{alg:upperBondRange} details the procedure used to compute an upper bound to the range of functions $f_j(e)$ for each of the possible sampled edges $e\in \E$ and partitions $j\in[k]$. 
The main idea is to first iterate through all the nodes maintaining a vector of size $k$ 
(lines \ref{alglineRange:initVectors}-\ref{alglineRange:updateVectors}). 
Each entry in a vector is then used to compute an upper bound on the range of $f_j(e)$, 
for $j\in[k]$, by iterating all edges $e\in \E$ (lines~\ref{alglineRange:initRanges}-\ref{alglineRange:ubRange}). 
For each edge $e\in \E$ we consider the vector corresponding to the node with minimum degree over $e\in \E$ 
to obtain the upper bounds $R_j$, for $j\in [k]$ (line~\ref{alglineRange:minDeg}). 

\emph{Time complexity.} Next we analyze the time complexity of Algorithm~\ref{alg:upperBondRange},
showing that in practice it is bounded by $\bigO(m)$. 
First, computing the vectors $\mathbf{r}_v$, for $v\in V$, requires at most $\bigO(m)$ by the handshaking lemma. 
Next, the algorithm iterates the vectors $\mathbf{r}_z, z\in V$ for all $z$ corresponding to the minimum degree nodes over all edges $e\in \E$. 
By storing only the non-zero entries over vectors $\mathbf{r}_z, z\in V$, the total non-zero entries are bounded by $\bigO(k)$ and by $\bigO(d_z)$. 
Consider the bound $\bigO(k)$ then the time complexity of  Algorithm~\ref{alg:upperBondRange} is bounded by $\bigO(km)$, otherwise by
\ifextended
Lemma~\ref{lemma:ChibaN}, 
\else
a known result~\citep{Chiba1985} (see our extended version),
\fi
the bound is $\bigO(\arb m)$, where $\arb$ is the arboricity of $\G$. 
For practical values of $k$, i.e., when $k$ is a large constant, the above bound is linear in $m$. Also note that if $k\ge d_{\max}$ where $d_{\max}$ is the maximum degree of a node in $\G$ then we can avoid iterating all entries in $\mathbf{r}_z, z\in V$, and use a tight deterministic upper bound on each $f_j$ reducing the time complexity $\bigO(\arb m)$ to $\bigO(m)$, yielding linear complexity again \edit{(see~\Cref{subsec:pdimBound})}.

\subsection{Variance estimation}\label{app:varianceEst}
\begin{algorithm}[t]
	\caption{$\mathtt{Fixq}$}\label{alg:fixQ}
	\KwIn{$G=(V,E), \nodesetPartition, |\wedgNodeSetGeneral{v}|_{v\in V}$, $q$, sample size $c$.}
	\KwOut{Terms $A_j,B_j,C_j, j\in[k]$.}
	$\mathcal{S} \gets \mathtt{UniformSample}(E,c)$\tcp*{$|\mathcal{S}|=c$}
	\For{$e\in \mathcal{S}$}{
		$a_j(e) \gets \sum_{v\in V_j, v\in \neighborEdge{e}} 1/|\wedgNodeSetGeneral{v}|$\;
		$b_j(e) \gets \sum_{v\in V_j, v\in e}|\triSetEdge{e}|/|\wedgNodeSetGeneral{v}| + \sum_{v\in V_j, v\in \neighborEdge{e}} 1/|\wedgNodeSetGeneral{v}|$\;
		$\bar{a} \gets \bar{a} + a_j(e)$\;
		$\bar{b} \gets \bar{b} + b_j(e)$\;
	}
	\For{$e\in \mathcal{S}$}{
		$\hat{a}_j(e) \gets a_j(e) -\bar{a}/c$\;
		$\hat{b}_j(e) \gets b_j(e) -\bar{b}/c$\;
	}
	\For{$j\gets 1$ to $k$}{
		$A_j \gets \sum_{e\in \mathcal{S}} \hat{a}_j(e)^2$\; 
		$B_j \gets \sum_{e\in \mathcal{S}} 2\hat{a}_j(e)\hat{b}_j(e)$\;
		$C_j \gets \sum_{e\in \mathcal{S}} \hat{b}_j(e)^2$\;
	}
	\KwRet{$A_j,B_j,C_j, j\in[k]$;}
\end{algorithm}
The procedure that we use to estimate the variance of the random variables $f_j$ is detailed in Algorithm~\ref{alg:fixQ}.

\subsection{Filtering small-degree nodes}\label{app:filterSmall}
In this section we briefly show that filtering small degree nodes, as described in Section~\ref{subsec:filtersmall}, yields no estimation error for~\mainAlg.
\begin{lemma}\label{lemma:triangleDecomp}
Let $v\in \V$ and $|\triSetNode{v}^L|$ be the counts returned for node $v$ by Algorithm~\ref{alg:preprocess}, and $\G'$ be the filtered graph of the input graph $\G$. Then $|\triSetNode{v}| = |\triSetNode{v}^L| + |\triSetNode{v}'|$, where $\triSetNode{v}'$ (resp. $\triSetNode{v}$) is the set of triangles containing node $v\in \V'$ in $\G'$ (resp. $\G$).
\end{lemma}
\begin{proof}
Pick an arbitrary node $v\in \V'$ and let $\triSetEdge{v}$ be the set of triangles containing node $v\in \V'$ in $\G = (\V,\E)$. Then the set $\triSetEdge{v} = \{\singleTri_1, \dots, \singleTri_{|\triSetEdge{v}|}\}$ can be partitioned as follows, let $\triSetNode{v}^L = \{\singleTri \in \triSetNode{v}: \text{it exists } w\in (\V\setminus \V') \text{ and } w \in \delta\}$ corresponding to the set of triangles containing at least one node removed from $\G$ by Algorithm~\ref{alg:preprocess} as from the statement, and $\triSetNode{v}' = \triSetNode{v} \setminus \triSetNode{v}^L$. Therefore it follows that $\triSetNode{v} = \triSetNode{v}^L \cup \triSetNode{v}'$, yielding the claim, as $\triSetNode{v}^L \cap \triSetNode{v}' = \emptyset$.
\end{proof}
Lemma~\ref{lemma:triangleDecomp} allows us to safely remove small degree nodes while focusing on estimating the number of remaining coefficients $\clustGenPartition_j$ in the filtered graph $\G'$. The next lemma shows that if we obtain function $f_j$
with respect to some slightly modified scores $\clustGenPartition'_j$ we can recover $|f_j-\clustGenPartition_j| \le \varepsilon_j$, for $j\in [k]$ on the original graph $\G$, i.e., the desired output.

\begin{corollary}\label{corollary:approxMetricDecomp}
Let $\clustMetric_v' = \frac{|\triSetNode{v}'|}{|\wedgNodeSetGeneral{v}|}$ where $\wedgNodeSetGeneral{v}$ refers to the graph $\G$ (i.e., not preprocessed) and $\clustGenPartition_j' = 1/|\V_j| \sum_{v\in \V_j} \clustMetric_v'$ then if $f_j'$ is an estimate such that 
$
|f_j'-\clustGenPartition_j' | \le \varepsilon_j$, for $j\in [k]$ in $\G'$
then $f_j = f_j'+\frac{1}{|\V_j|} \sum_{v\in \V_j}\frac{|\triSetNode{v}^L|}{|\wedgNodeSetGeneral{v}|}$ is such that $|f_j-\clustGenPartition_j| \le \varepsilon_j$, for $j\in [k]$ in $\G$. 

\end{corollary}
\begin{algorithm}[t]
	\caption{Filter small-degree nodes}\label{alg:preprocess}
	\KwIn{$G=(V,E)$.}
	\KwOut{Filtered graph $G'=(V',E')$, counts $|\triSetNode{v}^L|$ for $v\in V$.}
	$V'\gets V$\;
	\ForEach{$v\in V' : \nodeDeg{v} =1$}{
		$V'\gets V'\setminus \{v\}$\;	
	}
	$E' \gets \mathtt{Update}(E, V')$\;
	$\beta \gets \mathtt{FindThreshold}(G)$ \tcp*{$\Theta(n)$}
	\ForEach{$v\in V' : 2\le d(v) \le \beta$}{
		\ForEach{$\singleTri \in \triSetNode{v}$}{
			\lForEach{$w\in \singleTri$}{
				$|\triSetNode{w}^L| \gets |\triSetNode{w}^L| +1$}
		}
		$\V' \gets \V' \setminus{v}$\;
		$\E' \gets  \mathtt{Update}(\E, \V')$\;
	}
	\KwRet{$\G'=(\V',\E'), |\triSetNode{v}^L|$ for $v\in\V$}\;

\end{algorithm}

\begin{proof}
The proof directly follows from the definition of $\clustMetric_v$ which by Lemma~\ref{lemma:triangleDecomp} can be written as $\clustMetric_v = \frac{|\triSetNode{v}^L|+ |\triSetNode{v}'|}{|\wedgNodeSetGeneral{v}|}$.
Hence, $f_j = \frac{1}{|\V_j|}\sum_{v\in \V_j} \clustMetric_v = \frac{1}{|\V_j|}\sum_{v\in \V_j} \frac{|\triSetNode{v}'|}{|\wedgNodeSetGeneral{v}|} + \frac{1}{|\V_j|}\sum_{v\in \V_j} \frac{|\triSetNode{v}^L|}{|\wedgNodeSetGeneral{v}|} $ hence by the definition of $f_j'$, and the fact that there is no error over the second term, the claim follows.
\end{proof}

The above result captures the fact that we can execute~\mainAlg on the processed graph $\G'$, by only adopting $\wedgNodeSetGeneral{v}$, for $v\in V$, from the original graph $\G$ without any loss on the guarantees over $\G$, with negligible overhead (i.e., only $\bigO(n)$ total additional work).

The exact procedure for  filtering small degree nodes is detailed in Algorithm~\ref{alg:preprocess}.


\section{Baselines}\label{appsec:baselines}

\begin{algorithm}[t]
	\caption{\texttt{\baseFull}}\label{alg:fullWS}
	\SetKwComment{Comment}{$\triangleright$\ }{}
	\KwIn{$\G=(\V,\E)$, partitions $V_i$, $\varepsilon_i, i=1,\dots,k, \eta$, $\clustMetric$.}
	\KwOut{$f(V_i) \in\Psi(V_i) \pm \varepsilon_i$ w.p.\ $\ge 1-\eta$.}
	$\widehat{\clustMetric}_{v} \gets 0, v\in \V$; $s\gets \ceil{\tfrac{1}{2\varepsilon_i^2} \log(2k/\eta)}$\;
		\ForEach{$i \gets 1$ to  $k$}{
			$\mathcal{S} \gets \emptyset$\;
				\For{$j \gets 1$ to $s$}{
					$v\gets \mathtt{Uniform}(V_i)$\;
					\If{$\clustMetric = \clustCoeff$}{
						$\mathcal{S}\gets \mathcal{S} \cup \mathtt{SampleWedge}(v)$\;}
					\ElseIf{$\clustMetric=\closureCoeff$}{
						$\mathcal{S}\gets \mathcal{S} \cup \mathtt{Sample2Path}(v)$\;
					}
				}
				\ForEach{$\mathtt{w} \in \mathcal{S} : ``\mathtt{w}=\mathtt{closed}$''}
				{
					$\estFunc_i \gets \estFunc_i + \tfrac{1}{s}$\;
			}}
		\KwRet{$\estFunc_i, i=1,\dots,k$}\;
	\end{algorithm}


	\begin{algorithm}[t]
		\caption{\texttt{SampleWedge}~\citep{Kolda2014, Seshadhri2014}}\label{alg:WS}
		\SetKwComment{Comment}{$\triangleright$\ }{}
		\KwIn{$\G=(\V,\E), v\in \V$.}
		\KwOut{A wedge sampled uniformly at random from $\wedgNodeSetCenter{v}$.}
			$u_1 \gets \mathtt{Uniform}(\neighborNode{v})$\;
			$u_2 \gets \mathtt{Uniform}(\neighborNode{v}\setminus\{u_1\})$\;
			$\wedg \gets \langle u_1,u_2\rangle$\;
		\KwRet{$\wedg$}\;
	\end{algorithm}

	\begin{algorithm}[t]
		\caption{\texttt{Sample2Path}}\label{alg:2PS}
		\SetKwComment{Comment}{$\triangleright$\ }{}
		\KwIn{$\G=(\V,\E), v\in \V$.}
		\KwOut{A 2-path sampled uniformly at random from $\wedgNodeSetHead{v}$.}
		$p_{u_1}, \dots p_{u_{|\nodeDeg{v}|}} \gets \tfrac{\nodeDeg{u_1}-1}{\sum_{u\in \neighborNode{v}} (\nodeDeg{u}-1)}, \dots, \tfrac{\nodeDeg{u_{|\nodeDeg{v}|}} -1}{ \sum_{u\in \neighborNode{v}} (\nodeDeg{u}-1) }, u_i \in \neighborNode{v}$\;
			$u_1 \gets \mathtt{Sample}(\neighborNode{v}, p_i)$\;
			$u_2 \gets \mathtt{Uniform}(\neighborNode{u_1}\setminus\{v\})$\;
			$\wedg \gets \langle u_1,u_2\rangle$\;
		\KwRet{$\wedg$}\;
	\end{algorithm}

The baseline considered is based on the state-of-the-art approach devised for estimating local clustering coefficients by sampling~\citep{Seshadhri2014}. We denoted such algorithm by~\baseFull. 
We present such baseline in Algorithm~\ref{alg:fullWS}.
Note that the~\baseFull exactly coincides with the approach of~\citet{Seshadhri2014} when the considered metric is the clustering coefficient, in particular,
such algorithm proceeds as follows: consider each partition independently $\V_i$,  $i=1,\dots,k$:  
($i$)~uniformly sample a random node $v$ from each partition $\V_i$, $i=1,\dots,k$; 
($ii$)~for the sampled node, uniformly sample a wedge centered at the node and update an estimate if the wedge is closed, i.e., it forms a triangle; 
($iii$)~repeat such steps until concentration (i.e., for $\bigO(\varepsilon_i^{-2} \log(k/\eta))$).  
Such approach is based on the fact that a random sampled wedge from a node $v\in V_i$ 
provides an unbiased estimate of $\clustCoeff_v$. 
Inspired by such approach we designed a non trivial baseline for estimating the closure coefficient $\closureCoeff_v$ for a node $v\in \V$, which is based on uniformly sampling a wedge \emph{headed} at $v\in \V$, that is we uniformly sample $\wedg$ from $\wedgNodeSetHead{v}$, which requires particular attention to avoid bias in the final sampling procedure, in particular we have the following.

\begin{lemma}\label{lemma:unbiasedBaseline}
	Each wedge $\wedg \in \wedgNodeSetHead{v}$ in output to Algorithm~\ref{alg:2PS} is sampled uniformly at random from $\wedgNodeSetHead{v}$ for $v\in V$, and the probability that a sampled path is closed, i.e., forms a triangle with $v\in\V$ corresponds to $\closureCoeff_v$.
\end{lemma}
\begin{proof}
	Let us compute the probability to sample a path $\wedg = \langle u_1, u_2 \rangle \in \wedgNodeSetHead{v}$ of length-2 starting from a node $v\in \V$,
	\begin{align*}
	&\mathbb{P}[\wedg= \langle u_1, u_2 \rangle \text{ is sampled} ] = \mathbb{P}[u_1 \text{ is 1-st node}] \mathbb{P}[u_2 \text{ is 2-nd node}] \\
	&= p_{u_1} \cdot p_{u_2} = \tfrac{\nodeDeg{u_1}-1}{\sum_{u\in \neighborNode{v}} (\nodeDeg{u}-1)} \cdot \tfrac{1}{\nodeDeg{u_1}-1} =  \tfrac{1}{\sum_{u\in \neighborNode{v}} (\nodeDeg{u}-1)}
	\end{align*}
	Therefore the 2-path $\wedg = \langle u_1, u_2 \rangle$ is sampled uniformly among all the $\sum_{u\in \neighborNode{v}} (\nodeDeg{u}-1)$ paths of length 2 headed at $v\in \V$. To compute the probability that such path is closed, notice that a path can be closed only if $\{u_1,u_2,v\}\in \triSet$, that is if the three nodes form a triangle, hence
	\[
	\mathbb{P}[\wedg= \langle u_1, u_2 \rangle \text{ is closed} ] = \tfrac{2|\triSetNode{v}|}{\sum_{u\in \neighborNode{v}} (\nodeDeg{u}-1)} = \closureCoeff_v.
	\] 
	where we used the fact that each triangle contributes to two distinct wedges that can be sampled by Algorithm~\ref{alg:2PS}.
\end{proof}

\begin{corollary}
	The output $f_i$ of Algorithm~\ref{alg:fullWS} is unbiased and it holds that $\Prob[|f_i-\clustGenPartition_i| \ge \varepsilon_i] \le \eta$ simultaneously for all $i=1,\dots,k$.
\end{corollary}
\begin{proof}
	When Algorithm~\ref{alg:WS} is executed for the clustering coefficient $\clustCoeff$, 
	this immediately follows from the results of~\citet{Seshadhri2014}.
	While when Algorithm~\ref{alg:WS} is executed for the closure coefficient $\closureCoeff$ we e can write $f_i$ as,
	\[
	\estFunc_i = \frac{1}{s}\sum_{i=1}^s \sum_{v\in V} X_\wedg^v 
	\]
	where $X_\wedg^v$ is an indicator random variable if the wedge $\wedg$ headed at $v\in \V$sampled by the algorithm  is closed, clearly $\Prob[X_\wedg^v = 1] = \frac{\closureCoeff_v}{|V_i|}$ as it is the results of the event that node $v\in \V_i$ is sampled (which occurs with probability $1/|\V_i|$) and that a closed wedge headed at $v\in \V_i$ is sampled that occurs with probability $\closureCoeff_v$ by Corollary~\ref{lemma:unbiasedBaseline}, hence $\expectation[\estFunc_i] = \clustGenPartition_i$. The concentration of $f_i$ follows by Hoeffding's bound~(Theorem~\ref{th:Hoeffding}) and the application of the union bound over the $k$ partitions.
\end{proof}

\section{Parameter setting}\label{appsec:parameterGuidance}
\edit{Following the discussion in~\Cref{subsec:adaptivity}, since~\mainAlg adapts both the parameter $q$ and the bounds $\widehat{\varepsilon}_j$ we found that best parameter setting is as follows:
\begin{itemize}
	\item Setting the parameter $C$ (the threshold defining the filtering of small-degree nodes) according to the degree distribution of the graph. 
	That is, such that the minimum-degree of the nodes $v\in V'$ in the remaining graph $G'$ have degree $\ge 10$ in the original graph $G$ (note that they may have smaller degree in $G'$). 
	This helps to obtain a better bound for the values $R_j$, for $j\in[k]$.
	\item Setting the parameter $\eta = 0.01$, as it gives high probabilistic guarantees of success and it has little impact on the final sample size.
	\item Setting $c$, i.e., the sample size used to estimate the variance of the functions $f_j$, for $j\in [k]$ and optimize the parameter $q$ to a small constant, (we use $c=500$), therefore fixing the value of $q$ becomes extremely efficient.
	\item Setting the parameter $\theta$ controlling the geometric sample schedule $s_i = \theta s_{i-1}$ to $\theta = 1.4$, in accordance with previous work~\cite{Riondato2018Abra, Pellegrina2023Silvan}. Often yielding good results in practice as shown in~\Cref{sec:exps}.
	\item Setting the parameters $\varepsilon_j = \varepsilon \in (0.15,0.05)$, this is given by the fact that~\mainAlg's guarantees are adaptive. Hence, as from~\Cref{exps:sota} it is often the case that~\mainAlg returns bounds $\widehat{\varepsilon}_j$ much smaller than $\varepsilon_j$ (up to the order of $10^{-4}$). This is clearly, another advantage of our algorithm $\varepsilon$.
\end{itemize}
Concerning~\algFixedSS we observe that it is often sufficient to set the sample size $s = m/500$ where $m$ is the number of edges in the graph $G$, to obtain empirical errors $|f_j-\clustGenPartition_j|$ that are negligible, yielding also remarkably accurate relative approximations.
}

