\section{Proof of Theorem \ref{thm1}}
\label{app:thm1}
%{\bf Proof of Theorems \ref{thm1} and \ref{thm2}}. 
\begin{proof} 
We begin by proving the existence of a continuous function $F^* : \mathcal{X} \to \mathbb{R}$ and a bounded coefficient vector $\gamma^* \in \mathbb{R}^q$ that jointly minimize the population risk associated with the semi-parametric logistic model~(\ref{eq:logit1}).
%\paragraph{Compact Hypothesis Space.}

Let $D \subset \mathbb{R}^{d-1}$ be a compact domain and denote by $C(D)$ the space of continuous functions on $D$ endowed with the uniform norm $\|F\|_\infty = \sup_{x \in D} |F(x)|$. For fixed constants $C_F, C_{\bm{\gamma}} > 0$, we define the hypothesis space:
\[
  \Theta := \left\{(F, \bm{\gamma}) : F \in C(D),\, \|F\|_\infty \leq C_F,\ \bm{\gamma} \in \mathbb{R}^q,\ \|\bm{\gamma}\|_1 \leq C_{\bm{\gamma}} \right\}.
\]
We equip $\Theta$ with the product metric:
\[
  d\big((F,\bm{\gamma}), (F',\bm{\gamma}')\big) = \|F - F'\|_\infty + \|\bm{\gamma} - \bm{\gamma}'\|_1.
\]

\paragraph{Step 1: Compactness of $\Theta$.}
\begin{itemize}
  \item The $\ell_1$-ball $\{\bm{\gamma} \in \mathbb{R}^q : \|\bm{\gamma}\|_1 \leq C_{\bm{\gamma}\}}$ is compact as it is closed and bounded in finite-dimensional Euclidean space.
  \item The set $\{F \in C(D) : \|F\|_\infty \leq C_F\}$ is closed, uniformly bounded, and equicontinuous on the compact domain $D$. By the Arzelà–Ascoli theorem, this set is compact in the uniform topology.
  \item Hence, $\Theta$ is compact as a product of two compact metric spaces.
\end{itemize}

\paragraph{Step 2: Continuity of the Risk Function.}
We define the population risk as
\[
  \mathcal{R}(F, \bm{\gamma}) := \mathbb{E}_{(\bm{X},\bm{z},y)}\left[ \ell\left(y, F(\mathbf{X}) + \mathbf{z}^\top \bm{\gamma} \right) \right],
\]
where $\ell(y,\eta) = -y\eta + \log(1 + e^{\eta})$ is the logistic loss.

Let $(F,\bm{\gamma}), (F',\bm{\gamma}') \in \Theta$. For any realization $(\mathbf{X}, \mathbf{z}, y)$, and assuming $\|\mathbf{z}\|_1 \leq C_{\mathbf{z}}$ almost surely, we have
\[
\left|F(\mathbf{X}) + \mathbf{z}^\top \bm{\gamma} - F'(\mathbf{X}) - \mathbf{z}^\top \bm{\gamma}'\right| 
\leq \|F - F'\|_\infty + C_{\mathbf{z}} \|\bm{\gamma} - \bm{\gamma}'\|_1 =: \Delta + C_{\mathbf{z}} \delta.
\]
The logistic loss $\ell(y, \cdot)$ is 1-Lipschitz in $\eta$, so
\[
\left| \ell(y, F(\mathbf{X}) + \mathbf{z}^\top \bm{\gamma}) - \ell(y, F'(\mathbf{X}) + \mathbf{z}^\top \bm{\gamma}') \right| 
\leq \Delta + C_{\mathbf{z}} \delta.
\]
Taking expectations, we obtain
\[
\left|\mathcal{R}(F,\bm{\gamma}) - \mathcal{R}(F',\bm{\gamma}')\right| \leq (1 \vee C_{\mathbf{z}}) \cdot d((F,\bm{\gamma}), (F',\bm{\gamma}')),
\]
i.e., $\mathcal{R}$ is Lipschitz continuous on $\Theta$.

\paragraph{Step 3: Existence of a Minimizer.}
Since $\mathcal{R}$ is continuous on the compact set $\Theta$, the extreme value theorem implies the existence of a minimizer:
\[
(F^*, \bm{\gamma}^*) := \arg\min_{(F,\bm{\gamma}) \in \Theta} \mathcal{R}(F,\bm{\gamma}),
\quad \text{with } \mathcal{R}^* := \mathcal{R}(F^*, \bm{\gamma}^*).
\]

\paragraph{Step 4: Approximation by Truncated Signatures.}
By the universality property of truncated path signatures (see the last key property in Section \ref{sec:path}), for any $\varepsilon > 0$, there exists $p^* \in \mathbb{N}$ and $\bm{\beta}_{p^*}^* \in \mathbb{R}^{s_d(p^*)}$ such that
\[
\left|F^*(\mathbf{X}) - \langle \bm{\beta}_{p^*}^*, S_{p^*}(\wt{\mathbf{X}})\rangle \right| < \varepsilon \quad \text{a.s.}
\]
Let $\bm{\theta}_{p^*}^* := (\bm{\beta}_{p^*}^{*\top}, \bm{\gamma}^{*\top})^\top\in \mathbb{R}^{s_d(p^*)+q}$. Define the population risk of oracle path-signature model:
\[
  \mathcal{R}_{p^*}(\bm{\theta}_{p^*}^*) := \mathbb{E}_{(\bm{X},\bm{z},y)} \left[ \ell\left(y, \widetilde{\bm{S}}_{p^*}^\top \bm{\theta}_{p^*}^* \right) \right],
\]
where $\widetilde{\bm{S}}_{p^*} := (S_{p^*}(\wt{\mathbf{X}})^\top, \mathbf{z}^\top)^\top$. Then:
\begin{align}
\left| \mathcal{R}_{p^*}(\bm{\theta}_{p^*}^*) - \mathcal{R}^* \right|
&= \left| \mathbb{E}_{(\bm{X},\bm{z},y)} \left[ \ell\left( y, \widetilde{\bm{S}}_{p^*}^\top \bm{\theta}_{p^*}^* \right) - \ell\left( y, F^*(\mathbf{X}) + \mathbf{z}^\top \bm{\gamma}^* \right) \right] \right| \notag \\
&\leq \mathbb{E}_{(\bm{X},\bm{z},y)} \left| \ell\left( y, \widetilde{\bm{S}}_{p^*}^\top \bm{\theta}_{p^*}^* \right) - \ell\left( y, F^*(\mathbf{X}) + \mathbf{z}^\top \bm{\gamma}^* \right) \right| \notag \\
&\leq \mathbb{E}_{(\bm{X},\bm{z},y)} \left| \widetilde{\bm{S}}_{p^*}^\top \bm{\theta}_{p^*}^* - \left(F^*(\mathbf{X}) + \mathbf{z}^\top \bm{\gamma}^* \right) \right| \notag \\
&< \varepsilon.
\label{eq:thm1_approx}
\end{align}
This establishes Theorem~\ref{thm1}.
\end{proof}

\section{Proof of Theorem \ref{thm2}}
\label{app:thm2}
\begin{proof}
%\paragraph{Proof of Theorem~\ref{thm2}.}
For a fixed truncation order $p$, define the minimal population risk:
\[
  L(p) := \inf_{\bm{\theta}_p \in B_{p,r}} \mathcal{R}_p(\bm{\theta}_p) = \mathcal{R}_p(\bm{\theta}_p^*),
\]
where $B_{p,r}$ is a compact convex parameter space, and $\bm{\theta}_p^*$ exists since $\mathcal{R}_p$ is convex in $\bm{\theta}_p$ and continuous.

We note that the Hessian of the logistic risk is given by:
\[
  \nabla^2 \mathcal{R}_p(\bm{\theta}_p) 
  = \mathbb{E}_{(\bm{X},\bm{z},y)} \left[ \sigma'(\widetilde{\bm{S}}_p^\top \bm{\theta}_p) \cdot \widetilde{\bm{S}}_p \widetilde{\bm{S}}_p^\top \right] \succeq 0,
\]
where $\sigma(\eta) = (1 + e^{-\eta})^{-1}$ and $\sigma'(\eta) = \sigma(\eta)(1 - \sigma(\eta)) \in (0, 1/4]$. Hence, $\mathcal{R}_p$ is convex, ensuring the existence of $\bm{\theta}_p^*$.

Moreover, the nested structure $B_{0,r} \subset B_{1,r} \subset \cdots \subset B_{p,r} \subset \cdots$ implies that $L(p)$ is non-increasing in $p$. By the approximation argument in Theorem~\ref{thm1}, we know that for any $\varepsilon^* >0$ there exist some $p^*$ and $\bm{\theta}_{p^*}^*$ such that $\left|\mathcal{R}_{p^*}(\bm{\theta}_{p^*}^*) - \mathcal{R}^*\right| < \varepsilon^* $. If $L(p)$ are strictly smaller for some $p > p^*$, i.e.,
\[
  \mathcal{R}_{p^*}(\bm{\theta}_{p^*}^*) - L(p) \geq \varepsilon^* > 0,
\]
then we would obtain
\[
  \left| \mathcal{R}_{p^*}(\bm{\theta}_{p^*}^*) - \mathcal{R}^* \right|= \mathcal{R}_{p^*}(\bm{\theta}_{p^*}^*)-L(p) + L(p) - \mathcal{R}^*
  \geq \varepsilon^* + L(p)-\mathcal{R}^*  \geq \varepsilon^*,
\]
which is a contradiction. Hence, $L(p)$ attains its minimum at $p^*$ and remains constant for all $p \geq p^*$. This concludes the proof of Theorem~\ref{thm2}.
\end{proof}

\section{Proof of Theorem \ref{thm3}}
\label{app:thm3}
%{\bf Proof of Theorems \ref{thm3} and \ref{thm4}}. 
Here we will make extensive use of the concentration results developed by \citet{vanHandel2014}, as well as key analytical techniques from \citet{ferm2022linear}. We focus on the centered empirical risk associated with path signatures truncated at order $p$. Specifically, for any $\bm{\theta}_p \in B_{p,r}$, we define
\begin{align}
Z_{p,n}(\bm{\theta}_p) \coloneqq \widehat{R}_{p,n}(\bm{\theta}_p) - R_p(\bm{\theta}_p),
\label{eq:Zmn}
\end{align}
where $\widehat{R}_{p,n}(\bm{\theta}_p)$ denotes the empirical risk computed from $n$ samples, and $R_p(\bm{\theta}_p)$ is its population analogue.

The next lemma shows that the process $\big(Z_{p,n}(\bm{\theta}_p)\big)_{\bm{\theta}_p \in B_{p,r}}$ is sub-Gaussian with respect to a suitably defined metric. This property allows us to apply a chaining tail inequality from \citet{vanHandel2014}, yielding a uniform high-probability bound on the deviations of $Z_{p,n}(\bm{\theta}_p)$ over the parameter set $B_{p,r}$. This concentration result serves as a central component in the proof of Theorem~\ref{thm3}.


\begin{lemma}\label{lem:A3} %% new lemma 1 
Under assumptions (A.2)–(A.3), for any $p \in \mathbb{N}$, the stochastic process $\big(Z_{p,n}(\bm{\theta}_p)\big)_{\bm{\theta}_p \in B_{p,r}}$ is subgaussian with respect to the semimetric
\begin{equation}\label{eq:D}
    D(\bm{\theta}_p, \bm{\eta}_p) = \frac{C}{\sqrt{n}} \|\bm{\theta}_p - \bm{\eta}_p \|, \quad \bm{\theta}_p, \bm{\eta}_p \in B_{p,r},
\end{equation}
where the constant $C$ is defined as
\begin{equation}\label{eq:C}
    C = 2 \left(C_{\bm{z}} + e^{C_{\bm{X}}+T} \right).
\end{equation}
\end{lemma}

\begin{proof}
By definition, for any $\bm{\theta}_p \in B_{p,r}$, we have $\mathbb{E}[Z_{p,n}(\bm{\theta}_p)] = 0$. Let the loss function $\ell_{(\wt{\bm{X}}, \bm{z}, y)}: B_{p,r} \to \mathbb{R}$ be defined as
\[
\ell_{(\wt{\bm{X}}, \bm{z}, y)}(\bm{\theta}_p) = -y \langle \bm{\theta}_p, \widetilde{\bm{S}}_p(\widetilde{\bm{X}}, \bm{z}) \rangle + \log\left(1 + e^{\langle \bm{\theta}_p, \widetilde{\bm{S}}_p(\widetilde{\bm{X}}, \bm{z}) \rangle} \right).
\]
We first show that $\ell_{(\wt{\bm{X}}, \bm{z}, y)}$ is $C$-Lipschitz. For any $\bm{\theta}_p, \bm{\eta}_p \in B_{p,r}$,
\begin{align}
\big|\ell_{(\wt{\bm{X}}, \bm{z}, y)}(\bm{\theta}_p) - \ell_{(\wt{\bm{X}}, \bm{z}, y)}(\bm{\eta}_p)\big|
&= \left| -y \langle \bm{\theta}_p, \widetilde{\bm{S}}_p(\widetilde{\bm{X}}, \bm{z}) \rangle + \log\left(1 + e^{\langle \bm{\theta}_p, \wt{\bm{S}}_p(\widetilde{\bm{X}}, \bm{z}) \rangle}\right) \right. \notag\\
&\quad + \left. y \langle \bm{\eta}_p, \widetilde{\bm{S}}_p(\widetilde{\bm{X}}, \bm{z}) \rangle - \log\left(1 + e^{\langle \bm{\eta}_p, \widetilde{\bm{S}}_p(\widetilde{\bm{X}}, \bm{z}) \rangle}\right) \right| \notag \\
&\leq |y \langle \bm{\theta}_p - \bm{\eta}_p, \widetilde{\bm{S}}_p(\widetilde{\bm{X}}, \bm{z}) \rangle| + \left|\log\left(1 + e^{\langle \bm{\theta}_p, \widetilde{\bm{S}}_p(\widetilde{\bm{X}}, \bm{z}) \rangle}\right) - \log\left(1 + e^{\langle \bm{\eta}_p, \widetilde{\bm{S}}_p(\widetilde{\bm{X}}, \bm{z}) \rangle}\right) \right| \notag \\
&\leq (|y| + 1) \| \widetilde{\bm{S}}_p(\widetilde{\bm{X}}, \bm{z}) \| \cdot \|\bm{\theta}_p - \bm{\eta}_p\| \notag \\
&\leq 2(\| \bm{z} \| + \| \widetilde{\bm{S}}_p(\widetilde{\bm{X}}) \|) \|\bm{\theta}_p - \bm{\eta}_p \| \notag \\
&\leq 2(C_{\bm{z}} + e^{C_{\bm{X}}+T}) \|\bm{\theta}_p - \bm{\eta}_p\| := C \|\bm{\theta}_p - \bm{\eta}_p \|. \label{eq:lipschitz}
\end{align}
The bound on the exponential term uses the fact that the function $f(t) = \log(1 + e^t)$ is 1-Lipschitz, since its derivative $f'(t) = \frac{e^t}{1 + e^t} \in (0,1)$. Applying Lemma 5.1 of \cite{lyons2014rough}, the norm of the truncated signature $\| \widetilde{\bm{S}}_p(\widetilde{\bm{X}}) \|)$ has the following bound:
\[
\| \wt{\bm{S}}_p(\wt{\bm{X}}) \|\leq \sum_{k=0}^p \frac{\|\wt{\bm{X}}\|_{TV}^k}{k!} \leq e^{\|\wt{\bm{X}}\|_{TV}} = e^{\|\wt{\bm{X}}\|_{TV}+\|t\|_{TV}} \leq e^{C_{\bm{X}}+T}.
\]
Hence, for any $\bm{\theta}_p, \bm{\eta}_p \in B_{p,r}$, the random variable
\[
Z_{\ell} := \ell_{(\wt{\bm{X}}, \bm{z}, y)}(\bm{\theta}_p) - \ell_{(\wt{\bm{X}}, \bm{z}, y)}(\bm{\eta}_p)
\]
is $C \|\bm{\theta}_p - \bm{\eta}_p\|$-subgaussian. By Hoeffding's lemma \citep{Levin:2016}, for all $\lambda \in \mathbb{R}$,
\[
\mathbb{E}\left[ \exp\left( \lambda (Z_{\ell} - \mathbb{E}[Z_{\ell}]) \right) \right] \leq \exp\left( \frac{\lambda^2 (2C \|\bm{\theta}_p - \bm{\eta}_p\|)^2}{8} \right).
\]
Define
\[
Z_{p,n}(\bm{\theta}_p) = \frac{1}{n} \sum_{i=1}^n \left(\ell_{(\wt{\bm{X}}_i, \bm{z}_i, y_i)}(\bm{\theta}_p) - \mathbb{E}[\ell_{(\wt{\bm{X}}_i, \bm{z}_i, y_i)}(\bm{\theta}_p)] \right).
\]
Then, by independence and applying the above subgaussianity to each summand,
\begin{align*}
\mathbb{E}\left[ \exp\left( \lambda (Z_{p,n}(\bm{\theta}_p) - Z_{p,n}(\bm{\eta}_p)) \right) \right]
&= \prod_{i=1}^n \mathbb{E}\left[ \exp\left( \frac{\lambda}{n} \left(Z_{\ell}^{(i)} - \mathbb{E}[Z_{\ell}^{(i)}] \right) \right) \right] \\
&\leq \exp\left( \frac{\lambda^2 C^2 \|\bm{\theta}_p - \bm{\eta}_p\|^2}{2n} \right) \\
&= \exp\left( \frac{\lambda^2 D(\bm{\theta}_p, \bm{\eta}_p)^2}{2} \right),
\end{align*}
where $D(\bm{\theta}_p, \bm{\eta}_p) = \frac{C}{\sqrt{n}} \|\bm{\theta}_p - \bm{\eta}_p\|$. Thus, the process $\big(Z_{p,n}(\bm{\theta}_p)\big)_{\bm{\theta}_p \in B_{p,r}}$ is subgaussian with respect to $D$.
\end{proof}

Now we derive a maximal tail inequality for the process $Z_{p,n}(\bm{\theta}_p)$.

\begin{proposition}\label{prop:A1} %% New prop 1
Under assumptions (A.2)–(A.3), for any $p \in \mathbb{N}$, $x > 0$, and any fixed $\bm{\theta}^0_p \in B_{p,r}$, the following bound holds:
\[
\mathbb{P}\left(\sup_{\bm{\theta}_p \in B_{p,r}} Z_{p,n}(\bm{\theta}_p) \geq 108 Cr \sqrt{\frac{s_d(p) + q}{n}} \sqrt{\pi} + Z_{p,n}(\bm{\theta}^0_p) + x \right) \leq 36 \exp\left(- \frac{x^2 n}{144 C^2 r^2} \right),
\]
where the constant $C$ is defined in equation~\emph{(\ref{eq:C})}.
\end{proposition}

\begin{proof}
By Lemma~\ref{lem:A3}, the process $\left(Z_{p,n}(\bm{\theta}_p)\right)_{\bm{\theta}_p \in B_{p,r}}$ is subgaussian with respect to the metric
\[
D(\bm{\theta}_p, \bm{\eta}_p) = \frac{C}{\sqrt{n}} \|\bm{\theta}_p - \bm{\eta}_p\|.
\]
Applying Theorem 5.29 of \citet{Levin:2016} to the process $Z_{p,n}$ over the metric space $(B_{p,r}; D)$ yields:
\[
\mathbb{P}\left( \sup_{\bm{\theta}_p \in B_{p,r}} Z_{p,n}(\bm{\theta}_p) - Z_{p,n}(\bm{\theta}^0_p) \geq C_0 \int_0^\infty \sqrt{\log N(\varepsilon, B_{p,r}, D)} \, \mathrm{d}\varepsilon + x \right) \leq C_0 \exp\left(- \frac{x^2}{C_0 \, \mathrm{diam}(B_{p,r})^2} \right),
\]
where we take the universal constant $C_0 = 36$ here, and $N(\varepsilon, B_{p,r}, D)$ denotes the $\varepsilon$-covering number of $B_{p,r}$ under the metric $D$. The diameter of $B_{p,r}$ with respect to $D$ satisfies:
\[
\mathrm{diam}(B_{p,r}) = \sup_{\bm{\theta}_p, \bm{\eta}_p \in B_{p,r}} D(\bm{\theta}_p, \bm{\eta}_p) = \frac{2Cr}{\sqrt{n}}.
\]
Using Lemma 5.13 of \citet{Levin:2016}, we relate the covering number under $D$ to that under the Euclidean norm:
\[
N(\varepsilon, B_{p,r}, D) = N\left( \frac{\sqrt{n}}{C} \varepsilon, B_{p,r}, \|\cdot\| \right),
\]
which implies
\[
N(\varepsilon, B_{p,r}, D) \leq \left( \frac{3Cr}{\sqrt{n} \varepsilon} \right)^{s_d(p) + q}, \quad \text{for } \varepsilon < \frac{Cr}{\sqrt{n}},
\]
and $N(\varepsilon, B_{p,r}, D) = 1$ otherwise. Consequently, the entropy integral can be bounded as follows:
\begin{align*}
\int_0^\infty \sqrt{\log N(\varepsilon, B_{p,r}, D)} \, \mathrm{d}\varepsilon 
&= \int_0^{\frac{Cr}{\sqrt{n}}} \sqrt{(s_d(p) + q) \log \left( \frac{3Cr}{\sqrt{n} \varepsilon} \right)} \, \mathrm{d}\varepsilon \\
&\leq 3Cr \sqrt{\frac{s_d(p) + q}{n}} \int_0^\infty 2x^2 e^{-x^2} \, \mathrm{d}x \\
&= 3Cr \sqrt{\frac{s_d(p) + q}{n}} \sqrt{\pi},
\end{align*}
where the second inequality follows from the change of variable $x = \sqrt{\log \left( \frac{2Cr}{\sqrt{n} \varepsilon} \right)}$.
Substituting back into the concentration inequality completes the proof.
\end{proof}

We now divide the proof of Theorem \ref{thm3} into two cases, as $\mathbb{P}(\widehat{p} \neq p^*) = \mathbb{P}(\widehat{p} > p^*) + \mathbb{P}(\widehat{p} < p^*)$. We first consider the case when $\widehat{p} > p^*$ in the following proposition.

\begin{proposition}\label{prop:A2}
    Let $0 < \rho < \frac{1}{2}$, and let $\mathrm{pen}_n(p, q)$ be defined as in Eq. (\ref{eq:penalty}). Let $n_1$ be the smallest integer satisfying
    \begin{equation}\label{eq:n1}
        n_1 \geq \left(\frac{432 \sqrt{\pi} C r \sqrt{s_d(p^* + 1) + q}}{C_{\mathrm{pen}} \sqrt{e^q} (\sqrt{s_d(p^* + 1)} - \sqrt{s_d(p^*)})}\right)^{\frac{1}{\frac{1}{2} - \rho}},
    \end{equation}
    Then, under assumptions (A.1)-(A.4), for any $p > p^*$ and $n \geq n_1$, we have
    \begin{equation}\label{eq:prob}
        \mathbb{P}(\widehat{p} = p) \leq 74 \exp\left(-c_0  \left(n^{1 - 2\rho} + s_d(p)\right)\right),
    \end{equation}
    where
    \begin{equation}\label{eq:C3}
        c_0 = \frac{C_{\mathrm{pen}}^2 d^{p^* + 1}e^q}{256 r C \left(36 r C + 1\right) s_d(p^* + 1)}.
    \end{equation}
\end{proposition}

\begin{proof}
    Theorems \ref{thm1} and \ref{thm2} guarantee the existence of \( p^* \). We now define
    \[
    u_{p,n} = \frac{1}{2} \left( \mathrm{pen}_n(p,q) - \mathrm{pen}_n(p^*,q) \right) = \frac{C_{\mathrm{pen}}}{2} \sqrt{e^q} n^{-\rho} \left( \sqrt{s_d(p)} - \sqrt{s_d(p^*)} \right).
    \]
    Since \( p \mapsto \mathrm{pen}_n(p,q) \) is increasing in \( p \), it is clear that \( u_{p,n} > 0 \) for any \( p > p^* \). From Lemma 2 of \cite{ferm2022linear}, we have the following bound for any \( p > p^* \):
    \begin{equation}\label{eq:lemma2}
    \mathbb{P}(\widehat{p} = p) \leq \mathbb{P} \left( 2 \sup_{\bm{\theta}_p \in B_{p,r}} \left| \widehat{R}_{p,n}(\bm{\theta}_p) - R_p(\bm{\theta}_p) \right| \geq \mathrm{pen}_n(p,q) - \mathrm{pen}_n(p^*,q) \right).
    \end{equation}
    We now proceed with the following decomposition:
    \begin{align}
    \mathbb{P}(\widehat{p} = p) \leq & \mathbb{P} \left( \sup_{\bm{\theta}_p \in B_{p,r}} \left| Z_{p,n}(\bm{\theta}_p) \right| > u_{p,n} \right) \notag \\
    = & \mathbb{P} \left( \sup_{\bm{\theta}_p \in B_{p,r}} Z_{p,n}(\bm{\theta}_p) > u_{p,n} \right) + \mathbb{P} \left( \sup_{\bm{\theta}_p \in B_{p,r}} \left( - Z_{p,n}(\bm{\theta}_p) \right) > u_{p,n} \right), \label{eq:prop2_0}
    \end{align}
    where we focus on the first term of the inequality. The second term can be handled analogously, as Proposition \ref{prop:A1} remains valid when \( Z_{p,n}(\bm{\theta}_p) \) is replaced by \( -Z_{p,n}(\bm{\theta}_p) \). Let \( \bm{\theta}^0_p \) denote a fixed point within \( B_{p,r} \), to be specified later. Then, we have
    \begin{align}
    \mathbb{P} \left( \sup_{\bm{\theta}_p \in B_{p,r}} Z_{p,n}(\bm{\theta}_p) > u_{p,n} \right) 
    = & \mathbb{P} \left( \sup_{\bm{\theta}_p \in B_{p,r}} Z_{p,n}(\bm{\theta}_p) > u_{p,n}, Z_{p,n}(\bm{\theta}^0_p) \leq \frac{u_{p,n}}{2} \right) \notag \\
    & + \mathbb{P} \left( \sup_{\bm{\theta}_p \in B_{p,r}} Z_{p,n}(\bm{\theta}_p) > u_{p,n}, Z_{p,n}(\bm{\theta}^0_p) > \frac{u_{p,n}}{2} \right) \notag \\
    \leq & \mathbb{P} \left( \sup_{\bm{\theta}_p \in B_{p,r}} Z_{p,n}(\bm{\theta}_p) > \frac{u_{p,n}}{2} + Z_{p,n}(\bm{\theta}^0_p) \right) + \mathbb{P} \left( Z_{p,n}(\bm{\theta}^0_p) > \frac{u_{p,n}}{2} \right). \notag
    \end{align}
    We deal with each term separately. The first part is handled by Proposition \ref{prop:A1}. To ensure that the quantity \( \frac{u_{p,n}}{2} - 108 C r \sqrt{\frac{\pi (s_d(p) + q)}{n}} \) is positive, we compute
    \begin{align}
    \frac{u_{p,n}}{2} - 108 C r \sqrt{\frac{\pi (s_d(p) + q)}{n}} 
    = & \frac{C_{\mathrm{pen}}}{2} n^{-\rho} \sqrt{e^q} \left( \sqrt{s_d(p)} - \sqrt{s_d(p^*)} \right) - 108 C r \sqrt{\frac{\pi (s_d(p) + q)}{n}} \notag \\
    = & \frac{C_{\mathrm{pen}}}{2} n^{-\rho} \sqrt{e^q} \left( \sqrt{s_d(p)} - \sqrt{s_d(p^*)} \right) - 108 C r \sqrt{\frac{\pi (s_d(p) + q)}{n}} \notag \\
    = & \sqrt{s_d(p)} n^{-\rho} \sqrt{e^q} \frac{C_{\mathrm{pen}}}{2} \left( 1 - \sqrt{\frac{s_d(p^*)}{s_d(p)}} - \frac{2 \times 108 \sqrt{\pi (s_d(p) + q)} C r}{C_{\mathrm{pen}} \sqrt{e^q} \sqrt{s_d(p)}} n^{\rho - \frac{1}{2}} \right) \notag \\
    \geq & \sqrt{s_d(p)} n^{-\rho} \sqrt{e^q} \frac{C_{\mathrm{pen}}}{2} \left( 1 - \sqrt{\frac{s_d(p^*)}{s_d(p^* + 1)}} - \frac{216 \sqrt{\pi (s_d(p) + q)} C r}{C_{\mathrm{pen}} \sqrt{e^q} \sqrt{s_d(p^* + 1)}} n^{\rho - \frac{1}{2}} \right). \notag
    \end{align}
    Let $n_1 \in \mathbb{N}$ be such that
    \begin{equation}\notag
        1 - \sqrt{\frac{s_d(p^*)}{s_d(p^* + 1)}} - \frac{216 \sqrt{\pi (s_d(p) + q)} C r}{C_{\mathrm{pen}} \sqrt{e^{q}} \sqrt{s_d(p^* + 1)}} n_1^{\rho - \frac{1}{2}} > \frac{1}{2} \left( 1 - \sqrt{\frac{s_d(p^*)}{s_d(p^* + 1)}} \right),
    \end{equation}
    which implies
    \begin{equation}\notag
        n_1 > \left( \frac{432 \sqrt{\pi} C r \sqrt{s_d(p^* + 1) + q}}{C_{\mathrm{pen}} \sqrt{e^{q}} (\sqrt{s_d(p^* + 1)} - \sqrt{s_d(p^*)})} \right)^{\frac{1}{\frac{1}{2} - \rho}}.
    \end{equation}
    Then for any $n \geq n_1$, we have
    \begin{equation}\notag
        \frac{u_{p,n}}{2} - 108 C r \sqrt{\frac{\pi (s_d(p) + q)}{n}} \geq \sqrt{s_d(p)} n^{-\rho} \sqrt{e^{q}} \frac{C_{\mathrm{pen}}}{4} \left( 1 - \sqrt{\frac{s_d(p^*)}{s_d(p^* + 1)}} \right) > 0.
    \end{equation}
    Hence, applying Proposition \ref{prop:A1} to $x = \frac{u_{p,n}}{2} - 108 C r \sqrt{\frac{\pi (s_d(p) + q)}{n}}$, we obtain for $n \geq n_1$:
    \begin{align}
        \mathbb{P}\left( \sup_{\bm{\theta}_p \in B_{p,r}} Z_{p,n}(\bm{\theta}_p) > \frac{u_{p,n}}{2} + Z_{p,n}(\bm{\theta}^0_p) \right) & \leq 36 \exp\left( -\frac{n}{144 C^2 r^2} \left( \frac{u_{p,n}}{2} - 108 C r \sqrt{\frac{\pi s_d(p)}{n}} \right)^2 \right) \notag \\
        & \leq 36 \exp\left( -\frac{s_d(p) n^{1 - 2\rho} e^{q} C_{\mathrm{pen}}^2}{144 C^2 r^2 \times 16} \left( 1 - \sqrt{\frac{s_d(p^*)}{s_d(p^*+1)}} \right)^2 \right) \notag \\
        &= 36 \exp\left( -\kappa_1 s_d(p) n^{1 - 2\rho} \right), \label{eq:prop2_1}
    \end{align}
    where
    \[
        \kappa_1 = \frac{C_{\mathrm{pen}}^2e^q}{2304 C^2 r^2} \left( 1 - \sqrt{\frac{s_d(p^*)}{s_d(p^*+1)}} \right)^2.
    \]
    Now we turn to the second part of the inequality in Eq.~(\ref{eq:prop2_0}). Since \( |Z_{p,n}(\bm{\theta}^0_{p})| \leq C \| \bm{\theta}^0_p \| \), by Hoeffding's inequality, for \( n \geq n_1 \), we have:
    \begin{align}
        \mathbb{P}\left( Z_{p,n}(\bm{\theta}^0_p) > \frac{u_{p,n}}{2} \right) 
        & \leq \exp\left( -\frac{n u_{p,n}^2}{8 C \|\bm{\theta}^0_p\|} \right) \notag \\
        & = \exp\left( -\frac{n^{1 - 2\rho} e^{q} C_{\mathrm{pen}}^2 \left( \sqrt{s_d(p)} - \sqrt{s_d(p^*)} \right)^2}{32 C \|\bm{\theta}^0_p\|} \right) \notag \\
        & \leq \exp\left( -\frac{n^{1 - 2\rho} e^{q} C_{\mathrm{pen}}^2 s_d(p)}{32 C \|\bm{\theta}^0_p\|} \left( 1 - \sqrt{\frac{s_d(p^*)}{s_d(p^* + 1)}} \right)^2 \right) \notag \\
        & = \exp\left( -\kappa_2 n^{1 - 2\rho} s_d(p) \right), \label{eq:prop2_2}
    \end{align}
    where
    \[
        \kappa_2 = \frac{C_{\mathrm{pen}}^2e^q}{32 C \|\bm{\theta}^0_p\|} \left( 1 - \sqrt{\frac{s_d(p^*)}{s_d(p^* + 1)}} \right)^2.
    \]
    Combining Eqs.~(\ref{eq:prop2_1}) and (\ref{eq:prop2_2}), we obtain:
    \begin{align}
        \mathbb{P}\left( \sup_{\bm{\theta}_p \in B_{p,r}} Z_{p,n}(\bm{\theta}_p) > u_{p,n} \right) 
        & \leq 36 \exp\left( -\kappa_1  n^{1 - 2\rho}  s_d(p) \right) + \exp\left( -\kappa_2  n^{1 - 2\rho} s_d(p) \right) \notag \\
        & \leq 37 \exp\left( -\kappa_3  n^{1 - 2\rho}  s_d(p) \right) \notag \\
        & \leq 37 \exp\left( -\frac{\kappa_3}{2}  \left( n^{1 - 2\rho} + s_d(p) \right) \right), \notag
    \end{align}
    where \( \kappa_3 = \min(\kappa_1, \kappa_2) \). The same proof works for the process \( -Z_{p,n}(\bm{\theta}_p) \), so we have:
    \[
        \mathbb{P}(\widehat{p} = p) \leq 2 \times 37 \exp\left( -\frac{\kappa_3}{2}  \left( n^{1 - 2\rho} + s_d(p) \right) \right).
    \]
    We are now left with the task of choosing an optimal \( \bm{\theta}^0_p \). Since
    \[
        \kappa_3 = \min(\kappa_1, \kappa_2) = \frac{C_{\mathrm{pen}}^2e^q}{32} \left( 1 - \sqrt{\frac{s_d(p^*)}{s_d(p^* + 1)}} \right)^2 \min \left( \frac{1}{72 C^2 r^2}, \frac{1}{C \|\bm{\theta}^0_p\|} \right),
    \]
    and since \( \bm{\theta}^0_p \in B_{p,r} \), \( \|\bm{\theta}^0_p\| \leq r \), we have:
    \[
        \min \left( \frac{1}{72 C^2 r^2}, \frac{1}{C \|\bm{\theta}^0_p\|} \right) \geq \frac{1}{72 C^2 r^2 + C r}.
    \]
    Noting that
    \[
        \sqrt{s_d(p^* + 1)} - \sqrt{s_d(p^*)} = \sqrt{d^{p^* + 1} + s_d(p^*)} - \sqrt{s_d(p^*)} \geq \sqrt{\frac{d^{p^* + 1}}{2}},
    \]
    we define
    \[
        c_0 = \frac{1}{2} \times \frac{C_{\mathrm{pen}}^2 d^{p^* + 1}e^q}{64 s_d(p^* + 1) (72 C^2 r^2 + C r)},
    \]
    which completes the proof.
\end{proof}

Before we treat the case \( p < p^* \), we first need to establish a rate of convergence for \( \widehat{L_n} \), which can be obtained using similar arguments to those in the previous proof. The following proposition provides the result.

\begin{proposition}\label{prop:A3}
    For any \( \epsilon > 0 \), \( p \in \mathbb{N} \), let \( n_2 \in \mathbb{N} \) be the smallest integer such that
    \begin{equation}\label{eq:prop3_1}
        n_2 \geq \frac{432^2 C^2 \pi r^2 (s_d(p) + q)}{\varepsilon^2}.
    \end{equation}
    Then, for any \( n \geq n_2 \),
    \[
    \mathbb{P} \left( |\widehat{L_n}(p) - L(p)| > \varepsilon \right) \leq 74 \exp \left( - c_5 n \varepsilon^2 \right),
    \]
    where \( c_5 \) is defined as
    \begin{equation}\label{eq:prop3_2}
        c_5 = \frac{1}{8 r (288 C^2 r + C)}.
    \end{equation}
\end{proposition}

\begin{proof}
    By Lemma 1 of \cite{ferm2022linear}, we have the following inequality:
    \begin{equation}\label{eq:prop3}
        |\widehat{L}_n(p) - L(p)| \leq \sup_{\bm{\theta}_p \in B_{p,r}} | \widehat{R}_{p,n}(\bm{\theta}_p) - R_{p}(\bm{\theta}_p) |
    \end{equation}
    for any \( p \in \mathbb{N} \). Thus, we obtain the following probability bound:
    \[
    \mathbb{P} \left( |\widehat{L_n}(p) - L(p)| > \varepsilon \right) \leq \mathbb{P} \left( \sup_{\bm{\theta}_p \in B_{p,r}} |Z_{p,n}(\bm{\theta}_p)| > \varepsilon \right) = \mathbb{P} \left( \sup_{\bm{\theta}_p \in B_{p,r}} Z_{p,n}(\bm{\theta}_p) > \varepsilon \right) + \mathbb{P} \left( \sup_{\bm{\theta}_p \in B_{p,r}} (-Z_{p,n}(\bm{\theta}_p)) > \varepsilon \right).
    \]
    Fix \( \bm{\theta}^0_p \in B_{p,r} \). For \( n \geq n_2 \), we have
    \[
    \frac{\varepsilon}{2} - 108 C r \sqrt{\frac{\pi (s_d(p) + q)}{n}} > \frac{\varepsilon}{4} > 0.
    \]
    Using Proposition~\ref{prop:A1} and Proposition~\ref{prop:A2}, we get the following bounds:
    \begin{align}
        \mathbb{P} \left( \sup_{\bm{\theta}_p \in B_{p,r}} Z_{p,n}(\bm{\theta}_p) > \varepsilon \right)
        &\leq \mathbb{P} \left( \sup_{\bm{\theta}_p \in B_{p,r}} Z_{p,n}(\bm{\theta}_p) > \frac{\varepsilon}{2} + Z_{p,n}(\bm{\theta}^0_p) \right) + \mathbb{P} \left( Z_{p,n}(\bm{\theta}^0_p) > \frac{\varepsilon}{2} \right) \notag \\
        &\leq 36 \exp \left( - \frac{n \left( \frac{\varepsilon}{2} - 108 C r \sqrt{\frac{\pi (s_d(p) + q)}{n}} \right)^2}{144 C^2 r^2} \right) + \exp \left( - \frac{n \varepsilon^2}{8 C \|\bm{\theta}^0_p\|} \right) \notag \\
        &\leq 36 \exp \left( - \frac{n \varepsilon^2}{2304 C^2 r^2} \right) + \exp \left( - \frac{n \varepsilon^2}{8 C \|\bm{\theta}^0_p\|} \right) \notag \\
        &\leq 37 \exp \left( - \kappa_4 n \varepsilon^2 \right), \notag
    \end{align}
    where
    \[
    \kappa_4 = \min \left( \frac{1}{2304 C^2 r}, \frac{1}{8 C \|\bm{\theta}^0_p\|} \right) \geq \frac{1}{2304 C^2 r^2 + 8 C r} = c_5.
    \]
    A similar analysis applies to \( (-Z_{p,n}(\bm{\theta}_p)) \), so we have
    \[
    \mathbb{P} \left( |\widehat{L_n}(p) - L(p)| > \varepsilon \right) \leq 74 \exp \left( - \kappa_4 n \varepsilon^2 \right) \leq 74 \exp \left( - c_5 n \varepsilon^2 \right),
    \]
    which completes the proof.
\end{proof}

We are now ready to address the case where \( p < p^* \).
\begin{proposition}\label{prop:A4}
Let \( 0 < \rho < \frac{1}{2} \), and let \(\operatorname{pen}_n(p, q)\) be defined as in~\eqref{eq:penalty}. Define \(n_3\) as the smallest integer satisfying
\begin{equation}\label{eq:n3}
    n_3 \geq \left( \frac{2 \sqrt{s_d(p^*) + q}}{L(p^*-1) - \widetilde{\mathcal{R}}^*} 
    \left( \sqrt{e^q} C_{\mathrm{pen}} + 432 C r \sqrt{\pi} \right) \right)^{1/\rho}.
\end{equation}
Then, under Assumptions~(A.1)--(A.4), for any \(p < p^*\) and \(n \geq n_3\), we have
\[
\mathbb{P}(\widehat{p} = p) \leq 148 \exp\left( - n \frac{c_5}{4} \left( L(p) - L(p^*) - \operatorname{pen}_n(p^*, q) + \operatorname{pen}_n(p, q) \right)^2 \right),
\]
where \(c_5\) is defined in~\eqref{eq:prop3_2}.
\end{proposition}

\begin{proof}
This result follows from Proposition~\ref{prop:A3}. For any \(p < p^*\),
\begin{align}
    \mathbb{P}(\widehat{p} = p)
    &\leq \mathbb{P}\left( \widehat{L}_n(p) - \widehat{L}_n(p^*) \leq \operatorname{pen}_n(p^*, q) - \operatorname{pen}_n(p, q) \right) \notag \\
    &= \mathbb{P}\left( \widehat{L}_n(p^*) - L(p^*) + L(p) - \widehat{L}_n(p) 
    \geq L(p) - L(p^*) - \left( \operatorname{pen}_n(p^*, q) - \operatorname{pen}_n(p, q) \right) \right) \notag \\
    &\leq \mathbb{P}\left( \left| \widehat{L}_n(p) - L(p) \right| \geq \frac{1}{2} \Delta(p) \right) 
    + \mathbb{P}\left( \left| \widehat{L}_n(p^*) - L(p^*) \right| \geq \frac{1}{2} \Delta(p) \right), \notag
\end{align}
where we define
\[
\Delta(p) := L(p) - L(p^*) - \operatorname{pen}_n(p^*, q) + \operatorname{pen}_n(p, q).
\]

To apply Proposition~\ref{prop:A3}, we must ensure that \(\Delta(p) > 0\). Since \(p \mapsto L(p)\) is decreasing and achieves its minimum at \(p = p^*\), and is bounded below by \(\widetilde{\mathcal{R}}^*\) (see Theorem~\ref{thm2}), and since \(p \mapsto \operatorname{pen}_n(p, q)\) is strictly increasing, it follows that for \(p < p^*\),
\[
\Delta(p) > L(p^* - 1) - \widetilde{\mathcal{R}}^* - \sqrt{e^q} C_{\mathrm{pen}} n^{-\rho} \sqrt{s_d(p^*)}.
\]
Thus, a sufficient condition to ensure \(\Delta(p) > 0\) is
\begin{equation}\label{eq:prop4_1}
    L(p^* - 1) - \widetilde{\mathcal{R}}^* - \sqrt{e^q} C_{\mathrm{pen}} n^{-\rho} \sqrt{s_d(p^*)} 
    > \frac{1}{2}\left( L(p^* - 1) - \widetilde{\mathcal{R}}^* \right),
\end{equation}
which leads to the requirement
\[
n_3 \geq \left( \frac{2 \sqrt{e^q} C_{\mathrm{pen}} \sqrt{s_d(p^*)}}{L(p^*-1) - \widetilde{\mathcal{R}}^*} \right)^{1/\rho}.
\]

In addition, to apply Proposition~\ref{prop:A3}, \(n_3\) must also satisfy the condition~\eqref{eq:prop3_1}, which states:
\[
n_3 \geq \frac{432^2 C^2 \pi r^2 (s_d(p) + q)}{\left( \Delta(p) \right)^2}.
\]
To upper bound this quantity uniformly over all \(p < p^*\), note that
\begin{align}
    \frac{432^2 C^2 \pi r^2 (s_d(p) + q)}{\left( \Delta(p) \right)^2}
    &\leq \frac{4 \times 432^2 C^2 \pi r^2 (s_d(p^*) + q)}{\left( L(p^* - 1) - \widetilde{\mathcal{R}}^* \right)^2} \notag \\
    &= \left( \frac{2 \times 432 C r \sqrt{\pi (s_d(p^*) + q)}}{L(p^* - 1) - \widetilde{\mathcal{R}}^*} \right)^2. \notag
\end{align}

Hence, combining both constraints and using that \(\rho < \frac{1}{2}\), it suffices to take
\[
n_3 \geq \left( \max\left\{ 
\frac{2 \sqrt{e^q} C_{\mathrm{pen}} \sqrt{s_d(p^*)}}{L(p^* - 1) - \widetilde{\mathcal{R}}^*}, 
\frac{2 \times 432 C r \sqrt{\pi (s_d(p^*) + q)}}{L(p^* - 1) - \widetilde{\mathcal{R}}^*} 
\right\} \right)^{1/\rho}.
\]
This can be compactly written as
\[
n_3 \geq \left( \frac{2 \sqrt{s_d(p^*) + q}}{L(p^*-1) - \widetilde{\mathcal{R}}^*} 
\left( \sqrt{e^q} C_{\mathrm{pen}} + 432 C r \sqrt{\pi} \right) \right)^{1/\rho},
\]
which completes the proof.
\end{proof}

Now we are in a position to prove Theorem \ref{thm3}.\\
\begin{proof}
The result follows by combining Propositions~\ref{prop:A2} and~\ref{prop:A4}. To ensure their applicability, we must verify that the sample size \(n\) satisfies the bounds in equations~\eqref{eq:n1} and~\eqref{eq:n3}. Define
\[
M = \max\left\{
\left(
\frac{432 \sqrt{\pi} C r \sqrt{s_d(p^* + 1) + q}}{C_{\mathrm{pen}} \sqrt{e^q} \left( \sqrt{s_d(p^* + 1)} - \sqrt{s_d(p^*)} \right)}
\right)^{\frac{1}{\frac{1}{2} - \rho}},
\left(
\frac{2 \sqrt{s_d(p^*) + q}}{L(p^* - 1) - \widetilde{\mathcal{R}}^*} \left( \sqrt{e^q} C_{\mathrm{pen}} + 432 C r \sqrt{\pi} \right)
\right)^{\frac{1}{\rho}}
\right\}.
\]
Let \(\tilde{\rho} := \min\left(\rho, \frac{1}{2} - \rho\right)\). Then, a crude bound on \(M\) is given by:
\begin{align*}
M &\leq \left( 432 C r \sqrt{\pi} + \sqrt{e^q} C_{\mathrm{pen}} \right) \sqrt{s_d(p^* + 1) + q} \\
&\qquad \times \max\left\{
\frac{2}{L(p^* - 1) - \widetilde{\mathcal{R}}^*},
\frac{1}{C_{\mathrm{pen}} \sqrt{e^q} \left( \sqrt{s_d(p^* + 1)} - \sqrt{s_d(p^*)} \right)}
\right\}^{\frac{1}{\tilde{\rho}}} \\
&\leq \left( 432 C r \sqrt{\pi} + \sqrt{e^q} C_{\mathrm{pen}} \right) \sqrt{s_d(p^* + 1) + q} \left(
\frac{2}{L(p^* - 1) - \widetilde{\mathcal{R}}^*} +
\frac{\sqrt{2}}{C_{\mathrm{pen}} \sqrt{e^q} \sqrt{d^{p^* + 1}}}
\right)^{\frac{1}{\tilde{\rho}}}.
\end{align*}
We now analyze the error probability:
\[
\mathbb{P}(\widehat{p} \neq p^*) = \mathbb{P}(\widehat{p} > p^*) + \mathbb{P}(\widehat{p} < p^*) \leq \sum_{p > p^*} \mathbb{P}(\widehat{p} = p) + \sum_{p < p^*} \mathbb{P}(\widehat{p} = p).
\]
For the overestimation term, Proposition~\ref{prop:A2} implies that for all \(n \geq n_a\),
\[
\sum_{p > p^*} \mathbb{P}(\widehat{p} = p) \leq 74 e^{-c_0  n^{1 - 2\rho}} \sum_{p > p^*} e^{-c_0 s_d(p)}.
\]
For the underestimation term, Proposition~\ref{prop:A4} yields:
\begin{align*}
\sum_{p < p^*} \mathbb{P}(\widehat{p} = p)
&\leq 148 \sum_{p = 0}^{p^* - 1} \exp\left( - \frac{c_5}{4} n \left( L(p) - L(p^*) - \operatorname{pen}_n(p^*, q) + \operatorname{pen}_n(p, q) \right)^2 \right) \\
&\leq 148 p^* \exp\left( - \frac{c_5}{16} n \left( L(p^* - 1) - \widetilde{\mathcal{R}}^* \right)^2 \right),
\end{align*}
where we have used that for \(n \geq n_a\), condition~\eqref{eq:prop4_1} holds. Define
\[
\kappa_5 := \min\left( c_0, \frac{c_5 \left( L(p^* - 1) - \widetilde{\mathcal{R}}^* \right)^2}{16} \right).
\]
Then, the total error probability satisfies
\[
\mathbb{P}(\widehat{p} \neq p^*) \leq 74 e^{-\kappa_5  n^{1 - 2\rho}} \sum_{p > 0} e^{-c_0 s_d(p)} + 148 p^* e^{-\kappa_5 n} \leq c_1 e^{-\kappa_5 n^{1 - 2\rho}},
\]
where we define
\[
c_1 := 74 \sum_{p > 0} e^{-c_0s_d(p)} + 148 p^*.
\]
To conclude, we derive a lower bound on \(\kappa_5\):
\begin{align}
\kappa_5 &= \min\left( c_0 , \frac{c_5 \left( L(p^* - 1) - \widetilde{\mathcal{R}}^* \right)^2}{16} \right) \notag\\
&= \min\left( \frac{ C_{\mathrm{pen}}^2 d^{p^* + 1}e^q}{128 s_d(p^* + 1)(72 C^2 r^2 + C r)},
\frac{\left( L(p^* - 1) - \widetilde{\mathcal{R}}^* \right)^2}{128 r(288 C^2 r + C)} \right) \notag\\
&\geq \frac{1}{128 r (72 C^2 r + C)} \min\left( \frac{ C_{\mathrm{pen}}^2 d^{p^* + 1}e^q}{s_d(p^* + 1)},
\frac{\left( L(p^* - 1) - \widetilde{\mathcal{R}}^* \right)^2}{4} \right) =: c_2.\label{eq:k5_c2}
\end{align}
This completes the proof.
\end{proof}

\section{Proof of Theorem \ref{thm4}}
\label{app:thm4}
\begin{proof}
We proceed to bound the excess risk of the selected model $\widehat{p}$ relative to the oracle model $p^*$. Almost surely, we have
\begin{align}
    \mathcal{R}_{\widehat{p}}(\widehat{\bm{\theta}}_{\widehat{p}}) - \mathcal{R}_{p^*}(\bm{\theta}_{p^*}^*) 
    &= \mathcal{R}_{\widehat{p}}(\widehat{\bm{\theta}}_{\widehat{p}}) - \mathcal{R}_{\widehat{p}}(\bm{\theta}_{\widehat{p}}^*) + \mathcal{R}_{\widehat{p}}(\bm{\theta}_{\widehat{p}}^*) - \mathcal{R}_{p^*}(\bm{\theta}_{p^*}^*) \notag \\
    &= \mathcal{R}_{\widehat{p}}(\widehat{\bm{\theta}}_{\widehat{p}}) - \widehat{\mathcal{R}}_{\widehat{p},n}(\widehat{\bm{\theta}}_{\widehat{p}}) 
    + \widehat{\mathcal{R}}_{\widehat{p},n}(\widehat{\bm{\theta}}_{\widehat{p}}) - \widehat{\mathcal{R}}_{\widehat{p},n}(\bm{\theta}_{\widehat{p}}^*) \notag \\
    &\quad + \widehat{\mathcal{R}}_{\widehat{p},n}(\bm{\theta}_{\widehat{p}}^*) - \mathcal{R}_{\widehat{p}}(\bm{\theta}_{\widehat{p}}^*) + \mathcal{R}_{\widehat{p}}(\bm{\theta}_{\widehat{p}}^*) - \mathcal{R}_{p^*}(\bm{\theta}_{p^*}^*) \notag \\
    &\leq \mathcal{R}_{\widehat{p}}(\widehat{\bm{\theta}}_{\widehat{p}}) - \widehat{\mathcal{R}}_{\widehat{p},n}(\widehat{\bm{\theta}}_{\widehat{p}}) 
    + \widehat{\mathcal{R}}_{\widehat{p},n}(\bm{\theta}_{\widehat{p}}^*) - \mathcal{R}_{\widehat{p}}(\bm{\theta}_{\widehat{p}}^*) 
    + \mathcal{R}_{\widehat{p}}(\bm{\theta}_{\widehat{p}}^*) - \mathcal{R}_{p^*}(\bm{\theta}_{p^*}^*) \notag \\
    &\leq 2 \sup_{\bm{\theta}_{\widehat{p}} \in B_{\widehat{p},r}} \left| \widehat{\mathcal{R}}_{\widehat{p},n}(\bm{\theta}_{\widehat{p}}) - \mathcal{R}_{\widehat{p}}(\bm{\theta}_{\widehat{p}}) \right| 
    + \mathcal{R}_{\widehat{p}}(\bm{\theta}_{\widehat{p}}^*) - \mathcal{R}_{p^*}(\bm{\theta}_{p^*}^*). \label{eq:thm4_bound}
\end{align}

We now bound the expected value of each term in \eqref{eq:thm4_bound}. For the first term, by Corollary 5.25 in \citet{Levin:2016} and Proposition~\ref{prop:A1}, for any $p \in \mathbb{N}$,
\[
\mathbb{E}\left[\sup_{\bm{\theta}_p \in B_{p,r}} \left| \widehat{\mathcal{R}}_{p,n}(\bm{\theta}_p) - \mathcal{R}_{p}(\bm{\theta}_p) \right| \right] 
\leq 12 \int_{0}^{\infty} \sqrt{\log N(\varepsilon, B_{p,r}, D)}\, d\varepsilon 
\leq 36 C r \sqrt{s_d(p) + q} \sqrt{\frac{\pi}{n}},
\]
where $N(\varepsilon, B_{p,r}, D)$ denotes the $\varepsilon$-covering number with respect to the distance $D$, defined by \eqref{eq:D}. Applying this with $p = \widehat{p}$ yields
\[
\mathbb{E}\left[\sup_{\bm{\theta}_{\widehat{p}} \in B_{\widehat{p},r}} \left| \widehat{\mathcal{R}}_{\widehat{p},n}(\bm{\theta}_{\widehat{p}}) - \mathcal{R}_{\widehat{p}}(\bm{\theta}_{\widehat{p}}) \right| \right] 
\leq 36 C r \sqrt{\frac{\pi}{n}} \, \mathbb{E}\left[\sqrt{s_d(\widehat{p}) + q}\right].
\]
To bound this expectation, Proposition~\ref{prop:A2} implies
\begin{align*}
    \mathbb{E}\left[\sqrt{s_d(\widehat{p}) + q}\right] 
    &= \sum_{p \leq p^*} \sqrt{s_d(p) + q} \, \mathbb{P}(\widehat{p} = p) 
    + \sum_{p > p^*} \sqrt{s_d(p) + q} \, \mathbb{P}(\widehat{p} = p) \\
    &\leq (p^* + 1) \sqrt{s_d(p^*) + q} 
    + \sum_{p > p^*} 74 \sqrt{s_d(p) + q} \, \exp\left(-c_0  (n^{1 - 2\rho} + s_d(p))\right) \\
    &\leq (p^* + 1) \sqrt{s_d(p^*) + q} 
    + e^{-c_0 n^{1 - 2\rho}} \sum_{p > p^*} 74 \sqrt{s_d(p) + q} \, \exp(-c_0  s_d(p)),
\end{align*}
with \eqref{eq:k5_c2}, $c_2 \leq c_0$,  we have 
\begin{align*}
    \mathbb{E}\left[\sup_{\bm{\theta}_{\widehat{p}} \in B_{\widehat{p},r}} \left| \widehat{\mathcal{R}}_{\widehat{p},n}(\bm{\theta}_{\widehat{p}}) - \mathcal{R}_{\widehat{p}}(\bm{\theta}_{\widehat{p}}) \right| \right] 
    &\leq 36 C r \sqrt{\frac{\pi}{n}} \,  (p^* + 1) \sqrt{s_d(p^*) + q} 
    \\
    &\quad + 36 C r \sqrt{\frac{\pi}{n}} \, e^{-c_2 n^{1 - 2\rho}} \sum_{p > p^*} 74 \sqrt{s_d(p) + q} \, \exp(-c_0  s_d(p))
\end{align*}
Now for the second term in \eqref{eq:thm4_bound}, we use the uniform upper bound for the non-negative logistic risk
\[
\mathbb{E}[\mathcal{R}_p(\bm{\theta}_p)] 
=  \mathbb{E}\left[Y \langle \bm{\theta}_p, \widetilde{S}_{p} \rangle + \log(1 + e^{\langle \bm{\theta}_p, \widetilde{S}_{p} \rangle}) \right]  
\leq \log 2 + |\langle \bm{\theta}_p, \widetilde{S}_{p} \rangle|\leq \log 2 + r(C_z + e^{C_X+T}) = \log 2+rC,
\]
from which it follows that
\[
 0\leq\mathbb{E}[\mathcal{R}_{\widehat{p}}(\bm{\theta}_{\widehat{p}}^*) - \mathcal{R}_{p^*}(\bm{\theta}_{p^*}^*)] 
\leq (\log2+rC) \, \mathbb{P}(\widehat{p} \neq p^*).
\]
Note that $\mathcal{R}_{p^*}(\bm{\theta}_{p^*}^*)$ corresponds to the risk-minimizing oracle model. Applying Theorem~\ref{thm3}, we obtain
\[
 0\leq\mathbb{E}[\mathcal{R}_{\widehat{p}}(\bm{\theta}_{\widehat{p}}^*) - \mathcal{R}_{p^*}(\bm{\theta}_{p^*}^*)] 
\leq (\log2+rC)  c_1  \, e^{-c_2 n^{1 - 2\rho}}.
\]
Combining the above bounds yields
\[
\left| \mathbb{E}[\mc{R}_{\widehat{p}}(\widehat{\bm{\theta}}_{\widehat{p}})] - \mc{R}_{p^*}(\bm{\theta}_{p^*}^*) \right| 
\leq \frac{c_3}{\sqrt{n}} + c_4  e^{-c_2  n^{1 - 2\rho}},
\]
where the constants are defined as
\begin{equation} \label{eq:C5C6}
    c_3 = 36 C r \sqrt{\pi} (p^* + 1) \sqrt{s_d(p^*) + q}, \quad
c_4 = rC \left(2664 \sqrt{\pi} \sum_{p > p^*} \sqrt{s_d(p) + q} \, e^{-c_0  s_d(p)}+c_1\right) + c_1 \log 2,
\end{equation}
Applying Theorem \ref{thm1}, we obtain
\[
\left| \mathbb{E}[\mc{R}_{\widehat{p}}(\widehat{\bm{\theta}}_{\widehat{p}})] - \mc{R}^* \right| 
\leq \frac{c_3}{\sqrt{n}} +  c_4  e^{-c_2  n^{1 - 2\rho}}.
\]
\end{proof}

