\title{Hardware-efficient tractable probabilistic inference for TinyML Neurosymbolic AI applications}

\author{
\IEEEauthorblockN{Jelin Leslin\IEEEauthorrefmark{1}, Martin Trapp\IEEEauthorrefmark{2}, Martin Andraud\IEEEauthorrefmark{1}\IEEEauthorrefmark{3}}
 \IEEEauthorblockA{\IEEEauthorrefmark{1}\small Aalto University, Department of Electronics and Nanoengineering~~\{firstname.lastname\}@aalto.fi}
