%\label{sec:3.4.2}


Taking into account the finite propagation speed that characterizes
the solutions of the wave equation, or, more precisely, the
``Huygens-principle'' Condition~\ref{huygens-conj} introduced in
Section~\ref{sec:2.2}, we propose to produce the solution of the
original problem (\ref{waveeqn0}) in the interior domain $D$ as the
sum of wave-equation solutions multiply scattered by the arcs
$\Gamma_j, j=1,\cdots,N$. We thus consider the wave equation problems
exterior to each arc $\Gamma_j$, $j=1,\cdots,N$,
\begin{eqnarray}
\label{waveeqn-Gj2}
\begin{cases}
\pa_t^2u_j(x,t)-c^2\Delta u_j(x,t)=0, & (x,t)\in \Gamma_j^\mathrm{c}\times\R, \cr
u_j(x,t)= f_j(x,t),  & (x,t)\in\Gamma_j\times\R,
\end{cases}
\end{eqnarray}
where $\Gamma_j^\mathrm{c}=\R^2\backslash\Gamma_j$. Theorem~\ref{welltime}
tells us that, for given $p\in\R$, $\sigma>0$, $\alpha\ge0$ and for
$f_j\in H_{\sigma,\alpha}^p(\R,H^{1/2}(\Gamma_j))$, the wave equation
problem \eqref{waveeqn-Gj2} admits a unique solution
$u_j\in H_{\sigma,\alpha}^{p-3}(\R,H_{loc}^1(\Gamma_j^c))$. The
following lemma, whose proof is straightforward, expresses the
Condition~\ref{huygens-conj} in terms related to the curve
$\mathcal C = \Gamma_j$ in~(\ref{waveeqn-Gj2}) and the complete
boundary $\Gamma$---and thus presents that Huygens condition in
the form in which it will be used in the proof of
Theorem~\ref{equivalence-int}.
\begin{lemma}
\label{localpro}
Let $p\in\R$, $\sigma>0$ and $T_0>0$, and assume that, for all
$j=1,\cdots,N$,
\begin{itemize}
\item[(a)] $f_j\in H_{\sigma,T_0}^{p}(\R,H^{1/2}(\Gamma_j))$ satisfies
    \begin{equation}\label{ini_set}
    f_j(x,t)=0\quad\mbox{for}\quad (x,t)\in\Gamma_{j}^0\times \R;
    \end{equation}
\item[(b)] $\Gamma_j$ satisfies Condition~\ref{huygens-conj}.
\end{itemize}
Then, letting $t_0=\delta_{\mathrm{min}}/c>0$, and
calling $u_j\in H_{\sigma,T_0}^{p-3}(\R,H_{loc}^1(\Gamma_j^c))$ the unique solution of the wave equation problem \eqref{waveeqn-Gj2}, we have
\begin{equation}\label{ini_set_res}
u_j(x,t)=0\quad\mbox{for}\quad
  (x,t)\in (\Gamma\backslash\Gamma_j) \times (-\infty,T_0+t_0].
\end{equation}
\end{lemma}

To describe the proposed multiple-scattering scheme, we use the
notational conventions 
\be\label{sum_conv}
\sum_{k\backslash \{j\}}:=\sum_{k=1, k\ne
  j}^N\qquad\mbox{and} \qquad \sum_{k\backslash\{j,j+1\}}:=\sum_{k=1,
  k\ne j, k\ne (j+1)}^N, 
\en 
and, for $j=1,\cdots,N$, we inductively
define boundary-condition functions $g_{j,m}(x,t)$ ($m\geq 1$) and
associated wave-equation solutions $v_{j,m}(x,t)$ ($m\geq 1$) to the
problems (\ref{waveeqn-Gj2}) as detailed in what follows.

\begin{definition}\label{inductive_int}
  For $m\in\mathbb{N}$, we define $v_{j,m}(x,t)$ to equal
  the solution $u_j(x,t)$ of the wave equation
  problem~(\ref{waveeqn-Gj2}) with boundary-condition function
  $f_j = g_{j,m}$---so that $v_{j,m}$ satisfies the boundary
  conditions
\begin{equation}\label{bdry_int}
v_{j,m}(x,t) = g_{j,m}(x,t)\quad \mbox{for}\quad (x,t)\in \Gamma_j\times \R,\quad m \in\mathbb{N},
\end{equation}
for all $j=1,\cdots,N$, where
$g_{j,m}(x,t):\Gamma_{j}\times \R\to\mathbb{C}$ denotes the causal
functions defined inductively via the relations
\begin{equation}
  \label{criterion_int1}
  g_{j,1}(x,t)= -\chi_j(x)u^i(x,t)\quad (x,t)\in \Gamma_j\times \R,
\end{equation}
and, for $m\ge 1$,
\begin{equation}
  \label{criterion_int2}
  g_{j,m+1}(x,t)=-\chi_j(x) \sum_{k\backslash \{j\}}\widetilde v_{k,j,m}(x,t), \quad (x,t)\in  \Gamma_j\times \R.
\end{equation}
Here, for $j=1,\dots,N$, $(x,t)\in\Gamma_{j}\times \R$,
$k=1,\cdots,N, k\ne j$, and $m\ge 1$, $\widetilde v_{k,j,m}(x,t)$ denotes
the function
\begin{equation}\label{vtilde}
  \widetilde v_{k,j,m}(x,t)=
\begin{cases}
v_{k,m}(x,t), & x\in\Gamma_j, k\notin\{j-1, j+1\}  ,\cr
v_{k,m}(x,t), & x\in\Gamma_j\backslash \Gamma_k, k=j-1\; \mathrm{and}\; k=j+1  , \cr
0, & x\in\Gamma_{j-1,j}^{\mathrm{ov}}, k=j-1, \cr
0, & x\in\Gamma_{j,j+1}^{\mathrm{ov}}, k=j+1.
\end{cases}
\end{equation}
\end{definition}

\begin{remark}
\label{remarkg}
  The definition of the windowing function $\chi_j$ ($j=1,\cdots,N$)
  ensures that
  \be
\label{vanishing}
g_{j,m}(x,t)=0\quad \mbox{for}\quad (x,t)\in \Gamma_{j}^0\times
\R,\quad j=1,\cdots,N,\;m \in\mathbb{N}, \en which is a crucial
property in the proposed multiple scattering algorithm---in that it
ensures that the solution of the problem of scattering by the open arc
$\Gamma_j$ with boundary conditions given by the incident field
$g_{j,m}$ coincides, at least for a certain time interval, with the
solution of the problem of scattering by the complete surface
$\Gamma$, with incident field equal to $g_{j,m}$ for $x\in \Gamma$.
Moreover, the function $g_{j,m}(x,t)$ is continuous and vanishes at
the endpoints of $\Gamma_j^{\mathrm{tov}}$, despite the seemingly
discontinuous nature of the closely related definition~\eqref{vtilde}
at those points. The claimed continuity of $g_{j,m}(x,t)$ holds since,
for $m \geq 2$ and $k = j\pm 1$, $g_{k,m}(x,t)$ is continuous and
vanishes at the endpoints of $\Gamma_j^{\mathrm{tov}}$ for all
$t \in \mathbb{R}$ (as it follows from the
definitions~\eqref{criterion_int1}--\eqref{criterion_int2} with
$j=k$), which implies that $v_{k,m}$, and, thus,
$\widetilde{v}_{k,j,m}(x,t)$, tend to zero, for all
$t \in \mathbb{R}$, as $x$ approaches the endpoints of
$\Gamma_j^{\mathrm{tov}}$.
\end{remark}

We now consider the $M\times N$-th order multiple-scattering sum
\begin{equation}\label{mult-scatt-int}
  u_M(x,t):=\sum_{m=1}^M\sum_{j=1}^N
  v_{j,m}(x,t),
\end{equation}
which includes contributions from all $M\times N$ ``ping-pong''
scattering iterates $v_{j,m}(x,t)$ with $j=1,\cdots,N$,
$m=1,\dots, M$. Theorem~\ref{equivalence-int} below establishes that,
throughout $D$, the multiple-scattering sum $u_M$ coincides with the
exact solution $u$ of the original wave equation problem
(\ref{waveeqn0}) for $t\leq T(M)$, where, for $M\in\mathbb{N}$ we
define
\begin{equation}
  \label{eq:TM}
  T(M) = M \delta_{\mathrm{min}}/c.
\end{equation}
The proof of Theorem~\ref{equivalence-int} relies on certain
relations, established in the following lemma, concerning the
solutions $v_{j,m}$ and the boundary value functions $g_{j,m}$
introduced in Definition~\ref{inductive_int}.
\begin{lemma}\label{localrels} With reference to
  equation~\eqref{eq:TM}, for each $M\in\mathbb{N}$ and each
  integer $j$, $1\leq j\leq N$, the relations
\begin{align}
&  v_{j,M}(x,t)+\sum_{m=1}^{M-1}\sum_{k=1}^N v_{k,m}(x,t)+u^i(x,t)=0, \quad (x,t)\in\Gamma_j^{\mathrm{tov}}\times \R,\label{A1}\\
& v_{j,M}(x,t)+v_{j\pm 1,M}(x,t)+\sum_{m=1}^{M-1}\sum_{k=1}^N v_{k,m}(x,t)+u^i(x,t)=0, \quad (x,t)\in\left(\Gamma_j\cap \Gamma_{j\pm 1}\right)\times \R,  \quad \mbox{and}\label{A2}\\
& g_{j,M}(x,t)=0,\quad (x,t)\in\Gamma_{j}\times (-\infty,T(M-1)]\phantom{\sum_{k=1}^N}\label{A3}
\end{align}
are satisfied.
\end{lemma}
\begin{proof} We establish~\eqref{A1} through~\eqref{A3} by induction
  in $M$. In the case $M=1$, \eqref{A1} follows directly
  from~\eqref{bdry_int} and~\eqref{criterion_int1};
  equation~\eqref{A2} results once again from~\eqref{bdry_int}
  and~\eqref{criterion_int1} together with~\eqref{eq:POU1}
  and~\eqref{eq:POU2}; and~\eqref{A3} follows
  from~\eqref{criterion_int1} since
  $u^i\in H_{\sigma,0}^{p}(\R,H^{1/2}(\pa D))$ and, thus, vanishes for
  $t\leq 0$ (Section~\ref{sec:2.3}). Having established~\eqref{A1}
  through~\eqref{A3} for $M=1$, the corresponding inductive steps are
  considered next.

  Let $L\in \mathbb{N}$ and assume~\eqref{A1} holds for $M= L$ and
  $1\leq j\leq N$. Then, the validity of~\eqref{A1} with $M=L+1$ is
  equivalent to the validity of the relation
  \begin{equation}
    \label{eq:A1diff1}
    v_{j,L+1}(x,t)+\sum_{k\backslash \{j\}} v_{k,L}(x,t) = 0,\quad (x,t)\in\Gamma_j^{\mathrm{tov}}\times \R,
  \end{equation}
  which results as the differnce between the $M = L+1$ and the $M=L$
  versions of~\eqref{A1}.  But, in view of~\eqref{bdry_int}
  and~\eqref{vtilde} and since $\chi_j(x) = 1$ for
  $x\in \Gamma_j^{\mathrm{tov}}$,~\eqref{eq:A1diff1} coincides
  with~\eqref{criterion_int2} for
  $(x,t)\in \Gamma_j^{\mathrm{tov}}\times\mathbb{R}$ and therefore
  holds true. The proof of~\eqref{A1} for $M\in\mathbb{N}$ is thus
  complete.

  We next consider the inductive step for~\eqref{A2} with a ``$+$''
  sign; the relation with a ``$-$'' sign follows similarly. Let us
  thus assume the $+$-sign version of~\eqref{A2} holds for $M = L$ for
  a given $L\in\mathbb{N}$ and for $1\leq j\leq N$. The validity of
  the $+$-sign version of~\eqref{A2} for $M = L+1$ is equivalent to
  the validity of the relation
  \begin{equation}
    \label{eq:A1diff}
    v_{j,L+1}+v_{j+1,L+1}+\sum_{k\backslash\{j,j+1\}}v_{k,L}(x,t)
    = 0,\quad (x,t)\in \Gamma_{j,j+1}^{\mathrm{ov}}\times \R,
 \end{equation}
 that results as the difference between the $M = L+1$ and the $M=L$
 $+$-sign relations. But, in view of~\eqref{bdry_int}
 and~\eqref{criterion_int2} and using the notations~\eqref{sum_conv}, the relation~\eqref{eq:A1diff} may be
 re-expressed in the form
 $-\chi_j(x) \sum_{k\backslash \{j\}}\widetilde v_{k,j,L}(x,t)
 -\chi_{j+1}(x) \sum_{k\backslash \{j+1\}}\widetilde
 v_{k,j+1,L}(x,t)+\sum_{k\backslash \{j,j+1\}}v_{k,L}(x,t) =
 0$. Using all four expressions in~\eqref{vtilde} for the case
 $x\in\Gamma_{j,j+1}^{\mathrm{ov}}$
 considered presently, in turn, the latter relation is equivalent to
 $-\chi_j(x) \sum_{k\backslash \{j,j+1\}} v_{k,j,L}(x,t)
 -\chi_{j+1}(x) \sum_{k\backslash \{j,j+1\}}
 v_{k,j+1,L}(x,t)+\sum_{k\backslash \{j,j+1\}}v_{k,L}(x,t) =
 0$---which clearly holds true in view of~ \eqref{eq:POU1}
 and~\eqref{eq:POU2}. The proof of~\eqref{A2} is thus complete.

 We finally consider the inductive step for~\eqref{A3}: assuming this
 relation holds for $M = L\in\mathbb{N}$ and for $1\leq j\leq N$, we
 seek to establish its $M=L+1$ version which, in view
 of~\eqref{criterion_int2}, may equivalently be expressed in the form
\begin{equation}
  \label{eq:A3Lp1}
  -\chi_j(x) \sum_{k\backslash \{j\}}\widetilde v_{k,j,L
  }(x,t) =0  \quad\mbox{on}\quad\Gamma_j\times (-\infty,T(L)].
\end{equation}
To establish~\eqref{eq:A3Lp1}, using~\eqref{bdry_int},~\eqref{vtilde}
and the inductive hypothesis we show that each term
$\widetilde v_{k,j,L}(x,t)$ in the sum~\eqref{eq:A3Lp1} vanishes for
$(x,t)\in \Gamma_j\times (-\infty,T(L)]$, and we do this for each
one of the two cases $k=j\pm 1$ and $k\ne j\pm1$. In the first case,
and restricting attention to the subcase $k=j+1$ (since the subcase
$k=j-1$ follows similarly) we see from~\eqref{vtilde} that
$\widetilde v_{j+1,j,L}(x,t)=0$ for
$(x,t)\in\Gamma_{j,j+1}^{\mathrm{ov}}\times\R$, and
$\widetilde v_{j+1,j,L}(x,t) = v_{j+1,L}(x,t)$ for
$(x,t)\in(\Gamma_j\setminus\Gamma_{j+1})\times\R$, so that, for the
$k=j+1$ subcase considered presently, it only remains to show that
$v_{j+1,L}(x,t) = 0$ for
$(x,t)\in(\Gamma_j\setminus\Gamma_{j+1})\times(-\infty,T(L)]$. But,
in view of~\eqref{bdry_int} we have
$v_{j+1,L}(x,t) = g_{j+1,L}(x,t)$ for
$(x,t)\in\Gamma_{j+1}\times\R$, and, thus (i)~$v_{j+1,L}(x,t)=0$ for
$(x,t)\in\Gamma_{j+1}\times(-\infty,T(L-1)]$ (since $g_{j+1,L}(x,t) = 0$
for $(x,t)\in\Gamma_{j+1}\times(-\infty,T(L-1)]$ by the $M=L$ inductive
hypothesis); and (ii)~ $v_{j+1,L}(x,t)=0$ for
$(x,t)\in\Gamma_{j+1}^{0}\times\R$ (since, on account of the
$\chi_{j+1}(x)$ factor in~\eqref{criterion_int2} we have
$g_{j+1,L}(x,t) = 0$ for
$(x,t)\in\Gamma_{j+1}^{0}\times\R$). The conclusions in the
points~(i) and~(ii) just considered enable us to invoke
Lemma~\ref{localpro} with $j$ replaced by $j+1$, and, thus, to
ascertain that $v_{j+1,L}(x,t)=0$ for
$(x,t)\in(\Gamma_j\setminus\Gamma_{j+1})\times(-\infty,T(L)]$---which
concludes the proof in the case $k=j\pm 1$. In the case $k\ne j\pm1$,
finally, by~\eqref{vtilde} we have
$\widetilde v_{k,j,L}(x,t)=v_{k,L}(x,t)$, and the proof follows by
invoking Lemma~\ref{localpro} once again, on the basis of the
inductive hypothesis (which tells us that
$v_{k,L}(x,t) = g_{k,L}(x,t) = 0$ for
$(x,t)\in\Gamma_k\times(-\infty,T(L-1)]$), together with the fact that
$\mathrm{dist}(\Gamma_k,\Gamma_j)\geq \delta_\mathrm{min}$, to
conclude that $\widetilde v_{k,j,L}(x,t) = v_{k,L}(x,t)=0$ for
$(x,t)\in\Gamma_j\times(-\infty,T(L)]$, as needed. The proof of the
lemma is now complete.
\end{proof}


\begin{theorem}
\label{equivalence-int}
Let $M\in\mathbb{N}$, $p\in\R$ and $\sigma>0$. Then, with reference to equation~\eqref{sum_conv}, for given
$u^i\in H_{\sigma,0}^{p}(\R,H^{1/2}(\Gamma))$ we have
$u_M \in H_{0}^{p-3/2}(T(M),H^1(D))$, and the solution $u$ of the
problem~\eqref{waveeqn} with $E=D$ (interior problem) is given by
\begin{equation}\label{thm_eqn}
  u(x,t) =u_M(x,t)\quad \mbox{for}\quad  (x,t)\in D\times (-\infty,T(M)].
\end{equation}
\end{theorem}
\begin{proof}
  The fact that $u_M \in H_{0}^{p-3/2}(T(M),H^1(D))$ follows as in the
  proof of \cite[Theorem 2.8]{BY23}. In view of the uniqueness of
  solution to equation~\eqref{waveeqn-Gj2}, to
  establish~\eqref{thm_eqn} it suffices to show that for all
  $M\in\mathbb{N}$, the function $u_M$ satisfies the boundary
  conditions
\begin{equation}\label{bound-int0}
u_M(x,t)+u^i(x,t)=0\quad\mbox{for}\quad (x,t)\in\Gamma\times (-\infty,T(M)],
\end{equation}
or, equivalently, since $\Gamma = \cup_{j=1}^N \Gamma_j$, that
\begin{equation}\label{bound-int0j}
u_M(x,t)+u^i(x,t)=0\;\mbox{ for }\; (x,t)\in\Gamma_j\times (-\infty,T(M)]\;\mbox{ and }\; 1\leq j\leq N.
\end{equation}
Noting that
\begin{equation}\label{mult-scatt-int_Lp1}
u_M(x,t)=  \sum_{k=1}^N v_{k,M}(x,t) + \sum_{m=1}^{M-1}\sum_{k=1}^N v_{k,m}(x,t),
\end{equation}
in what follows we establish~\eqref{bound-int0j} for a given $j$
($1\leq j\leq N$) by separately considering~\eqref{mult-scatt-int_Lp1}
in the cases $(x,t)\in\Gamma^\mathrm{tov}_j\times (-\infty,T(M)]$ and
$(x,t)\in\left(\Gamma_j\cap \Gamma_{j\pm 1}\right)\times (-\infty,T(M)]$.

In order to verify~\eqref{bound-int0j} for a given $j$ and for
$(x,t)\in\Gamma^\mathrm{tov}_j\times (-\infty,T(M)]$ we first note
that since we have $g_{k,M}(x,t) = 0$ for
$(x,t)\in \Gamma_k\times (-\infty,T(M-1)$ (in view of~\eqref{A3})
and $g_{k,M}(x,t) = 0$ for $(x,t)\in \Gamma_k^0\times\mathbb{R}$
(in view of~\eqref{vanishing}), and in consideration
of~\eqref{bdry_int}, Lemma~\ref{localpro} tells us that, for
$k\ne j$, $v_{k,M}(x,t) = 0$ for
$(x,t)\in (\Gamma_j\backslash\Gamma_k) \times (-\infty,T(M)]$. Applying
this relation for $k=j\pm 1$ we conclude that
\begin{equation}\label{bound-int1.31}
  v_{j\pm 1,M}(x,t) = 0\; \mbox{ for }\;
  (x,t) \in\Gamma_j^{\mathrm{tov}}\times (-\infty, T(M)],
\end{equation}
while
applying it for other values of $k$ we obtain
\begin{equation}\label{bound-int1.41}
  v_{k,M}(x,t) = 0\quad \mbox{for}\quad
  k\not\in\{j-1,j,j+1\}\quad \mbox{and}\quad
  (x,t) \in\Gamma_j\times (-\infty, T(M)].
\end{equation}
In view of~\eqref{bound-int1.31} and~\eqref{bound-int1.41},
equation~\eqref{mult-scatt-int_Lp1} reduces to
\begin{equation}\label{mult-scatt-int_tov}
u_M(x,t)=   v_{j,M}(x,t) + \sum_{m=1}^{M-1}\sum_{k=1}^N v_{k,m}(x,t) \;\mbox{ for }\; (x,t) \in\Gamma_j^{\mathrm{tov}}\times (-\infty, T(M)],
\end{equation}
and it reduces to
\begin{equation}\label{mult-scatt-int_ov}
u_M(x,t)=   v_{j,M}(x,t) + v_{j\pm 1,M}(x,t) + \sum_{m=1}^{M-1}\sum_{k=1}^N v_{k,m}(x,t) \;\mbox{ for }\; (x,t)\in \Gamma_j\cap \Gamma_{j\pm 1}\times (-\infty,
T(M)].
\end{equation}
The desired relation~\eqref{bound-int0} now follows directly
from~\eqref{mult-scatt-int_tov} and~\eqref{mult-scatt-int_ov} in view
of~\eqref{A1} and~\eqref{A2}, and the proof is thus complete.
\end{proof}

\subsection{FTH-MS solver: interior problem}
\label{sec:3.2}

The procedure embodied in Definition~\ref{inductive_int},
Lemma~\ref{localrels} and Theorem~\ref{equivalence-int} can readily be
implemented, on the basis of the methods described in
Section~\ref{sec:2.1} and \cite{BY23}, as an effective methodology for
the solution of the problem~\eqref{waveeqn} with $E=D$ (interior
problem); the resulting interior FTH-MS algorithm is described in what
follows. Using the notations introduced in Section~\ref{sec:2.1}, for
$m\in\N$, $j=1,\cdots,N$ and $q\in\mathcal{Q}$ we call
$G_{j,m,q}(x,\omega)= \mathbb{F}_{q,slow}(g_{j,m})(x,\omega)$ the slow
Fourier-transform of the boundary data $g_{j,m}$, and we let
$V_{j,m,q}$ denote the solution to the Helmholtz equation problem in
$\Gamma_j^\mathrm{c}$ with Dirichlet boundary data $G_{j,m,q}$ on $\Gamma_j$. The solution $V_{j,m,q}$ is expressed in the form
\be
\label{FDsolk-interior}
V_{j,m,q}(x,\omega)={\mathcal S}_{\Gamma_j}
[\Psi_{j,m,q}](x,\omega),\quad (x,\omega)\in \Gamma_j^c\times\R, \en
(equation~\eqref{SL_rep} but with
$(x,\omega)\in \Gamma_j^\mathrm{c}\times\R$), where,
using~\eqref{SL_bnd_op},
$\Psi_{j,m,q} \in \widetilde{H}^{-1/2}(\Gamma_j)$ denotes the unique
solution of the frequency-domain BIE \be
\label{FDBIEk-interior}
V_{\Gamma_j} [\Psi_{j,m,q}](x,\omega)= G_{j,m,q}(x,\omega),\quad
(x,\omega)\in{\Gamma_j}\times \R, \en see
  e.g.~\cite{SW84}. The solution $v_{j,m}$ is then given by \be
\label{TDsol-interior}
v_{j,m}(x,t)= \mathbb{F}^{-1}\left(\sum_{q\in\mathcal{Q}} e^{i\omega
    s_q}V_{j,m,q}\right)(x,t)= \sum_{q\in\mathcal{Q}}\mathbb{F}^{-1}
\left(V_{j,m,q}\right)(x,t-s_q),\quad (x,t)\in \Gamma_j^\mathrm{c}\times\R.
\en Using these results, notations and conventions, the proposed
FTH-MS method for the interior problem~\eqref{waveeqn} is presented in
what follows (Algorithm~\ref{alg-interior}). Here and throughout this paper, the symbol sequence ``$\mathrel{+}=$'' denotes the binary assignment operator commonly used in C++ and other
programming languages, which adds the value of the right operand to
the value of the left operand, and then assigns the result back to the left operand.

\begin{algorithm}
  \caption{FTH-MS solver for the problem (\ref{waveeqn}) in interior
    domains}
\label{alg-interior}
\begin{algorithmic}[1]
\STATE Initialize $u_M(x,t)=0, (x,t)\in E\times [0,s_Q]$.
\STATE Do $m=1,2,\cdots,M$
\STATE \ \ \ \ Do $j=1,2,\cdots,N$
\STATE \ \ \ \ \ \ \ \ Evaluate the boundary data $g_{j,m}(x,t), (x,t)\in\Gamma_j\times[0,s_Q+H]$ via relations (\ref{criterion_int1})-(\ref{criterion_int2}).
\STATE \ \ \ \ \ \ \ \ Set $v_{j,m}(x,t)=0, (x,t)\in \ov{E}\times [0,s_Q+H]$.
\STATE \ \ \ \ \ \ \ \ Do $q=1,2,\cdots,Q$
\STATE \ \ \ \ \ \ \ \ \ \ \ \ \label{seven} Evaluate the boundary data $G_{j,m,q}(x,\omega)= \mathbb{F}_{q,slow}(g_{j,m})(x,\omega), (x,\omega)\in\Gamma_j\times \R$.
\STATE \ \ \ \ \ \ \ \ \ \ \ \ Solve the integral equations (\ref{FDBIEk-interior}) with solution $\Psi_{j,m,q}$.
\STATE \ \ \ \ \ \ \ \ \ \ \ \ \label{nine} Compute $V_{j,m,q}(x,\omega), (x,\omega)\in \Gamma_j^c\times \R$ using equation (\ref{FDsolk-interior}).
\STATE \ \ \ \ \ \ \ \ \ \ \ \ \label{ten} Compute $v_{j,m}(x,t)\mathrel{+}= \mathbb{F}^{-1}(V_{j,m,q})(x,t-s_q), (x,t)\in \ov{E}\times [0,s_Q+H]$.
\STATE \ \ \ \ \ \ \ \ End Do
\STATE \ \ \ \ \ \ \ \ Compute $u_M(x,t)\mathrel{+}=v_{j,m}(x,t), (x,t)\in E\times [0,s_Q]$ per equation~\eqref{mult-scatt-int} (see Remark~\ref{infty_and_trapping_i}).
\STATE \ \ \ \ End Do
\STATE End Do
\end{algorithmic}
\end{algorithm}

\noindent


\begin{remark}\label{infty_and_trapping}
  The patches $\Gamma_j$ should be specifically chosen to be
  nontrapping, since, as detailed in
  Remarks~\ref{infty_and_trapping_i}
  and~\ref{infty_and_trapping_ii}, the use of such type of patches
  significantly impacts the efficiency of the algorithm.
\end{remark}
\begin{remark}\label{infty_and_trapping_i}
  Although Algorithm~\ref{alg-interior}, per its line 12, evaluates
  $u_M(x,t)$ as a sum of an increasing number of terms as $t$ and $M$
  grow, the selection of non-trapping patches $\Gamma_j$ ensures the
  rapid decay of the solutions $v_{j,m}(x,t)$ as $t$ increases---at
  least for the cases considered in this paper, where the 2D incident
  signal consists entirely of frequency components at nonzero
  frequencies. In such cases, integration by parts arguments similar
  to the 3D treatment~\cite{AB22} can be used to establish fast
  solution decay. As a result of this rapid decay, the total number of
  active terms $v_{j,m}(x,t)$ in the algorithm's line 12 (i.e., those
  exceeding a given error tolerance $\varepsilon^\mathrm{tol}>0$) remains asymptotically
  close to a fixed integer over time. Consequently, the computational
  cost per unit time remains uniformly bounded as time grows.  In
  cases for which the incident signal includes frequency content at
  zero frequency the frequency-asymptotic methods presented
  in~\cite{ABL25} could be applied in the present context to ensure,
  once again, uniformly bounded computing times as time grows.
  \end{remark}  
\begin{remark}\label{infty_and_trapping_ii}
  The use of non-trapping patches $\Gamma_j$ offers a significant
  computational advantage when iterative linear algebra algorithms are
  employed to obtain the required frequency-domain
  solutions. Specifically, the number of iterations required for an
  iterative algorithm to solve the integral
  equations~(\ref{FDBIEk-interior}) on non-trapping patches is
  considerably lower than that required for solving the corresponding
  equations on trapping curves; see Figure~\ref{Example5.3}.
\end{remark}

\subsection{FTH-MS solver: exterior problem}
\label{sec:3.3}

The methods introduced in Sections~\ref{sec:3.1} and~\ref{sec:3.2},
including Theorem~\ref{equivalence-int}, can be extended with minimal
modifications to apply to the wave equation~\eqref{waveeqn} in an
exterior domain $E$, including scenarios where the boundary
$\Gamma = \partial E$ consists of a combination of open and closed
curves. Using this strategy, the implementation of the exterior FTH-MS
solver involves decomposing each connected component of the curve
boundary $\Gamma$ into a union of overlapping open arcs, as described
in Section~\ref{sec:3.2}. This approach is particularly beneficial
when the curves induce trapping, as discussed in
Remark~\ref{infty_and_trapping}. As part of this treatment, the
necessary frequency-domain solutions are obtained through
equations~\eqref{FDsolk-interior} and~\eqref{FDBIEk-interior}.

If preferable, however, boundary-connected components that are closed
curves can be treated as a single patch $\Gamma_j$, and in that case
the necessary frequency-domain solutions $V_{j,m,q}$
(cf. Section~\ref{sec:3.2}) are obtained in the form \be
\label{FDsolk-closed}
V_{j,m,q}(x,\omega)=\left({\mathcal D}_{\Gamma_j} -i\eta {\mathcal
    S}_{\Gamma_j}\right)[\widehat \Psi_{j,m,q}](x,\omega),\quad (x,\omega)\in
D_j^c\times\R. \en Here, defining $G_{j,m,q}$ as in
Section~\ref{sec:3.2}, $\Psi_{j,m,q} \in H^{1/2}(\Gamma_j)$ denotes
the unique solution of the frequency-domain CFIE \be
\label{FDBIEk-closed}
\left(\frac{1}{2}I+K_{\Gamma_j}-i\eta V_{\Gamma_j} \right)[\widehat
\Psi_{j,m,q}](x,\omega)= G_{j,m,q}(x,\omega),\quad
(x,\omega)\in{\Gamma_j}\times\R; \en cf. Section~\ref{sec:2.1}. The
FTH-MS algorithm then proceeds as in the interior domain case
considered in the previous section. In all numerical examples in this
paper that include closed curves as connected boundary components,
these curves are treated using the CFIE equation, as outlined above.



\section{Computational implementation}
\label{sec:4}

The numerical implementations of both the interior-domain
Algorithm~\ref{alg-interior} and the exterior-domain counterpart
outlined in Section~\ref{sec:3.3} require the evaluation of Fourier
transforms, layer potentials, and boundary integral operators. The
next two subsections summarize the strategies employed for these
computations.

\subsection{High-frequency Fourier transform methods}\label{sec:4.1}
The Fourier transformation procedures we use coincide with those
proposed in~\cite{ABL20}. They rely on the fact that if $g(t)$ and
$G(\omega)$ are smooth functions that decay superalgebraically---i.e.,
faster than any negative power of $t$ and $\omega$, respectively, as
these variables tend to $\pm\infty$---then the error in the truncated
Fourier-transform approximation
\begin{equation}
  \label{eq:ft_appr} g(t) \approx \frac{1}{2\pi} \int_{-W}^{W}
G(\omega)e^{-i\omega t} \, d\omega
\end{equation} of the exact transform~(\ref{backwardFT}), as well as
the error in the corresponding forward transform of $g(t)$ truncated
to the interval $[-T,T]$, both decay superalgebraically as $W \to
\infty$ and $T \to \infty$, respectively. Consequently, the needed
Fourier transform~\eqref{eq:ft_appr} and related time-truncated
inverse Fourier transform can be evaluated by means of the
high-frequency quadrature methods~\cite[Secs. 3 and 4]{BY23},
respectively, with  errors that decay superalgebraically fast as both the
integration intervals and the number of quadrature points are
increased.

In the 2D context, in particular, owing to the fact that the 2D
frequency-domain solutions generally contains integrable
$\mathcal{O}(\log|\omega|)$ singularities, the evaluation of the
corresponding Fourier transforms with high-order accuracy requires
special considerations. In detail, in the 2D case the approximate
inverse Fourier transform integrals (\ref{eq:ft_appr}) are expressed
in the form
\begin{eqnarray}
\label{backwardFT1} g(t)\approx
\frac{1}{2\pi}\left(\int_{-W}^{-w_c}+\int_{-w_c}^{w_c}+\int_{w_c}^{W}\right)
G(\omega)e^{-i\omega t}d\omega,
\end{eqnarray} which may be further decomposed into 1)~Integrals of the form
\begin{eqnarray}
\label{int1} I_a^b[G](t)=\int_{a}^{b} G(\omega)e^{-i\omega t}d\omega,
\end{eqnarray} where $G$ is a smooth non-periodic function; and, 2)
Half-interval integrals
\begin{eqnarray}
\label{int2} I_0^{w_c}[G](t)=\int_{0}^{w_c} G(\omega)e^{-i\omega
t}d\omega\quad\mbox{and}\quad I_{-w_c}^0[G](t)=\int_{-w_c}^0
G(\omega)e^{-i\omega t}d\omega,
\end{eqnarray} where $G(\omega)$ contains a logarithmic singularity at
$\omega=0$. The regular integral $I_a^b[G](t)$ can be evaluated by
expressing the non-periodic function $G(\omega), \omega\in [w_c,W]$ as
a Fourier-continuation trigonometric polynomial~\cite{BL10,AB16,ABL20} and
subsequent explicit term-wise integration. To treat the integral
$I_0^{w_c}[G](t)$, which involves a logarithmic singularity at
$\omega=0$, at fixed cost for arbitrarily large times $t$, a modified
``Filon-Clenshaw-Curtis'' high-order quadrature approach was developed
in~\cite{ABL20} by introducing a graded set \ben
\left\{\mu_j=w_c\left(\frac{j}{P}\right)^p, j=1,\cdots,P\right\}, \enn
of points in the interval $(0,w_c)$ and associated integration
sub-intervals $(\mu_j,\mu_{j+1}), j=1,\cdots,P$, on each one of which
the integral $I_{\mu_j}^{\mu_{j+1}}[G](t)$ is produced by means of the
Clenshaw-Curtis quadrature rule. The Fourier transform \ben
\mathbb{F}_{q,slow}(g)(\omega):=\int_{-H}^H
g(t+s_q)\sqcap_q(t)e^{i\omega t}dt \enn for smooth boundary-values
function $g$, finally, can be obtained in a manner analogous to that
used for the evaluation of $I_{w_c}^W[G](t)$ except that, on account
of the use of compactly supported windowing function $\sqcap_q$, the
integrand may be viewed as a periodic function and, thus, a regular
Fourier expansion of the function $g(t+s_q)\sqcap_q(t), t\in[-H,H]$
may be used, instead of a the Fourier continuation used for
$I_{w_c}^W[G](t)$.


