\section{Estimates for conjugator length and norm}

Let $\aH = T_\aH \rtimes \sH \leq G = T \rtimes \On$ be a locally compact split subgroup of the Euclidean group $G = T \rtimes \On$. By \Cref{lem:structureofH} we may fix once and for all a compact subset $S \subseteq H$ for which $H = \langle S \rangle$, with which we consider the word length $\ell_S$ on $H$. 

In order to compute the growth of the conjugator length function of $H$ we need to estimate the shortest length of a possible conjugator for pairs of conjugated elements $h,h'$ whose lengths add to $n$. 
We start by relating the length of an element in $\coconjH{h}{h'}$ to the norm (i.e. Euclidean length) of its translation part. 

\begin{lemma} \label{lem:firstapprox}
Let $\aH = T_H \rtimes \sH$ be as usual. Then 
there exist constants $A=A(\aH,S) > 0$, $B=B(\aH,S) \geq 0$, $C=C(\aH,S) > 0$ and $D=D(\aH,S) \geq 0$ such that
\[A\cdot \ell_S(t^\lambda w) - B \leq \| \lambda \| \leq C\cdot \ell_S(t^\lambda w) + D\]
for all $t^\lambda \in T_H$ and all $w \in \sH$, where $\| \lambda \|$ denotes the Euclidean norm of $\lambda \in \R^n$.
\end{lemma}
\begin{proof}
By \Cref{lem:structureofH}, $\sH$ is compact and $\aH$ is compactly generated, hence the inclusion map $T_\aH \into H = T_\aH \rtimes \sH$ is a quasi-isometry; see, for instance, \cite[Proposition~4.C.11]{Cornulier--delaHarpe}. We can thus find a compact generating set $S_0 \subseteq T_\aH$ and obtain constants 
$\quer{A} > 0$, $\quer{B} \geq 0$, $\quer{C} > 0$ and $\quer{D} \geq 0$ such that
\begin{equation} \label{eq:firstQI}
\quer{A}\cdot \ell_S(t^\lambda w) - \quer{B} \leq \ell_{S_0}(t^\lambda) \leq \quer{C}\cdot \ell_S(t^\lambda w) + \quer{D} \quad \quad \forall t^\lambda \in T_H, w\in \sH.
\end{equation}
By \Cref{lem:structureofH}(3), $T_H$ is quasi-isometrically embedded in $\R^n$ with $T \qi \R^m$ for some $m \leq n$. 
In particular, choosing the origin $\mbf{0} \in \R^n$ as base point, the map 
\[T_\aH \to \R^m \subseteq \R^{n} \quad \text{ given by } \quad t^\lambda \mapsto t^\lambda \bullet \mbf{0} \define \mbf{0} + \lambda = \lambda\]
is a quasi-isometric embedding by the \v{S}varc--Milnor lemma; see \cite[Theorem~4.C.5]{Cornulier--delaHarpe}. Hence there are further constants 
$\til{A} > 0$, $\til{B} \geq 0$, $\til{C} > 0$ and $\til{D} \geq 0$ such that 
\begin{equation} \label{eq:secondQI}
\til{A}\cdot \ell_{S_0}(t^\lambda) - \til{B} \leq \| \lambda \| \leq \til{C}\cdot \ell_{S_0}(t^\lambda) + \til{D} \quad \quad \forall t^\lambda \in T_H.
\end{equation}
Combining \Cref{eq:firstQI,eq:secondQI} we construct constants as claimed.
\end{proof}

\Cref{lem:firstapprox} motivates the following.

\begin{definition}
\label{def:ctd}
The \emph{conjugator translation norm} $\ctn(h,h')$ of a pair of conjugate elements $h,h'\in\aH$ is given by 
\[
\ctn(h,h')\define \min \{ \| \lambda \| \, : \, k=t^\lambda w\in \aH \text{ is such that } khk^{-1}=h'\}. 
\]  	
\end{definition} 

The following are immediate from \Cref{lem:firstapprox}.

\begin{corollary} \label{cor:secondapprox}
In the notation of \Cref{lem:firstapprox} we have 
\[ A \cdot \cl(h,h') - B \leq \ctn(h,h') \leq C \cdot \cl(h,h') + D.\]
\end{corollary}


\begin{corollary} \label{cor:thirdapprox}
Suppose $h = t^\lambda h_0$, $h' = t^{\lambda'} h_0' \in H$ are conjugate. Then there exists an increasing affine map $m_{\aH,S} : \Z_{\geq 0} \to \Z_{\geq 0}$ such that 
\[\ell_S(h) + \ell_S(h') \leq n \iff \|\lambda\| + \|\lambda'\| \leq m_{\aH,S}(n).\]
\end{corollary}

In analogy to the conjugator length we define a function maximizing the value of $\ctn$. 

\begin{definition}
	\label{def:CTD}

	The \emph{conjugator translation norm function} $\Tnorm:\N\to\Z_{\geq 0}$ of $H$ is defined by 
	\[
	\Tnorm(n) \define \max\{ \ctn(h,h')  :  h=t^\lambda w\sim h'=t^{\lambda'}w' \, \text{ and } \, \| \lambda\| +\| \lambda'\|\leq n\}.
	\]
\end{definition}

\begin{lemma}
	\label{prop:reduce-to-translations}
	The function $\Tnorm$ has the same growth rate as $\CLF$.  
\end{lemma}

\begin{proof}
Immediate from \Cref{cor:secondapprox,cor:thirdapprox}.
\end{proof}

We now determine the growth type of $\Tnorm$. 

\begin{prop}
	\label{prop:Tnorm-growth}
	If $\aH$ is a locally compact split subgroup of $\Isom(\E^n)$ whose conjugator length function is nonconstant, then the function $\Tnorm$ for $\aH$ grows linearly. 
\end{prop}

\begin{proof}
Recall that $H$ is compactly generated by $S$. It suffices to prove that there is an increasing affine map $M_{\aH,S} \qeq n\mapsto n$ for which $\ctn(h,h') \leq M_{\aH,S}(n)$ whenever $h = t^\lambda h_0$ and $h' = t^{\lambda'} h_0'$ are conjugate and satisfy $\|\lambda\| + \|\lambda'\| \leq n$. This implies that $\Tnorm(n) \leq M_{\aH,S}(n)$ by definition, whence $\Tnorm(n)$ grows linearly on $n$.

So let $h = t^\lambda h_0 \sim h' = t^{\lambda'} h_0'$ be given as above, and let $g = t^{\eta_u} u$ be a conjugating element that realizes $\ctn(h,h')$. We need to estimate $\|\eta_u\|$. 

By \Cref{thm:coconj}, we know that $\eta_u$ satisfies \Cref{eq:eta}, that is, $\lambda' - u \lambda = (\Id-h_0') \eta_u$. 
Note that the vector $\eta_u$ is, by assumption, shortest possible in $L_\aH$. 
Now, taking $A = \Id-h_0'$ and $b = \lambda'-u\lambda$ we see that 
\[\eta_u \in \mathcal{L}_{A,b} = \{x \in \mathrm{span}_{\R}(L_H) \mid Ax = b\}. \]
We may thus apply \Cref{prop:pseudoinverse} which shows that the shortest possible element in $\mathcal{L}_{A,b}$ is 
\[\eta_0 \define A^+ b,\] 
where $A^+$ is the Moore--Penrose pseudoinverse of $A = \Id-h_0'$. But $\eta_u \in L_\aH$ and, by part~(4) of \Cref{lem:structureofH}, $L_\aH$ has bounded covolume in its real span. Thus there is a constant $k_0 = k_{0,\aH} \geq 0$ such that
\begin{equation} \label{eq:boundingetau}
\|\eta_u\| \leq \|\eta_0\| + k_0.
\end{equation}

On the other hand, 
\Cref{lem:structureofH}(1) also implies that the set 
$\Id - \sH = \{\Id - w \mid w \in \sH\}$ 
is compact. Taking operator norms $|-|$ in our ambient Euclidean space $\E^n \cong \R^n$, we claim that the set $\{ |B^+| \, : \, B \in \Id-\sH \}$ is bounded. To see why, one can deduce this from the constructive proof of \cite[Teorema~16.1]{ElonLinA} on the existence of pseudoinverses, or argue as follows. We apply \Cref{prop:calculatingpseudoinverses} with the aim of constructing matrices $B_1$ and $B_2$ to form $B^+$ while noting that the norms of column vectors of $B_1$ and $B_2$ are uniformly bounded (when $B$ ranges through $\Id-\sH$), which then implies that $|B^+|$ itself is bounded as $B^+ = B_1 B_2^{-1}$. 
Indeed, first note that $\{(\Id-w)^\ast \mid w \in \sH\}$ is also bounded and let $B = \Id-w$ with $w\in H_0$. Since $w\in \sH \leq \On$, the image of $w^\ast$ is spanned by unit vectors, whence the image of $(\Id-w)^\ast = \Id-w^\ast$ is spanned by vectors of norm at most $2$. Thus, as seen in \Cref{prop:calculatingpseudoinverses}, the first matrix $B_1$ will then consist of column vectors with norm at most $2$. As for the second matrix $B_2$, note that if $v$ is any such vector from the given basis of $\Range(\Id-w^\ast)$, then 
\[
\|(\Id-w)^\ast v \| = \|v-w^\ast v\| \leq \|v\|+\|v\| \leq 4
\] since $w^\ast \in \On$. Then, choosing orthonormal bases for the kernels of the $B^\ast$ with $B \in \Id-\sH$, the second matrix $B_2$ from \Cref{prop:calculatingpseudoinverses} will have column vectors whose norms are at most $4$. Altogether, the operator norms of $B_1$ and $B_2$ are uniformly bounded as $B$ ranges through $\Id-\sH$, hence $|B^+| = |B_1 B_2^{-1}| \leq |B_1| |B_2|^{-1}$ is uniformly bounded as well.

The previous paragraph thus gives us a constant $k_1 > 0$ such that $|B^+| < k_1$ for all $B \in \Id-\sH$, in particular $|A^+| < k_1$ as well. 
Note also that
\[\|b\| = \|\lambda'-u\lambda\| \leq \|\lambda'\| + |u|\cdot \|\lambda\|.\]
Thus, taking $k_2 = k_{2,\aH,u} = \max\{1, |u|\}$, we get 
\[\|b\| \leq k_2 \cdot (\|\lambda'\| + \|\lambda\|).\]
A priori, $k_2$ depends on the operator norm $|u|$. But again using that $\sH$ is compact by part~(1) of \Cref{lem:structureofH}, there is a uniform upper bound on the operator norm of elements in $\sH$. In particular, taking the constant $k_3 = k_{3,\sH} \define \max\{ |w| \, : \, w \in H_0\} > 0$, we obtain
\begin{equation} \label{eq:lastconstant}
\|b\| \leq k_3 \cdot (\|\lambda'\| + \|\lambda\|).
\end{equation}

Combining \Cref{eq:boundingetau} and \Cref{eq:lastconstant}, it follows that
\[ \|\eta_u\| \leq \|\eta_0\| + k_0 = \|A^+ b\| + k_0 \leq |A^+| \cdot \|b\|+k_0\leq k_1 k_3 (\|\lambda'\| + \|\lambda\|) + k_0 \leq M_\aH(n), \]
where $M_\aH(x) \define k_1 k_3 x + k_0$. This completes the proof.
\end{proof}

\medskip

\begin{proof}[Proof of \Cref{thm:lineargrowth}]
Note that $H$ might be abelian, e.g. when $\sH = \id$, or compact, when $T_\aH = \id$. In such cases $\CLF$ is constant. Otherwise apply \Cref{prop:reduce-to-translations} and \Cref{prop:Tnorm-growth}.
\end{proof}

\medskip

We conclude with an example. 
\begin{figure}[htb]
    \centering
    \begin{overpic}[width=0.5\linewidth, trim={19ex 12ex 10ex 0},clip]{A2conjugates-final-roots}%,grid,tics=10 
    \put(35,53){\small{$w$}}
    \put(30,49){\small{$\eta_u$}}
    \put(35,35){\small{\textcolor{magenta}{$\alpha_2$}}}
    \put(47,35){\small{\textcolor{magenta}{$\alpha_1$}}}
    \put(38,47){\small{$h$}}
    \put(52,70){\small{$h'$}}
    \put(42,53){\small{$\eta_0$}}
    \end{overpic}
    \caption{This figure shows, among other things, the conjugacy class of the elements labeled $h$ and $h'$ (purple triangles) in a type-$\widetilde{\mathtt{A}}_2$ Coxeter group. Each turquoise element conjugates $h$ to $h'$. The distance of the yellow vertex to the origin realizes $\ctn(h,h')$; cf. \Cref{ex:conjugatornorm}. A similar figure first appeared in \cite{MST4}, Example~1.1.}
    \label{fig:conjugatornorm}
\end{figure}

\begin{example}
\label{ex:conjugatornorm}
    Suppose $W$ is a Coxeter group of type $\widetilde{\mathtt{A}}_2$ generated by $S=\{s_1, s_2\}$. Then $H=W$ has spherical part isomorphic to the symmetric group on three letters, and translation part isomorphic to the group of translations by the coroot lattice $L_H\cong\R^\vee$. This group acts on $\R^2$ and induces there a tiling by equilateral triangles as shown in \Cref{fig:conjugatornorm}. Each triangle corresponds to a unique group element. The coroot lattice $\R^\vee$ is shown with bold black dots in the same picture. 

    Let $h=t^\lambda s_1$ with $\lambda={\alpha_1^\vee+\alpha_2^\vee}$. The purple elements are all conjugate to $h$. Put $h'=t^{\lambda'}w_0$ with $w_0=s_1s_2s_1$ and $\lambda'=4\alpha_1^\vee + 3\alpha_2^\vee$. The turquoise elements (both shades) are in the coconjugation set $\coconjH{h}{h'}$, where we label the shortest such element by $w$. One can see that these elements are aligned on an affine translate of the fix-set of the spherical part $s_1$ of $h$. Using notation from the proof of \Cref{prop:Tnorm-growth}, the spherical part  $u$ of $w$ is $s_2$ here and  $\eta_u$ is the black vertex of the triangle labeled $w$. The yellow vertex corresponds to $\eta_0$, which is the real solution to \Cref{eq:eta} in this situation and hence realizes the conjugator translator norm $\ctn(h,h')$.  
\end{example}



