\subsection{The Potential Fredholm NN for the Helmholtz PDE}\label{semi-linear-pde-section}
We now consider the Helmholtz PDE, which is of the form:
\begin{eqnarray}\label{helmholtz-pde}
\begin{cases}
 \Delta u(x) - \lambda u(x) = \psi(x), \quad x \in \Omega \\ 
u(x) = f(x), \quad x \in \partial \Omega.   
\end{cases}
\end{eqnarray}

Theorem \ref{BIM} holds for the PDE (\ref{helmholtz-pde}), however the fundamental solution changes, and we have $\Phi(x,y) = -\frac{1}{2 \pi} K_0(\lambda | x-y|),$ where $K_0$ is the modified Bessel function of the second kind (with index 0, in 2D space). Even though many of the calculations for the PFNN construction remain the same as in the linear Poisson PDE, we provide the detailed calculations below, as the change in the fundamental solution leads to different handling of the double layer potential formulation, and subsequent changes to the neural network construction. We now prove the following proposition. %These proofs provide insight into the underlying mathematical framework required for the proposed construction in such a way that it may be used for future research.

\begin{proposition}\label{semi-linear-pot}
The Helmholtz PDE \eqref{helmholtz-pde} can be solved using a Fredholm NN with $M+1$ hidden layers, where the first $M$ layers solve the BIE (\ref{BIE}) on a discretized grid of the boundary, $y_1, \dots, y_N$. The final hidden and output layers are constructed according to the Fredholm NN representation of the double layer potential for PDE \eqref{helmholtz-pde}, with weights $W_{M+1} \in \mathbb{R}^{N \times N}, W_O \in \mathbb{R}^N$ given by:
\begin{eqnarray}
    W_{M+1}= I_{N \times N},
    \,\,\,\,\
    W_{O}= \left(\begin{array}{cccc}
	\mathcal{D} \Phi({x}, {y}_1)\Delta \sigma_{y}, & \mathcal{D} \Phi({x}, {y}_2)\Delta\sigma_{y}, & \dots, & \mathcal{D} \Phi({x}, {y}_N) \Delta \sigma_{y}
\end{array}\right)^{\top},
\end{eqnarray}
where, $\mathcal{D} \Phi({x}, {y}_i)$ as defined in Proposition \ref{prop-poisson}. The corresponding biases $b_{M+1} \in \mathbb{R}^{N}$ and $b_O \in \mathbb{R}$ are given by:
\begin{flalign}
   &b_{M+1} = \left(\begin{array}{ccc}
		- \beta({x}^{\star}), \dots, - \beta({x}^{\star})
	\end{array}\right)^{\top}, \\ 
 &b_O= \Big(\frac{1}{2} + \int_{\Omega} \lambda \Delta \Phi(x, y) dy \Big) \beta({x}^{\star}) + \int_{\partial \Omega} \beta(y) \frac{\partial \Phi(x^*, y)}{\partial n_y} d\sigma_y + \int_{\mathcal{D}} \Phi({x},{y}) f({y}) d {y},
\end{flalign}
where we define $\delta\Phi(x,y) := \Phi(x,y) - \Phi(x^*,y)$.
\end{proposition}

\begin{proof}

It is known that the fundamental solution of the linear operator $\mathcal{L} := \Delta - \lambda$ satisfies:
\begin{equation}
\mathcal{L} \Phi(x,y) = \delta(x - y).
\end{equation}
and is given by $\Phi(x,y) = -\frac{1}{2\pi} K_0\left( \sqrt{\lambda} |x - y| \right)$, where $K_0$ is the modified Bessel function of the second kind. The corresponding BIE is:
\begin{equation}\label{bie-sl}
\beta(x) = 2\left( f(x) - \int_{\Omega} \Phi(x,y) \psi(y) dy \right) - 2 \int_{\partial \Omega} \beta(y) \frac{\partial \Phi(x,y)}{\partial n_y} d\sigma_y.
\end{equation}
It can be shown that the resulting kernel in the BIE (\ref{bie-sl}) is indeed non-expansive. Furthermore, it is known from the properties of the Bessel function that the weak singularity can be treated numerically (more details are given in section \ref{numerics-section}). Now, the change in the differential operator creates a difference in the discontinuity dynamics. Hence, we will need to modify the calculations as we approach the boundary. To this end, we consider the following steps:

\begin{itemize}

\item[{\it Step 1.}] Let $x \in \Omega$. Fix $\epsilon > 0$ and consider the ball centered at $x$ with radiues $\epsilon$, such that $B(x,\epsilon) \subset \Omega$. In $\Omega - B(x,\epsilon)$, $\Phi(x,y)$ is smooth. We have:
\begin{equation}
0 = \int_{\partial \Omega} \mathcal{L}\Phi(x,y) d\sigma_y = \int_{\Omega - B(x,\epsilon)} \Delta_y \Phi(x, y) dy - \lambda \int_{\partial B(x,\epsilon)} \frac{\partial \Phi(x,y)}{\partial n_y} d\sigma_y.
\end{equation}
By the Divergence Theorem, this becomes:
\begin{eqnarray}
0 &=& \int_{\partial \Omega} \frac{\partial \Phi(x,y)}{\partial n_y} d\sigma_y - \lambda \int_{\partial B(x,\epsilon)} \frac{\partial \Phi(x,y)}{\partial n_y} d\sigma_y \notag \\
&=& \int_{\partial \Omega} \frac{\partial \Phi(x,y)}{\partial n_y} d\sigma_y + \int_{\partial B(x,\epsilon)} \frac{\partial \Phi(x,y)}{\partial n_y} d\sigma_y - \int_{\Omega - B(x,\epsilon)} \Phi(x,y) dy.
\end{eqnarray}

Let us now consider the second term, where the outer unit normal to $\Omega - B(x,\epsilon)$ is $n_y = \frac{x - y}{|x - y|}$.
Furthermore, note that $K_0(z) \sim - \ln(z)$ as $z \to 0$ (see e.g., \cite{kropinski2011fast}), and so we have:
\begin{flalign}
\frac{\partial \Phi(x,y)}{\partial n_y} = \nabla_y  \Phi(x, & y)  \cdot \frac{x - y}{|x - y|} \approx \frac{\sqrt{\lambda}}{2\pi} \big( \ln(\sqrt{\lambda} |x - y|) \big)' \big( (y_1 - x_1)^2 + (y_2 - x_2)^2 \big)  = -\frac{1}{2\pi |x - y|}.
\end{flalign}

% {\color{red} \begin{flalign}
% \frac{\partial \Phi(x,y)}{\partial n_y} = \nabla_y \Phi(x,y) \cdot \frac{x - y}{|x - y|} &= -\frac{\sqrt{\lambda} K_0 '\left( \sqrt{\lambda} |x - y| \right)}{2\pi |x - y|^2} \cdot \frac{x - y}{|x - y|} \notag \\&\approx \frac{\sqrt{\lambda}}{2\pi} \left[ \ln(\sqrt{\lambda} |x - y|) \right]' \left[ (y_1 - x_1)^2 + (y_2 - x_2)^2 \right]  = -\frac{1}{2\pi |x - y|}.
% \end{flalign}}

% \[
% \begin{pmatrix}
%   \tilde u(x_1) \\[0.3em]
%   \tilde u(x_2) \\[0.3em]
%   \vdots       \\[0.3em]
%   \tilde u(x_N)
% \end{pmatrix}
% \]


Thus, we obtain
$\int_{\partial B(x,\epsilon)} \frac{\partial \Phi(x,y)}{\partial n_y} ds(y) \approx -1,$ and therefore get:
\begin{equation}
\int_{\partial \Omega} \frac{\partial \Phi(x,y)}{\partial n_y} d\sigma_y = 1 + \int_{\Omega} \lambda \Phi(x,y) dy.
\end{equation}

\item[{\it Step 2.}] Now, consider $x^* \in \partial \Omega$.
We know that $\frac{\partial \Phi(x,y)}{\partial n_y}$ is not defined for $x^* = y$. Fix $x^* \in \partial \Omega$ and consider $B(x^*,\epsilon)$ and $\Omega_\epsilon \equiv \Omega - \left( \Omega \cap B(x,\epsilon) \right)$. Furthermore, let $\Xi_\epsilon = \left\{ y \in \partial B(x^*,\epsilon) : n_y \cdot (x^* - y) < 0 \right\}$ and $\tilde{\Xi}_\epsilon = \partial \Omega_\epsilon \cap \Xi_\epsilon$. Then:
\begin{eqnarray}
0 &=& \int_{\partial \Omega_\epsilon} \mathcal{L}\Phi(x^*,y) dy = \int_{\Omega_\epsilon} \Delta_y \Phi(x^*,y) dy - \int_{\partial \Omega_\epsilon} \frac{\partial \Phi(x^*,y)}{\partial n_y} d\sigma_y \notag \\
&=& \int_{\partial \Omega} \frac{\partial \Phi(x^*,y)}{\partial n_y} d\sigma_y + \int_{\tilde{\Xi}_\epsilon} \frac{\partial \Phi(x^*,y)}{\partial n_y} d\sigma_y - \int_{\Omega_\epsilon} \Phi(x^*,y) dy.
\end{eqnarray}

In the above, $n_y$ is the outer unit normal to $\Omega_\epsilon$. For $y \in \tilde{\Xi}_\epsilon$, $n_y = \frac{x^* - y}{|x^* - y|}$. Similar steps as before give:
\begin{equation}
\int_{\tilde{\Xi}_\epsilon} \frac{\partial \Phi(x^*,y)}{\partial n_y} d\sigma_y \approx \int_{\tilde{\Xi}_\epsilon} \frac{-1}{2\pi |x^* - y|} d\sigma_y \approx -\frac{1}{2\pi \epsilon} \left( \frac{1}{2} 2\pi \epsilon \right) = -\frac{1}{2}.
\end{equation}

Therefore:
\begin{equation}
\int_{\partial \Omega} \frac{\partial \Phi(x^*,y)}{\partial n_y} d\sigma_y = -\frac{1}{2} + \int_{\Omega} \lambda \Phi(x^*,y) dy.
\end{equation}
\end{itemize}

With the above results at hand, the double layer potential can be written as:
\begin{flalign}\label{potential-limit-expression}
u(x) = \int_{\partial \Omega} \big(\beta(y) &- \beta(x^*)\big) 
\Big( \frac{\partial \Phi(x,y)}{\partial n_y} - \frac{\partial \Phi(x^*, y)}{\partial n_y} \Big) d\sigma_y
 \nonumber \\
& + \beta(x^*)\Big(\frac{1}{2} + \int_{\Omega} \lambda \delta \Phi(x, y) dy \Big) + \int_{\Omega} \Phi(x, y) \psi(y) dy 
+ \int_{\partial \Omega} \beta(y) \frac{\partial \Phi(x^*, y(s))}{\partial n_y} d\sigma_y.
\end{flalign}
\end{proof}

As shown, in the case of the Helmholtz PDE, the difference in the fundamental solution creates an additional term in this new double layer potential representation. This, in turn, corresponds to a different bias term in the output of the constructed neural network. Indeed, as we will show in the next section, the properties of the fundamental solution, and by extension, its numerical integration, plays an important role in the approximation efficiency of the Fredholm NN. 

\section{Consistency and error analysis}\label{error-section}
In this section, we will provide bounds for the approximation errors associated with the given approach. Before proceeding with the rigorous treatment of the error bounds, we recall two important points: firstly, we note that the Fredholm NN replicates the process of successive approximations, which inherently introduces an approximation error $||\beta_M - \beta||$. Secondly, the solution constructed by the double layer potential satisfies identically the boundary condition when the BIE is satisfied. Therefore, based on these observations, it is expected that a stable scheme ensures that approximation errors at the boundary decrease progressively as the number of iterations increases. 
\par Here, we  provide bounds for these errors. Indeed, the Fredholm NN and subsequently the PFNN  construction provide a framework where this is possible. This is an important step, since DNN-based models often lack consistent error estimates, and often exhibit relatively large errors on the boundaries. 
\par For the completeness of the presentation, we recall the following proposition from \cite{georgiou2024fredholm}. 
\begin{proposition} Consider the integral equation $f(x) = (\mathcal{T}f)(x)$, where the integral operator:
\begin{eqnarray}
	(\mathcal{T}f)(x) = g(x) + \int_{\mathcal{A}}K(x,z) f(z)dz,
\end{eqnarray}
is non-expansive and $\mathcal{A}:=[a,b]$. Then, the error in the M-layer FNN approximation to the solution of the integral equation, $f_M$, satisfies the following bound:
 \begin{eqnarray}\label{fnn-error}
    \left\|f-f_M\right\|_{\mathcal{A}} \leq \frac{\mathrm{e}^{1-q}}{1-q}\left( \left\|T g-g\right\|_{\mathcal{A}} + \frac{D(b-a)^2}{2n} \right)\mathrm{e}^{-(1-q) v_M},
\end{eqnarray}
where $D = \max_{x \in \mathcal{A}} \frac{d}{dz} \big(K(x,z)g(z)\big)$, $v_0=0, v_M=\sum_{\nu=0}^{M-1} \kappa$ (since in the Fredholm NN we consider constant values for the parameter in the Krasnoselskii-Mann iteration, $\kappa_{\nu} = \kappa$.
\end{proposition}

\par Given that the Fredholm NN replicates a discretization of the BIE, as well as the corresponding integrals in the proposed formula for the potential, it will be useful to use a notation for the discretization that encapsulates various schemes that may be considered. Throughout the proof, we will use the notation $\tilde{\int_{\mathcal{A}}}$ to represent the discretized version of $\int_{\mathcal{A}}$, for any arbitrary domain $\mathcal{A} \subseteq \mathbb{R}^n$ (in our case, $A \subseteq \mathbb{R}$). We emphasize that this notation is useful so that the results that follow can be applied to any chosen discretization scheme.\par 
We now demonstrate the main result pertaining to the errors bounds in the boundary conditions.
\begin{theorem}\label{error-bounds-thrm}
 Consider the PDE of the form (\ref{helmholtz-pde}), with a potential  given in form (\ref{potential-limit-expression}) and corresponding BIE, (\ref{BIE}), whose Fredholm NN approximation is given by $\beta_M(x): \partial \Omega \rightarrow \mathbb{R}$. Furthermore, define the following terms, depending on the discretization scheme selected for the integrals in (\ref{potential-limit-expression}):
 \begin{flalign}
     &D_1(\mathcal{A}) := \left\|\ \int_{\Omega} \lambda \delta \Phi(x, y) dy -  \tilde{\int_{\Omega}} \lambda \delta \Phi(x, y) dy \right\|_{\mathcal{A}}, \\
     &D_2(\mathcal{A}) := \left\| \int_{\Omega} \Phi(x, y) \psi(y)  dy - \tilde{\int_{\Omega}}\Phi(x, y) \psi(y) dy \right\|_{\mathcal{A}}, \\
    &D_3(\mathcal{A}) := \left\|\int_{\partial \Omega} \Big(\beta_M(y) - \beta_M(x^*)\Big) \mathcal{D} \Phi(x,y) d\sigma_y - \tilde{\int_{\partial \Omega}} \big(\beta_M(y) - \beta_M(x^*)\big) \mathcal{D} \Phi(x,y) d\sigma_y\right\|_{\mathcal{A}}, \\
     & D_4(\mathcal{A}) := \left\| \int_{\partial \Omega} \beta_{M}(y)  \frac{\partial \Phi(x, y)}{\partial n_y}  d\sigma_y - \tilde{\int_{\partial \Omega}} \beta_M(y) \, \frac{\partial \Phi(x, y)}{\partial n_y} d\sigma_y \right\|_{\mathcal{A}},
 \end{flalign}
 when $x \in \mathcal{A}$. Then, the PFNN construction providing $\tilde{u}$, as approximation of the solution of the PDE, satisfies the following error bound:
\begin{flalign}\label{error-domain}
    \left\|u - \tilde{u} \right\|_{\Omega} \leq \left\|\beta - \beta_M \right\|_{\partial \Omega}\left( \frac{1}{2} + 2\left\|\int_{\partial \Omega}  \mathcal{D} \Phi(x,y)d\sigma_y\right\|_{\Omega} + \left\| \int_{\Omega} \lambda \delta \Phi(x, y) dy \right\|_{\Omega} + \left\| \int_{\partial \Omega}\frac{\partial \Phi(x, y)}{\partial n_y} d\sigma_y \right\|_{\Omega} \right) \notag \\ + \left\|\beta_M\right\| D_1(\Omega) + D_2(\Omega) + D_3(\Omega) + D_4(\Omega).
\end{flalign}
Furthermore, the following inequality holds for errors on the boundary, $x\in \partial \Omega$: 
\begin{flalign}\label{error-boundary}
  \left\|f - \tilde{u} \right\|_{\partial \Omega} \leq \left\|\beta - \beta_M \right\|_{\partial \Omega} \left( \frac{1}{2} + \left\| \int_{\partial \Omega}\frac{\partial \Phi(x^*, y)}{\partial n_y} d\sigma_y \right\|_{\partial \Omega} \right)  + D_2(\partial \Omega) + D_4(\partial \Omega),  
\end{flalign}
where $\left\|\beta - \beta_M \right\|_{\partial \Omega}$ is the error in the  FNN approximation of the boundary function $\beta$, as given in (\ref{fnn-error}).
\end{theorem}
\begin{proof}
The proof entails decomposing the error into the components arising from the Fredholm NN estimator and the subsequent PFNN construction. Both of these are directly associated to well-known numerical methods with well-defined error bounds, which we can now take advantage of in the context of Fredholm NNs. 
\par Considering the potential formulation (\ref{potential-limit-expression}) and keeping the notation $\mathcal{D} \Phi({x}, {y}):=\frac{\partial \Phi}{\partial n_{y}}({x}, {y})- \frac{\partial \Phi}{\partial n_{y}}(x^*, {y})$, we can write: 
\begin{flalign}
\left\|u -  \tilde{u}\right\|_{\Omega} &\leq \left\|\int_{\partial \Omega} \big(\beta(y) - \beta(x^*) \big) \mathcal{D} \Phi(x,y) d\sigma_y -  \tilde{\int_{\partial \Omega}} \big(\beta_M(y) - \beta_M(x^*)\big) \mathcal{D} \Phi(x,y) d\sigma_y \right\|_{\Omega} \notag \\ 
&+ \left\| \beta(x^*) \Big(\frac{1}{2} + \int_{\Omega} \lambda \Delta \Phi(x, y) dy \Big) - \beta_M(x^*) \Big(\frac{1}{2} +  \tilde{\int_{\Omega}} \Delta \Phi(x, y) dy \Big) \right\|_{\Omega} \nonumber \\
&+ \left\| \int_{\Omega} \Phi(x, y) \psi(y) dy - \tilde{\int_{\Omega}} \Phi(x, y) \psi(y) dy \right\|_{\Omega} \notag \\ 
&+ \left\|\int_{\partial \Omega} \beta(y) \frac{\partial \Phi(x, y)}{\partial n_y}d\sigma_y - \tilde{\int_{\Omega}}\beta_M(y) \frac{\partial \Phi(x, y)}{\partial n_y} d\sigma_y\right\|_{\Omega}.
\end{flalign}
We now consider each of the terms in the above expression separately. For clarity, in the steps below we gather the terms corresponding to the integral discretization errors and subsequently handle these using the well-known results for discretized integrals:
\begin{itemize}
    \item[{\it 1st term:}]
\begin{flalign}
    &\left\| \int_{\partial \Omega} \big(\beta(y) - \beta(x^*)\big) \mathcal{D} \Phi(x,y) d\sigma_y - \tilde{\int_{\partial \Omega}}\big(\beta_{M}(y) - \beta_{M}(x^*)\big) \mathcal{D} \Phi(x,y) d\sigma_y \right\|_{\Omega} \notag \\
     \leq &\left\| \int_{\partial \Omega}\Big(\big(\beta(y) -  \beta_M(y)\big) + \big(\beta_M(x^*) -  \beta(x^*)\big)\Big) \mathcal{D} \Phi(x,y) d\sigma_y \right\|_{\Omega} \notag \\ 
      + & \left\|\int_{\partial \Omega} \Big(\beta_M(y) - \beta_M(x^*)\Big) \mathcal{D} \Phi(x,y) d\sigma_y - \tilde{\int_{\partial \Omega}} \big(\beta_M(y) - \beta_M(x^*)\big) \mathcal{D} \Phi(x,y) d\sigma_y\right\|_{\Omega} \notag \\
     \leq & \int_{\partial \Omega} 2\left\|\beta_M - \beta\right\|_{\partial \Omega} \mathcal{D} \Phi(x,y)d\sigma_y + D_3(\Omega) \leq 2\left\|\beta_M - \beta\right\|_{\partial \Omega} \left\|\int_{\partial \Omega}  \mathcal{D} \Phi(x,y)d\sigma_y\right\|_{\Omega} + D_3(\Omega),
\end{flalign}
 where for the last steps we recall that the normal derivative of the fundamental solution is non-negative (see calculations for the potential above).
    \item[{\it 2nd term:}] 
    \begin{flalign}
    & \left\| \beta(x^*) \Big(\frac{1}{2} + \int_{\Omega} \lambda \delta \Phi(x, y) dy \Big)  - \beta_{M}(x^*) \Big(\frac{1}{2} +  \tilde{\int_{\partial \Omega}} \lambda \delta \Phi(x, y) dy \Big)  \right\|_{\Omega} \notag \\
    \leq& \frac{1}{2} \left\| \beta - \beta_{M} \right\|_{\partial \Omega} + \left\| \beta(x^*) \int_{\Omega} \lambda \delta \Phi(x, y)dy  - \beta_{M}(x^*)  \int_{\Omega} \lambda \delta \Phi(x, y)dy \right\|_{\Omega} \notag \\
     +& \left\|\beta_M(x^*) \int_{\Omega} \lambda \delta \Phi(x, y) dy   - \beta_{M}(x^*) \tilde{\int_{\Omega}} \delta \Phi(x, y) dy \right\|_{\Omega} \notag \\
    \leq & \left\|\beta - \beta_M\right\|_{\partial \Omega} \left( \frac{1}{2} + \left\| \int_{\Omega} \lambda \delta \Phi(x, y) dy \right\|_{\Omega} \right)  + \left\|\beta_M \right\|D_1(\Omega).
    \end{flalign}

    \item[{\it 3rd term:}]
    \begin{eqnarray}
    \left\| \int_{\Omega} \Phi(x, y) \psi(y)  dy - \tilde{\int_{\Omega}}\Phi(x, y) \psi(y) dy \right\|_{\Omega} =: D_2(\Omega).
    \end{eqnarray}

    \item[{\it 4th term:}]
    \begin{flalign}
    & \left\| \int_{\partial \Omega} \beta(y) \frac{\partial \Phi(x, y)}{\partial n_y} d\sigma_y - \tilde{\int_{\partial \Omega}} \beta_M(y)  \frac{\partial \Phi(x, y)}{\partial n_y} d\sigma_y \right\|_{\Omega} \notag \\
    \leq & \left\| \int_{\partial \Omega} \beta(y) \, \frac{\partial \Phi(x, y)}{\partial n_y} d\sigma_y - \int_{\partial \Omega} \beta_{M}(y)  \frac{\partial \Phi(x, y)}{\partial n_y} d\sigma_y \right\|_{\Omega} \notag \\
    + & \left\| \int_{\partial \Omega} \beta_{M}(y)  \frac{\partial \Phi(x, y)}{\partial n_y}  d\sigma_y - \tilde{\int_{\partial \Omega}} \beta_M(y) \frac{\partial \Phi(x, y)}{\partial n_y} d\sigma_y \right\|_{\Omega} \notag \\
    \leq & \int_{\partial \Omega} \left\| \beta - \beta_{M} \right\|_{\partial \Omega} \frac{\partial \Phi(x, y)}{\partial n_y}  d\sigma_y + D_4(\Omega) \leq \left\| \beta - \beta_{M} \right\|_{\partial \Omega} \left\| \int_{\partial \Omega}\frac{\partial \Phi(x, y)}{\partial n_y} d\sigma_y \right\|_{\Omega} + D_4(\Omega).
    \end{flalign}

\end{itemize}
Hence, we obtain:
\begin{flalign}
    \left\|u - \tilde{u} \right\|_{\Omega} \leq \left\|\beta - \beta_M \right\|\left( \frac{1}{2} + 2\left\|\int_{\partial \Omega}  \mathcal{D} \Phi(x,y)d\sigma_y\right\|_{\Omega} + \left\| \int_{\Omega} \lambda \Delta \Phi(x, y) dy \right\|_{\Omega} + \left\| \int_{\partial \Omega}\frac{\partial \Phi(x, y)}{\partial n_y} d\sigma_y \right\|_{\Omega} \right) \notag \\ + \left\|\beta_M\right\|_{\partial \Omega} D_1(\Omega) + D_2(\Omega) + D_3(\Omega) + D_4(\Omega). 
\end{flalign}
The error bound for the boundary condition follows directly from the above, by noticing the vanishing terms as $x\rightarrow x^*$.
\end{proof}

The above result in combination with \eqref{fnn-error} provide an explicit expression for the error bounds in the PFNN construction, which depend on the boundary conditions of the PDE (via the BIE), the fundamental solution of the differential operator and the discretization of the integrals in the FNN representation of the potential. Through this composition, we are able to define the approximation errors in detail and quantify how or when larger errors may arise. 
\par Therefore, within the proposed framework, we see that the error in the model approximation can be attributed to: a) the number of hidden layers in the Fredholm NN, which is equivalent to the number of iterations required to converge to the fixed point within a certain accuracy, and b) the number of nodes used to construct the FNN on which we approximate the solution of the PDE, and which are then used for the numerical integration. However, we also see that the error bound also depends explicitly on the boundary function $\left\|\beta_M \right\|$. This occurs from two components of expression \eqref{error-domain} due to the error in the integral approximation. In particular, this dependency occurs through the term $\|\beta_M\|D_1(\Omega)$, as well as $D_4(\mathcal{A})$, where $\mathcal{A} = \Omega$ or $\partial \Omega$, since:
\begin{equation}
    D_4(\mathcal{A}) \leq C \max_{\substack{x \in \mathcal{A}}}\frac{d}{dy}\Big( \beta_M(y)\frac{\partial \Phi(x,y)}{\partial n_y} \Big) = C_1 \|\beta_M\|_{\mathcal{A}} + C_2,
\end{equation}
by a simple application of the product rule, where $C>0$ is a constant depending on the size of the discretization grid and $C_1, C_2 > 0$ are constants depending on the derivatives of $\frac{\partial \Phi(x,y)}{\partial n_y}$ and $\beta_M$, respectively. 
This decomposition of the errors therefore provides insight into how the form of the PDE can actually affect the error of the numerical approximation. 
\par Finally, we note that the  error analysis can be useful when considering the computational requirements for the construction of DNNs under the proposed framework. In particular, for a given computational cost, there exists a trade-off between the number of layers in the Fredholm NN for the approximation of the boundary function $\beta_M$, and the discretization of the integral terms; increasing the number of hidden layers in the Fredholm NN will ensure a smaller error $\left\| \beta_M - \beta \right\|$, thus decreasing the first four components in (\ref{error-domain}), but selecting a more computationally demanding numerical integration will decrease the final four terms. The selection of these hyperparameters can be done in a robust way since we know the components and how the underlying form of the PDE can affect the errors. 

\section{Recurrent PFNN construction for semi-linear elliptic PDEs}\label{non-linear-section}
We now turn to the case of non-linear (semi-linear) elliptic PDEs of the form: %The Limit-Informed framework can be used in combination with an appropriate iterative scheme to constuct an elliptic PDE at each iteration. To present this methodology, we will be considering non-linear PDEs of the form below (deferring more general cases for future work): 
\begin{eqnarray}\label{nl-pde}
\begin{cases}
\Delta u(x) = F(x, u(x)), \quad x \in \Omega \\
u(x) = f(x), \quad x \in \partial \Omega.
\end{cases} 
\end{eqnarray}

For their solution, fixed point schemes are often employed, which linearize the PDE at each step of the iteration. In line with this approach, we consider the monotone iteration scheme (see e.g., \cite{deng1996boundary}), as below: 

\begin{enumerate}
    \item Choose a $\lambda > 0$ "sufficiently large" (see below)
    \item Take an initial guess $u_0(x)$
    \item Solve, for $n = 0, 1, 2, \ldots$ the PDE:
    \begin{equation} 
    \begin{cases}
    \Delta u_{n+1}(x) - \lambda u_{n+1}(x) = -\lambda u_n(x) + F(x, u_n(x)), & x \in \Omega, \label{iteration}\\
    u_{n+1}(x) = f(x), & x \in \partial \Omega.
    \end{cases}
    \end{equation}
\end{enumerate}

Regarding the appropriate choice for $\lambda$, the value must be large enough to ensure the mapping:
\begin{eqnarray}\label{mapping}
T(u) = (\Delta - \lambda)^{-1}\big( - \lambda u + F(x,u) \big),
\end{eqnarray}
is a contraction, with the resulting iteration given by $u_{n+1} = T(u_n)$.
%$$(\mathcal{L}u)(x): = -\lambda u_n(x) + F(x, u_n(x))$$ is a contraction. 
By Banach's fixed point theorem, this ensures that the scheme converges to the solution of the PDE (see \cite{deng1996boundary, sakakihara1987iterative} for such conditions and further details, and \cite{brebbia2016boundary} for other iterative schemes).\par This iterative scheme allows us to apply the proposed framework at each step of the scheme, whereby the source term will change at each iteration, in accordance to \eqref{iteration}. We therefore refer to this as a Recurrent Potential Fredholm NN (RPFNN) construction.\par 
Given that the source terms will depend on the solution $u_n(x)$, the numerical approximation of the integrals $\int_{\Omega} \Phi(x,y)\psi(y)dy$ must be considered. Here, we select a straightforward quadrature rule, across the points at which $u_n(x)$ has been calculated in order to avoid any interpolation-like approximations. For clarity, a full description of the fixed point algorithm solved via the FNN is given in Algorithm \ref{alg:nl-algo} and a schematic representation is given in Fig. \ref{fig:nl-algo}.

\begin{algorithm}[hbt!]\caption{Recurrent PFNN construction}\label{alg:nl-algo}
\small
\begin{algorithmic}
\State {Set number of iterations $N'$.}
\State {Set polar grid points $\mathcal{R} = \{r_1, \ldots, r_{M_r}\}$ and $\Theta = \{\theta_1, \ldots, \theta_{M_{\theta}}\}$.}
\State {Select parameter $\lambda$ and initialize $u_0(x)$ (e.g., $u_0(x) = g(x)$).}
\Ensure The approximated fixed-point solution $u^*(x)$
\While{$n \leq N'$}
    \State {Step 1. Construct the PDE (\ref{iteration}) with source term $\psi_n(x) := -\lambda u_n(x) + F(x,u_n(x))$.}
    \State {Step 2. Approximate the integral with respect to the Poisson source term by:
    \begin{eqnarray}
        \int_{\Omega} \Phi(x, y) \psi_n(y) dy \approx \sum_{r \in \mathcal{R}} \sum_{\theta \in \Theta} \Phi(x,r, \theta) \psi_n(r,\theta)r \Delta r \Delta \theta.
    \end{eqnarray}
    }
    \State {Step 3. Solve the BIE (\ref{bie-sl}) via the FNN.}
    \State {Step 4. Solve the PDE using the PFNN to estimate $u_n(r_i, \theta_j)$ for $i \in \{1, \ldots M_r\}$, $j \in \{1, \ldots M_{\theta} \}$. }
    \State{Step 5. Set $n \rightarrow n+1$.}
\EndWhile \\
\Return {$u_{N'}(x)\approx u^*(x).$}
\end{algorithmic}
\end{algorithm}

\begin{figure}[ht]
    \centering
    \includegraphics[width=0.85\textwidth]{RPNN.pdf}
    \caption{Schematic of the Recurrent Potential Fredholm NN to solve semi-linear elliptic PDEs.} \label{fig:nl-algo}
\end{figure}

\begin{lemma}
    Consider the non-linear PDE (\ref{nl-pde}), where $F(x,u)$ is $C^1$ with respect to $(x,u) \in \Omega \times \mathbb{R}$, and $\lambda >0$ such that the mapping $T(u)$, as given in \eqref{mapping}, is a $q$-contraction, with $q<1$.  Furthermore, let the approximation $\tilde{u}_n(x)$ be given by the Recurrent PFNN construction, as described in Algorithm \ref{alg:nl-algo}, and with known $u_0(x)$. Then, the following error bounds hold:
    \begin{flalign}\label{error-recurrent}
    \begin{cases}
        \left\|\tilde{u}_n - u \right\|_{\Omega} \leq  \epsilon^{RPFNN}_{\Omega} + q^n\left\| u_0 - u  \right\|_{\Omega}, \\
        \left\|\tilde{u}_n - f \right\|_{\partial \Omega} \leq  \epsilon^{RPFNN}_{\partial \Omega} + q^n\left\| u_0 - u  \right\|_{\partial \Omega},
    \end{cases}
    \end{flalign}
 where $\epsilon_{\Omega}^{RPFNN}, \epsilon_{\partial \Omega}^{RPFNN}$ denote the errors associated with the PFNN construction in the domain and on the boundary, as given by (\ref{error-domain}) and (\ref{error-boundary}) respectively.   
\end{lemma}
\begin{proof}
Notice that we can decompose the error into a component arising from the fixed point iterations and another due to the neural network approximation by writing $\left\|\tilde{u}_n - u \right\|_{\Omega} \leq \left\|\tilde{u}_n - u_n \right\|_{\Omega} + \left\|u_n - u \right\|_{\Omega}$. Substituting the error bound (\ref{error-domain}) and using the known error bound for the fixed point iterations results in (\ref{error-recurrent}). The error on the boundary follows in exactly the same fashion.
\end{proof}


\section{The Potential Fredholm Neural Network for Inverse Problems} \label{inverse-section}
To showcase the applications of the proposed framework, we now turn to the inverse problem for the family of PDEs examined in this paper. 
Here, we demonstrate how the proposed approach can be used to solve the inverse source problem for the Poisson PDE. Analogously, this framework can be applied to the other elliptic PDEs examined in this work; for brevity, we defer this for future examination. 
\par We will be considering the inverse source problem for the PDE \eqref{poisson}, consisting of a known boundary function $f : \partial \Omega \to {\mathbb R}$, as well as a coarse set of data points $\{ u(x_i) \}_{i=1,\cdots, n}$, $x_i \in \Omega$, and looking to approximate the unknown source function $\psi: \Omega \to {\mathbb R}$, using for a suitable model, represented by $\psi_{\theta}: \Omega \to {\mathbb R}$ with parameters $\theta$ (e.g., a shallow neural network), such that the data $\{\tilde{u}(x_i) \}$ and function $f(x)$ satisfy the Poisson PDE \eqref{poisson}.
\par Note that the inverse source problem is well known to be an ill-posed problem, not admitting a unique solution. Indeed, there are infinitely many functions $\psi(x), x\in \Omega$ that satisfy \eqref{poisson}. Therefore, with this perspective, our goal is to learn the source term such that when used in the PDE, the resulting solution closely matches our data, rather than learning the exact source term function per se. This can now be studied within the framework of the PFNN; conceptually, the inverse problem consists of, given the data $\tilde{u}$, $f$, modelling the unknown source function, such that, when using the approximated source function in the forward PFNN, the resulting solution to the PDE, $\hat{u}$, is as close as possible to the given data $\tilde{u}$. 

\par Our strategy takes advantage of the structure and convergence properties of the PFNN as follows: select a set of parameters $\theta$ such that when constructing the estimated kernel ${\psi}_{\theta}(\cdot, \cdot)$ and then feeding this into the PFNN with $M$ hidden layers, denoted by $PFNN_M( \cdot ; {\psi}_{\theta})$, the output, $\hat{u}(x;{\psi}_{\theta})$ (which will also be denoted $\hat{u}(x)$ for brevity), is as ''close'' as possible (in terms of an appropriately chosen loss function) to the given data $\tilde{u}$. The learning problem then reduces to the optimization problem of tuning the parameters $\theta$ appropriately until we reach the optimal set $\theta^*$ and the corresponding source model ${\psi}_{\theta^*}$. 
 \par As mentioned, the described inverse problem is ill-posed. Hence, we require a regularization component. For our approach (and the example that is presented in section \ref{sec-inv-sec}, where we use a shallow neural network model for the approximation $\psi_{\theta}$), we apply a Tikhonov regularization, encapsulated by the term:
\begin{equation}\label{reg}
    \mathcal{R}(\theta) = \|\psi_{\theta} \|_2^2, 
    %\equiv \sum_j (\hat{\psi}_{\theta}(x_j))^2, \,\,\ \text{for } x_j \in \Omega
\end{equation}
where and the complete loss function is given by: 
\begin{equation}\label{inverse-loss}
     L(\theta) = \frac{1}{N} \sum_{i=1}^{N} \Big(\tilde{u}(x_i) - \hat{u}(x_i; {\psi}_\theta) \Big)^2 + \lambda_{reg}\mathcal{R}(\theta).
\end{equation}
\begin{algorithm}[hbt!]\caption{PFNN for the inverse source problem}\label{alg:inverse}
\begin{algorithmic}
\Ensure {Coarse grid $\{x_i\}_{i=1, \dots N}$ and data $\tilde{u}(x_i)$, for $x_i \in \Omega$.}
\State {Create grid $\{x^b_i\}_{i=1, \dots N'}$ and set the PFNN with nodes corresponding to $\{x^b_i\}$  and depth $M$.}
\State {Set number of training epochs $N$, initialize iterations, $n=0$.}
\State {Approximate the unknown source $\psi(x)$ with model ${\psi}_{\theta^{(n)}}(x)$, where $\theta^{(n)}$ denotes the set of unknown  parameters of the NN (weights and biases) at iteration $n$ of training.}
\While{$n \leq N$}
    \State {Step 1. Construct a PFNN, $PFNN(x;{\psi}_{\theta^{(n)}})$.}
    \State {Step 2. Use the PFNN output, $\hat{u}(x_i; {\psi}_{\theta^{(n)}})$ to calculate the model loss given by \eqref{inverse-loss}. }
    \State {Step 3. Train model and set $n=n+1$.}
\EndWhile \\
\Return {${\psi}_{\theta^{*}}(x)$}
\end{algorithmic}
\end{algorithm}
\begin{figure}[!ht]
\begin{center}
  \includegraphics[width = 0.9\textwidth]{PFNN_inverse.pdf} 
\end{center}
\caption{Schematic representation of Algorithm \ref{alg:inverse} to solve the inverse problem using the Potential FNN framework.}\label{fig:inverse}
\end{figure}
\par Training the model ${\psi}_{\theta}$ is done using a sparse grid of $u(x_i)$ values and we subsequently test the model on a larger grid over the domain $\Omega$. Hence, in this way, we essentially learn the source term and simultaneously the full solution $u(x), x \in \Omega$, by passing through the Potential Fredholm NN. The approach is detailed in Algorithm \ref{alg:inverse} and shown schematically in Fig. \ref{fig:inverse}. 
\par We highlight that the structure of the PFNN itself ensures that we are simultaneously accounting for the data loss, as well as ensuring that the model adheres to the physics of the problem. This is an important novelty of the proposed method: rather than considering an arbitrary neural network structure and calculating the residuals of the PDE, a neural network with a pre-determined, numerical-analysis based architecture is used to ensure that the functions passed through it adhere to the given physics of the problem (in our case the PDE). 



\section{Numerical Implementation}\label{numerics-section}
In this section, we detail the numerical implementation of the neural network construction for the examples analyzed above. To this end, it is important to note that the fundamental solutions both for the Poisson as well as the Helmholtz operators exhibit weak singularities which, although integrable, can cause issues during the numerical estimation of the integrals which depend on them. We describe how these are handled to ensure high accuracy is maintained throughout the domain and boundary. With these examples we aim to show in detail how the theoretical framework presented above can be used to construct the PFNNs and can create accurate and explainable neural network models, whose properties and performance can be understood through the lens of classical numerical analysis for the solution of both forward and inverse problems of elliptic PDEs.
\par The calculations in the examples that follow were done in \emph{Matlab}. %Numerical integration was performed using the \emph{SciPy} quad function (based on the \emph{QUADPACK} adaptive quadrature routine). 
\subsection{Solution of the Forward Problem}
\subsubsection{The Poisson PDE}
Recall the form of the BIE (\ref{BIE}). To construct the integral equation, we have $\frac{\partial \Phi(x, y)}{\partial n_y} = n_y \cdot \nabla_y\Phi(x,y) $, with $n_y = \frac{y}{|y|}$. Therefore:
\begin{equation}\notag 
    \nabla_y \Phi(x, y) = \left( \frac{y_1 - x_1}{2 \pi |x - y|^2}, \frac{y_2 - x_2}{2 \pi |x - y|^2} \right),
\end{equation}
and writing in terms of the arc-length parameterization we get:
\begin{equation}
    \frac{\partial \Phi(x, y(\theta_2))}{\partial n_y} = \frac{r_2^2 - r_1 r_2 \cos (\theta_1 - \theta_2)}{2 \pi |x - y|^2 |y|}.
\end{equation}
%Note that for $y \in \partial \Omega$, $r_2 = 1$, which simplifies further to:
%\begin{equation}
%    \frac{\partial \Phi(x, y(\theta_2))}{\partial n_y} = \frac{1 - r_1 %\cos(\theta_1 - \theta_2)}{2 \pi (1 + r_1^2 - 2r_1 \cos(\theta_1 - \theta_2))}.
%\end{equation
For the BIE in particular we have $x, y \in \partial \Omega$, and the kernel in the integral operator will become:
\begin{equation}\notag
    \frac{\partial \Phi(x, y(s))}{\partial n_y} = \frac{1 - \cos(\theta_1 - \theta_2)}{2 \pi (2 - 2\cos(\theta_1 - \theta_2))} = \frac{1}{4 \pi},
\end{equation}
and, finally, the integral term is given by: 
\begin{flalign}\label{poisson-fund}
     \int_{\Omega} \Phi(x, y) \psi(y) dy &= \int_0^{2\pi} \int_0^1 \frac{1}{2\pi} \ln |x - y| \psi(y) dy =  \notag \\ &=\int_0^{2\pi} \int_0^1 \frac{1}{2\pi} \ln \left( (r_1 \cos \theta_1 - r_2 \cos \theta_2)^2 + (r_1 \sin \theta_1 - r_2 \sin \theta_2)^2 \right)^{\frac{1}{2}}
    \psi(r_2, \theta_2) r_2 dr_2 d\theta_2.
\end{flalign}
Written out explicitly, the BIE becomes:
\begin{flalign}\label{poisson-ex}
    \beta(x) = 2 \Big( f(x) - \int_0^{2\pi} \int_0^1 \frac{1}{2\pi} \ln \big((\cos \theta_1 - r_2 \cos \theta_2)^2 + (\sin \theta_1 - r_2 \sin \theta_2)^2 \big)^{\frac{1}{2}} 
    &\psi(r_2, \theta_2) r_2 dr_2 d\theta_2 \Big)
    \notag \\ &- 2 \int_{\partial \Omega} \beta(\theta) \frac{1}{4\pi} d\theta,
\end{flalign}
and the final layer of the PFNN is as described in Proposition \ref{prop-poisson}. As we have noted, the double integral in \eqref{poisson-fund} is weakly singular at points within the integration domain. Hence, using naive numerical integration schemes may cause large errors. To account for this, we use an adaptive quadrature approach explicitly specifying the points at which singularities arise, i.e., at $r_2 = r_1$ and $\theta_2 = \theta_1$ (this specification can easily be implemented both in \emph{Matlab} as well as \emph{Python}). In this way, we compute the integral term required both for the BIE and for the final layer of the neural network in accordance to \eqref{potential-form-1}.  Finally, the term $\int_{\partial \Omega} \frac{1}{4\pi} \beta(y(s)) ds$ in \eqref{potential-form-1} is approximated with a simple Riemann sum on the selected grid that we use to estimate the boundary function $\beta(x)$.

Here, for our illustrations, we consider the following Poisson PDE:
 \begin{equation}
 \Delta u(x) = 2x_1,
     \label{ex1}
 \end{equation}
on the unit disc, ${\Omega} = \{x \in \mathbb{R}^2: x_1^2 + x_2^2 \leq 1 \}$ with boundary condition $f(x)=0$, for $x \in  \partial {\Omega}$, 
for which, an analytical solution exists, and it is given by: 
\begin{equation}\label{example-poisson}
u(x) = \frac{1}{4}x_1(x_1^2 + x_2^2 -1).
\end{equation}
We consider a $\phi-$grid for the BIE of size $N = 1000$ to ensure sufficiently accurate approximation of the boundary function $\beta(x_i),$ for $x_i = (1,\phi_i)$, and an $r-$ grid of size $100$. To show the effect of the number of hidden layers in the FNN on the overall error in the solution of the PDE, we use various layers selections $M$ in the estimation of the boundary function $\beta(x)$. The solution and error metrics $L_{\infty}$ and Mean Absolute Error (MAE) are given in Fig. \ref{fig:poisson_1}. 

