\section{The Poisson PDE}

The Poisson equation is given by:
\begin{equation}
    \Delta u(x) = \Psi_0(x), \quad x \in \Omega
\end{equation}
with boundary condition:
\begin{equation}
    u(x) = f(x), \quad x \in \partial \Omega.
\end{equation}

Throughout the calculations that follow, we will be considering a 3D spherical domain, with unit radius and the corresponding unit circle boundary. 

We know that the fundamental solution of the Laplace equation satisfies:
\begin{equation}
    \Delta_y \Phi(x, y) = \delta(x - y).
\end{equation}

We have the expression:
\begin{equation}
    \Phi(x, y) = \frac{1}{2\pi} \ln |x - y|, \quad \text{for} \ n = 2.
\end{equation}

By the classical theorem of potential theory, we have the following theorem:

\begin{theorem}
   For $x \in \partial \Omega$ and $n_x$ representing the outward normal to $\Omega$:

\begin{equation}
    \lim_{h \to 0^+} \int_{\partial \Omega} \beta(y(s)) \frac{\partial \Phi(x + h n_x, y(s))}{\partial n_y} ds = 
    \int_{\partial \Omega} \beta(y(s)) \frac{\partial \Phi(x, y(s))}{\partial n_y} ds - \frac{1}{2} \beta(x).
\end{equation} 

\end{theorem}


The double layer potential is given by:
\begin{equation}
    u(x) = \int_{\partial \Omega} \beta(y(s)) \frac{\partial \Phi(x, y(s))}{\partial n_y} ds + \int_{\Omega} \Phi(x, y) \Psi(y) dy,
\end{equation}
where $\beta$ is a density defined on the boundary $\partial \Omega$, such that:
\begin{equation}
    f(x) = \int_{\partial \Omega} \beta(y(s)) \frac{\partial \Phi(x, y(s))}{\partial n_y} ds + 
    \int_{\Omega} \Phi(x, y) \Psi(y) dy + \frac{1}{2} \beta(x), \quad \text{for} \ x \in \partial \Omega.
\end{equation}

\subsection{Solve the Boundary Integral Equation}
The boundary integral equation is defined as:
\begin{equation}
    \frac{\partial \Phi(x, y(s))}{\partial n_y} = \nabla_y \Phi(x - y) \cdot v(y).
\end{equation}

Consider:
\begin{equation}
    x = (x_1, x_2) = (r_1 \cos \theta_1, r_1 \sin \theta_1), \quad y = (y_1, y_2) = (r_2 \cos \theta_2, r_2 \sin \theta_2).
\end{equation}

Then:
\begin{equation}
    \Phi(x - y) = \frac{1}{2 \pi} \ln \left( (x_1 - y_1)^2 + (x_2 - y_2)^2 \right)^{\frac{1}{2}}.
\end{equation}

Taking the derivative yields:
\begin{equation}
    \frac{\partial}{\partial y_1} \Phi(x - y) = \frac{1}{2 \pi} \frac{y_1 - x_1}{(x_1 - y_1)^2 + (x_2 - y_2)^2}.
\end{equation}

Therefore:
\begin{equation}
    \nabla_y \Phi(x - y) = \left( \frac{y_1 - x_1}{2 \pi |x - y|^2}, \frac{y_2 - x_2}{2 \pi |x - y|^2} \right).
\end{equation}

The outward normal is given by:
\begin{equation}
    n(y) = \frac{y}{|y|} = \left( \frac{y_1}{|y|}, \frac{y_2}{|y|} \right).
\end{equation}

\subsection{Further Simplifications}
The expression for $\frac{\partial \Phi(x, y(s))}{\partial n_y}$ simplifies to:
\begin{equation}
    \frac{\partial \Phi(x, y(s))}{\partial n_y} = \frac{r_2^2 - r_1 r_2 \cos (\theta_1 - \theta_2)}{2 \pi |x - y|^2 |y|}.
\end{equation}

Note that for $y \in \partial \Omega$, $r_2 = 1$, which simplifies further to:
\begin{equation}
    \frac{\partial \Phi(x, y(s))}{\partial n_y} = \frac{1 - r_1 \cos(\theta_1 - \theta_2)}{2 \pi (1 + r_1^2 - 2r_1 \cos(\theta_1 - \theta_2))}.
\end{equation}

For $x, y \in \partial \Omega$, the boundary integral equation simplifies to:
\begin{equation}
    \frac{\partial \Phi(x, y(s))}{\partial n_y} = \frac{1 - \cos(\theta_1 - \theta_2)}{2 \pi (2 - 2\cos(\theta_1 - \theta_2))} = \frac{1}{4 \pi}.
\end{equation}

\subsection{Poisson Source Term}
We now consider the term arising from the Poisson source term:
\begin{equation}
    \int_{\Omega} \Phi(x, y) \Psi_0(y) dy = \int_0^{2\pi} \int_0^1 \frac{1}{2\pi} \ln |x - y| \Psi_0(y) dy.
\end{equation}

The boundary integral equation becomes:
\begin{equation}
    f(x) - \int_{\Omega} \Phi(x, y) \Psi_0(y) dy = \int_{\partial \Omega} \beta(y(s)) \frac{\partial \Phi(x, y(s))}{\partial n_y} ds + \frac{1}{2} \beta(x).
\end{equation}

\begin{equation}
    = \int_0^{2\pi} \int_0^1 \frac{1}{2\pi} \ln \left( (r_1 \cos \theta_1 - r_2 \cos \theta_2)^2 + (r_1 \sin \theta_1 - r_2 \sin \theta_2)^2 \right)^{\frac{1}{2}}
    \Psi_0(r_2, \theta_2) r_2 dr_2 d\theta_2,
\end{equation}
where the $r_2$ term is the Jacobian from the transformation to polar coordinates.

The BIE, with $x, y \in \partial \Omega$, now becomes:
\begin{flalign}
    f(x) - &\int_{\Omega} \Phi(x, y) \Psi_0(y) dy = \int_{\partial \Omega} \beta(y(s)) \frac{\partial \Phi(x, y(s))}{\partial n_y} ds + \frac{1}{2} \beta(x). \notag \\ &
\Rightarrow \beta(x) = 2 \left( f(x) - \int_{\Omega} \Phi(x, y) \Psi_0(y) dy \right) - 2 \int_{\partial \Omega} \beta(y(s)) \frac{\partial \Phi(x, y(s))}{\partial n_y} ds.
\end{flalign}

This expression becomes:
\begin{flalign}
    \beta(x) = 2 \Big( f(x) - \int_0^1 \int_0^{2\pi} \frac{1}{2\pi} \ln \left[ (\cos \theta_1 - r_2 \cos \theta_2)^2 + (\sin \theta_1 - r_2 \sin \theta_2)^2 \right]^{\frac{1}{2}} 
    &\Psi_0(r_2, \theta_2) r_2 dr_2 d\theta_2 \Big)
    \notag \\ &- 2 \int_{\partial \Omega} \beta(\theta) \frac{1}{4\pi} d\theta.
\end{flalign}

Notice that the kernel is non-expansive, as required under the Fredholm Neural Network framework. Solving the BIE is the first step in the solution process. We then proceed with the calculation of the double layer potential in order to retrieve the solution of the PDE.


\subsection{Limit - Informed Neural Network}

Our approach relies on the underlying mathematical computations that show the dynamics of the double layer potential as we approach the boundary. We give detailed computations below, proving the formula used to construct the neural networks.

Let:
\begin{equation}
    P(x) = \int_{\partial \Omega} \beta(y(s)) \frac{\partial \Phi(x, y(s))}{\partial n_y} ds + \int_{\Omega} \Phi(x, y) \Psi(y) dy,
\end{equation}
and we have:
\begin{equation}
    P(x) = \int_{\partial \Omega} \left[ \beta(y(s)) - \beta(x_0) \right] \frac{\partial \Phi(x, y(s))}{\partial n_y} ds + \beta(x_0) + \int_{\Omega} \Phi(x, y) \Psi(y) dy.
\end{equation}

Where we have used the fact that:
\begin{equation}
    \int_{\partial \Omega} \frac{\partial \Phi(x, y(s))}{\partial n_y} ds = 1, \quad \text{for} \ x \in \Omega.
\end{equation}

Similarly, for $x_0 \in \partial \Omega$ such that $x \to x_0$:
\begin{equation}
    P(x_0) = \int_{\partial \Omega} \left[ \beta(y(s)) - \beta(x_0) \right] \frac{\partial \Phi(x_0, y(s))}{\partial n_y} ds + \frac{1}{2} \beta(x_0) + \int_{\Omega} \Phi(x_0, y) \Psi_0(y) dy,
\end{equation}
where we have used that:
\begin{equation}
    \int_{\partial \Omega} \frac{\partial \Phi(x, y(s))}{\partial n_y} ds = \frac{1}{2}, \quad \text{for} \ x \in \partial \Omega.
\end{equation}

Hence:
\begin{equation}
    P(x) - P(x_0) = \int_{\partial \Omega} \left[ \beta(y(s)) - \beta(x_0) \right] 
    \left( \frac{\partial \Phi(x, y(s))}{\partial n_y} - \frac{\partial \Phi(x_0, y(s))}{\partial n_y} \right) ds
    + \frac{1}{2} \beta(x_0) + \int_{\Omega} \left[ \Phi(x, y) - \Phi(x_0, y) \right] \Psi_0(y) dy
\end{equation}

and therefore:
\begin{flalign}
    P(x) = \int_{\partial \Omega} [ \beta(y(s)) - & \beta(x_0) ] 
    \left( \frac{\partial \Phi(x, y(s))}{\partial n_y} - \frac{\partial \Phi(x_0, y(s))}{\partial n_y} \right) ds
    + \frac{1}{2} \beta(x_0) \notag \\ &+ \int_{\partial \Omega} \beta(y(s)) \frac{\partial \Phi(x_0, y(s))}{\partial n_y} ds + \int_{\Omega} \Phi(x, y) \Psi_0(y) dy + P(x_0).
\end{flalign}

The equation can be simplified to:
\begin{equation}
    P(x) = \int_{\partial \Omega} \left[ \beta(y(s)) - \beta(x_0) \right] 
    \left( \frac{\partial \Phi(x, y(s))}{\partial n_y} - \frac{1}{4 \pi} \right) ds
    + \frac{1}{2} \beta(x_0) + \int_{\partial \Omega} \frac{1}{4\pi} \beta(y(s)) ds + \int_{\Omega} \Phi(x, y) \Psi_0(y) dy.
\end{equation}


\section{The Semi-Linear elliptic PDE}\label{app-b}

We consider the semi-linear PDE of the form:
\begin{equation}
\Delta u(x) - \lambda u(x) = \psi_0(x), \quad x \in \Omega
\end{equation}
\begin{equation}
u(x) = f(x), \quad x \in \partial \Omega
\end{equation}

We know that the fundamental solution of the linear operator $\mathcal{L} := \Delta - \lambda$ solving the equation
\begin{equation}
\mathcal{L} \Phi(x,y) = \delta(x - y)
\end{equation}
The fundamental solution is given by:
\begin{equation}
\Phi(x,y) = -\frac{1}{2\pi} K_0\left( \sqrt{\lambda} |x - y| \right),
\end{equation}
where $K_0$ is the modified Bessel function of the second kind. We know that the BIE to be solved is given by:
\begin{equation}
\beta(x) = 2\left( f(x) - \int_{\Omega} \Phi(x,y) \psi_0(y) dy \right) - 2 \int_{\partial \Omega} \beta(y) \frac{\partial \Phi(x,y)}{\partial n_y} ds.
\end{equation}

Hence, for $x = (x_1, x_2)$, $y = (y_1, y_2)$, we have that:
\begin{equation}
\frac{\partial \Phi(x,y)}{\partial y_1} = -\frac{\sqrt{\lambda} (y_1 - x_1)}{2\pi |x - y|} K_0' \left( \sqrt{\lambda} |x - y| \right)
\end{equation}
and similarly for the derivative with respect to $y_2$. Therefore, we obtain:
\begin{equation}
\frac{\partial \Phi(x,y)}{\partial n_y} = -\frac{\sqrt{\lambda} K_0' \left( \sqrt{\lambda} |x - y| \right)}{2\pi |x - y|} \left[ y_1 (y_1 - x_1) + y_2 (y_2 - x_2) \right]
\end{equation}

Firstly, note that we consider $|y| = 1$, since we are integrating along the boundary. Furthermore, from the properties of the Bessel function, we know that:
\begin{equation}
K_0'(x) = -K_1(x).
\end{equation}

As a next step, we want to ensure that numerical integration can be carried out. For this reason, the kernel can also be written as:
\begin{equation}
\frac{\partial \Phi(x,y)}{\partial n_y} = \frac{\sqrt{\lambda} K_1 \left( \sqrt{\lambda} |x - y| \right)}{2\pi |x - y|^2} \left( y_1 (y_1 - x_1) + y_2 (y_2 - x_2) \right)
\end{equation}
\begin{equation}
= \frac{\sqrt{\lambda} K_1 \left( \sqrt{\lambda} |x - y| \right)}{4\pi |x - y|}
\end{equation}
for $x,y \in \partial \Omega$.

As an important final step, we must examine the behavior of the kernel as $x \to y$ where the Bessel function exhibits a singularity. In this case, we have that:
\begin{equation}
K_0(z) \sim - \ln(z), \quad \text{(see e.g. \cite{kropinski2011fast})}.
\end{equation}
Then
\begin{equation}
\Phi(x,y) \sim \frac{1}{2\pi} \ln \left( \sqrt{\lambda} |x - y| \right),
\end{equation}
and so:
\begin{equation}
\frac{\partial \Phi(x,y)}{\partial n_y} = \frac{y_1 (y_1 - x_1) + y_2 (y_2 - x_2)}{2\pi |x - y|^2} = \frac{1}{4\pi},
\end{equation}
for $|x - y| \to 0$, with $x,y \in \partial \Omega$.

\subsection{Handling the discontinuity}

From the underlying potential theory, we know that the singularity creates a jump discontinuity. To see how this affects the limit-based results, we consider the following calculations:

\begin{itemize}

\item[{\it Step 1.}] Let $x \in \Omega$. Fix $\epsilon > 0$ such that $B(x,\epsilon) \subset \Omega$. In $\Omega - B(x,\epsilon)$, $\Phi(x,y) = \Phi(x-y)$ is smooth.
\begin{equation}
0 = \int_{\partial \Omega} \mathcal{L}\Phi(x-y) ds(y) = \int_{\Omega - B(x,\epsilon)} \Delta_y \Phi(x-y) dy - \lambda \int_{\partial B(x,\epsilon)} \frac{\partial \Phi(x-y)}{\partial n_y} ds(y).
\end{equation}
By the Divergence Theorem, this becomes:
\begin{eqnarray}
0 &=& \int_{\partial \Omega} \frac{\partial \Phi(x-y)}{\partial n_y} ds(y) - \lambda \int_{\partial B(x,\epsilon)} \frac{\partial \Phi(x-y)}{\partial n_y} ds(y) \\
&=& \int_{\partial \Omega} \frac{\partial \Phi(x-y)}{\partial n_y} ds(y) + \int_{\partial B(x,\epsilon)} \frac{\partial \Phi(x-y)}{\partial n_y} ds(y) - \int_{\Omega - B(x,\epsilon)} \Phi(x-y) dy.
\end{eqnarray}

Considering the second term, the outer unit normal to $\Omega - B(x,\epsilon)$ is
\begin{equation}
n_y = \frac{x - y}{|x - y|}, \quad \text{so,}
\end{equation}
\begin{equation}
\frac{\partial \Phi(x,y)}{\partial n_y} = \nabla_y \Phi(x,y) \cdot \frac{x - y}{|x - y|} = -\frac{\sqrt{\lambda} K_0 \left( \sqrt{\lambda} |x - y| \right)}{2\pi |x - y|^2} \left[ (y_1 - x_1)^2 + (y_2 - x_2)^2 \right].
\end{equation}

However, since $K_0(z) \sim \ln(z)$ as $z \to 0$, in $B(x,\epsilon)$, we have:
\begin{equation}
\frac{\partial \Phi(x,y)}{\partial n_y} \approx \frac{\sqrt{\lambda}}{2\pi} \left[ -\ln(\sqrt{\lambda} |x - y|) \right]' = -\frac{1}{2\pi |x - y|}.
\end{equation}

Thus, we obtain:
\begin{equation}
\int_{\partial \Omega} \frac{\partial \Phi(x-y)}{\partial n_y} ds(y) \approx -1.
\end{equation}

Therefore, from the original expression, we have:
\begin{equation}
\int_{\partial \Omega} \frac{\partial \Phi(x-y)}{\partial n_y} ds(y) = 1 + \int_{\Omega} \lambda \Phi(x-y) dy.
\end{equation}

\item[{\it Step 2.}] Now consider $x \in \partial \Omega$.

We know that $\frac{\partial \Phi(x,y)}{\partial n_y}$ is not defined for $x = y$. Fix $x \in \partial \Omega$ and consider $B(x,\epsilon)$ and $\Omega_\epsilon \equiv \Omega - \left( \Omega \cap B(x,\epsilon) \right)$. Furthermore, let $\Xi_\epsilon = \left\{ y \in \partial B(x,\epsilon) : \nu(y) \cdot (x - y) < 0 \right\}$ and $\tilde{\Xi}_\epsilon = \partial \Omega_\epsilon \cap \Xi_\epsilon$. Then:
\begin{eqnarray}
0 &=& \int_{\partial \Omega_\epsilon} \mathcal{L}\Phi(x-y) dy = \int_{\Omega_\epsilon} \Delta_y \Phi(x-y) dy - \int_{\partial \Omega_\epsilon} \frac{\partial \Phi(x-y)}{\partial n_y} ds(y) \\
&=& \int_{\partial \Omega} \frac{\partial \Phi(x-y)}{\partial n_y} ds(y) + \int_{\tilde{\Xi}_\epsilon} \frac{\partial \Phi(x-y)}{\partial n_y} ds(y) - \int_{\Omega_\epsilon} \Phi(x-y) dy.
\end{eqnarray}

In the above, $n_y$ is the outer unit normal to $\Omega_\epsilon$. For $y \in \tilde{\Xi}_\epsilon$, $n(y) = \frac{x - y}{|x - y|}$.

Similar steps as before give:
\begin{equation}
\int_{\tilde{\Xi}_\epsilon} \frac{\partial \Phi(x-y)}{\partial n_y} ds(y) \approx \int_{\tilde{\Xi}_\epsilon} \frac{-1}{2\pi |x - y|} ds(y) \approx -\frac{1}{2\pi \epsilon} \left( \frac{1}{2} 2\pi \epsilon \right) = -\frac{1}{2}.
\end{equation}

Therefore, we obtain:
\begin{equation}
\int_{\partial \Omega} \frac{\partial \Phi(x-y)}{\partial n_y} ds(y) = 1 + \int_{\Omega} \lambda \Phi(x-y) dy.
\end{equation}

\end{itemize}

\subsection{The Limit - Informed Calculations}

As above, the double layer potential can be written as:
\begin{flalign}
\tilde{u}(x) = \int_{\partial \Omega} [\beta(y(s)) - \beta(x_0)] 
\left[ \frac{\partial \Phi(x,y(s))}{\partial n_y} - \frac{\partial \Phi(x_0, y(s))}{\partial n_y} \right] ds
+ \beta(x) ( C_1(x) - & C_2(x_0))  
+ \int_{\Omega} \Phi(x, y) \psi_0(y) dy \nonumber \\
+& \int_{\partial \Omega} \beta(y(s)) \frac{\partial \Phi(x, y(s))}{\partial n_y} ds
\end{flalign}
where:
\begin{eqnarray}
C_1(x) - C_2(x_0) = \int_{\partial \Omega} \frac{\partial \Phi(x - y)}{\partial n_y} ds(y) 
- \int_{\partial \Omega} \frac{\partial \Phi(x_0 - y)}{\partial n_y} ds(y) = \frac{1}{2} + \int_{\Omega} \lambda \Phi(x - y) dy - \int_{ \Omega} \lambda \Phi(x_0 - y) dy.
\end{eqnarray}


This will affect the final bias term, compared to the simple Laplacian example.

\end{comment}

