\section{Prerequisites from hyperbolic geometry}\label{sec-pre on hyp geo}

\subsection{Some definitions from coarse geometry}
For various notions and results in this section one is refered to \cite{gromov-hypgps} or
 \cite[Chapters I.1, III.H]{bridson-haefliger}. All our metric spaces are geodesic metric spaces
 and most of the time we work with graphs. Graphs are always assumed to be connected and the edge
 lengths are assumed to be $1$ so that these are geodesic metric spaces.

 A {\em geodesic segment} joining $x$ and $y$ in a metric space $X$ is denoted by $[x,y]_X$
 (or simply $[x,y]$ when $X$ is understood) and this is the image of an isometric embedding
 $\alpha: [0, d(x,y)]\map X$ with $\alpha(0)=x$ and $\alpha(d(x,y))=y$. For two subsets
 $A,B$ of a metric space $X$, the {\em Hausdorff distance} between $A$ and $B$ is
 $Hd(A,B):=inf~\{r\geq 0:A\sse N_r(B),B\sse N_r(A)\}$.
 A metric space $X$ is said to be {\em proper} if closed and bounded subsets of $X$ are compact.


Suppose $f:(X,d_X)\map(Y,d_Y)$ is a map between two metric spaces. Let $k\ge1$ and $\ep\ge0$. We say that $f$ is a
$(k,\epsilon)$-{\em quasiisometric (qi) embedding} (or just a qi embedding when the constants are
not important) if $$\frac{1}{k}d_X(x,x')-\ep\le d_Y(f(x),f(x'))\le kd_X(x,x')+\ep.$$
When the map $f$ is, moreover, an inclusion (e.g. when $X$ is a subgraph of $Y$) then we say that
$X$ is qi embedded in $Y$. A quasiisometric embedding $f:X\map Y$ is called a {\em quasiisometry}
if there is $R\geq 0$ such that $N_R(f(X))=Y$.
A map $\al:I\sse\R\map X$ is said to be $k$-{\em quasigeodesic} if it is $k$-qi embedding
where $I$ is an interval in $\mathbb R$. We note that in this case $\al$ is a geodesic if
$k=1, \epsilon =0$. When, moreover, $I$ is of the form $(-\infty, a]$ or $[a,\infty)$ for
some $a\in \mathbb R$ then $\al$ is called a {\em quasigeodesic ray} and when $I=\mathbb R$ then
it is called a {\em quasigeodesic line}.

\subsection{Hyperbolic metric spaces and hyperbolic groups}
We assume that the reader is familiar with hyperbolic spaces (and groups) and their boundaries
(see \cite{gromov-hypgps}, \cite{abc}, \cite[Chapter III.H]{bridson-haefliger} and \cite{GhH}).
In this section we briefly mention some of the results that we will need later in the paper.
Proofs of most of the results are omitted and references are given.

We recall that a geodesic metric space $X$ is  $\dl$-hyperbolic for some $\dl\geq 0$
(or just hyperbolic when the constant is not important) if the geodesic triangles are $\dl$-slim.
A finitely generated group $G$ is hyperbolic if one (any) of its Cayley graph with respect to
some (any) finite generating set is hyperbolic. In most cases, a choice of a generating set is
assumed and then the corresponding Cayley graph is denoted by $\Gamma_G$ or simply $\Gamma$.

%\smallskip
\subsubsection{Boundary at infinity}
Suppose $X$ is a hyperbolic metric space.
Two (quasi)geodesic rays $\al$ and $\bt$ in $X$  are said to be {\em asymptotic} if their
Hausdorff distance is finite. This defines an equivalence relation on the set of (quasi)geodesic rays.
The set of all equivalence classes of such rays is called the (quasi)geodesic boundary of $X$
and is denote by $\pa X$ (or $\pa_q X$ for the case of quasigeodesic boundary).

For a (quasi)geodesic ray $\al$, its equivalence class in $\pa X$ or $\pa_q X$ is denoted
by $\al(\infty)$. The natural map $\pa X\map \pa_q X$ is injective and it is a bijection for
proper hyperbolic spaces.\smallskip

{\bf Convention.} {\em From now, we shall abuse notation and use just $\pa X$ in stead of
$\pa_q X$ even in case of nonproper spaces, e.g. coned-off graphs of Cayley graphs.}\smallskip


However, in general, one can define a topology on $\bar{X}=X\cup \pa X$. See \cite[Chapter III.H, p. $432$]{bridson-haefliger}, \cite[p. $49$]{abc}. As we do not need
this explicitly anywhere in the paper we skip its definition and instead mention
various features of it through many lemmas and propositions. For instance we will make use of
the following lemma repeatedly in the paper`.

\begin{lemma}
Suppose we have an isometry $f:X\map X$ of hyperbolic metric space $X$. Then $f$ extends to a
homeomorphism $\bar{f}: \bar{ X}\map \bar{X}$.

This defines an action of $Isom(X)$ $-$ the group of isometries of $X$, on $\bar{X}$.
\end{lemma}
 The restriction of $\bar{X}$ in the above lemma to $\pa X$ is denoted by $\pa f$.
As quasiisometries are not continuous in general one cannot expect the analogue of the above
lemma to hold in that generality. However, each quasiisometry between hyperbolic metric
spaces induce a homeomorphism on the boundary. Using this one shows that boundary of a
hyperbolic group is well defined up to homeomorphism. Hence, for a hyperbolic group $G$,
we shall denote by $\pa G$ the boundary of any Cayley graph $\Gamma_G$ of $G$.
Moreover, the natural $G$-action on $\Gamma_G$ by isometries induces an action on
$\pa G$ through homeomorphisms.

\begin{defn}
Suppose $X$ is a hyperbolic metric space and $f:X\map X$ is an isometry.
For any $x\in X$ let $\mathcal O_x:\mathbb Z \map X$ be the map $n\mapsto f^n(x)$.

(1) We say that $f$ is an {\em elliptic} isometry of $X$ if the image of the map $\mathcal O_x$ has finite
diameter in $X$ for some (any) $x\in X$..

(2) We say that $f$ is a {\em loxodromic} isometry if for some (any) $x\in X$, the map
$\mathcal O_x$ is qi embedding of $\mathbb Z$ into $X$.
\end{defn}


\begin{lemma}{\em (Characteristics of loxodromic isometries)}\label{char loxo isom}
(a) Suppose $f$ is a loxodromic isometry of a hyperbolic metric space $X$. Let $x\in X$.
Then the following hold.

(1) $f$ has exactly two  fixed points in $\pa X$, namely the limits $\lim_{n\map \infty} f^{\pm n}(x)$
{\em (which we denote by $f^{\pm \infty}$ respectively)}.

(2) Given $\xi \in \pa X$, if $\xi\neq f^{-\infty}$ then $\lim_{n\map \infty} f^n.\xi= f^{\infty}$.

\smallskip
(b) Suppose $f$ is a nonelliptic isometry of a hyperbolic metric space $X$ such that $f$ has precisely
two fixed points in $\pa X$. Then $f$ is a loxodromic isometry.
\end{lemma}

\begin{defn}
Suppose $f,g$ two loxodromic isometries on a hyperbolic metric space $X$. We say that they are
{\em independent} loxodromic isometries if they have no common fixed points in $\pa X$.
\end{defn}

\begin{lemma}\label{lem-finding free qc}
Suppose $X$ is a hyperbolic metric space which may not be proper, and suppose $f,g$ are two independent loxodromic isometries
on $X$. Then there is $m\in\N$ such that the group $H=\lgl f^m,g^m\rgl \simeq \mathbb F_2$. Moreover, any orbit map
$H \map X$ is quasiisometric embedding.
\end{lemma}

We note that a hyperbolic group $G$ is said to be {\em nonelementary} if $G$ is not virtually cyclic.
\begin{lemma}\textup{(\cite[Lemma $3.10$]{bridson-haefliger}, \cite[Corollary $8.2.G$]{gromov-hypgps})}\label{lem-infinite ele loxo}
In a hyperbolic group $G$, any infinite order element $g$ acts on a Cayley graph of $G$ as a loxodromic isometry.

In a nonelementary hyperbolic group there are infinite order elements (which we call independent infinite order elements)
that induce two independent loxodromic isometries on a Cayley graph of $G$.
\end{lemma}
The following lemma is quite standard. But we could not find an explicit reference. Therefore, we
give a sketch of proof for it.


\begin{lemma}\label{lemma lox}
Suppose $f$ is an isometry of a hyperbolic metric space $X$ such that $f$ is not an elliptic
isometry and $f$ has at least two fixed points in $\partial X$. Then $f$ is loxodromic.
\end{lemma}
{\em Sketch of proof:} Let $\xi, \xi'\in \pa X$ be two points fixed by $f$.
We look at the union of all (uniform) quasigeodesics lines (see \cite[Lemma 2.4]{pranab-mahan})
in $X$ connecting $\xi, \xi'$. This is a quasiconvex set, say $A$, in $X$.
A small neighbourhood of $A$ in $X$ is path connected and with the induced path metric
from $X$ it is qi embedded in $X$ (see \cite[Lemma 1.97]{ps-kap}). Let $Y$ denote this
small neighbourhood of $A$ in $X$.
One then sees that the infinite cyclic group $\lgl f\rgl$ acts metrically properly and
coboundedly on $Y$ and completes the proof by using a version of Švarc--Milnor lemma
 (see \cite[Lemma 1.32]{ps-kap}).
\qed



\subsubsection{Limit sets}
\begin{defn}
Suppose $X$ is a hyperbolic metric space and $A\subset X$.
A point $\xi\in \pa X$ is called a {\em limit point} of $A$ if there is a sequence of points
$\{x_n\}$ in $A$ such that $\lim_{n\map \infty} x_n =\xi$ (in the topology of $\bar{X}$).


The limit set of $A$ in $\pa X$ is the set of all limit points of $A$.


If $\mathcal G$ is a group of isometries on $X$ then the limit set of $\mathcal G$
is the limit set of any orbit $\mathcal G.x$ where $x\in X$.

If $G$ is a hyperbolic group and $A\subset G$, $\Lambda_G(A)$ or simply $\Lambda(A)$
denotes the limit set of $A$ in $\pa G$ where $\pa G$ is understood to be the boundary
of a Cayley graph of $G$.
\end{defn}
It is not hard to see that $\Lambda_G(X)$ in the above definition is independent of $x\in X$.
The following are some common properties of limit sets of groups of isometries.

The following Lemma \ref{limit set basic} $(1)$ and $(2)$ are straightforward consequences of the version of Arzelà--Ascoli theorem as in \cite[Lemma $3.10$, I.3]{bridson-haefliger}; see the proof of \cite[Lemma $3.1$, III.H]{bridson-haefliger} for instance. Moreover, $(3)$ easily follows from $(2)$.

%\RED{reference?}
\begin{lemma}  \label{limit set basic}
(1) If $X$ is a proper hyperbolic metric space then for any set $A\subset X$,
$\Lambda_X(A)\neq \emptyset$ if and only if $A$ has infinite diameter.

In particular, for a hyperbolic group $G$, and a subset $A\subset G$,
$\Lambda_G(A)\neq \emptyset $ if and only if $A$ is infinite.

(2) Suppose $X$ is any hyperbolic metric space and $A,B$ are two subsets of $X$.
If $Hd(A,B)<\infty$ then $\Lambda_X(A)=\Lambda_X(B)$.

(3) Suppose $G$ is a hyperbolic group. Then the following hold:

(i) If $K<H$ are some subgroups of $G$ then $[H:K]<\infty$ implies
$\Lambda(K)=\Lambda(H)$.

(ii) For any $H<G$ and $x\in G$, $x\Lambda(H)=\Lambda(xH)=\Lambda(H^x)$ where $H^x$ denotes the conjugate of $H$ by $x$.
\end{lemma}

%\RED{reference?}
\begin{lemma}\textup{(\cite[Theorem $5.1$]{coornaert-mea})}\label{limit set minimal}
(1) Suppose $X$ is a hyperbolic metric space, and $\mathcal G$ is a group acting
properly discontinuously by isometries on $X$. Then $\Lambda_X(\mathcal G)$ is the
minimal, closed, $\mathcal G$-invariant subset of $\pa X$.

(2) Suppose $G$ is a hyperbolic group and $H$ is an infinite subgroup of $G$.
Then $\Lambda_G(H)$ is the minimal, closed, $H$-invariant subset of $\pa G$.

In particular, any $G$-orbit on $\pa G$ is dense in $\pa G$.
\end{lemma}



\section{Quasiconvex subgroups of hyperbolic groups}\label{sec-qc subgroups}
In this section we recall various results on quasiconvex subgroups of hyperbolic groups.
We recall that in a hyperbolic metric space $X$, a subset $A$ is called $k$-{\em quasiconvex}
for some $k\geq 0$ if for all $x,y\in A$ and all geodesic
$\gamma$ in $X$ joining $x,y$ we have $\gamma \subset N_k(A)$. When the constant $k$ is not
important, we say that $A$ is quasiconvex in $X$.
A subgroup $H$
of a hyperbolic group $G$ is said to be quasiconvex if it is quasiconvex in some (any)
Cayley graph of $G$. The following proposition summarizes some of the basic properties
of quasiconvex subgroups of hyperbolic groups which will be needed later.


\begin{prop}\label{qc prop}
Suppose $G$ is a hyperbolic group.
\begin{enumerate}
\item \textup{(\cite[Lemma $3.6$]{bridson-haefliger})} A subgroup $H$ is quasiconvex if and only if $H$ is a finitely generated, qi embedded subgroup of $G$.
In this case, $H$ is also hyperbolic. Quasiconvexity is independent of generating sets of $H$
and $G$.
\item Finite subgroups of $G$ are quasiconvex in $G$. Also, finite index subgroups of $G$
are quasiconvex in $G$.
\item Any cyclic subgroup of $G$ is qi embedded and hence quasiconvex.
If $g\in G$ is of infinite order then $g^{\pm \infty}=\lim_{n\map \pm \infty}g^n$ are the
unique fixed points of $g$ in $\pa G$ and $\Lambda_G(\lgl g\rgl)=\{g^{\pm \infty}\}$.
\item \textup{(\cite{GMRS})} If $H$ is quasiconvex in $G$ then $H$ has finite index in $Comm_G(H)$.
\item If $g,h\in G$ are two infinite order elements then either $\Lambda_G(\lgl g\rgl)=\Lambda_G(\lgl h\rgl)$
or $\Lambda_G(\lgl g\rgl)\cap \Lambda_G(\lgl h\rgl)=\emptyset$.

\item If $g,h \in G$ are two infinite order elements with different fixed points in $\pa G$,
then there is $n\in \N$ such that $\lgl g^n, h^n\rgl\isom \mathbb F_2$ is a qi embedded
subgroup of $G$.

If $G$ is nonelementary there are such pairs of infinite order elements.
\item Suppose $K<H<G$. If $H$ is quasiconvex in $G$ and $K$ is quasiconvex in $H$ then $K$
is quasiconvex in $G$.

If $K$ has finite index in $H$ then $K$ is quasiconvex in $G$ if and only if $H$ is quasiconvex in $G$.
\item \textup{(cf. \cite[Proposition $3$]{short}, \cite[Lemma $2.6$]{GMRS})}
Suppose $H_1, H_2$ are two quasiconvex subgroup of $G$. Then so is $H_1\cap H_2$.

Moreover, in this case, $\Lambda_G(H_1)\cap \Lambda_G(H_2)=\Lambda_G(H_1\cap H_2)$.
\item \textup{(\cite[Theorem $1.7$, III.H]{bridson-haefliger})}
Given $k\geq 0$ and $\delta \geq 0$ there is $D\geq 0$ such that the following holds:

Suppose $H$ is a $k$-quasiconvex subgroup of a $\delta$-hyperbolic group $G$ and
$\xi_1, \xi_2\in \Lambda_G(H)$ are two distinct points. Then for any geodesic line $\gamma$
in $\Gamma_G$ joining $\xi_1, \xi_2$, $\gamma \subset N_D(H)$.

\item \textup{(\cite{GMRS}[Lemma $2.9$])}
Suppose $G$ is a hyperbolic group and $H$ is a quasiconvex subgroup of $G$ such that
$\Lambda_G(H)=\pa G$. Then $H$ has finite index in $G$.
\end{enumerate}
\end{prop}




