\begin{lemma}\label{prop-finite-union-nowheredense}
Let $G$ be a nonelementary hyperbolic group. Let $H$ be an infinite index, quasiconvex
subgroup of $G$. Then $\Lambda_G(H)$ is nowhere dense in $\pa G$.
\end{lemma}
\begin{proof}
Without loss of generality both $G$ and $H$ are infinite groups. We prove the contrapositive statement.
Suppose $U\subset \Lambda_G(H)$ is a nonempty open subset of $\pa G$. Then
the set $V=\bigcup_{h\in H}h.U$ is an open and $H$-invariant subset of $\Lambda_G(H)$.
Also $V$ is an open subset of $\pa G$. Thus $\Lambda_G(H)\setminus V$ is an $H$-invariant
closed subset of $\Lambda_G(H)$. As $\Lambda_G(H)$ is the minimal, closed, $H$-invariant
subset of $\pa G$ (Lemma \ref{limit set minimal} $(2)$), and $U\neq \emptyset$ it follows
that $V=\Lambda_G(H)$ and it is an open subset of $\pa G$.

Now, as $H$ is an infinite hyperbolic group there is an infinite order element, say, $h\in H$.
Let $\xi \in \pa G$ be any element other than $h^{\pm \infty}$. Such a $\xi$ exists by
Proposition \ref{qc prop}(10) for otherwise $H$ will be of finite index in $G$. Now,
$h^n.\xi\map h^{\infty}$ as $n \map \infty$ by Lemma \ref{char loxo isom} $(2)$.
As $V$ is an open neighbourhood of $h^{\infty}$ in $\pa G$,
for all large $n$, we have $h^n.\xi \in V$. As $V$ is $H$-invariant it follows that $\xi\in V$.
Thus $V=\pa G$. Hence, $H$ has finite index in $G$ by Proposition \ref{qc prop}(10).
\end{proof}


As the topology on $\pa G$ makes it into a compact metrizable space, the Baire category theorem
gives the following immediate corollary.


\begin{cor}\label{cor-baire category}
Let $m\in\N$. Suppose $G$ is a hyperbolic group and $\{H_1, H_2, \cdots, H_m\}$ is a finite number of infinite index
quasiconvex subgroups of $G$. Then for any finite subset $S\sse G$, the set $\bigcup _{g\in S,~ 1\leq i\leq m} \Lambda_G(g H_i)$
is nowhere dense in $\pa G$. In particular, it is a proper subset of $\pa G$.
\end{cor}

The following result easily follows from \cite[lemma $1.2$]{GMRS}. However, for completeness we give a different proof. We refer the reader to Section \ref{sec-gen on mal} for relevant notation used in Lemma \ref{egh finite}.
\begin{lemma}\label{egh finite}
Suppose $G$ is a hyperbolic group and $H$ is a quasiconvex subgroup of $G$.
Then the set $\mathcal E_G(H)=\{H\cap H^g:g\in\mathcal I_G(H)\}$ has finitely many subgroups of $H$ up to conjugation
by elements of $H$.
\end{lemma}

\begin{proof} Let $\Gamma_G$ be a Cayley graph of $G$ with respect to a finite generating set.
Suppose $\Gamma_G$ is $\delta$-hyperbolic and $H$ is a $k$-quasiconvex in $\Gamma_G$.
Let $g\in \mathcal I_G(H)$ and $E=H\cap H^g$. Then by Proposition \ref{qc prop}(8), $E$ is an
infinite quasiconvex subgroup of $G$. Then the 1st part of the same proposition implies
that $E$ is an infinite hyperbolic group. It follows that $\Lambda_G(E)$ has at least two
distinct points by Proposition \ref{qc prop}(3).
Let $\xi_1\neq \xi_2$ be points of $\Lambda_G(E)$ and let $\gamma$ be a geodesic
line in $\Gamma_G$ joining them. Then there is a point $h\in H$ such that
$d_G(\gamma, h)\leq D=D(\delta,k)$ where is $D$ is as in Proposition \ref{qc prop}(9).
Hence, $d_G(1, h^{-1}\gamma)\leq D$. We note that (1)
$h^{-1}\xi_1,~h^{-1}\xi_2\in \Lambda_G(h^{-1}E)=\Lambda_G(h^{-1}Eh)$;
and (2) also $h^{-1}\xi_1,~h^{-1}\xi_2\in \Lambda_G (h.gHg^{-1})=\Lambda_G(h^{-1}gH)$.
As $h^{-1}gH$ is also a $k$-quasiconvex subset of $\Gamma_G$, we have
$d_G(1, h^{-1}gH)\leq 2D$. Let $x=h^{-1}g$. We note that the number of such left cosets $xH$
of $H$ such that $d_G(1, xH)\leq 2D$ is finite. Hence, $h^{-1}Eh=H\cap xHx^{-1}$ is
also finite. The Lemma follows. %\RED{We need to cite some part of GMRS. Check that.}
\end{proof}


\begin{lemma}\label{qc conjugate}
	Suppose $G$ is a hyperbolic group and $H$ is a quasiconvex subgroup.
	Let $x,y\in G$, and let $x$ be of infinite order. Then $x^n\in yHy^{-1}$ for some $n\in \N$ if and only if $x^{\infty}\in \Lambda_G(yH)$.
\end{lemma}
\begin{proof}
	We note that $yHy^{-1}$ is a quasiconvex subgroup of $G$ and so is $\lgl x\rgl$. Now, the
	lemma follows from the limit set intersection property of quasiconvex subgroups of
	hyperbolic groups, i.e. Proposition \ref{qc prop}(8) and the fact that
	$\Lambda_G(yHy^{-1})=\Lambda_G(yH)$, as follows.


	If $x^n\in yHy^{-1}$ then clearly $x^{\infty}\in \Lambda_G(yHy^{-1})=\Lambda_G(yH)$.
	On the other hand if, $x^{\infty}\in \Lambda_G(yH)$, then we have
	$x^{\infty}\in \Lambda_G(\lgl x\rgl)\cap \Lambda_G(yHy^{-1})=\Lambda_G(\lgl x\rgl\cap yHy^{-1})$.
	It follows that $\lgl x\rgl\cap yHy^{-1}=\lgl x^n\rgl$ for some $n\in \mathbb N$.
\end{proof}



\begin{lemma}\label{commen lemma}
Suppose $G$ is a hyperbolic group and $H$ is an infinite, quasiconvex subgroup of $G$.
Let $g\in  G\setminus Comm_G(H)$. Then $H\cap H^g$ has infinite index in $H$.
\end{lemma}
\proof We prove the contrapositive statement.
Suppose $x\in G$ such that $H\cap H^x$ has finite index in $H$.

{\bf Claim:} $\Lambda(H)=x\Lambda(H)$.

%We claim that  $x\in Comm_G(H)$.
By Lemma \ref{limit set basic}(3)(i), $\Lambda(H)=\Lambda(H\cap H^x)$. By the limit set intersection
property (Proposition \ref{qc prop}(8)), $\Lambda(H\cap H^x)=\Lambda(H)\cap \Lambda(H^x)$
as $H^x$ is a quasiconvex subgroup of $G$ too. Also by Lemma \ref{limit set basic}(3)(ii),
$\Lambda(H^x)=\Lambda (xH)=x\Lambda(H)$. Thus we have $\Lambda(H)=\Lambda(H)\cap x\Lambda(H)$.
This means that $\Lambda(H)\subset x\Lambda(H)$ whence $\Lambda(H)\supset x^{-1}\Lambda(H)$.
Then inductively, by repeated application of $x^{-1}$, we have a descending chain
$$\Lambda(H)\supset x^{-1}\Lambda(H)\supset x^{-2}\Lambda(H)\supset \cdots$$
Let $Z=\cap_{n\geq 0} x^{-n}\Lambda(H)$. It is easy to check that $Z$ is a
closed subset of $\pa G$ which is invariant under $\lgl x\rgl$. Now there are two cases to consider

{\bf Case 1.} Suppose $x$ has finite order. Let $x^n=1$. In that case,
$\Lambda(H)=x^{-n}\Lambda(H)$. Hence, from the descending chain it follows that
$\Lambda(H)=x^{-1}\Lambda(H)$, and thus $x\Lambda(H)=\Lambda(H)$.

{\bf Case 2.} Suppose $x$ has infinite order.
In this case, as each $x^{-n}\Lambda(H)$ is a nonempty closed subset of $\pa G$ which is
a compact space. Hence, by the finite intersection property of compact spaces, $Z$ is a nonempty set.
Hence, by Lemma \ref{limit set minimal} $(2)$, $x^{\pm \infty}\in Z$.
In particular, $x^{\pm \infty}\in \Lambda(H)$.
Hence, by Lemma \ref{qc conjugate}, $x^n\in H$. Thus, once again, using the descending chain,
as $x^{-n}\Lambda(H)=\Lambda(x^{-n} H)=\Lambda(H)$, we have $\Lambda(H)=x^{-1}\Lambda(H)$,
and so $x\Lambda(H)=\Lambda(H)$. This completes the proof of the claim.

Now, using the claim we have $\Lambda(H)=x\Lambda(H)=\Lambda(xH)=\Lambda(H^x)$
as was observed in the first paragraph of the proof of the claim.
Finally, we can use Corollary \ref{qc sbgp commens} below to finish the proof.
\qed

\begin{lemma}\label{commens lemma 2}
Suppose $G$ is a hyperbolic group and $H, K$ are two infinite quasiconvex subgroups of $G$.
Suppose $K<H$ and $\Lambda(K)=\Lambda(H)$. Then $[H:K]<\infty$.
\end{lemma}
\proof Let $\xi, \xi'$ be any two distinct point of $\Lambda(H)=\Lambda(K)$. Let $\gamma$ be a
geodesic line in $\Gamma_G$ joining these points. Then we know by Proposition
\ref{qc prop}(9) that
$\gamma \subset N_D(K)\cap N_D(H)$ for $D\geq 0$ as $K, H$ are quasiconvex in $G$.
Let $x\in \gamma$ and $h\in H$ be such that $d_G(x,h)\leq D$. Then $h\in N_{2D}(K)$.
Now, for any $h'\in H$, $h'\gamma$ is a geodesic joining
$h'\xi, h'\xi'\in h\Lambda(H)=\Lambda(H)=\Lambda(K)$ as $\Lambda(H)$ is stable under the
action of $H$. Thus by the same argument $h'.x\in N_D(K)$. Now, $d_G(h'x, h'h)=d_H(x,h)\leq D$
and hence, $h'h\in N_{2D}(K)$. Thus $H\subset N_{2D}(K)$. From this it easily follows
that $[H:K]<\infty$.
\qed

\begin{cor}\label{qc sbgp commens}
Suppose $G$ is a hyperbolic group and $H,K$ are two quasiconvex subgroup of $G$.
If $\Lambda(H)=\Lambda(K)$ then $H$, $K$ are commensurable subgroups of $G$, i.e. $H\cap K$ has
finite index in both $H$ and $K$.
\end{cor}
\proof By limit set intersection property of quasiconvex subgroups, i.e. Proposition \ref{qc prop}
(8), we have that $H\cap K$ is quasiconvex in $G$ and $\Lambda(H\cap K)=\Lambda(H)=\Lambda(K)$.
Then we are done by Lemma \ref{commens lemma 2}.
\qed





\subsection{Coned-off spaces and applications}
We remind the reader that the coning construction or the electrocution was introduced by Farb
in \cite{farb-relhyp}. Suppose $Y$ is any graph and $\{A_i\}$ is a collection of subgraphs
in $Y$. Then the coned-off graph $\hat{Y}$ is the new graph obtained
from $Y$ by introducing new vertices and edges along with those already in $Y$ as follows:

(1) Vertices: For each set $A_i$ suppose we have a new vertex $v_i$.

(2) Edges: $v_i$ is joined by an edge to each vertex of $A_i$.

\begin{prop}\textup{(\cite[Proposition $2.6$]{KR-FFC})} \label{coned space hyp}
Suppose $G$ is a hyperbolic group and $\{H_i: 1\leq i\leq l\}$ are quasiconvex subgroups of $G$.
Suppose that in a Cayley graph $\Gamma_G$ we cone off all the cosets of all the subgroups $H_i$.
Then the coned-off graph $\hat{\Gamma}_G$ is hyperbolic.

\end{prop}


\begin{prop}\textup{(\cite[Corollary $6.4$]{ab-mn-acy}, \cite[Theorem $2.6$]{KR-FFC}),
(See also \cite[Section 3.2]{pranab-ravi-ct})} \label{geod in coned space}
Suppose $G$, $\Gamma_G$ and $\{H_i: 1\leq i\leq l\}$ are as in Proposition \ref{coned space hyp}.
Then any (quasi) geodesic ray $\gamma$ in $\Gamma_G$ satisfies exactly one of the following
two properties:

(1) $\gamma$ is a finite diameter subset of $\hat{\Gamma}_G$ which is equivalent to
$\gamma(\infty)\in \Lambda_G(gH_i)$ for some $g\in G$ and $1\leq i\leq l$.

(2) $\gamma$ is an infinite diameter subset of $\hat{\Gamma}_G$. In this case,
there is $\eta \in \pa \hat{G}$ such that $\gamma(n)\map \eta$ as $n\map \infty$.
Moreover, for any (quasi)geodesic ray $\alpha$ in $\hat{\Gamma}_G$ such that
$\alpha(\infty)=\eta$ one has $Hd(\alpha, \gamma)<\infty$.
\end{prop}

Let $\pa_u G\subset \pa G$ denote the set of points $\xi$ for which there is a geodesic
ray in $\Gamma_G$ which is of infinite diameter in $\hat{\Gamma}_G$. Then we have the following:

\begin{theorem} \textup{(\cite[Theorem 3.2]{dow-tay-cosurface} (see also \cite[Theorem $6.7$]{ab-mn-acy})}
\label{u-boundary}

The natural map $\pa_u G\map \pa \hat{G}$ given by Proposition \ref{geod in coned space}(2)
is a homeomorphism.
\end{theorem}











Suppose $G$ is a hyperbolic group and $\{H_i:1\le i\le l\}$ are quasiconvex subgroups of $G$.
Suppose $\Gamma_G$ is the Cayley graph of $G$ with respect to a finite generating set. Let $\hat{\Gamma}_G$
be the graph obtained from $\Gamma_G$ by coning off all the cosets of the subgroups $H_i$, $1\leq i\leq l$.
We note that the isometric action of $G$ on $\Gamma_G$ naturally extends to an action of $G$ on
$\hat{\Gamma}_G$ by isometries.

\begin{prop}\label{lem-bounded proj in hat}
Given any $g\in G$, its action on $\hat{\Gamma}_G$ satisfies exactly one of the following:

(1) $g$ induces an elliptic isometry on $\hat{\Gamma}_G$ i.e.
$diam\{\pi(g^n):n\in\Z\}$ is finite in $\hat{\Gamma}_G$. This happens
if and only if some power of $g$ is conjugate to an element of $H_i$ for some $i\in\{1,\cdots,l\}$.

(2) $g$ acts by a loxodromic isometry on $\hat{\Gamma}_G$.
In particular, in this case, $n\mapsto g^n$, $n\in \Z$ is a quasigeodesic line in $\hat{\Gamma}_G$.
\end{prop}

\begin{proof}
We shall denote the metric on $\Gamma_G$ by $d_G$ and the metric on $\hat{\Gamma}_G$ by $\hat{d}_G$.

(1) If $g\in G$ has finite order then clearly it acts as an elliptic isometry on $\hat{\Gamma}_G$.
Suppose $g\in G$ has infinite order.
Suppose $g^m\in xH_ix^{-1}$ for some $x\in G$, $m\in\Z\setminus\{0\}$ and $i\in\{1,\cdots,l\}$.
Since $Hd_G(xH_i,xH_ix^{-1})\le d_G(1,x)<\infty$ and $Hd(\lgl g\rgl, \lgl g^m\rgl)<\infty$, it follows that there is a constant $D$ depending on these Hausdorff
distances such that $\lgl g\rgl\subset N_D(xH_i)$ in $\Gamma_G$. As the inclusion $\Gamma_G\map \hat{\Gamma}_G$ is distance
decreasing, it follows that $\lgl g\rgl\subset N_D(xH_i)$ in $\hat{\Gamma}_G$ as well. But the diameter of $xH_i$ is $2$
in $\hat{\Gamma}_G$. Thus the diameter of the $\lgl g\rgl$ is finite in $\hat{\Gamma}_G$.




 Conversely, suppose $diam\{\pi(g^n):n\in\N\}$ is finite in $\hat{\Gamma}_G$.
We know by Lemma \ref{lem-infinite ele loxo} that $n\mapsto g^n$, $n\in \N$, defines a quasigeodesic ray in $\Gamma_G$.
Then by Proposition \ref{geod in coned space} $(1)$, $g^{\infty}\in \Lambda_G(xH_i)$
for some $x\in G$ and $1\leq i\leq l$. Then by Lemma \ref{qc conjugate}, $g^m\in xH_ix^{-1}$ for some $m\in \N$.


(2) Suppose $g\in G$ is an infinite order element that does not act as an elliptic isometry on
$\hat{\Gamma}_G$. It follows from (1) that $\alpha_{\pm}:n\mapsto g^n$ for $n\in \Z_{\geq 0}$ (respectively
$n\in \Z_{\leq 0}$ defines two quasigeodesic rays in $\Gamma_G$ that do not converge to the limit set
of any coset of any of the $H_i$'s. By Proposition \ref{geod in coned space} $(2)$, the sequences
$\{g^n\}_{n\in ]N}$ and $\{g^{-n}\}_{n\in \N}$ are converging to some points of $\partial \hat{\Gamma}_G$.
However, these points are not equal to each other by Theorem \ref{u-boundary}. On the other hand, clearly
these points are fixed points of $g$. Hence, we are done by Lemma \ref{lemma lox}.
\end{proof}



\begin{prop}\label{pingpong criteria}{\em (Criterion for pingpong pair)}
Let $G$ be a nonelementary hyperbolic group. Let $\{H_i:1\le i\le l\}$ be a finite collection of infinite and quasiconvex subgroups of $G$.
Let $g_1,g_2\in G$ be two infinite order elements of $G$ which have disjoint fixed point sets in $\partial G$.
Further, suppose that for all $i\in\{1,\cdots,l\}$, no power of $g_j$, $j=1,2$, is conjugate in $G$ to an element of $H_i$.
	Then there is $m\in\N$ such that

\begin{enumerate}
\item $\lgl g^m_1,g^m_2\rgl< G$ is a free subgroup of rank $2$, and

\item $\langle g^m_1,g^m_2\rangle\cap g^{-1}H_ig=\{1\}$ for all $g\in G$ and for all $i\in\{1,\cdots,l\}$.
\end{enumerate}
\end{prop}

\begin{proof}
Let $\Gamma_G$ denote a Cayley graph of $G$ with respect to a finite generating set, and let
$\hat{\Gamma}_G$ denote the graph obtained from $\Gamma_G$ by coning off all the cosets of $\{H_i:1\le i\le l\}$
in $G$. It follows by Proposition \ref{lem-bounded proj in hat} $(2)$ that $g_1, g_2$ act by loxodromic
isometries on $\hat{\Gamma}_G$. By Theorem \ref{u-boundary} these elements are independent as
$g_1, g_2$ have no common fixed points in $\partial G$ and the fixed points of these isometries are
in $\partial_u G$. Then, by Lemma \ref{lem-finding free qc} for some $m\in \N$,
$g^m_1, g^m_2$ generate a free group, say $H$ and that the orbit map $H\map \hat{\Gamma}_G$
will be a qi embedding. It then follows that each element of $H\setminus \{1\}$ will act as a
loxodromic isometry on $\hat{\Gamma}_G$. Thus, once again, by Proposition \ref{lem-bounded proj in hat} $(1)$,
we have $H\cap gH_ig^{-1}=\{1\}$ for all $g\in G$ and $1\leq i\leq l$. This completes the proof of the
proposition.
\end{proof}

