\section{Stokes dipole}
\label{sec_dipole}
In order to obtain the Stokes dipole (and, more generally, any higher order multipole of the bounded Green function), it is possible to differentiate the solution eq. (\ref{eq56}) obtained in Section \ref{sec_green_function} at the pole point ${\pmb \xi}$. 
From eq. (\ref{eq8}) and from the expression of the Stokeslet dipole eq. (\ref{eqB16}), the Stokes dipole can be expressed as
\begin{equation}
\begin{array}{l}
 \nabla_{\alpha} \,G^b_{\,\, \beta} ({\pmb x},{\pmb \xi}) =
-\dfrac{r^b\, g_{\alpha\, \beta}({\pmb \xi})}{r^3}
+
3\dfrac{r^b\, r_\alpha\, r_\beta}{r^5}
+
\dfrac{r_\beta\, g^b_{\,\, \alpha} ({\pmb x}.{\pmb \xi}) \, - \, r_\alpha \,g^b_{\,\, \beta}({\pmb x},{\pmb \xi})}{r^3}
\\
[10pt]
\hspace{2.2cm}+
\dfrac{\partial \, W^b_{\,\, \beta} ({\pmb x},{\pmb \xi}) }{\partial \xi^{\alpha} }
- \Gamma^\gamma_{\alpha\, \beta} ({\pmb \xi})\,
  W^b_{\,\, \gamma} ({\pmb x},{\pmb \xi})
\end{array}
\label{eq64_8}
\end{equation}
where the $\Gamma^\gamma_{\alpha\, \beta} ({\pmb \xi}) $
are the Christoffel symbols of the second kind reported in eqs. (\ref{eqA7ch}). Focusing on the regular part, we have that
\begin{equation}
\Gamma^\gamma_{\alpha\, \beta} ({\pmb \xi})\,
  W^b_{\,\, \gamma} ({\pmb x},{\pmb \xi})
  =
  - \delta^2_\alpha \, \delta^2_\beta \, \xi \,W^b_{\, 1}({\pmb x},{\pmb \xi})
  \\
  + \left( \delta^1_\alpha \, \delta^2_\beta \, + \, 
  \delta^2_\alpha \, \delta^1_\beta 
    \right) \dfrac{W^b_{\, 2}({\pmb x},{\pmb \xi}) }{\xi^1} 
\label{eq66_}
\end{equation}
and
\begin{equation}
\begin{array}{l}
\dfrac{\partial\, W^b_{\,\, \beta}({\pmb x},{\pmb \xi})}{\partial \xi^1} =-
\displaystyle \sum^{*}
  \cos(n \phi+p_{(b)} + p_{(\beta)})\cos(\lambda z + q_{(b)} + q_{(\beta)}) \times 
  \\  
  [10pt]
  \hspace{2.2cm}
 \times  \left(\,{\bf C}(x) \left( \overline{\bf C}(R_o,R_i) \right)^{-1}  \dfrac{\partial \overline{\bf A}_\beta(\xi,R_o,R_i) }{\partial\, \xi}
\, \right)_{(b)}
\\
  [10pt]
\dfrac{\partial\, W^b_{\,\, \beta}({\pmb x},{\pmb \xi})}{\partial \xi^2} =-
\displaystyle \sum^{*}
  \sin(n \phi+p_{(b)} + p_{(\beta)})\cos(\lambda z + q_{(b)} + q_{(\beta)}) \times 
  \\  
  [10pt]
  \hspace{2.2cm}
 \times  \left( \,{\bf C}(x) \left( \overline{\bf C}(R_o,R_i) \right)^{-1}\,n\, \overline{\bf A}_\beta (\xi,R_o,R_i)
\, \right)_{(b)}
\\
  [10pt]
\dfrac{\partial\, W^b_{\,\, \beta}({\pmb x},{\pmb \xi})}{\partial \xi^3} =-
\displaystyle \sum^{*}
  \cos(n \phi+p_{(b)} + p_{(\beta)})\sin(\lambda z + q_{(b)} + q_{(\beta)}) \times 
  \\  
  [10pt]
  \hspace{2.2cm}
 \times  \left(\,{\bf C}(x) \left( \overline{\bf C}(R_o,R_i) \right)^{-1}\, \lambda \, \overline{\bf A}_\beta (\xi,R_o,R_i)
\, \right)_{(b)}
\end{array}
\label{eq566_}
\end{equation}
In a more compact form, eqs. (\ref{eq566_}) read
\begin{equation}
\begin{array}{l}
\dfrac{\partial\, W^b_{\,\, \beta}({\pmb x},{\pmb \xi})}{\partial \xi^\gamma} =-
\displaystyle \sum^{*}
  \cos(n \phi+p_{(b)} + p_{(\beta)}+ p_{(\gamma)})\cos(\lambda z + q_{(b)} + q_{(\beta)}+ q_{(\gamma)}) \times 
  \\  
  [10pt]
  \hspace{2.2cm}
 \times  \left(\,{\bf C}(x) \left( \overline{\bf C}(R_o,R_i) \right)^{-1}  \overline{\bf A'}_{(\beta,\, \gamma)} (\xi,R_o,R_i)
\, \right)_{(b)}
\end{array}
\label{eq57_}
\end{equation}
where $ \overline{\bf A'}_{(\beta,\, \gamma)}  (\xi,R_o,R_i)$ is given by
\begin{equation}
\begin{array}{l}
\overline{\bf A'}_{(\beta,\, 1)} (\xi,R_o,R_i) = \dfrac{\partial \overline{\bf A}_\beta(\xi,R_o,R_i) }{\partial\, \xi},\quad 
\overline{\bf A'}_{(\beta,\, 2)} (\xi,R_o,R_i) =\,n\,\overline{\bf A}_\beta (\xi,R_o,R_i) 
  \\  
  [10pt]
  \overline{\bf A'}_{(\beta,\, 3)} (\xi,R_o,R_i) =\,\lambda\,\overline{\bf A}_\beta (\xi,R_o,R_i) 
  \end{array}
\label{eq51_}
\end{equation}
In the Cartesian-Cartesian coordinate system, the confined Stokes dipole reads
\begin{equation}
\begin{array}{l}
 \dfrac{\partial \overline{G}_{i \, j}({\pmb x},{\pmb \xi}) }{\partial \overline{\xi}_k} 
= 
-\dfrac{(\overline{x}_i-\overline{\xi}_i)\, \delta_{j\, k}}{r^3}
+
3\dfrac{(\overline{x}_i-\overline{\xi}_i)\, (\overline{x}_j-\overline{\xi}_j)\,(\overline{x}_k-\overline{\xi}_k)}{r^5}
+
\dfrac{(\overline{x}_k-\overline{\xi}_k)\, \delta_{i\, j}  \, - \, (\overline{x}_j-\overline{\xi}_j)\, \delta_{i\, k} }{r^3}
\\
[15pt]
+\, \dfrac{\partial \overline{x}_i}{\partial x^b}
\left(
\dfrac{\partial \xi^\alpha}{\partial \overline{\xi}_k}
\dfrac{\partial \xi^\beta}{\partial \overline{\xi}_j}
\dfrac{\partial\, W^b_{\,\, \beta}({\pmb x},{\pmb \xi}) }{\partial\, \xi^\alpha}\,+ \, \xi^1 \, 
\dfrac{\partial \xi^2}{\partial \overline{\xi}_j}
 \dfrac{\partial \xi^2}{\partial \overline{\xi}_k}
 W^b_{\,\, 1}({\pmb x},{\pmb \xi})
 - \dfrac{1}{\xi^1} \left(
 \dfrac{\partial \xi^1}{\partial \overline{\xi}_j}
 \dfrac{\partial \xi^2}{\partial \overline{\xi}_k}
 +
  \dfrac{\partial \xi^2}{\partial \overline{\xi}_j}
 \dfrac{\partial \xi^1}{\partial \overline{\xi}_k}
  \right) 
  W^b_{\,\, 2}({\pmb x},{\pmb \xi})
 \right)
\end{array}
\label{eq69_}
\end{equation}
By defining the symmetry operator
\begin{equation}
\eta^{\gamma \, \delta}_{\alpha \, \beta}=
\delta^{\gamma}_{\alpha}\, \delta^{\delta}_{\beta}\,
+\,
\delta^{\delta}_{\alpha}\, \delta^{\gamma}_{\beta}
\label{eqB17}
\end{equation}
the confined Stokes dipole can be expressed in term of its symmetric (the first and second terms at the r.h.s of eq. (\ref{eqB16})) and antisymmetric (the third term at the r.h.s of eq. (\ref{eqB16})) parts as
\begin{equation}
\nabla_\alpha\, G^b_{\, \, \beta}({\pmb x},{\pmb \xi})
\,=\,
\dfrac{ \eta^{\gamma \, \delta}_{\alpha \, \beta} }{2}
\,
\nabla_\gamma\, G^b_{\, \, \delta}({\pmb x},{\pmb \xi})
\,+\,
\dfrac{ \varepsilon_{\zeta \alpha \beta}\, \varepsilon^{\zeta \gamma \delta} }{2}
\,
\nabla_\gamma\, G^b_{\, \, \delta}({\pmb x},{\pmb \xi})
\label{eq71_}
\end{equation}
where $\varepsilon_{\zeta \alpha \beta} \sqrt{g({\pmb \xi})} $
and $ \varepsilon^{\zeta \gamma \delta} / \sqrt{g({\pmb \xi})} $
are the absolute covariant and contravariant Ricci--Levi-Civita tensors respectively.

The term $\varepsilon^{\zeta \gamma \delta}\, \nabla_\gamma\, G^b_{\, \, \delta}({\pmb x},{\pmb \xi})\, /\,(2 \sqrt{g({\pmb \xi})}) $ in eq. (\ref{eq71_}), with $ \sqrt{g({\pmb \xi})}) = \xi^1$ in the cylindrical coordinate system,
is referred to as the confined {Couplet} (or also {Rotlet} \cite{blake_fundamental_1974}) and represents the far field 
velocity field of a rigid body rotating without translating at
the point ${\pmb \xi}$.

The first term at the l.h.s of eq. (\ref{eq71_}),
$  \eta^{\gamma \, \delta}_{\alpha \, \beta} 
\,
\nabla_\gamma\, G^b_{\, \, \delta}({\pmb x},{\pmb \xi})/2$, represents the far field flow due to a deforming body, such as a swimming microorganism, and it is referred to as the {Stresslet} (alternatively we could refer to it also as the {Strainlet} \footnote{The dichotomy Couplet and Stresslet have been introduced by Batchelor in \cite{batchelor_1970} with reference to the disturbance flow due to an infinitesimal immersed particle in a linear flow. Specifically, the Couplet refers to the disturbance flow due to a non rotating particle in the ambient flow (hence, introducing an additional torque to the fluid), and the Stresslet refers to the disturbance flow due to a rigid particle in the fluid (hence, introducing and additional stress). Alternatively to the term Couplet, the term Rotlet have been introduced, in the field of active particles, by Chwan and Wu \cite{chwang} for indicating the flow induced by a rotating infinitesimal particle in the fluid. Following this logic, it would be more appropriate to refer to a singularity as a Strainlet when it describes the infinitesimal deformation introduced by an active particle in the fluid, in dichotomy with its antisymmetric counterpart, the Rotlet.}).
Given the importance of these two singularities in the study of fluid-particle interaction in the Stokes regime, let us focus on each of them separately.

\subsection{Couplet}


Since the Christoffel symbol is symmetric, by applying the Ricci--Levi-Civita symbol, the contribute of the last term at the l.h.s of eq. (\ref{eq64_8}) is vanishing. Therefore, the confined Couplet in the cylindrical system reads
\begin{equation}
\dfrac{\varepsilon^{\beta \gamma \delta} }{2\, \xi}
\,
\nabla_\gamma\, G^b_{\, \, \delta}({\pmb x},{\pmb \xi})
=
\dfrac{\varepsilon^{\beta \gamma \delta}\, g^b_{\, \, \gamma}({\pmb x},{\pmb \xi}) }{2 \, \xi }
\, \dfrac{r_\delta}{r^3}
+
\dfrac{\varepsilon^{\beta \gamma \delta} }{2 \, \xi}
\,
\dfrac{\partial \, W^b_{\,\, \delta} ({\pmb x},{\pmb \xi}) }{\partial \xi^{\gamma} }
\label{eq72_}
\end{equation} 
In the Cartesian-Cartesian coordinate system, it can be expressed as
\begin{equation}
\dfrac{\varepsilon_{j k h} }{2}
\,
\dfrac{\partial \,  \overline{G}_{i \, h}({\pmb x},{\pmb \xi})}{\partial \, \overline{\xi}_k}
=
\dfrac{\varepsilon_{i j k}}{2 }
\, \dfrac{(x_k-\xi_k) }{r^3}
+ \dfrac{\varepsilon_{j h k}}{2}\,
\dfrac{\partial \overline{x}_i}{\partial x^b}\,
\dfrac{\partial \xi^\gamma}{\partial \overline{\xi}_h}\,
\dfrac{\partial \xi^\delta}{\partial \overline{\xi}_k}\,
\dfrac{\partial \, W^b_{\,\, \delta} ({\pmb x},{\pmb \xi})}{\partial\, \xi^\gamma}
\label{eq72_}
\end{equation} 
where the relation \cite{synge_tensor_1978}
\begin{equation}
\dfrac{\varepsilon^{\beta \gamma \delta} }{\sqrt{g({\pmb \xi})}}
=
\dfrac{\varepsilon^{\beta \gamma \delta} }{\xi}
=
\varepsilon_{i j k}
\dfrac{\partial \xi^\beta}{\partial \overline{\xi}_i}\,
\dfrac{\partial \xi^\gamma}{\partial \overline{\xi}_j}\,
\dfrac{\partial \xi^\delta}{\partial \overline{\xi}_k}\,
\end{equation}
has been used.
Figure \ref{fig6} shows, at the section of the cylinder $x^3=\xi^3$, the streamlines and the norm of the velocity field due to a Couplet oriented parallel to the symmetry axis of the cylinders $Y_3$ and placed at $\xi^1=(R_i+R_o)/2$. An effect of the Couplet in the annular region is the generation of two connected vortices in the confined fluid with their centers at around $x^1 \approx 1.7$ and $x^2 \approx \xi^2 \pm \pi/5 $. Specifically, for the case of an anticlockwise couplet, the fluid elements are repulsed from the vortex with center at $ x^2 \approx \xi^2 + \pi/5 $ and attracted
by the vortex centred at $ x^2 \approx \xi^2 - \pi/5$. The opposite occurs in the clockwise arrangement.
\begin{figure}
\centering
