\section{Bitensorial formulation of the Stokes unbounded singularities}
\label{App_Stokeslet}
In this appendix the bitensorial formulation of the Stokeslet and higher order singularities in generic coordinate systems is obtained. There are several methods to obtain the Green function of the unbounded Stokes flow developed in the literature \cite{pozrikidis_1992,ladyzhenskaia_mathematical_2014,kim_1991,giona_hydrodynamic_2022}. In the following the Pozrikidis method \cite[p. 22]{pozrikidis_1992}, developed in Cartesian coordinates, will be applied considering generic curvilinear coordinate systems at both the pole and field point. 

As obtained in Section \ref{setting} and in \cite{procopio_bitensorial_2022}, the bitensorial formulation of the Green problem of the unbounded Stokes flow is
\begin{equation}
\begin{cases}
\Delta_x\, S^b_{\, \, \beta} ({\pmb x},{\pmb \xi})
-
\nabla^b {\rm P}_\beta ({\pmb x},{\pmb \xi})
=
-8 \pi g^b_{\,\, \beta}({\pmb x},{\pmb \xi})\, \delta({\pmb x},{\pmb \xi})
\\
\nabla_b\,  S^b_{\, \, \beta} ({\pmb x},{\pmb \xi})=0
\\
S^b_{\, \, \beta} ({\pmb x},{\pmb \xi}) \rightarrow {0} \quad \text{for} \quad {\pmb x} \rightarrow \infty
\end{cases}
\label{eqB1}
\end{equation}
By applying the covariant derivative operator $\nabla_b$
to the moment balance equation in eqs. (\ref{eqB1}) and considering the incompressibility equation, a Poisson equation is obtained for the bitensorial pressure
\begin{equation}
\Delta_x {\rm P}_\beta ({\pmb x},{\pmb \xi})= 8 \pi \nabla_b \,g^b_{\, \, \beta} ({\pmb x},{\pmb \xi})\, \delta({\pmb x},{\pmb \xi})
\label{eqB2}
\end{equation}
In the Euclidean space, the covariant derivative of the parallel propagator vanishes. In fact, by the definition eq. (\ref{eq3})
\begin{equation}
\nabla_c \,g_{b \, \beta} ({\pmb x},{\pmb \xi})\, =\, 
\dfrac{\partial Y_i}{\partial \xi^\beta}\, \nabla_c \,\left(  
\dfrac{\partial Y_i}{\partial x^b} \right) \, = \,
\dfrac{\partial Y_i}{\partial \xi^\beta}\, \left(  
\dfrac{d^2 Y_i}{\partial x^b\, \partial x^c}- \Gamma^a_{b\, c} \, \dfrac{\partial Y_i}{\partial x^a}  \right) =0
\label{eqB3}
\end{equation}
where the relation  
\begin{equation}
\dfrac{\partial^2 Y_i}{\partial x^b\, \partial x^c}=
\Gamma^a_{b\, c} \, \dfrac{\partial Y_i}{\partial x^a}
\label{B4}
\end{equation}
valid for Euclidean spaces \cite{de_souza_2016}, has been considered.
Therefore, since $ \nabla_b \,g^b_{\, \, \beta} ({\pmb x},{\pmb \xi})\,=\, g^{b\, c}({\pmb x})\, \nabla_c \,g_{b \, \beta} ({\pmb x},{\pmb \xi})$, eq. (\ref{eqB2}) becomes
\begin{equation}
\Delta_x {\rm P}_\beta ({\pmb x},{\pmb \xi})= 8 \pi\,g^b_{\, \, \beta} ({\pmb x},{\pmb \xi}) \, \nabla_b \, \delta({\pmb x},{\pmb \xi})
\label{eqB5}
\end{equation}
By using the distributional identity
\begin{equation}
\delta({\pmb x}, {\pmb \xi})=
\Delta_x \left( \dfrac{1}{- 4 \pi\, r} \right)
\label{eqB6}
\end{equation}
Eq. (\ref{eqB5}) provides
\begin{equation}
{\rm P}_\beta({\pmb x},{\pmb \xi})
=-2 \, g^b_{\, \, \beta} ({\pmb x},{\pmb \xi}) \, \nabla_b \, 
\left( \dfrac{1}{r} \right) 
\label{eqB7}
\end{equation}
Considering that $ \nabla_b \, r^{-1}=-r_b\, /\, r^{3}$
and that $g^b_{\, \, \beta}({\pmb x},{\pmb \xi})\, r_b=-r_\beta$
(and, more generally, $g^b_{\, \, \beta}({\pmb x},{\pmb \xi}) \nabla_b f(r) = - \nabla_\beta f(r)$ for any function of the distance $f(r)$ 
) \cite{poisson_motion_2011}
\begin{equation}
P_\beta({\pmb x},{\pmb \xi})
=-2 \,   
\dfrac{r_\beta}{r^3} 
\label{eqB8}
\end{equation}
By using eqs. (\ref{eqB6}) and (\ref{eqB8}), the moment balance in eqs. (\ref{eqB1}) becomes
\begin{equation}
\Delta_x\, S^b_{\, \, \beta}({\pmb x},{\pmb \xi})
=
2 \left(\,
g^b_{\, \, \beta} ({\pmb x},{\pmb \xi}) \Delta_x
+
\nabla^b \, \nabla_\beta\, 
\right) \dfrac{1}{r}
\label{eqB9}
\end{equation}
Let us try, for $S^b_{\, \, \beta}({\pmb x},{\pmb \xi})$, a solution
a solution with the form
\begin{equation}
S^b_{\, \, \beta}({\pmb x},{\pmb \xi})
=
\left(\,
g^b_{\, \, \beta} ({\pmb x},{\pmb \xi}) \Delta_x
+
\nabla^b\, \nabla_\beta\, 
\right) H(r)
\label{eqB10}
\end{equation}
where $H(r)$ is a scalar function of $r$ to be determined.
Substituting eq. (\ref{eqB10}) into eq. (\ref{eqB9})
\begin{equation}
\Delta_x\, H(r)
=
\dfrac{2}{r}
\label{eqB11}
\end{equation}
Applying the Laplacian operator $\Delta_x$ to eq. (\ref{eqB11})
 and using eq. (\ref{eqB6})
\begin{equation}
\Delta_x\, \Delta_x\,  H(r)
=
- 8 \pi \, \delta({\pmb x},{\pmb \xi})
\label{eqB12}
\end{equation}
Equation (\ref{eqB12}) is the biharmonic Green problem having solution $H(r)=r$, hence
\begin{equation}
S^b_{\, \, \beta}({\pmb x},{\pmb \xi})
=
\left(\,
g^b_{\, \, \beta} ({\pmb x},{\pmb \xi}) \Delta_x
+
\nabla^b \, \nabla_\beta\, 
\right) r
\label{eqB13}
\end{equation}
By using the relation $\Delta_x\, r = 2/r$ expressed in eq. (\ref{eqB11})
and the definitions $r_b=\nabla_b \, r^2 /2$ and $r_\beta =\nabla_\beta\, r^2/2$, it is possible to obtain from eq. (\ref{eqB13}) 
\begin{equation}
S^b_{\, \, \beta}({\pmb x},{\pmb \xi})
= \dfrac{g^b_{\, \, \beta}({\pmb x},{\pmb \xi})}{r}- \dfrac{r_b\, r_\beta}{r^3}
\label{eqB14}
\end{equation}
or alternatively
\begin{equation}
S^b_{\, \, \beta}({\pmb x},{\pmb \xi})
=
\left(\,
g^b_{\, \, \beta}({\pmb x},{\pmb \xi})
+
r^b\, \nabla_\beta\, 
\right) \dfrac{1}{r}
\label{eqB15}
\end{equation}
Higher order singularities are obtained by differentiating the Stokeslet eq. (\ref{eqB14}) at its pole ${\pmb \xi}$. The bitensorial expression for the Stokes dipole then becomes
\begin{equation}
\nabla_\alpha\, S^b_{\, \, \beta}({\pmb x},{\pmb \xi})
= 
-\dfrac{r^b\, g_{\alpha\, \beta}({\pmb \xi})}{r^3}
+
3\dfrac{r^b\, r_\alpha\, r_\beta}{r^5}
+
\dfrac{r_\beta\, g^b_\alpha ({\pmb x}.{\pmb \xi}) \, - \, r_\alpha \,g^b_\beta({\pmb x},{\pmb \xi})}{r^3}
\label{eqB16}
\end{equation}
obtained considering that 
$\nabla_\beta \, \nabla_\alpha\, r^2/2\, =\, g_{\alpha\, \beta}({\pmb \xi})$, $\nabla^b \, \nabla_\beta \, r^2/2\, =\,- g^b_{\,\, \beta}({\pmb x},{\pmb \xi})$, $\nabla_\alpha\, r^{-3}\, =\, -3\, r_\alpha \, r^{-5}$.

As in eq. (\ref{eq71_}), the Stokeslet dipole can be expressed in term of its symmetric and antisymmetric part 
\begin{equation}
\nabla_\alpha\, S^b_{\, \, \beta}({\pmb x},{\pmb \xi})
\,=\,
\dfrac{ \eta^{\gamma \, \delta}_{\alpha \, \beta} }{2}
\,
\nabla_\gamma\, S^b_{\, \, \delta}({\pmb x},{\pmb \xi})
\,+\,
\dfrac{ \varepsilon_{\zeta \alpha \beta}\, \varepsilon^{\zeta \gamma \delta} }{2}
\,
\nabla_\gamma\, S^b_{\, \, \delta}({\pmb x},{\pmb \xi})
\label{eqB18}
\end{equation}
The first term in eq. (\ref{eqB18}), referred to as the unbounded {Stresslet} is
\begin{equation}
\dfrac{ \eta^{\gamma \, \delta}_{\alpha \, \beta} }{2}
\,
\nabla_\gamma\, S^b_{\, \, \delta}({\pmb x},{\pmb \xi})=
\left( 
- \dfrac{g^{\gamma \, \delta}({\pmb \xi}) \, g_{\alpha \,\beta}({\pmb \xi}) }{3}
+
\dfrac{ \eta^{\gamma \, \delta}_{\alpha \, \beta}  }{2}
\right)
3\dfrac{r^b\, r_\gamma\, r_\delta}{r^5}
\label{eqB19}
\end{equation}
whereas, the so called unbounded Couplet at the second term of eq. (\ref{eqB18}) is
\begin{equation}
\dfrac{\varepsilon^{\beta \gamma \delta} }{2}
\,
\nabla_\gamma\, S^b_{\, \, \delta}({\pmb x},{\pmb \xi})
=
\dfrac{\varepsilon^{\beta \gamma \delta}\, g^b_{\, \, \gamma}({\pmb x},{\pmb \xi}) }{2 \sqrt{g({\pmb \xi}) } }
\, \dfrac{r_\delta}{r^3}
\label{eqB20}
\end{equation} 
The unbounded Sourcelet ${\rm M}^a({\pmb x},{\pmb \xi})$ is the solution of the system eqs. (\ref{eq9}) considering $\partial V_f$ being a surface at infinity. In this case, the corresponding pressure $\phi({\pmb x},{\pmb \xi})$ is a constant \cite{pozrikidis_1992} and, from eq. (\ref{eq14}) and the expression of pressure associated with the Green function in the unbounded domain eq. (\ref{eqB8})
\begin{equation}
{\rm M}^a({\pmb x},{\pmb \xi})= \dfrac{r^a}{r^3}
\label{eqB21}
\end{equation}
The Source dipole in the unbounded domain, obtained by differentiating ${\rm M}^a({\pmb x},{\pmb \xi})$ at its pole ${\pmb \xi}$, is
\begin{equation}
\nabla_\beta\, {\rm M}^b({\pmb x},{\pmb \xi})\,=\,
-
\left(
\dfrac{g^b_{\, \, \beta}({\pmb x},{\pmb \xi})}{r^3}
+
3
\dfrac{r^b\,r_\beta}{r^5}
\right) 
\label{eqB22}
\end{equation}


