\section{Useful geometric relations for the cylindrical coordinate system}
\label{app_useful_geo}
The metric tensor of the cylindrical coordinate system at the point ${\pmb x}$ is obtained by using eqs. (\ref{eq20}) and the expression \cite{synge_tensor_1978}
\begin{equation}
g_{a\, b}({\pmb x})= \dfrac{\partial \overline{x}_i}{\partial x^a}\, \dfrac{\partial \overline{x}_i}{\partial x^b}
\label{eqA1}
\end{equation}
From which
\begin{equation}
g_{1\, 1}({\pmb x})= 1 ; \quad g_{2\, 2}({\pmb x})= (x^1)^2 ; \quad g_{3\, 3}({\pmb x})= 1 ;\quad g_{a\,b}({\pmb x}) = 0\quad \text{for}\quad a \neq b
\label{eqA2}
\end{equation}
the contravariant metric tensor $ g^{a\, b}({\pmb x})$, defined by the relation $g^{a\, c}({\pmb x})\, g_{c\, b}({\pmb x})= \delta^a_b$ reads

\begin{equation}
g^{1\, 1}({\pmb x})= 1 ; \quad g^{2\, 2}({\pmb x})= \dfrac{1}{ (x^1)^2} ; \quad g^{3\, 3}({\pmb x})= 1 ;\quad g^{a\,b}({\pmb x}) = 0\quad \text{for}\quad a \neq b
\label{eqA3}
\end{equation}
Similarly, at the point ${\pmb \xi}$, the metric tensor of the cylindrical coordinate system is
\begin{equation}
g_{1\, 1}({\pmb \xi})= 1 ; \quad g_{2\, 2}({\pmb \xi})= (\xi^1)^2 ; \quad g_{3\, 3}({\pmb \xi})= 1 ;\quad g_{\alpha\,\beta}({\pmb \xi}) = 0\quad \text{for} \quad \alpha \neq \beta
\label{eqA4}
\end{equation}
and
\begin{equation}
g^{1\, 1}({\pmb \xi})= 1 ; \quad g^{2\, 2}({\pmb \xi})= \dfrac{1}{ (\xi^1)^2} ; \quad g^{3\, 3}({\pmb \xi})= 1 ;\quad g^{\alpha \,\beta}({\pmb \xi}) = 0\quad \text{for}\quad \alpha \neq \beta
\label{eqA5}
\end{equation}
The
non vanishing entries of the
Christoffel symbols $\Gamma^a_{b \,c}({\pmb x})$ of second kind at the point ${\pmb x}$
are
\begin{equation}
\Gamma^{1}_{2\, 2}({\pmb x})\,=\, -x^1; \quad  \Gamma^{2}_{1\, 2}({\pmb x})\,=\,\Gamma^{2}_{2\, 1}({\pmb x})\, =\, \dfrac{1}{x^1}
\end{equation}
and of the Christoffel symbols $\Gamma^\alpha_{\beta\, \gamma}({\pmb \xi})$
at the point ${\pmb \xi}$
\begin{equation}
\Gamma^{1}_{2\, 2}({\pmb \xi})\,=\, -\xi^1; \quad  \Gamma^{2}_{1\, 2}({\pmb \xi})\,=\,\Gamma^{2}_{2\, 1}({\pmb \xi})\, =\, \dfrac{1}{\xi^1}
\label{eqA7ch}
\end{equation}
The transformation matrix $\dfrac{\partial \overline{x}_i}{\partial x^a}$,
that transforms the contravariant entries of a vector ${\pmb v}({\pmb x})$ from the cylindrical coordinates into the Cartesian coordinates via
\begin{equation}
\overline{v}_i({\pmb x})= \dfrac{\partial \overline{x}_i}{\partial x^a} \, v^a({\pmb x})
\label{eqA7}
\end{equation}
admits entries 
\begin{equation} 
\begin{array}{l}
\dfrac{\partial \overline{x}_1}{\partial x^1}= \cos{(x^2)}; \quad
\dfrac{\partial \overline{x}_1}{\partial x^2}= - x^1 \sin{(x^2)}; \quad
\dfrac{\partial \overline{x}_2}{\partial x^1}= \sin{(x^2)}; \quad
\dfrac{\partial \overline{x}_2}{\partial x^2}=  x^1 \cos{(x^2)}; 
\\
[15 pt]
\dfrac{\partial \overline{x}_3}{\partial x^3}= 1;
\quad 
\dfrac{\partial \overline{x}_1}{\partial x^3}= 
\dfrac{\partial \overline{x}_3}{\partial x^1}= 
\dfrac{\partial \overline{x}_2}{\partial x^3}= 
\dfrac{\partial \overline{x}_3}{\partial x^2}= 0
\end{array}
\label{eqA8}
\end{equation}
Its inverse matrix $\dfrac{\partial x^a}{\partial \overline{x}_i}$ is defined componentwise
\begin{equation}
\begin{array}{l}
\dfrac{\partial x^1}{\partial \overline{x}_1}= \cos{(x^2)} ; \quad
\dfrac{\partial x^1}{\partial \overline{x}_2}= \sin{(x^2)}; \quad
\dfrac{\partial x^2}{\partial \overline{x}_1}= - \dfrac{ \sin{(x^2)} }{x^1}; \quad
\dfrac{\partial x^2}{\partial \overline{x}_2}= \dfrac{ \cos{(x^2)} }{x^1} ;
\hspace{1cm} 
\\
[15 pt]
\dfrac{\partial x^3}{\partial \overline{x}_3}= 1;
\quad 
\dfrac{\partial x^1}{\partial \overline{x}_3}=  
\dfrac{\partial x^3}{\partial \overline{x}_1}= 
\dfrac{\partial x^2}{\partial \overline{x}_3}= 
\dfrac{\partial x^3}{\partial \overline{x}_2}= 0
\end{array}
\label{eqA9}
\end{equation}
Similarly, at the point ${\pmb \xi}$, the transformation matrix 
$ \dfrac{\partial \overline{\xi}_i}{\partial \xi^a}$
\begin{equation} 
\begin{array}{l}
\dfrac{\partial \overline{\xi}_1}{\partial \xi^1}= \cos{(\xi^2)}; \quad
\dfrac{\partial \overline{\xi}_1}{\partial \xi^2}= - \xi^1 \sin{(\xi^2)}; \quad
\dfrac{\partial \overline{\xi}_2}{\partial \xi^1}= \sin{(\xi^2)}; \quad
\dfrac{\partial \overline{\xi}_2}{\partial \xi^2}=  \xi^1 \cos{(\xi^2)}; 
\\
[15 pt]
\dfrac{\partial \overline{\xi}_3}{\partial \xi^3}= 1;
\quad 
\dfrac{\partial \overline{\xi}_1}{\partial \xi^3}= 
\dfrac{\partial \overline{\xi}_3}{\partial \xi^1}= 
\dfrac{\partial \overline{\xi}_2}{\partial \xi^3}= 
\dfrac{\partial \overline{\xi}_3}{\partial \xi^2}= 0
\end{array}
\label{eqA10}
\end{equation}
and the inverse matrix $ \dfrac{\partial \xi^a}{\partial \overline{\xi}_i}$
\begin{equation}
\begin{array}{l}
\dfrac{\partial \xi^1}{\partial \overline{\xi}_1}= \cos{(\xi^2)} ; \quad
\dfrac{\partial \xi^1}{\partial \overline{\xi}_2}= \sin{(\xi^2)}; \quad
\dfrac{\partial \xi^2}{\partial \overline{\xi}_1}= - \dfrac{ \sin{(\xi^2)} }{\xi^1}; \quad
\dfrac{\partial \xi^2}{\partial \overline{\xi}_2}= \dfrac{ \cos{(\xi^2)} }{\xi^1} ;
\hspace{1cm} 
\\
[15 pt]
\dfrac{\partial \xi^1}{\partial \overline{\xi}_1}= 1;
\quad 
\dfrac{\partial \xi^1}{\partial \overline{\xi}_3}=  
\dfrac{\partial \xi^3}{\partial \overline{\xi}_1}= 
\dfrac{\partial \xi^2}{\partial \overline{\xi}_3}= 
\dfrac{\partial \xi^3}{\partial \overline{\xi}_2}= 0
\end{array}
\label{eqA11}
\end{equation}




