Notably, by stationarity, for each $i \in\{f,w\}$  and for each $a \in \mathcal{A}$, 
$$x_{i,a}^{(t+1)} = \eta  U_{i,a}^{(t)}-\lambda_i + \mu_{i,a}.$$

\begin{customclm}{1}
\label{claim:stationarity_reqs}
    If $x_{i,a}^{(t+1)} >0$ and $x_{i,a'}^{(t+1)} >0$, then \begin{align*}
    x_{i,a}^{(t+1)}-x_{i,a'}^{(t+1)} = \eta U_{i,a}^{(t)}-\eta U_{i,a'}^{(t)} &\label{lagrangian_1}\tag{1}
\end{align*}
\end{customclm} 
\begin{proof}
    If $x_{i,a}^{(t+1)} >0, x_{i,a'}^{(t+1)} >0$, then by complementary slackness, we have $\mu_{i,a} = \mu_{i,a'} = 0$.

    By stationarity, this implies that $$x_{i,a}^{(t+1)} = \eta U_{i,a}^{(t)} - \lambda_i,$$ and 
    $$x_{i,a'}^{(t+1)} = \eta U_{i,a'}^{(t)} - \lambda_i.$$ 

    The claim immediately follows.
\end{proof}


\begin{customclm}{2}
\label{claim:kkt_ordering}
    Consider agent $i$ and two possible strategies of $i$: $a,a' \in \mathcal{A}$. If at least one of $x_{i,a}^{(t+1)}, x_{i,a'}^{(t+1)}$ has non-zero probability mass, then $x_{i,a}^{(t+1)} \ge x_{i,a'}^{(t+1)} $ if and only if $U_{i,a}^{(t)} \ge U_{i,a'}^{(t)}$ with equality if and only if $x_{i,a}^{(t+1)} = x_{i,a'}^{(t+1)}$.
\end{customclm}
\begin{proof}
    To begin, the KKT conditions imply 
    $$x_{i,a}^{(t+1)}-\eta U_{i,a}^{(t)}+\lambda_i \ge 0,$$
    and 
    $$x_{i,a}^{(t+1)}(x_{i,a}^{(t+1)}-\eta U_{i,a}^{(t)}+\lambda_i) = 0.$$
    This implies $$x_{i,a}^{(t)} = \begin{cases}
        \eta U_{i,a}^{(t)}-\lambda_i & \lambda_i < \eta U_{i,a}^{(t)}\\
        0 & \lambda_i \ge \eta U_{i,a}^{(t)}
    \end{cases}$$

    First, suppose $x_{i,a}^{(t+1)}\ge x_{i,a'}^{(t+1)}$. If $x_{i,a}^{(t+1)}>0$ and $x_{i,a'}^{(t+1)} = 0$, then from above we have $ \eta U_{i,a'}^{(t)}\le \lambda_i <\eta U_{i,a}^{(t)}$ and immediately we have $U_{i,a'}^{(t)}< U_{i,a}^{(t)}$. If both $x_{i,a}^{(t+1)}>0$ and $x_{i,a'}^{(t+1)} > 0$, then from Claim~\ref{claim:stationarity_reqs}, we have $$x_{i,a}^{(t+1)} - x_{i,a'}^{(t+1)}  = \eta\left(U_{i,a}^{(t)}-U_{i,a'}^{(t)}\right)\ge 0,$$
    so we have $U_{i,a'}^{(t)}\le U_{i,a}^{(t)}$ with equality if and only if $x_{i,a}^{(t+1)} = x_{i,a'}^{(t+1)}$.

    Next, suppose $U_{i,a'}^{(t)}\le U_{i,a}^{(t)}$. If both $x_{i,a}^{(t+1)}>0$ and $x_{i,a'}^{(t+1)} > 0$, then, $x_{i,a}^{(t+1)} \ge x_{i,a'}^{(t+1)}$ with equality if and only if $U_{i,a'}^{(t)}= U_{i,a}^{(t)}$ immediately follows from Claim~\ref{claim:stationarity_reqs}. Next, if $x_{i,a}^{(t+1)}>0$ and $x_{i,a'}^{(t+1)} = 0$, then we immediately have $x_{i,a}^{(t+1)}>x_{i,a'}^{(t+1)}$. Further, it cannot be the case that $U_{i,a'}^{(t)} =  U_{i,a}^{(t)}$ because this case implies $ \eta U_{i,a'}^{(t)}\le \lambda_i <\eta U_{i,a}^{(t)}$. Finally, if $x_{i,a}^{(t+1)}=0$ and $x_{i,a'}^{(t+1)} >0$, then we must have $ \eta U_{i,a}^{(t)}\le \lambda_i <\eta U_{i,a'}^{(t)}$ which contradicts our original assumption $U_{i,a'}^{(t)}\le U_{i,a}^{(t)}$ and we can conclude that such a probability assignment in $x_i^{(t+1)}$ is not possible.



\end{proof}
