\subsection{Convergence to $\epsilon$-Mixed NE}

First we state the main theorem to prove in this section. We will then prove several lemmas that will be necessary to prove this theorem. We will close by proving the main theorem. Throughout this section, we assume a firm and worker agent are learning strategies for $\mathcal{G}^{(1)}$ using Algorithm~\ref{alg:ftrl} parameterized by any $\eta >0, D>2$.


\begin{customthrm}{1}
    \label{thrm:ftrl_convergence_n=1}
    Suppose agents learn strategies for $\mathcal{G}^{(1)}$ using Algorithm~\ref{alg:ftrl} with $\alpha_i=\mathbf{0}$, any $\eta >0, D>2$, and arbitrary initial conditions $x_w^{(1)}, x_f^{(1)} \in \Delta(\mathcal{A})$. Then, for any $\epsilon>0$, there exists a finite time $t_\epsilon$ where $(x_f^{(\tau)},x_w^{(\tau)})$ is in $\epsilon$-Nash Equilibrium for all $\tau \ge t_\epsilon$. 
\end{customthrm}


\begin{customlem}{1}
\label{lem:worker_pmf_structure}
The sequence $x_{w,0}^{(t)}, \ldots, x_{w,1}^{(t)}$ is non-increasing at all time steps $t > 1$ for any arbitrary sequence of firm mixed strategies $x_{f}^{(1)}, \ldots, x_{f}^{(t-1)}$. Further, the sequence $u_w(x_f^{(t)},0), \ldots, u_w(x_f^{(t)},1)$ is non-increasing at all time steps $t > 1$ for any arbitrary firm mixed strategy $x_f^{(t)}$.
\end{customlem}
\begin{proof}
For any arbitrary sequence of firm mixed strategies $x_{f}^{(1)}, \ldots, x_{f}^{(t-1)}$, the cumulative utility the worker gets through time $t-1$ of an acceptance threshold $a \in \mathcal{A}$ is 
$$U_{w,a}^{(t-1)} = \sum_{\tau=1}^{t-1}\sum_{a_p \ge a}x_{f,a_p}^{(\tau)} \cdot a_p.$$
This implies the following cumulative utility relation between subsequent strategies $a_k < a_{k+1}$:
$$U_{w,a_k}^{(t-1)} = U_{w,a_{k+1}}^{(t-1)} + \sum_{\tau=1}^{t-1}x_{f,a_k}^{(\tau)} \cdot a_k.$$
Since $x_f$ is a probability distribution and each $a_k$ is non-negative, we can conclude $$U_{w,a_0}^{(t-1)} \ge \ldots \ge U_{w,a_D}^{(t-1)}.$$ 

By Claim~\ref{claim:kkt_ordering},  $x_{w,a_k}^{(t)} \ge x_{w,a_{k+1}}^{(t)}$ if and only if $U_{w,a_k}^{(t-1)} \ge U_{w,a_{k+1}}^{(t-1)}$ with equality if and only if $x_{w,a_k}^{(t)} = x_{w,a_{k+1}}^{(t)}$. Therefore, the sequence $x_{w,0}^{(t)},\ldots,x_{w,1}^{(t)}$ is non-increasing. 

The result above holds for the expected utility to the worker at any time step $t$ as well: $$u_w(x_f^{(t)},a_k) = u_w(x_f^{(t)},a_{k+1})  +x_{f,a_k}^{(t)} \cdot a_k,$$
so we may conclude
$$u_w(x_f^{(t)},a_0) \ge \ldots \ge u_w(x_f^{(t)},a_D).$$
\end{proof}

\begin{customlem}{2}
\label{lem:firm_pmf_structure}
     The sequence $x_{f,0}^{(t)},\ldots,x_{f,1}^{(t)}$ is unimodal at all time steps $t > 1$ for any arbitrary sequence of worker mixed strategies $x_{w}^{(1)}, \ldots, x_{w}^{(t-1)}$ that satisfy Lemma~\ref{lem:worker_pmf_structure}. Further, the sequence $u_f(0,x_w^{(t)}), \ldots, u_f(1,x_w^{(t)})$ is unimodal at all time steps $t > 1$ for any worker mixed strategy $x_w^{(t)}$ that satisfies Lemma~\ref{lem:worker_pmf_structure}.
\end{customlem}
\begin{proof}
    For any arbitrary sequence of worker mixed strategies $x_{w}^{(1)}, \ldots, x_{w}^{(t-1)}$, the cumulative utility the firm gets through time $t-1$ for an offer of $a \in \mathcal{A}$ is
    $$U_{f,a}^{(t-1)} = \sum_{\tau=1}^{t-1}\sum_{a_r\le a}x_{w,a_r}^{(\tau)} \cdot (1-a).$$
    We begin by showing the sequence $U_{f,0}^{(t-1)},\ldots,U_{f,1}^{(t-1)}$ is unimodal when the sequence $x_{w}^{(1)}, \ldots, x_{w}^{(t-1)}$ satisfies Lemma~\ref{lem:worker_pmf_structure}.

    Consider subsequent strategies $a_\ell = \frac{\ell}{D}, a_{\ell+1} = \frac{\ell+1}{D}$, then we have 
    \begin{align*}
        U_{f,a_{\ell+1}}^{(t-1)} - U_{f,a_{\ell}}^{(t-1)} = \sum_{\tau = 1}^{t-1} \left[x_{w,a_{\ell+1}}^{(\tau)}\left(\frac{D-\ell-1}{D}\right)- \sum_{a\le a_\ell} x_{w,a}^{(\tau)} \frac{1}{D}\right].\tag{1}\label{utility-diff}
    \end{align*}

    From expression~\ref{utility-diff}, note that
    \begin{align*}
        U_{f,a_{\ell}}^{(t-1)}\le U_{f,a_{\ell+1}}^{(t-1)} \iff \frac{\sum_{\tau=1}^{t-1}x_{w,a_{\ell+1}}^{(\tau)}}{\sum_{\tau=1}^{t-1}\sum_{a\le a_{\ell}}x_{w,a}^{(\tau)}} \ge \frac{1}{D-\ell-1}.\tag{2}\label{l+1>=l}
    \end{align*}

    Suppose $a_k = \frac{k}{D}$ is a cumulative utility maximizer, i.e., \begin{align*}
        U_{f,a_k}^{(t-1)} - U_{f,a}^{(t-1)} \ge 0,\forall a \neq a_k \in \mathcal{A}.\tag{3}\label{utility-max}
    \end{align*}

    So, to establish that $U_{f,a_1}^{(t-1)},\ldots,U_{f,a_{D-1}}^{(t-1)}$ is unimodal, it suffices to show
    \begin{align*}
        U_{f,a_{\ell-1}}^{(t-1)} - U_{f,a_{\ell}}^{(t-1)}, &\le 0&\forall \ell \in \{1,\ldots,k\}\\
        U_{f,a_\ell}^{(t-1)} - U_{f,a_{\ell+1}}^{(t-1)} &\ge 0. &\forall \ell \in \{k,\ldots,D-1\}
    \end{align*}


    By Lemma~\ref{lem:worker_pmf_structure}, $x_w^{(\tau)}$ is non-increasing as the acceptance thresholds $a \to 1$ at every time step $\tau$. Further, each $x_{w,a}^{(\tau)}\ge 0$ at every time step $\tau$, so whenever $i \ge j$, 
    $$\sum_{a\le a_i}x_{w,a}^{(\tau)} \ge \sum_{a\le a_j}x_{w,a}^{(\tau)}.$$
    Therefore, $\forall \ell \in\{1,\ldots,k\}$, 
    $$\frac{\sum_{\tau=1}^{t-1}x_{w,a_{\ell}}^{(\tau)}}{\sum_{\tau=1}^{t-1}\sum_{a\le a_{\ell-1}}x_{w,a}^{(\tau)}} \ge \frac{\sum_{\tau=1}^{t-1}x_{w,a_{k}}^{(\tau)}}{\sum_{\tau=1}^{t-1}\sum_{a\le a_{k-1}}x_{w,a}^{(\tau)}}\ge \frac{1}{D-k},$$
    and $\forall \ell \in\{k,\ldots,D-1\}$, 
    $$\frac{\sum_{\tau=1}^{t-1}x_{w,a_{\ell+1}}^{(\tau)}}{\sum_{\tau=1}^{t-1}\sum_{a\le a_\ell}x_{w,a}^{(\tau)}} \le \frac{\sum_{\tau=1}^{t-1}x_{w,a_{k+1}}^{(\tau)}}{\sum_{\tau=1}^{t-1}\sum_{a\le a_k}x_{w,a}^{(\tau)}}\le \frac{1}{D-k-1},$$
    where the last inequality in each expression follows from combining expressions~\ref{l+1>=l} and~\ref{utility-max}.
    Therefore,
    \begin{align*}
        \frac{\sum_{\tau=1}^{t-1}x_{w,a_{\ell}}^{(\tau)}}{\sum_{\tau=1}^{t-1}\sum_{a\le a_{\ell-1}}x_{w,a}^{(\tau)}} &\ge \frac{1}{D-\ell} &\forall \ell \in \{1,\ldots,k\},\\
        \frac{\sum_{\tau=1}^{t-1}x_{w,a_{\ell+1}}^{(\tau)}}{\sum_{\tau=1}^{t-1}\sum_{a\le a_\ell}x_{w,a}^{(\tau)}} &\le \frac{1}{D-\ell-1} & \forall \ell\in\{k,\dots,D-1\}.
    \end{align*}


    Finally, Claim~\ref{claim:kkt_ordering} implies that if the sequence $U_{f,0}^{(t-1)},\ldots,U_{f,1}^{(t-1)}$ is unimodal, then the sequence $x_{f,0}^{(t)},\ldots,x_{f,1}^{(t)}$ is unimodal as well.

    Further, the above logic holds for any time step $t$ where $x_{w}^{(t)}$ satisfies Lemma~\ref{lem:worker_pmf_structure}, so we can conclude $u_f(0,x_w^{(t)}), \ldots, u_f(1,x_w^{(t)})$ is unimodal as well. 

\end{proof}
Recall the following notation which will be used throughout the subsequent lemmas and main theorems.  
\begin{align*}
    w_{\max}^{(t)} &=  \max \{a | x_{w,a}^{(t)} >0 \},\\
    f_{\min}^{(t)} &= \min \{a | x_{f,a}^{(t)} >0 \}.
\end{align*}
\begin{customlem}{3}
    \label{lem:stationary_x_w}
    If agents play strategies at time $t$ such that $w_{\max}^{(t)} \le f_{\min}^{(t)}$, then $x_w^{(t+1)} = x_w^{(t)}$.
\end{customlem}
\begin{proof}
    Notice that, for any acceptance threshold $ a'\le f_{\min}^{(t)}$, $$u_w(x_f^{(t)},a') = \sum_{a \ge f_{\min}^{(t)}}x_{f,a}^{(t)} \cdot a$$
    because $x_{f,a}^{(t)} =0$ for all $a < f_{\min}^{(t)}$ by definition. This implies, for any $a,a' \le f_{\min}^{(t)}$, 
     \begin{align*}
         U_{w,a}^{(t)} - U_{w,a'}^{(t)} = U_{w,a}^{(t-1)} - U_{w,a'}^{(t-1)}. &\tag{1}\label{cumulative-utility-diff-same}
     \end{align*}
    % Next, for $a,a' \in \mathcal{A}$ where $a \le f_{\min}^{(t)} < a'$, $$u_w(x_f^{(t)},a) - u_w(x_f^{(t)},a') \ge x_{f,f_{\min}^{(t)}}^{(t)} \cdot f_{\min}^{(t)} >0.$$ 

    First, we show that any acceptance threshold that gets some mass at time $t$ and time $t+1$ must have the same probability mass difference with other such acceptance thresholds. Since $w_{\max}^{(t)} \le f_{\min}^{(t)}$, then for any $a,a' \in \mathcal{A}$ where $x_{w,a}^{(t)}>0, x_{w,a'}^{(t)}>0$, by Claim~\ref{claim:stationarity_reqs} and equation~\ref{cumulative-utility-diff-same}, $$x_{w,a}^{(t)} -x_{w,a'}^{(t)} = \eta(U_{w,a}^{(t-1)} - U_{w,a'}^{(t-1)}) = \eta(U_{w,a}^{(t)} - U_{w,a'}^{(t)} ).$$
    This implies that, if $x_{w,a}^{(t+1)}>0, x_{w,a'}^{(t+1)}>0$, then \begin{align*}
        x_{w,a}^{(t+1)} -x_{w,a'}^{(t+1)} = x_{w,a}^{(t)} -x_{w,a'}^{(t)} & \tag{2}\label{mass_diff}
    \end{align*}

    Next, suppose for some $ a,a' \le w_{\max}^{(t)}$, we have $x_{w,a}^{(t)}>0, x_{w,a'}^{(t)}>0$, but  $x_{w,a}^{(t+1)}>0, x_{w,a'}^{(t+1)}=0$. By Claim~\ref{claim:kkt_ordering}, the only way for this case to occur is for at least one acceptance threshold $a' \le w_{\max}^{(t)}$ to get 0 mass at time $t+1$ and no acceptance threshold greater than $w_{\max}^{(t)}$, which gets 0 mass at time $t$ by definition, to have non-zero mass at time $t+1$. Therefore, this is the only case to consider for an acceptance threshold getting 0 mass at time $t+1$ after having non-zero mass at time $t$.
    Here, the number of acceptance thresholds that get mass must be strictly less than those that do at time $t$, so by the primal constraints and equation~\ref{mass_diff} we must have $$ x_{w,a}^{(t+1)} > x_{w,a}^{(t)}.$$
    Then, by the KKT conditions, $$\lambda_w^{(t+1)} = \eta(U_{w,a}^{(t-1)}+u_w(x_f^{(t)},a))-x_{w,a}^{(t+1)} \ge \eta(U_{w,a'}^{(t-1)}+u_w(x_f^{(t)},a')).$$ 
    Since $w_{\max}^{(t)} \le f_{\min}^{(t)}$, then $u_w(x_f^{(t)},a)=u_w(x_f^{(t)},a')$, so $$ \eta(U_{w,a}^{(t-1)}-U_{w,a'}^{(t-1)}) \ge x_{w,a}^{(t+1)}.$$ 
    By Claim~\ref{claim:stationarity_reqs}, this implies 
    $$ x_{w,a}^{(t)} - x_{w,a'}^{(t)} \ge x_{w,a}^{(t+1)},$$ 
    however, since $x_{w,a'}^{(t)} >0$, this implies the contradiction
    $$ x_{w,a}^{(t)} > x_{w,a}^{(t+1)}.$$
    Therefore, it is impossible for some $a,a' \le w_{\max}^{(t)}$ to satisfy $x_{w,a}^{(t)}>0, x_{w,a'}^{(t)}>0$, but  $x_{w,a}^{(t+1)}>0, x_{w,a'}^{(t+1)}=0$.

    Finally, suppose for some $ a \le w_{\max}^{(t)} < a'$, we have $x_{w,a}^{(t)}>0, x_{w,a'}^{(t)}=0$, but  $x_{w,a}^{(t+1)}>0, x_{w,a'}^{(t+1)}>0$. Note by Claim~\ref{claim:kkt_ordering}, it is impossible for $x_{w,a}^{(t)}=0, x_{w,a'}^{(t)}>0$ since the cumulative utility functions are non-increasing as $a$ increases, so this is the only case to consider for an acceptance threshold gaining mass at time $t+1$ after having 0 mass at time $t$. Further, by the primal constraints and equation~\ref{mass_diff}, this implies $$x_{w,a}^{(t+1)} < x_{w,a}^{(t)}.$$
    First, by the KKT conditions, $$\eta U_{w,a'}^{(t-1)}\le\lambda_w^{(t)} = \eta U_{w,a}^{(t-1)}- x_{w,a}^{(t)},$$
    but if $x_{w,a'}^{(t+1)}>0$ $$\lambda_w^{(t+1)}< \eta  U_{w,a'}^{(t)}.$$
    Since $x_{w,a}^{(t+1)} < x_{w,a}^{(t)}$, $$\lambda_w^{(t+1)} = \eta(U_{w,a}^{(t-1)}+u_w(x_f^{(t)},a))- x_{w,a}^{(t+1)} \ge \lambda_w^{(t)} + \eta u_w(x_f^{(t)},a).$$
    However, since $u_w(x_f^{(t)},a) \ge u_w(x_f^{(t)},a')$ by Lemma~\ref{lem:worker_pmf_structure}, $$\lambda_w^{(t)}+\eta u_w(x_f^{(t)},a) \ge \eta( U_{w,a'}^{(t-1)}+u_w(x_f^{(t)},a')),$$
    which implies the contradiction $$ \lambda_w^{(t+1)} \ge \eta U_{w,a'}^{(t)}.$$
    Therefore, the same acceptance thresholds get non-zero probability mass at time $t$ and $t+1$ and their probability mass differences must remain the same, thus, $x_w^{(t+1)} = x_w^{(t)}$.
\end{proof}

\begin{customlem}{4}
    \label{lem:x_w_a_r,+_decreases}
    Suppose at time $t$ that $f_{\min}^{(t)} < w_{\max}^{(t)}$. Then, $x_{w,w_{\max}^{(t)}}^{(t+1)} < x_{w,w_{\max}^{(t)}}^{(t)}$.
\end{customlem}
\begin{proof}
    To begin, if $x_{w,w_{\max}^{(t)}}^{(t+1)} = 0$, then immediately by definition of $w_{\max}^{(t)}$, $$x_{w,w_{\max}^{(t)}}^{(t+1)} < x_{w,w_{\max}^{(t)}}^{(t)}.$$

    Next suppose $x_{w,w_{\max}^{(t)}}^{(t+1)} > 0$. First, by Lemma~\ref{lem:worker_pmf_structure} and the definition of $w_{\max}^{(t)}$, for all $a < w_{\max}^{(t)}$, $$x_{w,a}^{(t)} \ge x_{w,w_{\max}^{(t)}}^{(t)}>0,$$
    and Claim~\ref{claim:kkt_ordering} implies $$U_{w,a}^{(t-1)} \ge U_{w,w_{\max}^{(t)}}^{(t-1)}.$$
    Next, since $f_{\min}^{(t)} < w_{\max}^{(t)}$ it must be the case that, for all $a < w_{\max}^{(t)}$, $$u_w(x_f^{(t)},a) - u_w(x_f^{(t)},w_{\max}^{(t)})>0.$$
    Therefore, \begin{align*}
        U_{w,a}^{(t)} - U_{w,w_{\max}^{(t)}}^{(t)}  > U_{w,a}^{(t-1)} - U_{w,w_{\max}^{(t)}}^{(t-1)} &\tag{1}\label{growing_diff}
    \end{align*}
    Since $x_{w,w_{\max}^{(t)}}^{(t+1)} > 0$, then by Lemma~\ref{lem:worker_pmf_structure}, $x_{w,a}^{(t+1)} > 0$ for all $a < w_{\max}^{(t)}$. Then, Claim~\ref{claim:stationarity_reqs} and inequality~\ref{growing_diff} implies for all $a < w_{\max}^{(t)}$, $$x_{w,a}^{(t+1)} - x_{w,w_{\max}^{(t)}}^{(t+1)}>x_{w,a}^{(t)} - x_{w,w_{\max}^{(t)}}^{(t)}.$$
    If $x_{w,w_{\max}^{(t)}}^{(t+1)} \ge x_{w,w_{\max}^{(t)}}^{(t)}$, then this implies for all $a < w_{\max}^{(t)}$, 
    \begin{align*}
        x_{w,a}^{(t+1)} > x_{w,a}^{(t)} & \tag{2}\label{larger_a}
    \end{align*}
    However, by the primal constraint $$\sum_{a \le w_{\max}^{(t)}}x_{w,a}^{(t)} = 1,$$
    so the assumption $x_{w,w_{\max}^{(t)}}^{(t+1)} \ge x_{w,w_{\max}^{(t)}}^{(t)}$ along with inequality~\ref{larger_a} implies that  $$\sum_{a \le w_{\max}^{(t)}}x_{w,a}^{(t+1)} > 1,$$
    which violates the primal constraint at time $t+1$. Therefore, $$x_{w,w_{\max}^{(t)}}^{(t+1)} < x_{w,w_{\max}^{(t)}}^{(t)}.$$

\end{proof}
\begin{customlem}{5}
    \label{lem:a_r,+_never_increases}
    At any time step $t$, $w_{\max}^{(\tau)} \le w_{\max}^{(t)}$ for all $\tau \ge t$.
\end{customlem}
\begin{proof}
    First, if $f_{\min}^{(t)} \ge w_{\max}^{(t)}$, then by Lemma~\ref{lem:stationary_x_w}, $$x_{w}^{(t+1)} = x_w^{(t)} \implies x_{w,w_{\max}^{(t)}}^{(t+1)} = x_{w,w_{\max}^{(t)}}^{(t)}.$$

    Otherwise if $f_{\min}^{(t)} < w_{\max}^{(t)}$, then we will show it's impossible to have $a>w_{\max}^{(t)}$ with $x_{w,a}^{(t)}=0$ but $x_{w,a}^{(t+1)}>0$. 
    First, by Lemma~\ref{lem:x_w_a_r,+_decreases}, $$x_{w,w_{\max}^{(t)}}^{(t+1)} < x_{w,w_{\max}^{(t)}}^{(t)}.$$
    If $x_{w,w_{\max}^{(t)}}^{(t+1)} = 0$, then $x_{w,a}^{(t+1)} =0$ necessarily by Lemma~\ref{lem:worker_pmf_structure}. 

    Otherwise suppose $x_{w,w_{\max}^{(t)}}^{(t+1)}>0$.
    Note that the KKT conditions at time $t$ imply $$\eta U_{w,w_{\max}^{(t)}}^{(t-1)} -   \eta U_{w,a}^{(t-1)} \ge x_{w,w_{\max}^{(t)}}^{(t)}.$$
    Then, if $x_{w,a}^{(t+1)}>0$ and $x_{w,w_{\max}^{(t+1)}}^{(t+1)}>0$, by Claim~\ref{claim:stationarity_reqs}, it must be true that $$x_{w,w_{\max}^{(t)}}^{(t+1)} - x_{w,a}^{(t+1)} = \eta U_{w,w_{\max}^{(t)}}^{(t)} -   \eta U_{w,a}^{(t)},$$
    which implies $$x_{w,w_{\max}^{(t)}}^{(t+1)} > \eta U_{w,w_{\max}^{(t)}}^{(t)} -   \eta U_{w,a}^{(t)}.$$
    However, since $x_{w,w_{\max}^{(t)}}^{(t+1)} < x_{w,w_{\max}^{(t)}}^{(t)}$, then this implies $$U_{w,w_{\max}^{(t)}}^{(t-1)} -   \eta U_{w,a}^{(t-1)} > \eta U_{w,w_{\max}^{(t)}}^{(t)} -   \eta U_{w,a}^{(t)},$$ or $$u_w(x_f^{(t)},a) > u_w(x_f^{(t)},w_{\max}^{(t)})$$
    which is impossible by Lemma~\ref{lem:worker_pmf_structure}. Therefore, $w_{\max}^{(\tau)} \le w_{\max}^{(t)}$ for all $\tau \ge t$. 
\end{proof}

\begin{customlem}{6}
\label{lem:a_p,-_<=_a_r,+}
    Suppose at time $t$ that $w_{\max}^{(t)} < f_{\min}^{(t)}$. Then, there is always a time $t' >t$ where $f_{\min}^{(t')} \le w_{\max}^{(t')}$. 
\end{customlem}
\begin{proof}

     Suppose instead it is the case that for all $\tau \ge t$, $w_{\max}^{(\tau)} < f_{\min}^{(\tau)}$. First, notice by Lemma~\ref{lem:stationary_x_w} that for all $\tau \ge t$ where $w_{\max}^{(\tau)} < f_{\min}^{(\tau)}$,  $$x_w^{(\tau+1)} = x_w^{(\tau)},$$ thus,  $w_{\max}^{(\tau)} = w_{\max}^{(t)}$ for all $\tau \ge t$.

     Next, by definition of the firm's utility function, 
     \begin{align*}
     u_f(w_{\max}^{(\tau)}, x_w^{(\tau)}) \ge u_f(a, x_w^{(\tau)})+\frac{1}{D}, \forall a >w_{\max}^{(\tau)} 
     \end{align*}
    Therefore, since $w_{\max}^{(\tau)}$ is fixed for all $\tau \ge t$, there exists a time $t' > t$ where 
    \begin{align*}
        U_{f,w_{\max}^{(t')}}^{(t')} \ge  U_{f,a}^{(t')}, \forall a >w_{\max}^{(t')}
    \end{align*}
    So, if there exists $a> w_{\max}^{(t')}$ where $x_{f,a}^{(t')} >0$, then by Claim~\ref{claim:kkt_ordering}, it must be the case that $x_{f,w_{\max}^{(t')}}^{(t')} \ge x_{f,a}^{(t')} >0$ which implies 
    $$f_{\min}^{(t')} \le w_{\max}^{(t')}.$$
    Otherwise, if no such $a> w_{\max}^{(t')}$ where $x_{f,a}^{(t')} >0$ exists, then by definition of $f_{\min}^{(t')}$ and the primal constraints we again have
    $$f_{\min}^{(t')} \le w_{\max}^{(t')}.$$
    Therefore, by contradiction, there always exists a time $t' > t$ where $f_{\min}^{(t')} \le w_{\max}^{(t')}$.



\end{proof}

\begin{customlem}{7}
\label{lem:a_p,-_<=_a_r,+_for_all_t}
    Suppose at time $t$, $f_{\min}^{(t)} \le w_{\max}^{(t)}$. Then, there exists a finite time $t' \ge t$ where $f_{\min}^{(\tau)} \le w_{\max}^{(t)}$ for all $\tau \ge t'$. 
\end{customlem}
\begin{proof}
    Suppose at time $t$, $f_{\min}^{(t)} \le w_{\max}^{(t)}$. First, by Lemma~\ref{lem:a_r,+_never_increases}, $w_{\max}^{(\tau)} \le w_{\max}^{(t)}$ for all $\tau \ge t$. As a result, for all $\tau \ge t$, $$u_f(w_{\max}^{(t)}, x_w^{(\tau)}) \ge u_f(a, x_w^{(\tau)})+\frac{1}{D}, \forall a >w_{\max}^{(t)}.$$
    % Suppose there exists $a > w_{\max}^{(t)}$ where $x_{f,a}^{(t)}$
   which implies there exists a time $t'\ge t$ where for all $a >w_{\max}^{(t)}$ and all $\tau \ge t'$, $$U_{f,w_{\max}^{(t)}}^{(\tau)} \ge U_{f,a}^{(\tau)}.$$
    Therefore, by Claim~\ref{claim:kkt_ordering}, for all $\tau \ge t'$, it is impossible for at least one $a >w_{\max}^{(t)}$ to have $x_{f,a}^{(\tau)} >0$, but  $x_{f,w_{\max}^{(t)}}^{(\tau)} =0$. Thus, $f_{\min}^{(\tau)} \le w_{\max}^{(t)}$ for all $\tau \ge t'$.
\end{proof}

\begin{customlem}{8}
    \label{lem:a_p,-<a_r,+}
    Suppose at time $t$, $w_{\max}^{(t)} = \frac{k}{D}$ for some $k \in\{2,\ldots, D\}$,  $x_{w,w_{\max}^{(t)}}^{(t)} < \frac{1}{D-k+1}$, and $f_{\min}^{(t)} = w_{\max}^{(t)}$. Then, there is a finite time $t' > t$ where $f_{\min}^{(\tau)} < w_{\max}^{(t')}$ for all $\tau \ge t'$.
\end{customlem}
\begin{proof}
    Suppose at time $t$, $f_{\min}^{(t)} = w_{\max}^{(t)}$. First, by Lemma~\ref{lem:a_p,-_<=_a_r,+_for_all_t}, there exists a finite time $t' \ge t$ where $f_{\min}^{(\tau)} \le w_{\max}^{(t)}$ for all $\tau \ge t'$, so suppose $f_{\min}^{(\tau)} = w_{\max}^{(t)}$ for all $\tau \ge t'$. Then,  by Lemma~\ref{lem:stationary_x_w}, $x_w^{(\tau)} = x_w^{(t)}$ for all $\tau \ge t'$. Note that since $k \ge 2$, there exists a smaller action than $w_{\max}^{(t)}$: $w_{\max}^{(t)} - \frac{1}{D} \in\mathcal{A}$. Then $x_{w_{\max}^{(t)}}^{(\tau)}< \frac{1}{D-k+1}$ implies for all $\tau \ge t'$, 
    \begin{align*}
        u_f(w_{\max}^{(t)} - \frac{1}{D},x_w^{(\tau)}) > \left(1-\frac{1}{D-k+1}\right)\cdot \left(1-w_{\max}^{(t)} + \frac{1}{D}\right) = u_f(w_{\max}^{(t)},x_w^{(\tau)})
    \end{align*}
    which implies $$u_f(w_{\max}^{(t)} - \frac{1}{D},x_w^{(\tau)}) - u_f(w_{\max}^{(t)},x_w^{(\tau)})$$ is a constant, positive value for all $\tau \ge t'$. Therefore, there exists another time $t^*$ where 
    \begin{align*}
        U_{f,w_{\max}^{(t)} - \frac{1}{D}}^{(t^*)} \ge U_{f,w_{\max}^{(t)}}^{(t^*)} 
    \end{align*}
    Since $f_{\min}^{(\tau)} = w_{\max}^{(t)}$ for all $\tau \ge t'$, then we must have $x_{f,w_{\max}^{(t)}}^{(t^*)} >0$, but by Claim~\ref{claim:kkt_ordering},$$x_{f,w_{\max}^{(t)}-\frac{1}{D}}^{(t^*)} \ge x_{f,w_{\max}^{(t)}}^{(t^*} >0,$$
    which immediately implies $f_{\min}^{(t^*)} < w_{\max}^{(t)}$.

    Next, suppose at time $t$, $f_{\min}^{(t)} < w_{\max}^{(t)}$ and $x_{w,w_{\max}^{(t)}}^{(t)} < \frac{1}{D-k+1}$. Then, we will show it is impossible at time step $t+1$ to have $x_{f,a}^{(t+1)} = 0$ for all $a < w_{\max}^{(t)}$. 

    To begin, since  $x_{w,w_{\max}^{(t)}}^{(t)} < \frac{1}{D-k+1}$ and $u_f(w_{\max}^{(t)},x_w^{(t)}) \ge u_f(a,x_w^{(t)}) +\frac{1}{D}$ for all $a> w_{\max}^{(t)}$,
    \begin{align*}
        u_f(w_{\max}^{(t)} - \frac{1}{D},x_w^{(t)}) >  u_f(a,x_w^{(t)}),\forall a\ge w_{\max}^{(t)} &\tag{1}\label{inequality}
    \end{align*}
    First, suppose $x_{f,w_{\max}^{(t)}-\frac{1}{D}}^{(t)} >0.$ By Claim~\ref{claim:stationarity_reqs}, this implies for all $a \ge w_{\max}^{(t)}$ where $x_{f,a}^{(t)} >0$,
    \begin{align*}
        x_{f,w_{\max}^{(t)}-\frac{1}{D}}^{(t)} - x_{f,a}^{(t)}=\eta U_{f,w_{\max}^{(t)}-\frac{1}{D}}^{(t-1)} -\eta U_{f,a}^{(t-1)}, &\tag{2}\label{stationarity}
    \end{align*}and for all $a \ge w_{\max}^{(t)}$ where $x_{f,a}^{(t)} =0$,
    \begin{align*}
        U_{f,w_{\max}^{(t)}-\frac{1}{D}}^{(t-1)} >U_{f,a}^{(t-1)}. &\tag{3}\label{ordering}
    \end{align*}     
    Then, suppose $x_{f,w_{\max}^{(t)}-\frac{1}{D}}^{(t+1)} = 0$ and there exists $a \ge w_{\max}^{(t)}$ where $x_{f,a}^{(t+1)} >0$. This implies 
    $$U_{f,a}^{(t-1)}>U_{f,w_{\max}^{(t)}-\frac{1}{D}}^{(t-1)},$$
    so by inequalities~\ref{inequality} and~\ref{ordering}, it is impossible for such an $a$ to have $x_{f,a}^{(t)} =0$. So, it must be the case that $x_{f,a}^{(t)} >0$. Then by the KKT conditions, 
    \begin{align*}
        x_{f,a}^{(t+1)} &\le \eta  U_{f,a}^{(t)} - \eta U_{f,w_{\max}^{(t)}-\frac{1}{D}}^{(t)}
    \end{align*}
    Subtracting both sides by equation~\ref{stationarity} and applying inequality~\ref{inequality} implies
    $$x_{f,a}^{(t+1)} < x_{f,a}^{(t)}.$$
    Since this is true for any $a \ge w_{\max}^{(t)}$, then $$\sum_{a\ge w_{\max}^{(t)}}x_{f,a}^{(t+1)} < \sum_{a\ge w_{\max}^{(t)}}x_{f,a}^{(t)} \le 1,$$
    which implies by the primal constraints that it is impossible for all $a < w_{\max}^{(t)}$ to have $x_{f,a}^{(t+1)} = 0$ and this contradicts $x_{f,w_{\max}^{(t)}-\frac{1}{D}}^{(t+1)} = 0$.


    Next, suppose $x_{f,w_{\max}^{(t)}-\frac{1}{D}}^{(t)} =0.$ Then by Lemma~\ref{lem:firm_pmf_structure} there exists $f_{\min}^{(t)} \le a^* < w_{\max}^{(t)}-\frac{1}{D}$ such that 
    \begin{align*}
        U_{f,a^*}^{(t-1)} \ge U_{f,a}^{(t-1)}, \forall a \neq a^* & \tag{4}\label{mode_point}
    \end{align*}
    % Further, by Lemma~\ref{lem:firm_pmf_structure}, it is impossible for any $a \ge w_{\max}^{(t)}$ to have $x_{f,a}^{(t)} > 0$, so 
    % $$U_{f,a^*}^{(t-1)} > U_{f,a}^{(t-1)}, \forall a \neq a^*,$$.
    This implies, by Lemma~\ref{lem:firm_pmf_structure}, 
    \begin{align*}
        U_{f,w_{\max}^{(t)}-\frac{1}{D}}^{(t-1)} \ge U_{f,a}^{(t-1)}, \forall a \ge w_{\max}^{(t)} &\tag{5}\label{sequence}
    \end{align*}
    Then, if there exists $a \ge w_{\max}^{(t)}$ where $x_{f,a}^{(t+1)} > 0$, but all $a' < w_{\max}^{(t)}$ have $x_{f,a'}^{(t+1)} = 0$, then by Claim~\ref{claim:kkt_ordering}, $$U_{f,a}^{(t)} > U_{f,a^*}^{(t)},$$
    which along with inequality~\ref{mode_point} implies $$u_f(a,x_w^{(t)}) > u_f(a^*,x_w^{(t)}).$$
    However, by inequalities~\ref{inequality} and~\ref{sequence},  $$U_{f,w_{\max}^{(t)}-\frac{1}{D}}^{(t)} \ge U_{f,a}^{(t)},$$
    so by Claim~\ref{claim:kkt_ordering}, if $x_{f,a}^{(t+1)}> 0$, then $x_{f,w_{\max}^{(t)}-\frac{1}{D}}^{(t)} >0$ which contradicts all $a' < w_{\max}^{(t)}$ have $x_{f,a'}^{(t+1)} = 0$.

     Therefore, in all possible cases, $f_{\min}^{(t+1)} < w_{\max}^{(t)}$. Further, by Lemma~\ref{lem:x_w_a_r,+_decreases}, it is also the case that $$x_{w,w_{\max}^{(t)}}^{(t+1)}<x_{w,w_{\max}^{(t)}}^{(t)} < \frac{1}{D-k+1},$$
     so we can conclude $f_{\min}^{(\tau)} < w_{\max}^{(t)}$ for all $\tau \ge t$.

\end{proof}

\begin{customlem}{9}
\label{lem:a_r,+_decreasing_conditions}
    Suppose at time $t$,  $w_{\max}^{(t)} = \frac{k}{D}$ for some $k \in\{2,\ldots, D\}$,  $x_{w,w_{\max}^{(t)}}^{(t)} < \frac{1}{D-k+1}$, and $f_{\min}^{(\tau)} < w_{\max}^{(t)}$ for all $\tau \ge t$. Then, there is a finite time $t' > t$ where $w_{\max}^{(t')} < w_{\max}^{(t)}$.
\end{customlem}
\begin{proof}
    Suppose $f_{\min}^{(\tau)} < w_{\max}^{(t)}$ for all $\tau \ge t$. Then, we will show there must be another finite time $t' > t$ where $x_{w,w_{\max}^{(t)}}^{(t')} = 0$. Then by Lemma~\ref{lem:worker_pmf_structure} this implies it is also the case that $x_{w,a}^{(t')} = 0$ for all $a \ge w_{\max}^{(t)}$, and  we can conclude $w_{\max}^{(t')} < w_{\max}^{(t)}$. 

    First, note that since $k \ge 2$, there exists a smaller action than $w_{\max}^{(t)}$: $w_{\max}^{(t)} - \frac{1}{D} \in\mathcal{A}$.
    % \begin{align*}
    %     u_f(w_{\max}^{(t)}-\frac{1}{D},x_w^{(t)}) &= (1-x_{w,w_{\max}^{(t)}}^{(t)}) (1-(w_{\max}^{(t)}-\frac{1}{D})),\\
    %     u_f(w_{\max}^{(t)},x_w^{(t)}) &=  (1-w_{\max}^{(t)}).
    % \end{align*}
    Then, since $x_{w,w_{\max}^{(t)}}^{(t)} < \frac{1}{D-k+1}$, $$u_f(w_{\max}^{(t)}-\frac{1}{D},x_w^{(t)}) >u_f(w_{\max}^{(t)},x_w^{(t)}).$$
    Further, since $f_{\min}^{(\tau)} < w_{\max}^{(t)}$ for all $\tau \ge t$, by Lemma~\ref{lem:x_w_a_r,+_decreases} either $x_{w,w_{\max}^{(t)}}^{(\tau)} = 0$ or  $x_{w,w_{\max}^{(t)}}^{(\tau+1)}<x_{w,w_{\max}^{(t)}}^{(\tau)}$ for all $\tau \ge t$. Then, this implies by the definition of the firm's utility function that for all $\tau \ge t$,
    $$u_f(w_{\max}^{(t)}- \frac{1}{D}, x_w^{(\tau)}) -  u_f(w_{\max}^{(t)}, x_w^{(\tau)})> u_f(w_{\max}^{(t)}- \frac{1}{D}, x_w^{(t)}) -u_f(w_{\max}^{(t)}, x_w^{(t)})>0.$$
   %  Therefore,
   % $$U_{f,w_{\max}^{(t)} - \frac{1}{D}}^{(\tau+1)} - U_{f,w_{\max}^{(t)} - \frac{1}{D}}^{(\tau)}  > U_{f,w_{\max}^{(t)}}^{(\tau+1)}- U_{f,w_{\max}^{(t)}}^{(\tau)}.$$
   This implies there exists a time $t^*$ where  for all $\tau \ge t^*$, $$U_{f,w_{\max}^{(t)} - \frac{1}{D}}^{(\tau)} - U_{f,w_{\max}^{(t)}}^{(\tau)} \ge \frac{1}{\eta},$$
    and by Claim~\ref{claim:stationarity_reqs} and the primal constraints, it cannot be the case that both$$x_{f,w_{\max}^{(t)} - \frac{1}{D}}^{(\tau)}>0\text{ and }  
    x_{f,w_{\max}^{(t)}}^{(\tau)}>0,$$ and since $$U_{f,w_{\max}^{(t)} - \frac{1}{D}}^{(\tau)} > U_{f,w_{\max}^{(t)}}^{(\tau)},$$
    by Claim~\ref{claim:kkt_ordering}, we can conclude 
    $$x_{f,w_{\max}^{(t)}}^{(\tau)}=0, \forall \tau \ge t^*.$$

    So, there must always be a time $t^*> t$ where either $x_{w,w_{\max}^{(t)}}^{(t^*)} = 0$ or  $x_{w,w_{\max}^{(t)}}^{(t^*)}>0$ and $x_{f,w_{\max}^{(t)}}^{(\tau)} = 0$ for all $\tau \ge t^*$.
    The latter case implies that for all $\tau \ge t^*$, $$U_{w,w_{\max}^{(t)}}^{(\tau)} = U_{w,w_{\max}^{(t)}}^{(t^*-1)}.$$ 
    However, since $k\ge 2$, $\frac{1}{D}$ is a lower acceptance threshold for the worker than $w_{\max}^{(t)}$. Then, by the worker's utility function
    \begin{align*}
        u_w(x_f^{(t)},\frac{1}{D}) = \sum_{a \ge \frac{1}{D}}x_{f,a}^{(t)}\cdot a \ge (1-x_{f,0}^{(t)})\cdot \frac{1}{D}. &\tag{1}\label{1/D_bound}
    \end{align*}
    Note that by the fact that an acceptance threshold of $0$ for the worker cannot get more utility than an acceptance threshold of $\frac{1}{D}$, then by Lemma~\ref{lem:worker_pmf_structure} $$U_{w,0}^{(t)} = U_{w,\frac{1}{D}}^{(t)} \ge U_{w,a}^{(t)}, \forall a > \frac{1}{D}$$ for all time steps $t$, so by Claim~\ref{claim:stationarity_reqs} it is always the case that $x_{w,0}^{(t)} = x_{w,\frac{1}{D}}^{(t)} >0$. This implies that when $D>2$,
    $$u_f(\frac{1}{D},x_w^{(t)})  > u_f(0,x_w^{(t)}), \forall t.$$
    Therefore, $$U_{f,\frac{1}{D}}^{(t)} > U_{f,0}^{(t)}, \forall t$$
    So, by Claim~\ref{claim:kkt_ordering} $$x_{f,\frac{1}{D}}^{(t)}> x_{f,0}^{(t)}, \forall t. $$
    By the primal constraints, this implies $x_{f,0}^{(t)} < \frac{1}{2}$ for all $t$, so combining this fact with the lower bound~\ref{1/D_bound}, then for any time step $t$,
    $$U_{w,\frac{1}{D}}^{(t)} \ge U_{w,\frac{1}{D}}^{(t-1)}+ \frac{1}{2D}.$$ Therefore, since the cumulative utility of the offer $w_{\max}^{(t)}$ stops growing after time $t^*$, there must be a finite time $t' \ge t^*$ where $$U_{w,\frac{1}{D}}^{(t')} - U_{w,w_{\max}^{(t)}}^{(t')} \ge \frac{1}{\eta},$$
    and by Claim~\ref{claim:stationarity_reqs} and the primal constraints, it must be the case that $x_{w,w_{\max}^{(t)}}^{(t')}=0$ and we can conclude $w_{\max}^{(t')} < w_{\max}^{(t)}$.

\end{proof}
\begin{customlem}{10}
\label{lem:final_NE_convergence}
    Suppose at time $t$, $w_{\max}^{(t)} = \frac{k}{D}$ for some $k \in \{1,\ldots,D\}$, $f_{\min}^{(\tau)} \le w_{\max}^{(t)}$, and $x_{w,w_{\max}^{(t)}}^{(\tau)} \ge \frac{1}{D-k+1}$ for all $\tau \ge t$. Then, for any $\epsilon>0$, there exists a time $t_\epsilon \ge t$ where, for all $\tau \ge t_{\epsilon}$, $(x_f^{(\tau)}, x_w^{(\tau)})$ is in an $\epsilon$-mixed Nash Equilibrium. 
\end{customlem}
\begin{proof}
    % finite time until all greater offers have 0 mass
    Suppose at time $t$, $f_{\min}^{(\tau)} \le w_{\max}^{(t)}$ and $x_{w,w_{\max}^{(t)}}^{(\tau)} \ge \frac{1}{D-k+1}$ for all $\tau \ge t$. First, by definition of $w_{\max}^{(t)}$ and the firm's expected utility function, \begin{align*}
        u_f(w_{\max}^{(t)}, x_w^{(\tau)}) \ge u_f(a, x_w^{(\tau)})+\frac{1}{D}, \forall a > w_{\max}^{(t)} & \tag{1}\label{best-response-firm-greater-offers}
    \end{align*}
    This implies there exists a time $t' \ge t$ where for all $\tau \ge t'$ $$U_{f,w_{\max}^{(t)}}^{(\tau)} - U_{f,a}^{(\tau)} \ge \frac{1}{\eta}, \forall a> w_{\max}^{(t)}.$$
    Then, by Claim~\ref{claim:stationarity_reqs}, for each $a> w_{\max}^{(t)}$ and all time steps $\tau \ge t'$, it is impossible for $$x_{f,w_{\max}^{(t)}}^{(\tau)}>0, x_{f,a}^{(\tau)}>0.$$
    By expression~\ref{best-response-firm-greater-offers}, it must be the case that for all $\tau \ge t'$,
    \begin{align*}
        x_{f,a}^{(\tau)}= 0, \forall a> w_{\max}^{(t)} &\tag{2}\label{greater-offers-0}
    \end{align*}
    % next, a_r,+ is a utility maximizer
    Next, since, for all $\tau \ge t$,
    $$x_{w,w_{\max}^{(t)}}^{(\tau)} \ge \frac{1}{D-k+1},$$
    then for all $\tau \ge t$,
    \begin{align*}
        u_f(w_{\max}^{(t)}-\frac{1}{D},x_w^{(\tau)}) &\le (1-\frac{1}{D-k+1}) \frac{D-k+1}{D}\\
        &= \frac{D-k}{D} \\
        &= u_f(w_{\max}^{(t)},x_w^{(\tau)})
    \end{align*}
    By Lemma~\ref{lem:firm_pmf_structure}, if $u_f(w_{\max}^{(t)}-\frac{1}{D},x_w^{(\tau)}) \le u_f(w_{\max}^{(t)},x_w^{(\tau)})$, then it must also be the case that for all $a < w_{\max}^{(t)}$ and all $\tau \ge t$, $$u_f(a,x_w^{(\tau)}) \le u_f(w_{\max}^{(t)},x_w^{(\tau)}).$$
    Combining this with expression~\ref{best-response-firm-greater-offers}, we can conclude for all $\tau \ge t$ and all $a\neq w_{\max}^{(t)}$, 
    \begin{align*}
        u_f(w_{\max}^{(t)},x_w^{(\tau)}) \ge u_f(a,x_w^{(\tau)}). &\tag{3}\label{best-response-firm}
    \end{align*}


    We now break into the individual cases of $f_{\min}^{(\tau)} = w_{\max}^{(t)}$ for all $\tau \ge t$ and $f_{\min}^{(\tau)} < w_{\max}^{(t)}$ for all $\tau \ge t$ to finish the proof. It is sufficient to consider these two cases because after time $t'$ where expression~\ref{greater-offers-0} becomes true, then if $f_{\min}^{(t')} < w_{\max}^{(t)}$, but there exists a time $t^* > t'$ where $f_{\min}^{(t^*)} = w_{\max}^{(t)}$, then we immediately have $x_{f, w_{\max}^{(t)}}^{(t^*)} = 1$ and the first case below shows this implies convergence.

    % state 4 coverged to mixed-NE
    In the first case, suppose $f_{\min}^{(\tau)} = w_{\max}^{(t)}$ for all $\tau \ge t$. This implies that for all $a < w_{\max}^{(t)}$ and all $\tau \ge t$, $$x_{f,a}^{(\tau)} = 0.$$ Combining this with expression~\ref{greater-offers-0}, we can conclude that it must be the case that, for all $\tau \ge t'$ $$x_{f,w_{\max}^{(t)}}^{(\tau)} = 1.$$
    Thus, after time $t'$, the firm purely offers $w_{\max}^{(t)}$ for all future time steps and by expression~\ref{best-response-firm}, this offer will always be a best response to the worker's strategy. Further, $w_{\max}^{(t)}$ is the largest acceptance threshold with non-zero probability by definition, it is impossible for the worker switch acceptance thresholds to get more utility than $w_{\max}^{(t)}$. So, any mixture over acceptance thresholds $a\le w_{\max}^{(t)}$ is a best response to $x_{f,w_{\max}^{(t)}}^{(t')} = 1$. Therefore, for any $\epsilon\ge 0$, then for all $\tau \ge t'$,  $(x_w^{(\tau)}, x_f^{(\tau)})$ is in an $\epsilon$-mixed Nash Equilibrium.


    % state 5 converges to epsilon-NE for all epsilon>0 (only way for this case to make sense is if it approaches threshold but is never equal to it)
    In the second case, suppose $f_{\min}^{(\tau)} < w_{\max}^{(t)}$.  
    % $x_{w,w_{\max}^{(t)}}^{(\tau)} \ge \frac{1}{D-k+1}$ for all $\tau \ge t$. Let $t'\ge t$ be the time where expression~\ref{greater-offers-0} guarantees offers greater than $w_{\max}^{(t)}$ get 0 probability mass in all future time steps.
    The following two properties must hold in this case
    \begin{align*}
        x_{w,w_{\max}^{(t)}}^{(\tau)}> \frac{1}{D-k+1}, \forall \tau \ge t, &\tag{4}\label{state-5-prop-1}
    \end{align*}
    and there exists a $t^* \ge t'$ where
    \begin{align*}
        x_{f,w_{\max}^{(t)}}^{(t^*)} \ge x_{f,a}^{(t^*)}, \forall a \neq w_{\max}^{(t)}. &\tag{5}\label{state-5-prop-2}
    \end{align*}
    By Lemma~\ref{lem:x_w_a_r,+_decreases} $x_{w,w_{\max}^{(t)}}^{(\tau+1)} < x_{w,w_{\max}^{(t)}}^{(\tau)}$ when $f_{\min}^{(\tau)} < w_{\max}^{(t)}$, so $x_{w,w_{\max}^{(t)}}^{(\tau+1)} < \frac{1}{D-k+1}$ if $x_{w,w_{\max}^{(t)}}^{(\tau)} = \frac{1}{D-k+1}$, so property~\ref{state-5-prop-1} must hold. Next, if for all $\tau \ge t'$ there exists $f_{\min}^{(\tau)} \le a < w_{\max}^{(t)}$ where $$x_{f,a}^{(\tau)} > x_{f,w_{\max}^{(t)}}^{(\tau)}, $$
    then by the primal constraints this implies 
    $$\sum_{f_{\min}^{(\tau)} \le a < w_{\max}^{(t)}}x_{f,a}^{(\tau)} > \frac{1}{2},$$ 
    so by the worker's utility function $$u_w(x_f^{(\tau)},\frac{1}{D}) \ge u_w(x_f^{(\tau)},w_{\max}^{(t)}) + \frac{1}{2D},$$
    since a lower acceptance threshold, $\frac{1}{D}$ gets at least $\frac{1}{D}$ more utility than the acceptance threshold $w_{\max}^{(t)}$ with probability at least $\frac{1}{2}$. This implies there exists a time $t^* > t'$ where $$U_{w,\frac{1}{D}}^{(t^*)} - U_{w,w_{\max}^{(t)}}^{(t^*)} \ge \frac{1}{\eta},$$
    which implies $x_{w,w_{\max}^{(t)}}^{(t^*)} = 0$. Therefore, property~\ref{state-5-prop-2} must be true as well.

    Now, by property~\ref{state-5-prop-1}, then by the definition of the firm's utility function, for all $\tau \ge t$  $$u_f(w_{\max}^{(t)}, x_w^{(\tau)}) > u_f(w_{\max}^{(t)}-\frac{1}{D}, x_w^{(\tau)}),$$
    so by Lemma~\ref{lem:firm_pmf_structure},$$u_f(w_{\max}^{(t)}, x_w^{(\tau)}) > u_f(a, x_w^{(\tau)}), \forall a <w_{\max}^{(t)},$$
    and combining this with expression~\ref{best-response-firm-greater-offers},
    \begin{align*}
        u_f(w_{\max}^{(t)}, x_w^{(\tau)}) > u_f(a, x_w^{(\tau)}), \forall a \neq w_{\max}^{(t)} &\tag{4}\label{strict-best-response-state-5}
    \end{align*}

    % This implies for any $\epsilon>0$, there exists a $t_\epsilon$ where $$x_{w,w_{\max}^{(t)}}^{(t_{\epsilon})} - \frac{1}{D-k+1}<\epsilon.$$
    %  Then, if $x_{f,w_{\max}^{(\tau)}} = 0$ for all $\tau \ge t'$, then by examining the proof of Lemma~\ref{lem:a_r,+_decreasing_conditions}, it is necessarily the case that $w_{\max}$ decreases and the agents move out of state 5. So, there must be a time $t^* \ge t'$ where $$x_{f,w_{\max}^{(t)}}^{(t^*)} >0.$$
    % Next, given expression~\ref{strict-best-response-state-5}, we will show it is impossible for $x_{f,w_{\max}^{(t)}}^{(t^*+1)}<x_{f,w_{\max}^{(t)}}^{(t^*)}.$ Suppose $x_{f,w_{\max}^{(t)}}^{(t'+1)}<x_{f,w_{\max}^{(t)}}^{(t')},$ then by the primal constraints there must be $a \neq w_{\max}^{(t)}$ where $x_{f,a}^{(t'+1)}>x_{f,a}^{(t')}.$ If $x_{f,a}^{(t')} >0$, then since $x_{f,w_{\max}^{(t)}}^{(t')} >0$ as well, by Claim~\ref{claim:stationarity_reqs}, $$x_{f,a}^{(t')} - x_{f,w_{\max}^{(t)}}^{(t')} = \eta  U_{f,a}^{(t'-1)} - \eta  U_{f,w_{\max}^{(t)}}^{(t'-1)},$$
    % and if $x_{f,a}^{(t'+1)} >0$ as well, 
    % $$x_{f,a}^{(t'+1)} - x_{f,w_{\max}^{(t)}}^{(t'+1)} = \eta  U_{f,a}^{(t')} - \eta  U_{f,w_{\max}^{(t)}}^{(t')}.$$
    % However, since we assume $x_{f,w_{\max}^{(t)}}^{(t'+1)}<x_{f,w_{\max}^{(t)}}^{(t')}$ and $x_{f,a}^{(t'+1)}>x_{f,a}^{(t')},$ then this implies $$u_f(a,x_w^{(t')}) >u_f(w_{\max}^{(t)},x_w^{(t')}),$$
    % which contradicts expression~\ref{strict-best-response-state-5}. 
    % need 3 other cases of 0,>0 >0,0 and 0,0 (make this a lemma?) -- feels like there's an easier argument.
    Next, by property~\ref{state-5-prop-2}, Claim~\ref{claim:kkt_ordering},
    and expression~\ref{strict-best-response-state-5}, then for all $\tau \ge t^*$
    $$U_{f,w_{\max}^{(t)}}^{(\tau+1)} - U_{f,a}^{(\tau+1)} >U_{f,w_{\max}^{(t)}}^{(\tau)} - U_{f,a}^{(\tau)} \ge 0, \forall a \neq w_{\max}^{(t)}.$$
    Then, by Claim~\ref{claim:stationarity_reqs}, this implies for all $\tau \ge t^*$ and for all $a \neq w_{\max}^{(t)}$ where $x_{f,a}^{(\tau)}>0$ and $x_{f,a}^{(\tau+1)} >0$,
    $$x_{f,w_{\max}^{(t)}}^{(\tau+1)} - x_{f,a}^{(\tau+1)} > x_{f,w_{\max}^{(t)}}^{(\tau)} - x_{f,a}^{(\tau)}.$$
    Further, it cannot be the case that $x_{f,w_{\max}^{(t)}}^{(\tau+1)} = x_{f,w_{\max}^{(t)}}^{(\tau)}$ while $x_{f,a}^{(\tau+1)} < x_{f,a}^{(\tau)}$ for all such $a\neq w_{\max}^{(t)}$ because this implies $$\sum_{a \in \mathcal{A}}x_{f,a}^{(\tau+1)} < \sum_{a \in \mathcal{A}}x_{f,a}^{(\tau)}=1,$$
    which would violate the primal constraint at time $t+1$.


    So, we can conclude 
    $x_{f,w_{\max}^{(t)}}^{(\tau+1)} >x_{f,w_{\max}^{(t)}}^{(\tau)}$ for all $\tau \ge t^*$. Since for all $a >w_{\max}^{(t)}$, $x_{f,a}^{(\tau)} = 0$ for all $\tau \ge t'$ and $t^* \ge t'$, then this immediately implies
    $$\sum_{f_{\min}^{(\tau+1)}\le a<w_{\max}^{(t)}}x_{f,a}^{(\tau+1)} < \sum_{f_{\min}^{(\tau)}\le a<w_{\max}^{(t)}}x_{f,a}^{(\tau)}, \forall \tau \ge t^*$$
    So, by the primal constraints, we can conclude $$\underset{\tau\to\infty}{\lim}\sum_{f_{\min}^{(\tau)}\le a<w_{\max}^{(t)}}x_{f,a}^{(\tau)} = 0,$$
    and 
    $$\underset{\tau\to\infty}{\lim} x_{f,w_{\max}^{(t)}}^{(\tau)}= 1.$$
    Therefore, for any $\epsilon>0$ there exists a time $t_\epsilon$ where, for all $\tau \ge t_{\epsilon}$, $$x_{f,w_{\max}^{(t)}}^{(\tau)} > 1- \epsilon.$$
    By expression~\ref{strict-best-response-state-5}, the offer $w_{\max}^{(t)}$ is a best-response for the firm for all $\tau \ge t$, so $x_{f,w_{\max}^{(t)}}^{(\tau)} > 1- \epsilon$ implies $$u_f(x_f^{(\tau)}, x_w^{(\tau)}) \ge u_f(x_f', x_w^{(\tau)}) - \epsilon, \forall x_f' \in \Delta(\mathcal{A}).$$
    Further, $x_{f,w_{\max}^{(t)}}^{(\tau)} > 1- \epsilon$ implies the worker gets at most $\epsilon$ more utility by lowering their acceptance threshold from $w_{\max}^{(t)}$, so we also have
    $$u_w(x_f^{(\tau)}, x_w^{(\tau)}) \ge u_w(x_f^{(\tau)}, x_w') - \epsilon, \forall x_w' \in \Delta(\mathcal{A}).$$
    Therefore, the strategy profile $(x_f^{(t_\epsilon)}, x_w^{(t_\epsilon)})$ is an $\epsilon$-mixed NE.
\end{proof}

\newpage

Finally, we prove the main theorem of this section.

\begin{customthrm}{1}
    \label{thrm:ftrl_convergence_n=1}
    Suppose agents learn strategies for $\mathcal{G}^{(1)}$ using Algorithm~\ref{alg:ftrl} with $\alpha_i=\mathbf{0}$, any $\eta >0, D>2$, and arbitrary initial conditions $x_w^{(1)}, x_f^{(1)} \in \Delta(\mathcal{A})$. Then, for any $\epsilon>0$, there exists a finite time $t_\epsilon$ where $(x_f^{(\tau)},x_w^{(\tau)})$ is in $\epsilon$-Nash Equilibrium for all $\tau \ge t_\epsilon$. 
\end{customthrm}
\begin{proof}

    % new structure, like a state machine, one lemma -> another lemma, a_r,+ decreases a finite amount of time and each decrease takes a finite amount of time OR we are in epsilon-NE

    %% scaffolding
    To prove the theorem, we will show that, regardless of the initial conditions, the agents must always reach or approach a mixed Nash Equilibrium (NE) asymptotically, such that we can conclude the agents end in an $\epsilon$-NE at the last iterate.

    % map possible changes at time $t+1$
    We begin by describing all the possible conditions the agents' strategy profile, $(x_f^{(t)}, x_w^{(t)})$, could satisfy at any time $t$. Then, we use induction to show there is always a finite time where the agents are in one of two conditions for all future time steps. We conclude by showing that this implies the agents have converged to an $\epsilon$-NE for any $\epsilon>0$. See Figure~\ref{fig:thrm_1_state_machine} for a visual of how the algorithm moves through the possible conditions.

    % conditions
    To begin, at any time step $t$, $$w_{\max}^{(t)} = \frac{k}{D}, $$ for some $k \in \{1,\ldots,D\}$. Then, exactly one of the following conditions is satisfied by the agents' strategy profile at time $t$.
    \begin{enumerate}
        \item $w_{\max}^{(t)} < f_{\min}^{(t)}$
        \item $w_{\max}^{(t)} = f_{\min}^{(t)}$ and $x_{w,w_{\max}^{(t)}}^{(t)} < \frac{1}{D-k+1}$
        \item $f_{\min}^{(t)}<w_{\max}^{(t)} $ and $x_{w,w_{\max}^{(t)}}^{(t)} < \frac{1}{D-k+1}$
        \item $w_{\max}^{(t)} = f_{\min}^{(t)}$ and $x_{w,w_{\max}^{(t)}}^{(t)} \ge \frac{1}{D-k+1}$
        \item $f_{\min}^{(t)}< w_{\max}^{(t)} $ and $x_{w,w_{\max}^{(t)}}^{(t)} \ge \frac{1}{D-k+1}$
    \end{enumerate}

    % induction proof to reduce conditions
    Now, we consider each condition separately, and show the possible conditions that can be satisfied in time step $t+1$, given the condition satisfied at time step $t$. We say the agents move to condition $i$ if $(x_f^{(t+1)}, x_w^{(t+1)})$ satisfies condition $i$ for $i\in\{1,2,3,4,5\}$.\\

    First, suppose $(x_f^{(t)}, x_w^{(t)})$ is in \textbf{condition 1}. Then, in the next time step, either $f_{\min}^{(t+1)} > w_{\max}^{(t+1)}$ and the agents remain in condition 1 or $f_{\min}^{(t+1)} \le w_{\max}^{(t+1)}$ and the agents move to condition 2, 3, 4, or 5. \\

    Next, suppose $(x_f^{(t)}, x_w^{(t)})$ is in \textbf{condition 2}. First, by Lemma~\ref{lem:stationary_x_w}, $$x_w^{(t+1)} = x_w^{(t)},$$ so it cannot be the case that the agents move to condition 4 or 5. If, $f_{\min}^{(t+1)} >  w_{\max}^{(t+1)}$, then the agents move to condition 1. Next, if $f_{\min}^{(t+1)} = f_{\min}^{(t)}$, then the agents remain in condition 2. Finally, if $f_{\min}^{(t+1)} < f_{\min}^{(t)}$, then this implies $f_{\min}^{(t+1)} < w_{\max}^{(t+1)}$ since $f_{\min}^{(t)} = w_{\max}^{(t)}=w_{\max}^{(t+1)}$ and the agents move to condition 3.\\

    Next, suppose $(x_f^{(t)}, x_w^{(t)})$ is in \textbf{condition 3}. First, by Lemma~\ref{lem:x_w_a_r,+_decreases}, $$x_{w,w_{\max}^{(t)}}^{(t+1)} < x_{w,w_{\max}^{(t)}}^{(t)}.$$
    If $x_{w,w_{\max}^{(t)}}^{(t+1)} =0$, then by definition $w_{\max}^{(t+1)}\neq w_{\max}^{(t)}$, so by Lemma~\ref{lem:a_r,+_never_increases},
    $w_{\max}^{(t+1)} < w_{\max}^{(t)}$. Now, the agents can move to condition 1, 2, 3, 4, or 5, with the new $w_{\max}$ value.
    Otherwise, if $x_{w,w_{\max}^{(t)}}^{(t+1)}>0$, then by Lemma~\ref{lem:a_r,+_never_increases}, $w_{\max}^{(t+1)} = w_{\max}^{(t)}$. Since $x_{w,w_{\max}^{(t)}}^{(t+1)} < x_{w,w_{\max}^{(t)}}^{(t)}$, then the agents cannot move to condition 4 or 5. Further, since $w_{\max}^{(t+1)} = w_{\max}^{(t)}$, then by Lemma~\ref{lem:a_p,-<a_r,+}, $f_{\min}^{(t+1)} < w_{\max}^{(t+1)}$, and the agents cannot move back to condition 1 or 2. So, the agents remain in condition 3 in this case.\\


    Next, suppose $(x_f^{(t)}, x_w^{(t)})$ is in \textbf{condition 4}. First, by Lemma~\ref{lem:stationary_x_w} $$x_w^{(t+1)} = x_w^{(t)},$$  so the agents cannot move to condition 2 or 3. Next, if $f_{\min}^{(t+1)} > w_{\max}^{(t+1)}$, then the agents move to condition 1. If $f_{\min}^{(t+1)} = f_{\min}^{(t)}$, then the agents remain in condition 4. Otherwise, if $f_{\min}^{(t+1)} < f_{\min}^{(t)}$, then since $f_{\min}^{(t)} = w_{\max}^{(t)}=w_{\max}^{(t+1)}$, this implies $f_{\min}^{(t+1)} < w_{\max}^{(t+1)}$ and the agents move to condition 5.\\

    Next, suppose $(x_f^{(t)}, x_w^{(t)})$ is in \textbf{condition 5}. First,  by Lemma~\ref{lem:x_w_a_r,+_decreases}, $$x_{w,w_{\max}^{(t)}}^{(t+1)} < x_{w,w_{\max}^{(t)}}^{(t)}.$$ If $f_{\min}^{(t+1)} > w_{\max}^{(t+1)}$, then the agents move to condition 1.
    Next, if $x_{w,w_{\max}^{(t)}}^{(t+1)} \ge \frac{1}{D-k+1}$ and $f_{\min}^{(t+1)} < w_{\max}^{(t+1)}$, then the agents remain in condition 5. Next, if $x_{w,w_{\max}^{(t)}}^{(t+1)} \ge \frac{1}{D-k+1}$ but $f_{\min}^{(t+1)} = w_{\max}^{(t+1)}$, then the agents move to condition 4. Next, if $0< x_{w,w_{\max}^{(t)}}^{(t+1)} < \frac{1}{D-k+1}$, then the agents move to condition 2 or 3. Finally, if $x_{w,w_{\max}^{(t)}}^{(t+1)} =0 $ then by Lemma~\ref{lem:a_r,+_never_increases}, $$w_{\max}^{(t+1)} < w_{\max}^{(t)},$$ and the agents move to condition 1, 2, 3, 4, or 5.\\

    % finite time until only condition 4 or only condition 5
    Next, we show there exists a finite time where the agents remain in condition 4 or condition 5 for all future time steps. First, Lemma~\ref{lem:a_r,+_never_increases} shows that the value of $w_{\max}$ is non-increasing in all time steps, and further the number of $w_{\max}$ values is $|\mathcal{A}|$. So, it suffices to show for each unique $w_{\max}$ value that either the agents must remain in condition 4 or condition 5 for all future time steps or the value of $w_{\max}$ must decrease in finite time.\\ 

    Suppose $(x_f^{(t)}, x_w^{(t)})$ is in condition 1 at time $t$. From the cases above, the agents either remain in condition 1 or move to one of the other conditions, and Lemma~\ref{lem:a_p,-_<=_a_r,+} shows that it takes finite time for the agents to move to condition 2, 3, 4, or 5. Further,  Lemma~\ref{lem:a_p,-_<=_a_r,+_for_all_t} shows that once agents leave condition 1 for the first time per unique value of $w_{\max}$, it takes finite time to ensure the agents never enter condition 1 again for that $w_{\max}$ value. So, we may assume that the agents never enter condition 1 for the remainder of the cases. Next, if the agents are in condition 4 or 5, but don't stay there for all future time steps and  $w_{\max}$ does not decrease, then there must be a finite time where the agents move to condition 2 or 3. Next, if the agents are in condition 2, then from the cases above, they either remain there or move to condition 3, and Lemma~\ref{lem:a_p,-<a_r,+} shows that it takes finite time for the agents to move to condition 3. Then, from the cases above, agents must stay in condition 3 until $w_{\max}$ decreases in value, and Lemma~\ref{lem:a_r,+_decreasing_conditions} shows it takes finite time for $w_{\max}$ to decrease. Therefore, for each unique $w_{\max}$ value, either it takes a finite amount of time for its value to decrease, or the agents never leave condition 4 or 5.\\

    Finally, in the base case, suppose at time $t$, $w_{\max}^{(t)} =\frac{1}{D}$. Note that since $$U_{w,0}^{(t)} = U_{w,\frac{1}{D}}^{(t)}, \forall t$$ then by Claim~\ref{claim:kkt_ordering}, this is the smallest value in $\mathcal{A}$ that $w_{\max}^{(t)}$ can be. By definition of $w_{\max}$, this implies $x_{w,\frac{1}{D}}^{(t)} \ge \frac{1}{2}$ which satisfies the probability mass lower bound of condition 4 and 5 for $D>2$. Then, Lemmas~\ref{lem:a_p,-_<=_a_r,+} and ~\ref{lem:a_p,-_<=_a_r,+_for_all_t}, along with the fact that the lower bound of $f_{\min}^{(t)}$ is $\frac{0}{D}$, shows that it takes finite time for $f_{\min}^{(t)} \le  w_{\max}^{(t)}$ for all future time steps. Therefore, the conditions for the agents being in condition 4 or condition 5 are satisfied at the lowest value of $w_{\max}$. So, we can conclude there is always a finite time where the agents are in condition 4 or condition 5 for all future time steps.\\

    % todo -- special considerations for 0/1?
    % condition 4 or 5 => convergence to epsilon^*-NE if we remain in one for all future time steps
     Once agents are either in condition 4 or condition 5 for all future time steps, then the conclusion follows from Lemma~\ref{lem:final_NE_convergence}.
\end{proof}

