 % theorem set up 
\paragraph{Calculating a convergence rate} Theorem~\ref{thrm:ftrl_convergence_n=1} shows that approximate convergence to $\epsilon$-NE is guaranteed under broad conditions. In our second main result, Theorem~\ref{thrm:ftrl_convergence_rate}, we give conditions under which we can derive an upper bound on the number of iterations until convergence to $\epsilon$-NE when $\eta \le 1$. We do not believe our bound is tight, but our proof highlights the phases of the algorithm that make the convergence rate large in the worst case. In particular, as the conditions of Theorem~\ref{thrm:ftrl_convergence_n=1} show, the agents' strategies evolve differently depending on whether $x_{w,w_{\max}^{(t)}}^{(t)}$ is above or below the threshold $\frac{1}{D-k+1}$, and the \textit{rate} at which they change depends on how far $x_{w,w_{\max}^{(t)}}^{(t)}$ is from this threshold. However, since we assume all initial strategy masses and algorithm parameters are reduced rational numbers, then all strategy masses will be rational numbers which ensures, at any time $t$, $x_{w,w_{\max}^{(t)}}^{(t)}$ cannot be arbitrarily close to the threshold $\frac{1}{D-k+1}$. 

So, to calculate the convergence rate, we bound the largest bit size of the reduced form denominator of the strategy masses using standard bit arithmetic and then we use a bit counting argument to lower bound the distance of a strategy mass from a threshold to find the maximum number of iterations until the agents' strategies satisfy another condition. That is, if we first find the largest value of the denominator of one rational term in reduced form is  $D_1$ and the largest value of the denominator of a second rational term in reduced form, say $D_2$, finally, we can conclude the absolute difference between these two rational terms is at least \[2^{-(\log(D_1) +\log(D_2))}.\]
This logic is formalized in Lemma~\ref{lem:bits-to-bound}.


\paragraph{Assumptions}
% assumption recall and set up to be used throughout
Throughout these results, we assume that all initial strategy masses and algorithm parameters are rational numbers and we will represent the numbers in their reduced form, i.e., $\frac{m}{n}$ for $m,n \in\mathbb{Z}, n\neq 0$ where $m$ and $n$ are coprime. We also assume that for each $i \in \{f,w\}$ and all $a\in \mathcal{A}$ the numerator and denominator of both $x_{i,a}^{(1)}$ and the learning rate $\eta$ (in their reduced forms) are each represented in at most $c$ bits for some integer $c>0$. For any $t$, if $x_{i,a}^{(t)} =0$, then we use the convention that its numerator and denominator are represented in 1 bit, i.e., it is represented as $0 = \frac{0}{1}$. Finally, note that for all $k \in \{0,\ldots,D+1\}$, $k$ is at most $\log(D+1)$ bits. 

% Thus, there exists a constant integer $d>0$ such that the bits to represent the numerator and denominator of $\eta$ as well as all $k \in  \{0,\ldots,D+1\}$ can be upper bounded by $d \log(\frac{D}{\eta})$, and we will use $d$ as such throughout this section.




First, we state our second main result, prove several lemmas, and finally prove the main theorem.
\begin{customthrm}{2}
\label{thrm:ftrl_convergence_rate}
    Suppose agents learn strategies for $\mathcal{G}^{(1)}$ using Algorithm~\ref{alg:ftrl} with $\alpha_i=\mathbf{0}$, any $0<\eta \le 1, D>2$, and arbitrary initial conditions $x_w^{(1)}, x_f^{(1)} \in \Delta(\mathcal{A})$. Then, for any $\epsilon>0$, the time to convergence of Algorithm~\ref{alg:ftrl} to an $\epsilon$-Nash equilibrium is  
    \[O\left(\left[\left(2^{\frac{D}{\eta}^{{\frac{D^{31}}{\eta^5}}}}\right)\uparrow \uparrow D\right] +\log\left(\frac{D^3}{\epsilon}\right)\cdot \frac{D^2}{\eta}\right).\]
    % \[\left(\left(2^{D^{{M\cdot \frac{D^{27}}{\eta^5}}}}\right)\uparrow \uparrow D \right)+2\log\left(\frac{3D^3}{\epsilon}\right)\cdot \log\left(\frac{4D^2}{4D^2-\eta}\right)^{-1}.\]
    % \[\left(2^{D^{D^{12M\frac{D^{18}}{\eta}}}}\right)\uparrow \uparrow D +\log\left(\frac{3D^2}{2\epsilon}\right)\cdot \log\left(\frac{2}{2-\eta}\right)^{-1}\]
    % where \[M= 3483 c\cdot m\cdot d,\]
    % for a constant $M>0$.
\end{customthrm}



\begin{customlem}{12}
    \label{lem:max_bits_of_x_i,a^t}
    Let $D>2$ be an integer and $0<\eta\le 1$ be a rational number. 
    % and suppose $x_{i,a}^{(1)}$ is a  rational number where the numerator and denominator are each at most $c>0$ bits. 
    Then, for all $t> 1$, $x_{i,a}^{(t)}$ is a rational number and the maximum number of bits to represent the numerator and the denominator of $x_{i,a}^{(t)}$ are each upper bounded by $20c^2\log\left(D+1\right)(25D^8)^t$ bits.
\end{customlem}
\begin{proof}

    To begin, note that at time $t$, if $x_{i,a}^{(t)}>0$, then the primal constraints along with Claim~\ref{claim:stationarity_reqs} imply \[x_{i,a}^{(t)} = \frac{1}{n}\cdot \left(1+\eta \sum_{a'\in \mathcal{A}, x_{i,a'}^{(t)} >0, a' \neq a}\left(U_{i,a}^{(t-1)} - U_{i,a'}^{(t-1)}\right)\right).\tag{1}\label{x-i-t}\]
    where  
    \[n = |\{a : a\in \mathcal{A}, x_{i,a}^{(t)} >0\}|,\]
    and 
    \begin{align*}
        U_{f,a}^{(t)} - U_{f,a'}^{(t)} &= \sum_{\tau=1}^t\left[\sum_{a'' \le a}x_{w,a''}^{(\tau)}\cdot (1-a) - \sum_{a'' \le a'}x_{w,a''}^{(\tau)}\cdot (1-a')\right],\\
        U_{w,a}^{(t)} - U_{w,a'}^{(t)} &= \sum_{\tau=1}^t\left[\sum_{a'' \ge a}x_{f,a''}^{(\tau)}\cdot a'' - \sum_{a'' \ge a'}x_{f,a''}^{(\tau)}\cdot a''\right].
    \end{align*}
    Thus, $x_{i,a}^{(t)}$ is the result of a finite number of addition and multiplication operations of rational numbers, so $x_{i,a}^{(t)}$ will be rational as well.

    Next, finding the maximum number of bits the denominator and numerator of $x_{i,a}^{(t)}$ could have is equivalent to counting bits that result from the maximum number of multiplication and addition operations that occur between rational numbers in Equation~\ref{x-i-t}. Note that if there exists $i\in\{f,w\}, a \in \mathcal{A}, 1\le \tau \le t$ such that $x_{i,a}^{(\tau)} = 0$, then this necessarily reduces the number of operations in the term \[\sum_{a'\in \mathcal{A}, x_{i,a'}^{(t)} >0, a' \neq a}\left(U_{i,a}^{(t-1)} - U_{i,a'}^{(t-1)}\right).\] Thus, for a bit upper bound, it suffices to assume all variables have non-zero mass for all time steps $t$. Under this assumption, Equation~\ref{x-i-t} can be written as the recurrence relation
    \[x_{i,a}^{(t)} = x_{i,a}^{(t-1)}+\frac{1}{D+1}\cdot \left(1+\eta \sum_{a'\in \mathcal{A}, a' \neq a}\left(u_{i}(a,x_{-i}^{(t-1)}) - u_{i}(a',x_{-i}^{(t-1)})\right)\right),\tag{2}\label{x-i-t-reccurrence}\]
    where 
    \begin{align*}
        u_{f}(a,x_{w}^{(t-1)}) - u_{f}(a',x_{w}^{(t-1)}) &=\sum_{a'' \le a}x_{w,a''}^{(t-1)}\cdot (1-a) - \sum_{a'' \le a'}x_{w,a''}^{(t-1)}\cdot(1-a'),  \tag{3}\label{firm-bits}\\
        u_{w}(x_{f}^{(t-1)},a) - u_{w}(x_{f}^{(t-1)},a') &=\sum_{a'' \ge a}x_{f,a''}^{(t-1)}\cdot a'' - \sum_{a'' \ge a'}x_{f,a''}^{(t-1)}\cdot a''.\tag{4}\label{worker-bits}
    \end{align*}
    % setting up rational number bit calculations of multiplication and addition operations
    % Note that for  $r,s \in \mathbb{Q}$ where $r=\frac{r_1}{r_2},s=\frac{s_1}{s_2}$ for $r_1,r_2,s_1,s_2 \in \mathbb{Z}$ and $r_2,s_2 \neq 0$, \[r\cdot s = \frac{r_1 \cdot s_1}{r_2 \cdot s_2}, r + s = \frac{r_1\cdot s_2 + s_1 \cdot r_2}{r_2\cdot s_2}.\tag{5}\label{rational-math}\] Therefore, if $p_1,p_2$ are the number of bits to represent $r_1,r_2$, respectively, and $q_1,q_2$ are the number of bits to represent $s_1,s_2$, respectively, then the denominator of $r\cdot s$ and $r+s$ needs at most $p_2+q_2$ bits to be represented and the numerator of $r\cdot s$ needs at most $p_1 + q_1$ bits to be represented while the numerator of $r+s$ needs at most $\max\{p_1 + q_2, s_1+p_2\} +1$ bits to be represented.
    Then, we can bound the number of bits in $x_{i,a}^{(t)}$ as a function of the number of bits in $x_{i,a}^{(t-1)}$. This will create a recurrence relation on the maximum number of bits in the numerator and denominator of $x_{i,a}^{(t)}$ which we can solve to get our final bound.

    % calculating max bits
    % 1. assumption on bits at t-1
    Suppose for each $i \in \{f,w\}$ and all $a \in \mathcal{A}$, the numerator and denominator of the rational number $x_{i,a}^{(t-1)}$ can each be represented in at most $c_{t-1}$ bits. Recall our assumption that $\eta$ is rational  such that the bits to represent the numerator and denominator of $\eta$ in its reduced form is $c$ and that $D+1$ can be represented in $\log(D+1)$ bits. 
    % 2. max bits in 2 and 3
    % First, expressions~\ref{firm-bits} and~\ref{worker-bits} are each the sum and multiplication of rational numbers where we know the maximum numbers of bits in the numerator and denominator of each, so we can derive the expression for $u_{i}(a,x_{-i}^{(t-1)}) - u_{i}(a',x_{-i}^{(t-1)})$ as a rational number and determine the maximum number of bits in its numerator and denominator using~\ref{rational-math}. 
    % is equivalent to the expression \[\frac{x_1^0\cdot d_1^0\cdot( x_2^1\cdot d_2^1\cdots x_2^D\cdot d_2^D) + \cdots +x_1^D\cdot d_1^D\cdot( x_2^0\cdot d_2^0\cdots x_2^{D-1}\cdot d_2^{D-1})}{x_2^0\cdot d_2^0 \cdot x_2^1\cdot d_2^1\cdots x_2^D\cdot d_2^D} -\frac{y_1^0\cdot b_1^0\cdot( y_2^1\cdot b_2^1\cdots y_2^D\cdot b_2^D) + \cdots +y_1^D\cdot b_1^D\cdot( y_2^0\cdot b_2^0\cdots y_2^{D-1}\cdot b_2^{D-1})}{y_2^0\cdot b_2^0 \cdot y_2^1\cdot b_2^1\cdots y_2^D\cdot b_2^D}.\]
    % Then, the largest number of bits in the numerator of $u_{i}(a,x_{-i}^{(t-1)}) - u_{i}(a',x_{-i}^{(t-1)})$  is $2(c_{t-1} + log(D+1))(D+1) + D+1$ bits and in the denominator is $2(c_{t-1} + log(D+1))(D+1)$ bits. 
    % 3. max bits in term added to x_i,a^t+1
    % Next, since $\sum_{a'\in \mathcal{A}, a' \neq a}\left(u_{i}(a,x_{-i}^{(t-1)}) - u_{i}(a',x_{-i}^{(t-1)})\right)$ is the sum of $D$ of these numbers, then the sum is a rational number with at most $2D(D+1)(c_{t-1} + log(D+1))) +2D+1$ bits in the numerator and $2(c_{t-1} + log(D+1)) D(D+1)$ bits in the denominator. 
    % Then, since $\eta $ and $\frac{1}{D+1}$  each  have at most $c$ and $log(D+1)$ bits, respectively, in the numerator and the denominator and the fact that adding 1 adds no bits to the denominator and 1 bit to the numerator implies that $\frac{1}{D+1}\cdot \left(1+\eta \sum_{a'\in \mathcal{A}, a' \neq a}\left(u_{i}(a,x_{-i}^{(t-1)}) - u_{i}(a',x_{-i}^{(t-1)})\right)\right)$ has a numerator with at most $2D(D+1)(c_{t-1} + log(D+1)) +2D+1 + log(D+1)+c + 1$ bits and a denominator with at most  $2D(D+1)(c_{t-1} + log(D+1))+ log(D+1)+c$ bits. 
    % 4. putting it all together, max bits in x_i,a^t
    Then, using Equation~\ref{x-i-t-reccurrence} (and, consequently, Equations~\ref{firm-bits} and~\ref{worker-bits}) and standard rational bit arithmetic, we can conclude $x_{i,a}^{(t)}$ has an numerator with at most \[2D(D+1)\left(c_{t-1} + \log\left(D+1\right)\right)+ \log\left(D+1\right) +c+ c_{t-1}+ 2D + 3\] bits and a denominator with at most \[2D(D+1)\left(c_{t-1} + \log\left(D+1\right)\right)+ \log\left(D+1\right) +c+ c_{t-1}\] bits. 

    Clearly, $D>2$ implies the maximum number of bits of the numerator is larger than the denominator, so to find the maximum number of bits that can represent both the numerator and denominator in $x_{i,a}^{(t)}$, call this value $c_t$, it suffices to solve the linear recurrence 
    \[c_t = (2D(D+1)+1)c_{t-1} + \log\left(D+1\right)(2D(D+1)+1) + 2D+3+c.\]
    Through simple iteration, the closed form solution of this recurrence is
    \begin{align*}c_t = (2D(D+1)+1)^{t-1} c_1 &+ \left(\log\left(D+1\right)(2D(D+1)+1) + 2D+3+c\right)\cdot (\sum_{\tau=1}^{t-2}(2D(D+1)+1)^\tau)\\ &+ \log\left(D+1\right)(2D(D+1)+1) + 2D+3+c.
    \end{align*}
    Using the fact that, for any integers $t>0, x>0$, $\sum_{i=1}^tx^i \le x^{2t}$ and $ D>2$ implies $\log(D+1)>1$, then \[c_t \le 20c_1c \log\left(D+1\right)(25D^8)^t.\]
    % For the denominator, this yields the linear recurrence
    % \[c_t = (2D(D-1)+1)c_{t-1} + 2d(D^2-D+1),\]
    % which has the closed form 
    % \[c_t = (2D(D-1)+1)^{t-1} c_1 + 2d(D^2-D+1)\cdot (\sum_{\tau=1}^{t-2}(2D(D-1)+1)^\tau) + 2d(D^2-D+1).\]
    % % generous upper bound for both
    % This value can be upper bounded by 
    % % \[c_t = (3D^2)^{2(t-1)} c_1 + 2dD^2\cdot(3D^2)^{2(t-1)} + 2dD^2(3D^2)^{2(t-1)}.\]
    % \[c_t = 5c_1d(9D^8)^{t}.\]
    % substitute initial assumption into final bound
    Thus, since $x_{i,a}^{(1)}$ is assumed to have a numerator and a denominator each with at most $c$ bits, then we can conclude $c_1 = c$ and $x_{i,a}^{(t)}$ has a numerator and a denominator each represented by at most $ 20c^2 \log\left(D+1\right)(25D^8)^t$ bits.

\end{proof}

\begin{customlem}{13}
\label{lem:recurrence_relation_dynamics}
Suppose the agents run Algorithm~\ref{alg:ftrl} with $D>2$ and $\eta >0$.  Further, suppose at time $t$, $w_{\max}^{(t)} = \frac{k}{D}$ for some $k\in\{2,\ldots,D\}$, $x_{w,w_{\max}^{(t)}}^{(t)} \ge \frac{1}{D-k+1}$, $f_{\min}^{(t)} < f_{\max}^{(t)}$, and for all $a \in\mathcal{A} \setminus\{\frac{k}{D}, \frac{k-1}{D}\}$,\[U_{f,w_{\max}^{(t)}}^{(t-1)} -U_{f,a}^{(t-1)} \ge \frac{1}{\eta}.\] 
%$x_{w,w_{\max}^{(t)}}^{(t)} >\frac{1}{D-k+1}$, $f_{\min}^{(t)} = \frac{k-1}{D}$,
% Then, for all $\tau \ge t$ where $w_{\max}^{(\tau)}  = \frac{k}{D}$, $x_{w,w_{\max}^{(\tau)}}^{(\tau)} >\frac{1}{D-k+1}$, and $f_{\min}^{(\tau)} = \frac{k-1}{D}$, 
Then, each agent's mass on $w_{\max}^{(t)}$ evolves according to the following recurrence relations:
\[x_{f,w_{\max}^{(t)}}^{(t+1)} = \begin{cases}
    1 & f_{\min}^{(t+1)} = f_{\max}^{(t+1)},\\
    x_{f,w_{\max}^{(t)}}^{(t)} +\frac{\eta(D-k+1)}{2D}\left(x_{w,w_{\max}^{(t)}}^{(t)} - \frac{1}{D-k+1}\right) & f_{\min}^{(t+1)} < f_{\max}^{(t+1)},
\end{cases}\]
and 
\[x_{w,w_{\max}^{(t)}}^{(t+1)} = \begin{cases}
0 & w_{\max}^{(t+1)} < w_{\max}^{(t)},\\
    x_{w,w_{\max}^{(t)}}^{(t)} -\frac{\eta(k-1) k}{(k+1)D}\cdot \left(1-x_{f,w_{\max}^{(t)}}^{(t)}\right) & w_{\max}^{(t+1)} = w_{\max}^{(t)}.
\end{cases}\]
Further, for all $a \in\mathcal{A} \setminus\{\frac{k}{D}, \frac{k-1}{D}\}$,\[U_{f,w_{\max}^{(t)}}^{(t)} -U_{f,a}^{(t)} \ge \frac{1}{\eta}.\]
% Then, there exists a finite time $t_1\ge t$ where either $x_{w,w_{\max}^{(t)}}^{(t_1)} < \frac{1}{D-k+1}$, $x_{f,w_{\max}^{(t)}}^{(t_1)} =  1$, or $x_{f,w_{\max}^{(t)}}^{(\tau)} \ge 1-\epsilon$ for any $\epsilon>0$ and all $\tau \ge t_1$. 
% Further, there exists constants $c>0,d>0, m>0$ and values $\tau_{dec}, \tau_{conv},$ and $\tau_{\epsilon}$ such that, in the first case,  $x_{w,w_{\max}^{(t)}}^{(t+\tau_{dec})} < \frac{1}{D-k+1}$ is guaranteed when \[\tau_{dec} = \frac{\log(\frac{4D^3}{\eta}) + 20 c d(9D^8)^{t} +4d +3md + 5}{\log(1+\frac{\eta}{2D(D+1)})}+2,\]
% in the second case,  $x_{f,w_{\max}^{(t)}}^{(t+\tau_{conv})} =  1$ is guaranteed when \[\tau_{conv} = \frac{\log (\frac{3D^2}{\eta})+20c d(9D^8)^t + 4d + 3md + 5}{\log(1+\frac{\eta}{2D(D+1)})} +2,\]
% and in the third case, for any $\epsilon>0$, $x_{f,w_{\max}^{(t)}}^{(\tau)} \ge 1-\epsilon$ for all $\tau \ge t+\tau_{\epsilon}$ is guaranteed when
% \[\tau_{\epsilon} = \log\left(\frac{3D^2}{2\epsilon}\right)\cdot \log\left(\frac{2}{2-\eta}\right)^{-1} +2.\]

\end{customlem}
\begin{proof}
    First, we derive the expression for $x_{f,w_{\max}^{(t)}}^{(t+1)}$. 

    % for $\tau\ge t$.  Note we can assume that for $\tau$ such that $t \le \tau < t+\tau_{dec}$, $x_{w,w_{\max}}^{(\tau)} \ge \frac{1}{D-k+1}$.  Otherwise, there is certainly a time $\tau<t+\tau_{dec}$ where $x_{w,w_{\max}}^{(\tau)} < \frac{1}{D-k+1}$, as desired.  Let $t \le \tau < t+\tau_{dec}$. 
    To begin, the assumption $x_{w,w_{\max}^{(t)}}^{(t)} \ge \frac{1}{D-k+1}$ along with Lemma~\ref{lem:firm_pmf_structure} implies that for all $a \neq \frac{k}{D}$, \[u_f(w_{\max}^{(t)},x_w^{(t)})\ge u_f(a,x_w^{(t)}).\tag{1}\label{w-max-dominates}\]

    Since by assumption, for $ a\in\mathcal{A} \setminus\{\frac{k}{D}, \frac{k-1}{D}\}$,\[U_{f,w_{\max}^{(t)}}^{(t-1)} -U_{f,a}^{(t-1)} \ge \frac{1}{\eta},\]
    then Equation~\ref{w-max-dominates} implies that for all $a  \in\mathcal{A} \setminus\{\frac{k}{D}, \frac{k-1}{D}\}$,
    \[U_{f,w_{\max}^{(t)}}^{(t)} -U_{f,a}^{(t)} \ge \frac{1}{\eta}.\]

    Thus, by Claims~\ref{claim:stationarity_reqs} and~\ref{claim:kkt_ordering}, for $a  \in\mathcal{A} \setminus\{\frac{k}{D}, \frac{k-1}{D}\}$, $x_{f,a}^{(t)} = 0$ and $x_{f,a}^{(t+1)} = 0$.  
    % Moreover, if $x_{f,w_{\max}-\frac{1}{D}}^{(\tau)} = 0$, then $x_{f,w_{\max}}^{(\tau)} = 1$, as desired.  So we can assume that for $\tau < t + \tau_{conv}$, $x_{f,w_{\max}-\frac{1}{D}}^{(\tau)} > 0$.
    % Further, for all $t$ where $x_{w,w_{\max}}^{(t)} < \frac{1}{D-k+1}$, it holds that 
    % \[u_f(w_{\max}-\frac{1}{D},x_w^{(t)})> u_f(w_{\max},x_w^{(t)}).\tag{2}\label{w-max-1/D-dominates-w-max}\]
    This fact along with the assumption $f_{\min}^{(t)} < f_{\max}^{(t)}$ and $w_{\max}^{(t)} = \frac{k}{D}$ imply   \[x_{f,w_{\max}^{(t)}-\frac{1}{D}}^{(t)}>0 \text{ and } x_{f,w_{\max}^{(t)}}^{(t)}>0,\]
    so by Claim~\ref{claim:stationarity_reqs}, 
    \[x_{f,w_{\max}^{(t)}}^{(t)}- x_{f,w_{\max}^{(t)}-\frac{1}{D}}^{(t)} = \eta U_{f,w_{\max}^{(t)}}^{(t-1)} - \eta U_{f,w_{\max}^{(t)}-\frac{1}{D}}^{(t-1)}.\tag{2}\label{firm-mass-t}\]
    Note that by definition, $f_{\min}^{(t+1)} \le f_{\max}^{(t+1)}$. First, suppose $f_{\min}^{(t+1)} = f_{\max}^{(t+1)}$, then this implies $x_{f,f_{\max}^{(t+1)}}^{(t+1)} = 1$. Since $x_{f,a}^{(t+1)}=0$ for all $a  \in\mathcal{A} \setminus\{\frac{k}{D},\frac{k-1}{D}\}$ and $u_f(w_{\max}^{(t)},x_w^{(t)})\ge u_f(w_{\max}^{(t)}-\frac{1}{D},x_w^{(t)})$, then $f_{\max}^{(t+1)} = w_{\max}^{(t)}$, thus, $x_{f,w_{\max}^{(t)}}^{(t+1)} =1$.



    Otherwise, suppose $f_{\min}^{(t+1)} < f_{\max}^{(t+1)}$. Since $x_{f,a}^{(t+1)}=0$ for all $a  \in\mathcal{A} \setminus\{\frac{k}{D},\frac{k-1}{D}\}$, then $f_{\min}^{(t+1)} < f_{\max}^{(t+1)}$ implies $x_{f,w_{\max}^{(t)}-\frac{1}{D}}^{(t+1)} > 0$ and $x_{f,w_{\max}^{(t)}}^{(t+1)} > 0$. So, by Claim~\ref{claim:stationarity_reqs}, \[x_{f,w_{\max}^{(t)}}^{(t+1)}- x_{f,w_{\max}^{(t)}-\frac{1}{D}}^{(t+1)} = \eta U_{f,w_{\max}^{(t)}}^{(t)} - \eta U_{f,w_{\max}^{(t)}-\frac{1}{D}}^{(t)}.\]  
    This fact along with Equation~\ref{firm-mass-t} and the primal constraint that the probability mass must sum to 1 implies
    \[x_{f,w_{\max}^{(t)}}^{(t+1)} = x_{f,w_{\max}^{(t)}}^{(t)} +\frac{\eta}{2}\left(u_f(w_{\max}^{(t)},x_w^{(t)}) - u_f(w_{\max}^{(t)}-\frac{1}{D},x_w^{(t)})\right).\]
    Since \[u_f(w_{\max}^{(t)},x_w^{(t)}) = \left(1-\frac{k}{D}\right)\cdot 1,\]
    and \[u_f(w_{\max}^{(t)}-\frac{1}{D},x_w^{(t)}) = \left(1-\frac{k-1}{D}\right)\cdot (1-x_{w,w_{\max}^{(t)}}^{(t)}),\]
    then, 
    \[x_{f,w_{\max}^{(t)}}^{(t+1)} = x_{f,w_{\max}^{(t)}}^{(t)} +\frac{\eta(D-k+1)}{2D}\left(x_{w,w_{\max}^{(t)}}^{(t)} - \frac{1}{D-k+1}\right).\]

    Next, we write the expression for $x_{w,w_{\max}^{(t)}}^{(t+1)}$.

    % As before, we can assume that for $\tau$ such that $t \le \tau < t+\tau_{dec}$, $x_{w,w_{\max}}^{(\tau)} > 0$.  
    To begin, since $w_{\max}^{(t)}$ is defined as the largest acceptance threshold with mass at time $t$, the assumption $w_{\max}^{(t)} = \frac{k}{D}$ implies $x_{w,w_{\max}^{(t)}}^{(t)} >0$ and for all $a > w_{\max}^{(t)}$, $x_{w,a}^{(t)} =0$. Moreover, by Lemma~\ref{lem:worker_pmf_structure}, for all $a < w_{\max}^{(t)}$, $x_{w,a}^{(t)} >0$.  Then, by Claim~\ref{claim:stationarity_reqs}, for all $a < w_{\max}^{(t)}$,
    \[x_{w,w_{\max}^{(t)}}^{(t)} - x_{w,a}^{(t)} = \eta U_{w,w_{\max}^{(t)}}^{(t-1)} - \eta U_{w,a}^{(t-1)}.\tag{3}\label{worker-mass-t}\]

    Next, by Lemma~\ref{lem:a_r,+_never_increases}, $w_{\max}^{(t+1)} \le w_{\max}^{(t)}$. First, suppose $w_{\max}^{(t+1)} < w_{\max}^{(t)}$, then this implies by definition of $w_{\max}$, $x_{w,w_{\max}^{(t)}}^{(t+1)} = 0$. 

    Otherwise, suppose $w_{\max}^{(t+1)} = w_{\max}^{(t)}$. Then, as above, for all $a > w_{\max}^{(t)}$, $x_{w,a}^{(t)} =0$, and for all $a < w_{\max}^{(t)}$, 
    \[x_{w,w_{\max}^{(t)}}^{(t+1)} - x_{w,a}^{(t+1)} = \eta U_{w,w_{\max}^{(t)}}^{(t)} - \eta U_{w,a}^{(t)}.\]
    This fact along with Equation~\ref{worker-mass-t} and the primal constraint that the probability mass must sum to 1 implies 
    \[x_{w,w_{\max}^{(t)}}^{(t+1)} = x_{w,w_{\max}^{(t)}}^{(t)} +\frac{\eta}{k+1}\left(\sum_{a < w_{\max}}\left( u_w(x_f^{(t)}, w_{\max}^{(t)}) - u_w(x_f^{(t)}, a)\right)\right).\]

    From the above derivation of $x_{f,w_{\max}^{(t)}}^{(t+1)}$, the assumptions of this lemma imply $x_{f,a}^{(t)} =0$ for all $a \in\mathcal{A}\setminus\{\frac{k}{D}, \frac{k-1}{D}\}$ and $x_{f,w_{\max}^{(t)}}^{(t)} >0,x_{f,w_{\max}^{(t)}-\frac{1}{D}}^{(t)} >0$. Thus, \[u_w(x_f^{(t)}, w_{\max}^{(t)}) = \frac{k}{D}\cdot x_{f,w_{\max}^{(t)}}^{(t)},\]
    and for all $a < \frac{k}{D}$,
    \[u_w(x_f^{(t)}, a) = \frac{k}{D}\cdot x_{f,w_{\max}^{(t)}}^{(t)} + \frac{k-1}{D}\cdot (1-x_{f,w_{\max}^{(t)}}^{(t)}).\]
    Therefore,
    \[x_{w,w_{\max}^{(t)}}^{(t+1)} = x_{w,w_{\max}^{(t)}}^{(t)} -\frac{\eta(k-1) k}{(k+1)D}\cdot \left(1-x_{f,w_{\max}^{(t)}}^{(t)}\right).\]
    \end{proof}


    \begin{customlem}{14}
    \label{lem:bounding_recurrence_relation_time}
        Suppose the agents run Algorithm~\ref{alg:ftrl} with $D>2$ and $0< \eta \le 1$.  Further, suppose at time $t$, $w_{\max}^{(t)} = \frac{k}{D}$ for some $k\in\{2,\ldots,D\}$, $x_{w,w_{\max}^{(t)}}^{(t)} \ge \frac{1}{D-k+1}$, $f_{\min}^{(t)} < f_{\max}^{(t)}$, and for all $a \in\mathcal{A} \setminus\{\frac{k}{D}, \frac{k-1}{D}\}$,\[U_{f,w_{\max}^{(t)}}^{(t-1)} -U_{f,a}^{(t-1)} \ge \frac{1}{\eta}.\]

       Then, there exists an integer $\tau \ge 0$ where either 1) $x_{w,w_{\max}^{(t)}}^{(t+\tau)} < \frac{1}{D-k+1}$, 2) $x_{f,w_{\max}^{(t)}}^{(t+\tau)} = 1$, or 3) for any $\epsilon>0$, $x_{f,w_{\max}^{(t)}}^{(\tau')} \ge 1-\epsilon$ for all $\tau' \ge t+\tau$.\\
       In case 1, $\tau \le \tau_{dec}$ where
       \[\tau_{dec} = \frac{519c^2\left(25\frac{D^{10}}{\eta}\right)^t}{\log(1+\frac{\eta}{2D(D+1)})}.\]
       % \frac{\log(\frac{4D^3}{\eta}) + 20 c d(9D^8)^{t} +4d +3md + 5}{\log(1+\frac{\eta}{2D(D+1)})}+2,\]
       In case 2, $\tau \le \tau_{conv}$ where 
       \[\tau_{conv} = \frac{519c^2\left(25\frac{D^{10}}{\eta}\right)^t}{\log(1+\frac{\eta}{2D(D+1)})}.\]
       % \frac{\log (\frac{3D^2}{\eta})+20c d(9D^8)^t + 4d + 3md + 5}{\log(1+\frac{\eta}{2D(D+1)})} +2,\]
       In case 3, for any $\epsilon>0$, $\tau \le \tau_{\epsilon}$ where 
      \[\tau_{\epsilon} = 2\log\left(\frac{3D^3}{\epsilon}\right)\cdot \frac{4D^2}{\eta}.\]
    \end{customlem}
    \begin{proof}
    The assumptions at time $t$ satisfy those of  Lemma~\ref{lem:recurrence_relation_dynamics}, so there are three possible outcomes at time $t+1$. First, $w_{\max}^{(t+1)}< w_{\max}^{(t)}$ implies $x_{w,w_{\max}^{(t)}}^{(t+1)} = 0$ which implies the outcome $x_{w,w_{\max}^{(t)}}^{(t+1)} < \frac{1}{D-k+1}$ is reached at time $t+1$. Second, $f_{\min}^{(t+1)} = f_{\max}^{(t+1)}$ implies $x_{f,w_{\max}^{(t)}}^{(t+1)} = 1$ which implies the outcome $x_{f,w_{\max}^{(t)}}^{(t+1)}=1$ is reached at time $t+1$. Finally, $f_{\min}^{(t+1)} < f_{\max}^{(t+1)}$ and $w_{\max}^{(t+1)}= w_{\max}^{(t)}$ imply
    \[x_{w,w_{\max}^{(t)}}^{(t+1)} = x_{w,w_{\max}^{(t)}}^{(t)} -\frac{\eta(k-1) k}{(k+1)D}\cdot \left(1-x_{f,w_{\max}^{(t)}}^{(t)}\right),\tag{1}\label{worker-recurrence}\]
    and
    \[x_{f,w_{\max}^{(t)}}^{(t+1)} = x_{f,w_{\max}^{(t)}}^{(t)} +\frac{\eta(D-k+1)}{2D}\left(x_{w,w_{\max}^{(t)}}^{(t)} - \frac{1}{D-k+1}\right).\tag{2}\label{firm-recurrence}\]
    Further, for all $a \in\mathcal{A} \setminus\{\frac{k}{D}, \frac{k-1}{D}\}$,\[U_{f,w_{\max}^{(t)}}^{(t)} -U_{f,a}^{(t)} \ge \frac{1}{\eta}.\tag{3}\label{w-max-still-max}\]
    % Note that Equation~\ref{worker-recurrence} along with $f_{\min}^{(t)} < f_{\max}^{(t)}$ implies $x_{w,w_{\max}^{(t)}}^{(t+1)} < x_{w,w_{\max}^{(t)}}^{(t)}$ while Equation~\ref{firm-recurrence} along with $x_{w,w_{\max}^{(t)}}^{(t)} \ge \frac{1}{D-k+1}$ implies $x_{f,w_{\max}^{(t)}}^{(t+1)} > x_{f,w_{\max}^{(t)}}^{(t)}$ if $x_{w,w_{\max}^{(t)}}^{(t)} > \frac{1}{D-k+1}$ and otherwise $x_{f,w_{\max}^{(t)}}^{(t+1)} = x_{f,w_{\max}^{(t)}}^{(t)}$. 
    If either $x_{w,w_{\max}^{(t)}}^{(t+1)} < \frac{1}{D-k+1}$ or $x_{f,w_{\max}^{(t)}}^{(t+1)}=1$, then the conclusion again holds at time $t+1$, otherwise $x_{w,w_{\max}^{(t)}}^{(t+1)} \ge \frac{1}{D-k+1}$ and $x_{f,w_{\max}^{(t)}}^{(t+1)}<1$  and the assumptions of Lemma~\ref{lem:recurrence_relation_dynamics} are satisfied again. Therefore, $x_{w,w_{\max}^{(t)}}^{(t)}$ strictly decreases in mass while $x_{f,w_{\max}^{(t)}}^{(t)}$ weakly increases in mass according to Equations~\ref{worker-recurrence} and~\ref{firm-recurrence} until there exists a value $\tau \ge 0$  where either $x_{w,w_{\max}^{(t)}}^{(t+\tau)} < \frac{1}{D-k+1}$, $x_{f,w_{\max}^{(t)}}^{(t+\tau)} = 1$, or, for any $\epsilon>0$, $x_{f,w_{\max}^{(t)}}^{(\tau')} \ge 1-\epsilon$ for all $\tau' \ge t+\tau$. 

    To bound the time it takes for one of these cases to occur, we next find a closed form solution for the strategy mass recurrence relations. Note that Equations~\ref{worker-recurrence} and~\ref{firm-recurrence} only give a valid mass of $x_{w,w_{\max}^{(t)}}^{(\tau+1)}$ and  $x_{f,w_{\max}^{(t)}}^{(\tau+1)}$, respectively, if both $x_{w,w_{\max}^{(t)}}^{(\tau)} \ge \frac{1}{D-k+1}$ and $x_{f,w_{\max}^{(t)}}^{(\tau)} < 1$. So, we introduce new recurrent variables $w$ and $f$ where \[w^{(0)} = x_{w,w_{\max}^{(t)}}^{(t)}, f^{(0)} = x_{f,w_{\max}^{(t)}}^{(t)},\]
    and
    \begin{align*}
    w^{(\tau+1)} &= w^{(\tau)} -\frac{\eta(k-1) k}{(k+1)D}\cdot \left(1-f^{(\tau)}\right), &\tag{4}\label{worker-recurrence-proxy}\\
    f^{(\tau+1)} &= f^{(\tau)} +\frac{\eta(D-k+1)}{2D}\left(w^{(\tau)} - \frac{1}{D-k+1}\right),&\tag{5}\label{firm-recurrence-proxy}\
    \end{align*}
    such that we can conclude, for all $\tau \ge 0$, \[\begin{cases}
        x_{w,w_{\max}^{(t)}}^{(t+\tau+1)} = w^{(\tau+1)} & w^{(\tau)} \ge \frac{1}{D-k+1}, f^{(\tau)} < 1\\
        x_{w,w_{\max}^{(t)}}^{(t+\tau+1)} < \frac{1}{D-k+1} & w^{(\tau+1)} < \frac{1}{D-k+1}
    \end{cases}\]
     and 
     \[\begin{cases}
        x_{f,w_{\max}^{(t)}}^{(t+\tau+1)} = f^{(\tau+1)} & w^{(\tau)} \ge \frac{1}{D-k+1}, f^{(\tau)} < 1\\
        x_{f,w_{\max}^{(t)}}^{(t+\tau+1)} = 1 & f^{(\tau+1)} \ge 1
    \end{cases}\]
    Thus, we can analyze the limiting behavior of the closed form of Equations~\ref{worker-recurrence-proxy} and~\ref{firm-recurrence-proxy} to determine the outcomes of the variables $x_{w,w_{\max}^{(t)}}^{(t+\tau)} $ and $x_{f,w_{\max}^{(t)}}^{(t+\tau)}$ as a function of the conditions at time $t$.

    For ease of notation, let \[A:= \frac{\eta(k-1) k}{(k+1)D},B:= \frac{\eta(D-k+1)}{2D},C:= \frac{\eta}{2D}.\tag{6}\label{notation-1}\] Since $\eta >0$ and $D>2$, then $A,B,C$ are all positive reals.

    % Then, recurrence relations~\ref{worker-recurrence} and~\ref{firm-recurrence} simplify to 
    % \begin{align*}
    %     w^{(t+1)} &= w^{(t)} + A \cdot f^{(t)} - A,\\
    %     f^{(t+1)} &= f^{(t)} + B \cdot w^{(t)} - C.
    % \end{align*}
    Then, by applying Lemma~\ref{lem:solving_recurrence_relations} to Equations~\ref{worker-recurrence-proxy} and~\ref{firm-recurrence-proxy},
    \begin{align*}
        w^{(\tau)} &= \alpha_1^w\sqrt{AB}(1+\sqrt{AB})^{\tau-1} - \alpha_2^w\sqrt{AB}(1-\sqrt{AB})^{\tau-1} + \frac{1}{D-k+1},&\tag{7}\label{worker-closed}\\
        f^{(\tau)} &= \alpha_1^f\sqrt{AB}(1+\sqrt{AB})^{\tau-1} - \alpha_2^f\sqrt{AB}(1-\sqrt{AB})^{\tau-1} + 1,&\tag{8}\label{firm-closed}
    \end{align*} 
    where, in Expressions~\ref{a_1_w} through~\ref{a_2_f} in the statement of Lemma~\ref{lem:solving_recurrence_relations},
    \[c_w := w^{(0)} - \frac{1}{D-k+1},c_f := 1-f^{(0)}\tag{9}\label{notation-2}\] and either $\sign(\alpha_1^f)= \sign(\alpha_1^w)$ or $\alpha_1^f=\alpha_1^w = 0$. So, there are three possible cases to consider and we will show that these cases correspond to the three possible outcomes: 1) $\alpha_1^w,\alpha_1^f<0$ imply there exists $\tau \ge 0$ where $x_{w,w_{\max}^{(t)}}^{(t+\tau)} < \frac{1}{D-k+1}$, 2) $\alpha_1^w,\alpha_1^f>0$ imply  there exists $\tau \ge 0$ where $x_{f,w_{\max}^{(t)}}^{(t+\tau)} = 1$, or 3) $\alpha_1^w=\alpha_1^f=0$ imply for any $\epsilon>0$, there exists $\tau \ge 0$ where $x_{f,w_{\max}^{(t)}}^{(\tau')} \ge 1-\epsilon$ for all $\tau' \ge t+\tau$.

    %Bounding $\tau_{dec}$
    \textbf{Case 1:} $\alpha_1^w,\alpha_1^f <0$.\\
    Suppose $\alpha_1^w <0$ and note that $0<\eta \le 1$ implies $0<A < 1$ and $0<B < 1$ for all $k \in \{2,\ldots,D\}$. Then, $\alpha_1^w<0$ and $0<AB < 1$ imply \[\lim_{\tau \to \infty}w^{(\tau)} = -\infty.\] Thus, there exists $\tau_{dec} \ge 0$ where $w^{(\tau_{dec})} < \frac{1}{D-k+1}$, thereby implying $x_{w,w_{\max}^{(t)}}^{(t+\tau_{dec})} < \frac{1}{D-k+1}$. To upper bound the value of $\tau_{dec}$, we upper bound Equation~\ref{worker-closed} while maintaining its limiting behavior. That is, we first lower bound $\alpha_2^w$, and then we upper bound $\alpha_1^w$ with a negative number to ensure the final upper bound on $w^{(\tau)}$ also limits to $-\infty$.

    \textbf{Bounding $\alpha_2^w$ and $\alpha_1^w$.}\\
    First, we lower bound $\alpha_2^w$.
    \begin{align*}
        \alpha_2^w &\ge -\frac{1}{2B}  - \frac{1}{2\sqrt{AB}}\tag{10}\label{line1-alpha-2}\\
        &\ge -\frac{D + D(D+1)}{\eta}\tag{11}\label{line2-alpha-2}\\
        & \ge -\frac{3D^2}{\eta} 
    \end{align*}
    where Line~\ref{line1-alpha-2} follows from Equation~\ref{a_2_w} and that fact that $c_w,c_f \in [0,1]$ and Line~\ref{line2-alpha-2} follows from $B \ge \frac{\eta}{2D}$ and $\sqrt{AB} \ge \frac{\eta}{2D(D+1)}$ for all $k \in \{2,\ldots,D\}$.

    Next, we upper bound $\alpha_1^w$ with a negative value. First, note that $\alpha_1^w <0$ and $AB < 1$ imply $c_w-\frac{1}{B}c_f <0$, so $|\alpha_1^w|$ is minimized when $c_w-A\cdot c_f > 0$ and, thus, it suffices to upper bound $\alpha_1^w$ under the assumption $c_w-A\cdot c_f > 0$. 
    % To do so, we consider two cases of the initial conditions. Note that $\alpha_1^w <0$ and $AB < 1$ imply $c_w-\frac{1}{B}c_f <0$, so we consider the two cases of $c_w-A\cdot c_f \le 0$ and $c_w-A\cdot c_f > 0$. 
    % First, suppose $c_w-A\cdot c_f \le 0$. Then, the fact $\sqrt{AB} <1$ along with equation~\ref{a_1_w} and the assumption $c_w-A\cdot c_f \le 0$ imply \[\alpha_1^w \le \frac{1}{2}(c_w - \frac{1}{B}c_f)+\frac{1}{2}(c_w-A\cdot c_f)\tag{12}\label{case-1-bound-1}.\]
    % The right hand side of~\ref{case-1-bound-1} is a rational number since $w^{(t)}, f^{(t)}, D,\eta$ are all rational numbers and the right hand side only includes addition and multiplication operations. Recall that we assume any $k \in \{1,\ldots,D+1\}$ is represented in at most $d$ bits and the numerator and denominator of $\eta$ are each represented in at most $d$ bits. Next, by Lemma~\ref{lem:max_bits_of_x_i,a^t}, $w^{(t)}$ and $f^{(t)}$ are each rational numbers that have a numerator and denominator each represented by at most $8c d(9D^8)^{t}$ bits. Then, using the definitions in~\ref{notation-2}, we can conclude $c_w$ and $c_f$ are both rational and have denominators represented by at most $8c d(9D^8)^{t} + d$ bits and numerators represented by at most $8c d(9D^8)^{t} + d +1$ bits. Next, using the definitions in~\ref{notation-1}, the right hand side of~\ref{case-1-bound-1} has a denominator upper bounded by \[2\cdot c_w^D\cdot \eta^N \cdot (D-k+1)\cdot c_f^D\cdot (k+1)\cdot D.\]
    % Using bit calculations from the assumptions above, this number can be represented in at most $6d +1 + 16cd(9D^8)^t$ bits. Finally, since the numerator of the rational number on the right hand side of~\ref{case-1-bound-1} is at least 1 and we know $\alpha_1^w <0$, then we can conclude 
    % \[\alpha_1^w \le - 2^{-(6d+1+16cd(9D^8)^t)}.\]
    Then, the fact that $\sqrt{AB} <1$ along with Equation~\ref{a_1_w} and the assumption $c_w-A\cdot c_f > 0$ imply that any $x \in \mathbb{R}$ that satisfies \[\frac{c_w-Ac_f}{\frac{1}{B}c_f-c_w}<x \le \sqrt{AB},\tag{13}\label{case-1-bounds}\]
    also satisfies
     \[\alpha_1^w \le \frac{1}{2}(c_w - \frac{1}{B}c_f)+\frac{1}{2x}(c_w-A\cdot c_f)<0. \tag{14}\label{case-1-x-expression}\]
     Finally, since $\eta, D, c_w,c_f, A,$ and $B$ are all rational, we want to find an $x \in \mathbb{Q}$ that satisfies the bounds in~\ref{case-1-bounds} in order to count bits from a series of multiplication and addition operations of rational numbers.
     \paragraph{Constructing $x$.} To construct such a rational $x$, we lower bound the difference $\sqrt{AB} -\frac{c_w-Ac_f}{\frac{1}{B}c_f-c_w}$ by a rational number $r$ such that it suffices to set $x = \frac{c_w-Ac_f}{\frac{1}{B}c_f-c_w} + r$.

    To begin, using the definition of $A$ and $B$ from~\ref{notation-1},\[\sqrt{AB} -\frac{c_w-Ac_f}{\frac{1}{B}c_f-c_w} =\frac{\eta}{2D(k-1)}\left(\sqrt{2k(k-1)(k+1)(D-k+1)} - \frac{\frac{2D(k-1)}{\eta}c_w - \frac{2k(k-1)^2}{(k+1)}c_f}{\frac{2D}{\eta(D-k+1)}c_f-c_w}\right).\]
    % \[\frac{D_k^1\cdot c_w^N\cdot c_f^D\cdot \eta^D - D_k^2\cdot c_f^N\cdot \eta^N\cdot c_w^N}{D_k^3\cdot c_f^N\cdot c_w^D\cdot \eta^D - D_k^4\cdot c_w^N\cdot \eta^N \cdot c_f^D}\]
    Note that the first term in the parentheses is of the form $\sqrt{n}$ for $n \in \mathbb{Z}_{>0}$ and the second term in the parentheses is a rational number and let $\frac{R}{S}$ denote the reduced form of the second term in the parentheses. Further, note that the largest possible square in the radicand of the first term is $D^4$. Since $\sqrt{s^2 r} - a = s(\sqrt{r}-\frac{a}{s})$ for any $s,a \in \mathbb{Z}_{>0}$ and square-free $r \in \mathbb{Z}_{\ge 0}$, then pulling out all square terms to ensure the radicand is square-free increases the denominator of the second term by at most a factor of $D^2$.  Thus, by Lemma~\ref{lem:rational-approx-bound}, there exists coprime integers $P,Q$ where $Q \le C_k \cdot S$ for a constant $C_k <128(2k(k-1)(k+1)(D-k+1))^2$ such that \[\sqrt{AB} -\frac{c_w-Ac_f}{\frac{1}{B}c_f-c_w} \ge \frac{\eta}{2D(k-1)}\left(\frac{P}{Q} - \frac{R}{S}\right)>0.\] 
    Note that, for all $k \in \{2,\ldots,D\}$,
    \[C_k < 512D^8.\]
    % which is represented in at most $8\log(2D)$ bits.

    Further, let the reduced rational representation of $c_w,c_f,$ and $\eta$ be denoted as \[c_w = \frac{c_w^N}{c_w^D}, c_f = \frac{c_f^N}{c_f^D},\eta = \frac{\eta^N}{\eta^D},\]
    where $c_w^N, c_f^N,\eta^N \in \mathbb{Z} $ and $c_w^D, c_f^D,\eta^D \in \mathbb{Z}_{>0}$.
    Therefore, the largest denominator of $\frac{\eta}{2D(k-1)}\left(\frac{P}{Q} - \frac{R}{S}\right)$ is \[\eta^D\cdot 2\cdot D\cdot (k-1)\cdot 512\cdot D^8\cdot S^2, \tag{15}\label{largest-denominator-of-diff}\]
    where, using standard fraction simplification along with the factor of $D^2$ to ensure the radicand is square-free,
    \[S \le D^2\cdot \left(2D\cdot(k+1)\cdot c_f^N\cdot c_w^D\cdot \eta^D - (D-k+1)\cdot (k+1)\cdot c_w^N\cdot \eta^N \cdot c_f^D\right). \tag{16}\label{S-upper-bound}\]

    Finally, using standard bit arithmetic, we can calculate an upper bound on the maximum number of bits in expression~\ref{largest-denominator-of-diff}, denoted as $\beta$. Recall that the bits to represent the numerator and denominator of the rational $\eta$ in the reduced form is $c$ and for all $k \in \{0,\ldots,D+1\}$, the number of bits to represent $k$ is at most $\log(D+1)$.     
    \begin{align*}
        \beta &\le  2\log\left(D+1\right) + c + 2 + 8\log(2D) + 2 \log(S)\\
        &\le 10\log\left(2D+1\right) + c + 2  + 2\left(2\log(D) + 2\log\left(D+1\right) + c+44c^2\log\left(D+1\right)(25D^8)^t+2\right)&\tag{17}\label{line-2-beta}\\
        &\le 115c^2\log\left(2D+1\right)(25D^8)^t
    \end{align*}
    where Line~\ref{line-2-beta} follows from bound~\ref{S-upper-bound} and, using Definition~\ref{notation-2} and Lemma~\ref{lem:max_bits_of_x_i,a^t}, that, for $i \in \{f,w\}$, $c_i^N$ and $c_i^D$ are both represented in at most $22c^2\log\left(D+1\right)(25D^8)^t$ bits.

    Let $\beta'$ be the upper bound on $\beta$, i.e., $\beta' =115c^2\log\left(2D+1\right)(25D^8)^t$ and by Lemma~\ref{lem:bits-to-bound}, \[\sqrt{AB} -\frac{c_w-Ac_f}{\frac{1}{B}c_f-c_w} \ge 2^{-\beta'}=: r,\] and we set $x =\frac{c_w-Ac_f}{\frac{1}{B}c_f-c_w} + 2^{-\beta'} $.

    \paragraph{Using $x$ to bound $\alpha_1^w$.} Plugging this value of $x$ into expression~\ref{case-1-x-expression} gives a negative upper bound on $\alpha_1^w$ that is rational and, using similar bit arithmetic as above, the maximum number of bits to represent its denominator is \[\mathcal{B} = 259c^2\log\left(2D+1\right)(25D^8)^t.\tag{18}\label{final-beta-case-1}\]
    Thus, by Lemma~\ref{lem:bits-to-bound}, \[\alpha_{1}^w \le -2^{-\mathcal{B}}.\]

    \textbf{Bounding $\tau_{dec}$.}\\ 
    Since $0<AB\le 1$, then for all $\tau\ge 1$, \[(1-\sqrt{AB})^{\tau-1} < 1.\] 
    Therefore,
    \begin{align*}
