\begin{customthrm}{2}
\label{thrm:ftrl_convergence_rate}
    Suppose agents learn strategies for $\mathcal{G}^{(1)}$ using Algorithm~\ref{alg:ftrl} with $\alpha_i=\mathbf{0}$, any $0<\eta \le 1, D>2$, and arbitrary initial conditions $x_w^{(1)}, x_f^{(1)} \in \Delta(\mathcal{A})$. Then, for any $\epsilon>0$, the maximum time to convergence of Algorithm~\ref{alg:ftrl} to an $\epsilon$-Nash equilibrium is
    \[O\left(\left[\left(2^{\frac{D}{\eta}^{{\frac{D^{31}}{\eta^5}}}}\right)\uparrow \uparrow D\right] +\log\left(\frac{D^3}{\epsilon}\right)\cdot \frac{D^2}{\eta}\right).\]
    % \[\left(2^{D^{{ M\cdot \frac{D^{27}}{\eta^5}}}}\right)\uparrow \uparrow D +2\log\left(\frac{3D^3}{\epsilon}\right)\cdot \log\left(\frac{4D^2}{4D^2-\eta}\right)^{-1}.\]
    % \[\left(2^{D^{D^{12M\frac{D^{18}}{\eta}}}}\right)\uparrow \uparrow D +\log\left(\frac{3D^2}{2\epsilon}\right)\cdot \log\left(\frac{2}{2-\eta}\right)^{-1}\]
    % where \[M= 3483 c\cdot m\cdot d,\]
    % for a constant $M>0$.
\end{customthrm}
\begin{proof}

    % start by formalizing the conditions for convergence to eps-NE using theorem 1. reader should know what the goal of the bound is in this paragraph.
     To begin, recall that Lemma~\ref{lem:final_NE_convergence} gives the conditions at some time $t^*$ under which we can conclude that $(x_f^{(\tau)},x_w^{(\tau)})$ is in the same $\epsilon$-Nash equilibrium for all $\tau \ge t^*$, that is, the agents have converged to an $\epsilon$-Nash equilibrium. Thus, to find the maximum time to convergence of Algorithm~\ref{alg:ftrl} to an $\epsilon$-Nash equilibrium, it suffices to bound the time $t^*$ at which we are guaranteed the following conditions hold: Let $w_{\max}^{(t^*)} = \frac{k}{D}$ for some $k = \{1,\ldots,D\}$, then $x_{w,w_{\max}^{(t^*)}}^{(\tau)} \ge \frac{1}{D-k+1}$ for all $\tau \ge t^*$ and either $x_{f,w_{\max}^{(t^*)}}^{(\tau)} = 1$ for all $\tau \ge t^*$ or $x_{f,w_{\max}^{(t^*)}}^{(\tau)} \ge 1-\epsilon$ for all $\tau \ge t^*$. 

     % better scaffolding
    To do so, we first bound the time $t_1$ until, for $w_{\max}^{(t_1)} = \frac{k}{D}$ for some $k \in \{1,\ldots,D\}$, $x_{w,w_{\max}^{(t_1)}}^{(\tau)} \ge \frac{1}{D-k+1}$ for all $\tau \ge t_1$. Then, for any $\epsilon \ge 0$, we bound the maximum time $t_2$ until $x_{f,w_{\max}^{(t_1)}}^{(\tau)} \ge 1-\epsilon$ for all $\tau \ge t_1+t_2$. Thus, the maximum time to convergence for both agents will be $t^*= t_1 + t_2$. 

    % step 1 -- maximum time for a w_max to be guaranteed to pass threshold, call this time t_1 (should this be a separate lemma -- idk, this is most of the theorem actually).
    \textbf{Bounding $t_1$.}\\
     Here, we say $w_{\max}$ decreases in value at time $t$ if $w_{\max}^{(t+1)} < w_{\max}^{(t)}$. By Lemma~\ref{lem:a_r,+_never_increases}, $w_{\max}^{(t+1)} \le w_{\max}^{(t)}$ for all $t \ge 1$, so $w_{\max}^{(t)}$ can only ever decrease in value once per $k \in \{2,\ldots,D\}$. Note that in the proof of Theorem~\ref{thrm:ftrl_convergence_n=1}, the smallest possible value of $w_{\max}$ at convergence is $\frac{1}{D}$. Thus, to bound $t_1$, it suffices to first bound the maximum number of time steps for $w_{\max} = \frac{k}{D}$ to decrease in value for any $k \in \{2,\ldots,D\}$ as a function of the first time step where $w_{\max} = \frac{k}{D}$. Then, we can compose such a function $D-1$ times to get the final bound on $t_1$.

    Suppose $t_0$ is the first time step where $w_{\max}^{(t_0)}= \frac{k}{D}$ for some $k \in \{2,\ldots,D\}$ and that there exists a time where $w_{\max}^{(t_0)}$ decreases in value. We begin by bounding the time $\tau_1 \ge t_0$ where $x_{w,w_{\max}^{(t_0)}}^{(\tau_1)} < \frac{1}{D-k+1}$. Note that by Lemmas~\ref{lem:x_w_a_r,+_decreases} and~\ref{lem:stationary_x_w}, $x_{w,w_{\max}^{(t_0)}}^{(t)} \le x_{w,w_{\max}^{(t_0)}}^{(t-1)}$ for all $t >t_0$, i.e., the mass weakly decreases, so $\tau_1$ is the first time $x_{w,w_{\max}^{(t_0}}^{(\tau_1)}$ cross the threshold $\frac{1}{D-k+1}$.

    \paragraph{Bounding $\tau_1$} Here, we will show that there exists a time $\tau_1$ where \[t_0 \le \tau_1 \le t_0 + \frac{D^2}{\eta} + D^2\cdot t_0 +  \frac{519c^2\left(25\frac{D^{10}}{\eta}\right)^{t_0}}{\log(1+\frac{\eta}{2D(D+1)})}\]
    and $x_{w,w_{\max}^{(t_0)}}^{(\tau_1)} < \frac{1}{D-k+1}$.

    First, let $\tau_1' = t_0 + \frac{D^2}{\eta} + D^2\cdot t_0 +  \frac{519c^2\left(25\frac{D^{10}}{\eta}\right)^{t_0}}{\log(1+\frac{\eta}{2D(D+1)})}$ and suppose $x_{w,w_{\max}^{(t_0)}}^{(t)} \ge \frac{1}{D-k+1}$ for all $ t_0\le t < \tau_1'$ since, otherwise, we have found a $\tau_1$ within the bounds where $x_{w,w_{\max}^{(t_0}}^{(\tau_1)}$ cross the threshold $\frac{1}{D-k+1}$. 

     This assumption implies $x_{w,w_{\max}^{(t_0)}}^{(t)} >0$ for $t_0 \le t< \tau_1'$, so \[u_f(w_{\max}^{(t_0)}, x_w^{(t)}) = \left(1-\frac{k}{D}\right)\cdot 1.\] 
    This implies, for all offers $a > w_{\max}^{(t_0)}$ and all $t_0 \le t < \tau_1'$, \begin{align*}
        u_f(w_{\max}^{(t_0)}, x_w^{(t)}) - u_f(a, x_w^{(t)}) \ge \frac{1}{D}. & \tag{1}\label{u_bound_1}
    \end{align*}
    Next, for all offers $a = \frac{\ell}{D} < w_{\max}^{(t_0)}-\frac{1}{D}$ and all $t_0 \le t < \tau_1'$,
    \begin{align*}
        u_f(w_{\max}^{(t_0)},x_w^{(t)}) - u_f(a,x_w^{(t)}) &= \left(1-\frac{k}{D}\right) - \left(1-\frac{\ell}{D}\right)\cdot\left(1-\sum_{\frac{\ell}{D}<a'\le w_{\max}^{(t_0)}}x_{w,a'}^{(t)}\right)\\
        &\ge \left(1-\frac{k}{D}\right) - \left(1-\frac{\ell}{D}\right)\cdot\left(1-(k-\ell)\frac{1}{D-k+1}\right)&\tag{2}\label{u-bound-2}\\
        &= \frac{(k-\ell)^2 - (k-\ell)}{D(D-k+1)}\\
        &\ge \frac{1}{D^2} &\tag{3}\label{u-bound-3}
    \end{align*}
    Line~\ref{u-bound-2} follows from the assumption $x_{w_{\max}^{(t_0)}}^{(t)} \ge \frac{1}{D-k+1}$ and Lemma~\ref{lem:worker_pmf_structure} and Line~\ref{u-bound-3} follows from the bounds $1< k < D$ and $\ell < k-1$ and from the fact that $\ell \in \mathbb{Z}_{\ge 0}$ imply $(k-\ell)^2 - (k-\ell) >1$.

    % Then, combining bounds~\ref{u_bound_1} and~\ref{u-bound-3}, then for all $a \neq w_{\max}^{(t_0)}, a\neq w_{\max}-\frac{1}{D}$, for all $\tau \ge t_0$ where $x_{w,w_{\max}^{(t_0)}}^{(\tau)} \ge \frac{1}{D-k+1}$, $$u_f(w_{\max}^{(t_0)},x_w^{(\tau)}) - u_f(a,x_w^{(\tau)}) \ge \frac{1}{D^2}.$$
    Then, since the maximum utility any agent gains in a single time step is 1, then for all $a \neq w_{\max}^{(t_0)}, a\neq w_{\max}^{(t_0)}-\frac{1}{D}$,
    \[U_{f,w_{\max}^{(t_0)}}^{(t_0)} - U_{f,a}^{(t_0)} \ge -t_0. \tag{4}\label{cumulative-lower-bound-1}\]
    So, by bounds~\ref{u_bound_1},~\ref{u-bound-3}, and~\ref{cumulative-lower-bound-1} and the assumption that  $x_{w_{\max}^{(t_0)}}^{(t)} \ge \frac{1}{D-k+1}$ for all $t_0 \le t < \tau_1'$, we are guaranteed, for all $a \neq w_{\max}^{(t_0)}, w_{\max}^{(t_0)}-\frac{1}{D}$ that for all $t_0 + \frac{D^2}{\eta} + D^2\cdot t_0 \le t' < \tau_1'$,
    \[U_{f,w_{\max}^{(t_0)}}^{(t')} - U_{f,a}^{(t')} \ge \frac{1}{\eta}.\tag{5}\label{cumulative-lower-bound-2}\]
    Then, for all $a \neq w_{\max}^{(t_0)},w_{\max}^{(t_0)}-\frac{1}{D}$, Claims~\ref{claim:stationarity_reqs} and~\ref{claim:kkt_ordering} and the probability constraint along with bound~\ref{cumulative-lower-bound-2} imply 
    % it is impossible for both $x_{f,w_{\max}^{(t_0)}}^{(t_0 + \frac{D^2}{\eta} + D^2\cdot t_0)}>0$ and $x_{f,a}^{(t_0 + \frac{D^2}{\eta} + D^2\cdot t_0)}>0$. Further, since $U_{f,w_{\max}^{(t_0)}}^{(t_0 + \frac{D^2}{\eta} + D^2\cdot t_0)} > U_{f,a}^{(t_0 + \frac{D^2}{\eta} + D^2\cdot t_0)}$, then by Claim~\ref{claim:kkt_ordering}, we are guaranteed 
    $x_{f,a}^{(t')}=0$ and, thus, $f_{\min}^{(t')} \ge w_{\max}^{(t_0)}-\frac{1}{D}$ and $f_{\max}^{(t')} \le w_{\max}^{(t_0)}$ for all $ t_0 + \frac{D^2}{\eta} + D^2\cdot t_0 \le t'< \tau_1'$. Note that, by definition, $f_{\min}^{(t)} \le f_{\max}^{(t)}$ for all $t>0$, so we now go through the three possible cases implied by $f_{\min}^{(t')}, f_{\max}^{(t')} \in \{w_{\max}^{(t_0)}-\frac{1}{D}, w_{\max}^{(t_0)}\}$ for all $ t_0 + \frac{D^2}{\eta} + D^2\cdot t_0 \le t'<\tau_1'$.

    % cases to show either we apply lemma 17 or we reach the point earlier. (needs work)
    First, suppose that $f_{\min}^{(t')} = f_{\max}^{(t')} = w_{\max}^{(t_0)}$. Then, this implies $x_{f,w_{\max}^{(t_0)}}^{(t')} = 1$ and we can conclude convergence has occurred given our assumption $x_{w,w_{\max}^{(t_0)}}^{(t')} \ge \frac{1}{D-k+1}$ and we are done. 
    Next, suppose  $f_{\min}^{(t')} = f_{\max}^{(t')} = w_{\max}^{(t_0)}-\frac{1}{D}$ for all $ t_0 + \frac{D^2}{\eta} + D^2\cdot t_0 \le t'< \tau_1'$. Note that if there exists $t_0\le t <\tau_1$ where $f_{\min}^{(t)} \neq w_{\max}^{(t_0)}-\frac{1}{D}$ or $f_{\max}^{(t)} \neq w_{\max}^{(t_0)}-\frac{1}{D}$, then we will be in one of the other two cases. Then, for all $a < w_{\max}^{(t_0)}$ and all $ t_0 + \frac{D^2}{\eta} + D^2\cdot t_0 \le t'< \tau_1'$,
    \[u_w(x_f^{(t')}, a) - u_w(x_f^{(t')},w_{\max}^{(t_0)}) = \frac{k-1}{D}. \tag{6}\label{worker-fmin-utility-bound}\]
    Then, by Claim~\ref{claim:stationarity_reqs} and the probability mass constraint, \[x_{w,w_{\max}^{(t_0)}}^{(t'+1)} = x_{w,w_{\max}^{(t_0)}}^{(t')}+\frac{\eta}{k}\left(\sum_{a<w_{\max}^{(t_0)}}u_w(x_f^{(t')}, w_{\max}) - u_w(x_f^{(t')},a)\right),\]
    so substituting in Equation~\ref{worker-fmin-utility-bound} and using the fact that $k \in \{2,\ldots,D\}$ results in the following bound,
    \[x_{w,w_{\max}^{(t_0)}}^{(t'+1)} \le x_{w,w_{\max}^{(t_0)}}^{(t')}-\frac{\eta}{D^2}.\]
    Therefore, we are guaranteed $x_{w,w_{\max}^{(t_0)}}^{(t'+\frac{D}{\eta})}<\frac{1}{D-k+1}$.  

    Finally, suppose $f_{\min}^{(t')}  = w_{\max}^{(t_0)}-\frac{1}{D}$ and $f_{\max}^{(t')} = w_{\max}^{(t_0)}$. We further break this case into two subcases. First, suppose $x_{w,w_{\max}^{(t_0)}}^{(t')} = \frac{1}{D-k+1}$. Since $f_{\min}^{(t')} < w_{\max}^{(t_0)}$, then by Lemma~\ref{lem:x_w_a_r,+_decreases}, $x_{w,w_{\max}^{(t_0)}}^{(t'+1)} < \frac{1}{D-k+1}$. 
    Otherwise, suppose $x_{w,w_{\max}^{(t_0)}}^{(t')} > \frac{1}{D-k+1}$. Then, the assumptions of Lemma~\ref{lem:bounding_recurrence_relation_time} are satisfied and since we have assumed there exists a time where $w_{\max}^{(t_0)}$ decreases in value, we can conclude it will take at most \[ \tau_{dec} = \frac{519c^2\left(25\frac{D^{10}}{\eta}\right)^{t_0}}{\log(1+\frac{\eta}{2D(D+1)})}\] time steps to be guaranteed $x_{w,w_{\max}^{(t_0)}}^{(t'+ \tau_{dec})} < \frac{1}{D-k+1}$. 

    Since $\eta \le 1$ implies $\log(1+\frac{\eta}{2D(D+1)})<1,D>2$, and $t_0 \ge 1$, it is clear that $\tau_{dec} > \frac{D}{\eta} > 1$, thus we can conclude
    \[\tau_1 \le t_0 + \frac{D^2}{\eta} + D^2\cdot t_0 + \tau_{dec} = \tau_1'.\] 

    Next, we derive the maximum time steps $\tau_2 \ge \tau_1$ until $x_{w,w_{\max}^{(t_0)}}^{(\tau_2)}=0$ given that $x_{w,w_{\max}^{(t_0)}}^{(\tau_1)}< \frac{1}{D-k+1}$. 
    \paragraph{Bounding $\tau_2$.} We begin by bounding the time it takes for the firm's mass on  $w_{\max}^{(t_0)}$ to reach 0. We start by lower bounding \[\frac{1}{D-k+1}- x_{w,w_{\max}^{(t_0)}}^{(t_1)}\] 
    by a positive value since the firm's mass decreases on $w_{\max}^{(t_0)}$ at a rate proportional to this difference. By Lemma~\ref{lem:max_bits_of_x_i,a^t}, we know $x_{w,w_{\max}^{(t_0)}}^{(\tau_1)}$ has a denominator represented by at most $20c^2\log\left(D+1\right)(25D^8)^{\tau_1}$ bits and $\frac{1}{D-k+1}$ has a denominator represented by at most $\log(D)$ bits for any $k \in \{2,\ldots,D\}$, so their difference has a denominator that can be represented by at most $20c^2\log\left(D+1\right)(25D^8)^{\tau_1} + \log(D)$ bits. Then, by Lemma~\ref{lem:bits-to-bound}, \[\frac{1}{D-k+1} - x_{w,w_{\max}^{(t_0)}}^{(\tau_1)} >2^{-(20c^2\log\left(D+1\right)(25D^8)^{\tau_1} + \log(D))}.\tag{7}\label{D-k+1-diff-bound}\]

    Since $x_{w,w_{\max}^{(t_0)}}^{(\tau_1)}$ does not increase by Lemmas~\ref{lem:stationary_x_w} and~\ref{lem:x_w_a_r,+_decreases}, then the bound~\ref{D-k+1-diff-bound} implies for all $\tau \ge \tau_1$,
    \[u_f(w_{\max}^{(t_0)}-\frac{1}{D}, x_w^{(\tau)}) - u_f(w_{\max}^{(t_0)},x_w^{(\tau)}) > \frac{1}{D}\cdot 2^{-(20c^2\log\left(D+1\right)(25D^8)^{\tau_1} + \log(D))}.\]

    Next, since $$U_{f,w_{\max}-\frac{1}{D}}^{(\tau_1)} - U_{f,w_{\max}^{(t_0)}}^{(\tau_1)} \ge - \tau_1,$$
    Then it will take at most \[t'=\frac{D}{\eta}2^{20c^2\log\left(D+1\right)(25D^8)^{\tau_1} + \log(D)} + \tau_1 2^{20c^2\log\left(D+1\right)(25D^8)^{\tau_1} + \log(D)}\]
    time steps to be guaranteed, for all $\tau \ge \tau_1+t'$,
    \[U_{f,w_{\max}-\frac{1}{D}}^{(\tau)} - U_{f,w_{\max}^{(t_0)}}^{(\tau)} \ge \frac{1}{\eta}.\]

    Thus, by Claims~\ref{claim:stationarity_reqs} and~\ref{claim:kkt_ordering} and the probability constraint, we can say $x_{f,w_{\max}^{(t_0)}}^{(\tau)} =0$ for all $\tau \ge \tau_1+t'$. 

    Finally, we bound the time it takes for the worker to no longer put mass on $w_{\max}^{(t_0)}$. First, by Lemma~\ref{lem:worker_pmf_structure}, \[U_{w,\frac{1}{D}}^{(\tau_1+t')} - U_{w,w_{\max}^{(t_0)}}^{(\tau_1+t')} \ge 0,\] 
    and since $x_{f,w_{\max}^{(t_0)}}^{(\tau)} =0$ implies $f_{\max}^{(\tau)} < w_{\max}^{(t_0)}$ for all $\tau \ge \tau_1 + t'$ and, by the utility functions, $x_{f,0}^{(t)} \le \frac{1}{2}$ for all $t$, then for all $\tau \ge \tau_1+t'$,
    \[u_{w}(x_f^{(\tau)},\frac{1}{D}) - u_{w}(x_f^{(\tau)},w_{\max}^{(t_0)}) \ge \frac{1}{2D}.\]
    Thus, for all $\tau \ge \tau_1+t'+\frac{2D}{\eta}$, \[U_{w,\frac{1}{D}}^{(\tau)} - U_{w,w_{\max}^{(t_0)}}^{(\tau)} \ge \frac{1}{\eta}.\]
    Then, by Claims~\ref{claim:stationarity_reqs} and~\ref{claim:kkt_ordering} and the probability constraint, we can conclude  $x_{w,w_{\max}^{(t_0)}}^{(\tau)}=0$ for all $\tau \ge \tau_1+t'+\frac{2D}{\eta}$, i.e., $w_{\max}^{(t_0)}$ must decrease in value, and we can conclude \[\tau_2 \le \tau_1+t'+\frac{2D}{\eta}.\]

    \paragraph{Deriving the final bound on $t_1$} In total, the maximum number of time steps before $w_{\max}$ decreases as a function of the starting time step $t_0$ is $\tau_2 - t_0$ which can be bounded as follows
    \begin{align*}
       \tau_2 -t_0 &\le  \tau_1 + t' + \frac{2D}{\eta} - t_0\\
        &\le \tau_1+ \frac{2D}{\eta} + \frac{D}{\eta}2^{20c^2\log\left(D+1\right)(25D^8)^{2\tau_1}+\log(D)} - t_0 &\tag{8}\label{line-1-t-1}\\
        &\le 3\frac{D^2}{\eta}t_0\tau_{dec} + \frac{2D}{\eta}+  \frac{D}{\eta}2^{20c^2\log\left(D+1\right)(25D^8)^{8\frac{D^2}{\eta}t_0\tau_{dec}}+\log(D)} &\tag{9}\label{line-2-t-1}\\
        &\le 2^{\frac{D}{\eta}^{\left(\log\left(1+\frac{\eta}{2D(D+1)}\right)\right)^{-1}\cdot M \cdot \left(25^2\frac{D^{28}}{\eta^4}\right)^{t_0}}} 
    \end{align*}
    where $M = 164430 c^2$ and Line~\ref{line-1-t-1} follows from the expansion of $t'$ and Line~\ref{line-2-t-1} follows from the bound on $\tau_1$ and the final line finds a loose upper bound by combining and simplifying terms using the definition of $\tau_{dec}$.

 % \[\frac{D^2}{\eta} + D^2\cdot t_0 + \tau_{dec} + \frac{2D}{\eta} + \frac{D}{\eta}2^{d+1+5c d(9D^8)^{t_0 + \frac{D^2}{\eta} + D^2\cdot t_0 + \tau_{dec}}}\\+ (t_0 + \frac{D^2}{\eta} + D^2\cdot t_0 + \tau_{dec})2^{d+1+5c d(9D^8)^{t_0 + \frac{D^2}{\eta} + D^2\cdot t_0 + \tau_{dec}}}.\]


    % We can upper bound this term by 
    % \[ (\frac{6D^2}{\eta}t_0+ \tau_{dec})2^{(c+2 +(2+3d+2D)\cdot (\frac{3D^2}{\eta} t_0 + \tau_{dec}))}.\]
    % % We can further upper bound by 
    % \[2^{c+2+(3+3d+2D)(\frac{6D^2}{\eta}t_0+\tau_{dec})}.\]
    % Using the definition of $\tau_{dec}$, this term can be upper bounded by 
    % \[2^{c+2+(3+3d+2D)(\frac{6D^2}{\eta}t_0+\frac{c + 4+2m\cdot d  + (3+3d+2D)(\frac{4D^3}{\eta}t_0)}{\log(1+\frac{\eta}{2D(D+1)})})}.\]
    % % This is upper bounded by 
    % \[2^{\frac{1}{\log(1+\frac{\eta}{2D(D+1)})}\cdot \left(2c + 6 +2m\cdot d + (3+3d+2D)\frac{10D^3}{\eta}t_0\right)}.\]
    % \[8^{D^{\log\left(1+\frac{\eta}{2D(D+1)}\right)^{-1}\cdot D^{M\frac{D^{16}}{\eta}t_0}}}\]
    % where \[M= 3483c\cdot m\cdot d.\]

    % then the bound on the maximum number of time steps is
    % \[2^{\frac{1}{\log(1+\frac{\eta}{2D(D+1)})}\cdot \left(M\frac{20D^4}{\eta}\right)t_0}.\]

    Finally, since there are $D-1$ values of $w_{\max}$ that can decrease, i.e., $w_{\max} = \frac{k}{D}$ for $k \in \{2,\ldots,D\}$ and the derived bound on time to decrease does not depend on the value of $k$, then the maximum number of time steps to be guaranteed that $w_{\max}$ will no longer decrease in value is
    % \[8^{(9D^8)^{\frac{1}{\log(1+\frac{\eta}{2D(D+1)})}\cdot\left(9\frac{D^8}{\eta}\right)^{M\frac{D^2}{\eta}t_0}}} \uparrow \uparrow (D-1)\]
    % \[t_1=\left(8^{D^{\log\left(1+\frac{\eta}{2D(D+1)}\right)^{-1}\cdot D^{M\frac{D^{16}}{\eta}}}}\right) \uparrow \uparrow (D-1)\]
    \[t_1 = \left(2^{\frac{D}{\eta}^{\left(\log\left(1+\frac{\eta}{2D(D+1)}\right)\right)^{-1}\cdot M \cdot \left(25^2\frac{D^{28}}{\eta^4}\right)}}\right) \uparrow \uparrow (D-1)\]
    time steps. Note that $\uparrow \uparrow$ is the Knuth up arrow notation to denote $D-1$ tetrations~\citep{knuth1976mathematics}.

    % Step 2 -- maximum time to converge to eps-NE or exact NE
    \textbf{Bounding $t_2$.}\\
    From the previous section, we know $x_{w,w_{\max}^{(t_1)}}^{(\tau)} \ge \frac{1}{D-k+1}$ for all $\tau \ge t_1$. First, as in the first step of the $t_1$ bound, for all $a \neq w_{\max}^{(t_1)}$ and $a \neq w_{\max}^{(t_1)}- \frac{1}{D}$, then for all $\tau \ge t_1 + \frac{D^2}{\eta} + D^2 t_1$ \[x_{f,a}^{(\tau)} =0.\tag{10}\label{0-out-a}\]
    Then, if $k \ge 2$, we can apply Lemma~\ref{lem:bounding_recurrence_relation_time} to conclude that for any $\epsilon>0$, it will take at most 
    \[\tau_{eq} = \max\{\tau_{conv}, \tau_{\epsilon}\}\]
    % \[\tau_{conv} = \frac{\log (\frac{3D^2}{\eta})+20c d(9D^8)^{t_1 + \frac{D^2}{\eta} + D^2 t_1} + 4d + 3md + 5}{\log(1+\frac{\eta}{2D(D+1)})} +2\]
    time steps for $x_{f,w_{\max}^{(t_1)}}^{(\tau)} \ge 1-\epsilon$ for all $\tau \ge t_1 + \frac{D^2}{\eta} + D^2 t_1 + \tau_{eq}$.\\


    Otherwise, if $k=1$, then we are guaranteed the algorithm will eventually converge to an exact ($\epsilon=0$) NE. First, note that for all $t >0$ and all $a > \frac{1}{D}$, \[U_{w,0}^{(t)} = U_{w,\frac{1}{D}}^{(t)} \ge U_{w,a}^{(t)}.\]
    So, by Claims~\ref{claim:stationarity_reqs} and~\ref{claim:kkt_ordering}, for all $t>0$ and all $a > \frac{1}{D}$, \[x_{w,0}^{(t)} = x_{w,\frac{1}{D}}^{(t)} \ge x_{w,a}^{(t)}.\]
    Therefore, when $w_{\max}^{(t_1)} = \frac{1}{D}$, then we are guaranteed for all $\tau \ge t_1$
    \[x_{w,0}^{(\tau)} = x_{w,\frac{1}{D}}^{(\tau)} = \frac{1}{2}.\]
    This implies, for all $\tau \ge t_1$, \[u_f(\frac{1}{D},x_w^{(\tau)}) - u_f(0,x_w^{(\tau)}) = \frac{D-1}{D} - \frac{1}{2} = \frac{D-2}{2D}  >\frac{1}{2D}\tag{11}\label{1/d-better-bound}\]
    where the last inequality follows from $D>2$.
    Let $t' = t_1 + \frac{D^2}{\eta} + D^2 t_1$ and note by~\ref{0-out-a}, $f_{\min}^{(\tau)},f_{\max}^{(\tau)} \in\{0,\frac{1}{D}\}$ for all $\tau \ge t'$, so we next bound the time $t'' \ge t'$ where we are guaranteed $f_{\min}^{(\tau)} = f_{\max}^{(\tau)} = \frac{1}{D} = w_{\max}^{(t_1)}$ for all $\tau \ge t''$. Note that, \[U_{f,\frac{1}{D}}^{(t')} - U_{f,0}^{(t')} \ge -t'.\]
    Then, for $t'' = t' + \frac{2D}{\eta} + 2Dt'$ and for all $\tau \ge t''$, by bound~\ref{1/d-better-bound},
    \[U_{f,\frac{1}{D}}^{(\tau)} - U_{f,0}^{(\tau)} \ge \frac{1}{\eta}.\]
     Thus, by Claims~\ref{claim:stationarity_reqs} and~\ref{claim:kkt_ordering} and the probability constraint, we can conclude $f_{\min }^{(\tau)} = f_{\max}^{(\tau)} = w_{\max}^{(t_1)}$ for all $\tau \ge t''$ which immediately implies $x_{f,w_{\max}^{(t_1)}}^{(\tau)} =1$ for all $\tau \ge t''$.

    Therefore, the maximum time to convergence to an $\epsilon$-NE if $k\ge 2$ or exact NE if $k=1$ after time $t_1$ is \[t_2 = \frac{D^2}{\eta} + D^2 t_1 + \max\{ \tau_{eq}, \frac{2D}{\eta} + 2Dt_1 + \frac{2D^3}{\eta} + 2D^3t_1\}.\]
    \textbf{Final bound on time to convergence.}\\
    Using the definition of $\tau_{conv}$ and $\tau_{\epsilon}$ and the constant $M$ defined above, then the maximum time to convergence to $\epsilon$-NE can be bounded by \[t_1+ \max\left\{2^{\frac{D}{\eta}^{\left(\log\left(1+\frac{\eta}{2D(D+1)}\right)\right)^{-1}\cdot M \cdot \left(25^2\frac{D^{28}}{\eta^4}\right)^{t_1}}}, 2\log\left(\frac{3D^3}{\epsilon}\right)\cdot \frac{4D^2}{\eta}\right\}\]
    Since $\max\{x,y\} \le x+y$ for $x,y>0$, then the overall time to convergence is bounded by \[\left[\left(2^{\frac{D}{\eta}^{\left(\log\left(1+\frac{\eta}{2D(D+1)}\right)\right)^{-1}\cdot M \cdot \left(25^2\frac{D^{28}}{\eta^4}\right)}}\right)\uparrow \uparrow D\right] +2\log\left(\frac{3D^3}{\epsilon}\right)\cdot \frac{4D^2}{\eta}.\]
    Since $\log(1+x)^{-1} \le \frac{x+1}{x}$ for $x >0$, then \[\log\left(1+\frac{\eta}{2D(D+1)}\right)^{-1} \le \frac{4D^3}{\eta}.\]
    Thus, the bound can be simplified as 
    \[O\left(\left[\left(2^{\frac{D}{\eta}^{{\frac{D^{31}}{\eta^5}}}}\right)\uparrow \uparrow D\right] +\log\left(\frac{D^3}{\epsilon}\right)\cdot \frac{D^2}{\eta}\right).\]




\end{proof}

