\title{\bf Simple polynomial equations over $(m \times m)$-matrices}


\author{Vitalij A.~Chatyrko and Alexandre Karassev}

%\date{August 14, 2009}

\begin{abstract}
Let $m$ be any integer $\geq 3$. We consider the polynomial equation
$$X^n + a_{n-1}\cdot X^{n-1} + \dots + a_1 \cdot X + a_0 \cdot I = O,$$
over $(m \times m)$-matrices $X$ with the real entries, where $I$ is the identity matrix, $O$ is the null matrix, $a_i \in \mathbb R$
for each $i$ and $n \geq 1$. We discuss its solution set $S$ supplied with the natural Euclidean topology.
In particular, we describe the solution set $S$ for $m=3$ and calculate its dimension.

\end{abstract}


\keywords{polynomial equation over matrices; matrix algebra; covering dimension.}

\subjclass[2020]{Primary: 15A24, 54F45, Secondary: 15B30}

