\section{Preliminaries I}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%


For a given  $B\in M_m(\mathbb R)$, define
a map
$$Conj_B\colon GL_m (\mathbb R) \to M_m(\mathbb R)$$
by $Conj_B(X) = X^{-1} B X$.

The following is easy to verify.

\begin{lem}\label{fibres} The map $Conj_B$ is continuous, and the image $Conj_B(GL_m (\mathbb R))$ is $\sigma$-compact.
\end{lem}

For a given closed subgroup $G$ of $GL_m (\mathbb R)$ denote by $GL_m (\mathbb R)/G$ the quotient space of
the right cosets of $G$ in $GL_m (\mathbb R)$, and by $\pi: GL_m (\mathbb R) \to GL_m (\mathbb R)/G$
the canonical mapping.

Since the topological group $GL_m (\mathbb R)$ is locally compact, by the use of a well known fact (see, for example, \cite[Theorem 2]{P}) we have the following
equality:
$$\dim GL_m (\mathbb R) = \dim G + \dim GL_m (\mathbb R)/G.$$
Let $G_B = \{A  \in GL_m (\mathbb R): AB = BA\}$. It is easy to see that $G_B$ is closed subgroup of
$GL_m (\mathbb R)$.

The following is evident.

\begin{prop}
\begin{itemize}
\item[(i)] Let $X, Y \in GL_m (\mathbb R)$. If $Conj_B(X) = Conj_B(Y)$ then $Y = A X$ for some $A \in G_B$.
\item[(ii)] For any $X \in GL_m (\mathbb R)$ and $A \in G_B$ we have  $Conj_B(X) = Conj_B(AX)$.
\item[(iii)] There exist a continuous bijection $\alpha_B: GL_m (\mathbb R)/G_B \to Conj_B(GL_m (\mathbb R))$
such that $Conj = \alpha_B  \pi$.
\end{itemize}
\end{prop}

Since  the space $GL_m (\mathbb R)/G_B$ is  $\sigma$-compact and normal (see \cite[Theorem 1]{P}), we get

\begin{cor}\label{dimension} $\dim Conj_B(GL_m (\mathbb R)) = dim GL_m (\mathbb R)/G_B = \dim GL_m (\mathbb R)- \dim G_B.$
\end{cor}

Recall that $(m\times m)$-matrices $B_1$ and $B_2$ with entries from a field $\mathbb F$ are {\it similar} over $\mathbb F$ if there exists an  invertible $(m\times m)$-matrix  $C$ with entries from $\mathbb F$ such that $B_1 = C^{-1}B_2C$, and the similarity is an equivalence relation.

The following is evident.
\begin{prop} For any matrices $B_1$ and $B_2$ from $M_m (\mathbb R)$
we have the sets $Conj_{B_1}(GL_m (\mathbb R))$ and $Conj_{B_2}(GL_m (\mathbb R))$ coincide
or they are disjoint.

In particular, for any $B\in M_m(\mathbb R)$ we have $Conj_{B}(GL_m (\mathbb R)) = Conj_{J}(GL_m (\mathbb R))$, where $J$ is a real Jordan canonical form of $B$.
\end{prop}

  %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

\section{Preliminaries II}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

For distinct real numbers $a, b, c$ and  real numbers $p, q$, where $q \ne 0$, let 

$$J(a,b,c) = \left(\begin{array}{rrr}  a & 0 & 0 \\ 0 & b & 0  \\ 0 & 0 & c \end{array}\right),\,
J(a,a,b) = \left(\begin{array}{rrr}  a & 0 & 0 \\ 0 & a & 0  \\ 0 & 0 & b \end{array}\right),$$
$$J_1(a,a,b) = \left(\begin{array}{rrr}  a & 1 & 0 \\ 0 & a & 0  \\ 0 & 0 & b \end{array}\right),\,
J(a,a,a) = \left(\begin{array}{rrr}  a & 0 & 0 \\ 0 & a & 0  \\ 0 & 0 & a \end{array}\right),$$
$$J_1(a,a,a) = \left(\begin{array}{rrr}  a & 1 & 0 \\ 0 & a & 0  \\ 0 & 0 & a \end{array}\right),\,
J_2(a,a,a) = \left(\begin{array}{rrr}  a & 1 & 0 \\ 0 & a & 1  \\ 0 & 0 & a \end{array}\right),$$
$$J_c(a,p,q) = \left(\begin{array}{rrr}  a & 0 & 0 \\ 0 & p & q  \\ 0 & -q & p \end{array}\right),\,
U(a, p, q) = \left(\begin{array}{rrr}  a & 0 & 0 \\ 0 & p+iq & 0  \\ 0 & 0 & p-iq \end{array}\right).$$

The following is easy to verify
\begin{prop}\label{prop_commute}
\begin{itemize}
\item[(i)] $G_{J(a,b,c)} = \{A = \left(\begin{array}{rrr}  x & 0 & 0 \\ 0 & y & 0  \\ 0 & 0 & z \end{array}\right) : \det A \ne 0\}$,
\\
in particular, $\dim G_{J(a,b,c)} = 3.$
\\
\item[(ii)] $G_{J(a,a,b)} = \{A = \left(\begin{array}{rrr}  x & y & 0 \\ z & t & 0  \\ 0 & 0 & s \end{array}\right) : \det A  \ne 0\}$,
\\
in particular, $\dim G_{J(a,a,b)} = 5.$
\\
\item[(iii)] $G_{J_1(a,a,b)} = \{A = \left(\begin{array}{rrr}  x & y & 0 \\ 0 & x & 0  \\ 0 & 0 & z \end{array}\right) : \det A \ne 0\}$,
\\
in particular, $\dim G_{J_1(a,a,b)} = 3.$
\\
\item[(iv)] $G_{J(a,a,a)} =GL_3(\mathbb R)$,
%$ \{A = \left(\begin{array}{rrr}  x_{11} & x_{12}  & x_{13} \\ x_{21} & x_{22}
%& x_{23}  \\ x_{31} & x_{32} & x_{33} \end{array}\right) : \det A \ne %0\}$,
in particular, $\dim G_{J(a,a,a)} = 9.$
\\
\item[(v)] $G_{J_1(a,a,a)} = \{A=\left(\begin{array}{rrr}  x & y & z \\ 0 & x & 0  \\ 0 & s & t \end{array}\right) : \det A \ne 0\}$,
\\
in particular, $\dim G_{J_1(a,a,a)} = 5.$
\\
\item[(vi)] $G_{J_2(a,a,a)} = \{A =\left(\begin{array}{rrr}  x & y & z \\ 0 & x & y  \\ 0 & 0 & x \end{array}\right) : \det A \ne 0\}$,
\\
in particular, $\dim G_{J_2(a,a,a)} = 3.$
\\
\item[(vii)] $G_{J_c(a,p,q)} = \{A=\left(\begin{array}{rrr}  x & 0 & 0 \\ 0 & y & z  \\ 0 & -z & y \end{array}\right) : \det A \ne 0\}$,
\\
in particular, $\dim G_{J_c(a,p,q)} = 3.$
\end{itemize}
\end{prop}



%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\section{The structure and the dimension of $S$, the case $m=3$.}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

The following propositions are standard facts from matrix algebra (see, for example, \cite{L}).

\begin{prop} \label{auxprop_1} For any matrix $B \in M_3(\mathbb R)$ there exists
 a matrix $C\in GL_3(\mathbb R)$ such that $B = C^{-1} J C$, where $J$ is precisely  one of
 the following matrices:

$J(a,b,c),
J(a,a,b),
J_1(a,a,b),
J(a,a,a),
J_1(a,a,a),
J_2(a,a,a),
J_c(a,p,q).$

\end{prop}



\begin{prop}\label{auxprop_3} Any $B\in M_3(\mathbb R)$ is similar to $J_c(a,p,q)$ over $\mathbb R$ iff $B$  is similar to $U(a,p,q)$ over $\mathbb C$.
\end{prop}

Let  $f_s(x) = x^n + a_{n-1}x^{n-1} + \dots + a_1 x + a_0$ be a polynomial with real coefficients $a_i, 0 \leq i \leq n-1,$ corresponding to the polynomial  $F_s(X)$.

Consider the equation $$f_s(x) = 0 .\eqno{(3)}$$

The following lemmas are evident.
\begin{lem} \label{lem_1}
\phantom{*}

$$F_s(J(a,b,c)) = \left(\begin{array}{rrr}  f_s(a) & 0 & 0 \\ 0 & f_s(b) & 0  \\ 0 & 0 & f_s(c) \end{array}\right);\,
F_s(J(a,a,b)) = \left(\begin{array}{rrr}  f_s(a) & 0 & 0 \\ 0 & f_s(a) & 0  \\ 0 & 0 & f_s(b) \end{array}\right);$$

$$F_s(J_1(a,a,b)) = \left(\begin{array}{rrr}  f_s(a) & f'_s(a) & 0 \\ 0 & f_s(a) & 0  \\ 0 & 0 & f_s(b) \end{array}\right);\, F_s(J(a,a,a)) = \left(\begin{array}{rrr}  f_s(a) & 0 & 0 \\ 0 & f_s(a) & 0  \\ 0 & 0 & f_s(a) \end{array}\right);$$

$$F_s(J_1(a,a,a)) = \left(\begin{array}{rrr}  f_s(a) & f'_s(a) & 0 \\ 0 & f_s(a) & 0  \\ 0 & 0 & f_s(a) \end{array}\right);\,
F_s(J_2(a,a,a)) = \left(\begin{array}{rrr}  f_s(a) & f'_s(a) & \frac{1}{2}f''_s(a) \\ 0 & f_s(a) & f'_s(a)  \\ 0 & 0 & f_s(a) \end{array}\right);$$

$$F_s(U(a,p,q)) = \left(\begin{array}{rrr}  f_s(a) & 0 & 0 \\ 0 & f_s(p+iq) & 0  \\ 0 & 0 & f_s(p-iq) \end{array}\right).$$


In particular,

$a, b, c$ are distinct real roots of $(3)$ iff $J(a,b,c)$ is a solution of $(2)$;

$a, b$ are distinct real roots of $(3)$  iff $J(a,a,b)$ is a solution of $(2)$;

$a, b$ are distinct real roots of $(3)$ and $a$ is a root of multiplicity $\geq 2$ iff
$J_1(a,a,b)$ is a solution of $(2)$;

$a$ is a real root of $(3)$ iff $J(a,a,a)$ is a solution of $(2)$;

$a$ is a real root of $(3)$ of multiplicity $\geq 2$ iff $J_1(a,a,a)$ is a solution of $(2)$;

$a$ is a real root of $(3)$ of multiplicity $\geq 3$ iff $J_2(a,a,a)$ is a solution of $(2)$;

$a$ is a real root of $(3)$ and $p \pm iq$ are non-real roots of $(3)$ iff
$F_s(U(a,p,q)) = O$.
\end{lem}



\begin{lem} \label{lem_2} If $(m\times m)$-matrices $A$ and $B$ (with real or complex entries) are similar over $\mathbb R$ or $\mathbb C$, and $F_s(A) = O,$ then $F_s(B) = O.$

In particular, $J_c(a,p,q)$ is a solution of $(2)$ iff $a$ is a real root of $(3)$ and $p\pm iq$ are non-real roots of $(3)$.
\end{lem}

Let $S(B) =Conj_{B}(GL_3(\mathbb R))$ for any $B \in M_3(\mathbb R)$.


Using Propositions \ref{auxprop_1}, \ref{auxprop_3}, and Lemmas \ref{lem_1}, \ref{lem_2} we get the following.

\begin{thm} \label{character_theorem}The solution set $S$ of the equation $(2)$ is either empty or a disjoint union of the following sets:

$S(J(a,b,c))$, whenever $a,b,c$ are distinct real roots of  $(3)$,

$S(J(a,a,b))$, whenever $a,b$ are distinct real roots of  $(3)$,

$S(J_1(a,a,b))$, whenever $a, b$ are distinct real roots of  $(3)$ and
$a$ is a root of multiplicity $\geq 2$,

$S(J(a,a,a))$, whenever $a$ is a real root of  $(3)$,

$S(J_1(a,a,a))$, whenever $a$ is a real root of $(3)$ of multiplicity $\geq 2$,

$S(J_2(a,a,a))$, whenever $a$ is a real root of $(3)$ of multiplicity $\geq 3$,

$S(J_c(a,p,q))$, $q > 0$, whenever $a$ is a real root of $(3)$ and
$p \pm iq$ are non-real roots of $(3)$.
  \end{thm}



Using Proposition \ref{prop_commute} and Corollary \ref{dimension} we get the following corollary.
\begin{cor}
\begin{itemize}
\item[(i)] $\dim S(J(a,b,c)) = \dim S(J_1(a,a,b)) =$

$\dim S(J_2(a,a,a)) = \dim S(J_c(a,p,q)) = 6.$

\item[(ii)] $\dim S(J(a,a,b)) = \dim S(J_1(a,a,a)) = 4$ .

\item[(iii)]  $\dim S(J(a,a,a))= 0$,
moreover,

$S(J(a,a,a)) = \{\left(\begin{array}{rrr}  a & 0 & 0 \\ 0 & a & 0  \\ 0 & 0 & a \end{array}\right)\}$.
\end{itemize}
\end{cor}

 \begin{cor}\label{cor_sigma_compact} The solution set $S$ of the equation $(2)$, $m=3$, is
 $\sigma$-compact, and $\dim S$ is equal to $-1$ or it is the maximum of dimensions of sets $S(J)$ from Theorem \ref{character_theorem}, i.e. $0, 4$ or $6$.
  \end{cor}







