\section{Some examples of solution sets, the case $m=3$.}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

Here we will describe the solution sets of some equations. All facts here follow from the results of Section~4.

\begin{example} The solution set $S_1$ of $X^2+ I =O$ is  empty, and so
$\dim S_1 = -1.$

\end{example}

\begin{example}
\begin{itemize}
\item [(i)] The solution set $S_2$ of $X =O$ is equal to $S(J(0,0,0)) = \{O\}$, and so $\dim S_2 = 0.$
\item [(ii)] The solution set $S_3$ of $X - I=O$ is equal to $S(J(1,1,1)) = \{I\}$, and so $\dim S_3 = 0.$
\end{itemize}
\end{example}

\begin{example} The solution set $S_4$ of $X^2 =O$ is equal to $S(J(0,0,0)) \cup S(J_1(0,0,0))$, and
so $\dim S_4 = 4.$
\end{example}

\begin{example} The solution set $S_5$ of $X^2(X-I) =O$ is equal to $S(J(0,0,0)) \cup S(J_1(0,0,0)) \cup
S(J(1,1,1)) \cup S(J(0,0,1)) \cup S(J(1,1,0)) \cup S(J_1(0,0,1))$,
and
so $\dim S_5 = 6.$

Moreover, $S_5 \setminus (S_3 \cup S_4) = S(J(0,0,1)) \cup S(J(1,1,0)) \cup S(J_1(0,0,1))$,

 and so
$\dim S_5 \setminus (S_3 \cup S_4) = 6 > 4 = \dim (S_3 \cup S_4).$
\end{example}

\begin{example} The solution set $S_6$ of $X^2 - I=O$ is equal to
$S(J(1,1,1)) \cup S(J(-1,-1,-1)) \cup S(J(1,1,-1)) \cup S(J(-1,-1,1))$, and so $\dim S_6 = 4.$
\end{example}

\begin{example} The solution set $S_7$ of $X(X^2-I) =O$ is equal to $S(J(0,0,0)) \cup
S(J(1,1,1)) \cup  S(J(-1,-1,-1)) \cup S(J(0,0,1)) \cup S(J(1,1,0)) \cup S(J(0,0,-1)) \cup S(J(-1,-1,0))
\cup S(J(1,1,-1)) \cup S(J(-1,-1,1)) \cup S(J(-1,0,1))$, and
so $\dim S_7 = 6.$

Moreover, $S_7 \setminus (S_2 \cup S_6) = S(J(0,0,1)) \cup S(J(1,1,0)) \cup S(J(-1,0,1)) \cup S(J(0,0,-1)) \cup S(J(-1,-1,0))$,

 and so
$\dim S_7 \setminus (S_2 \cup S_6) = 6 > 4 = \dim (S_2 \cup S_6).$
\end{example}

\begin{example} The solution set $S_8$ of $X(X^2+I) =O$ is equal to $S(J(0,0,0)) \cup
S(J_c(0,0,1)) $, and
so $\dim S_8 = 6.$

Moreover, $S_8 \setminus (S_1 \cup S_2) =S(J_c(0,0,1)) $,

 and so
$\dim S_8 \setminus (S_1 \cup S_2) = 6 > 0 = \dim (S_1 \cup S_2)$
\end{example}

\begin{example} The solution set $S_9$ of $X^3 =O$ is equal to $S(J(0,0,0)) \cup S(J_1(0,0,0)) \cup
S(J_2(0,0,0))$, and
so $\dim S_9 = 6.$

Moreover, $S_9 \setminus (S_2 \cup S_4) =S(J_2(0,0,0)) $,

 and so
$\dim S_9 \setminus (S_2 \cup S_4) = 6 > 4 = \dim (S_2 \cup S_4).$
\end{example}




