\subsection{Single-axis Magnification}\label{subsec:SingleAxis}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\begin{figure}
\centerline{\scalebox{1}{\includegraphics[width=0.48\textwidth]{Figure7.pdf}}}
