\subsection{Interpolating operators and correlation functions for chimera baryons: spin and parity projection}
\label{sec:chimera_projections}



\begin{table}
    \centering
    \caption{Quantum numbers of the chimera baryons studied for this paper. For each chimera baryon, we list the matrix appearing in the interpolating operator, $\Gamma_1$, appearing in Eq.~(\ref{eq:baryon_ops}), the spin, $J$, and the irreducible representations of the unbroken global $Sp(4)$ and $SO(6)$ symmetries, acting on $({\rm f})$-type and $({\rm as})$-type fermions, respectively. 
    \label{tab:operators_baryons} \\    }
    \begin{tabular}{ |c|c|c|c|c| }
        \hline\hline
        $~~~$baryon$~~~$ & $~~~\Gamma_1~~~$ & $~~~J~~~$ & $~~~Sp(4)~~~$ & $~~~SO(6)~~~$ \\
        \hline
        $\Lambda_{\rm CB}$     & $\gamma_5$ & $1/2$ & $5$  & $6$   \\
        $\Sigma_{\rm CB}$      & $\gamma_i$ & $1/2$ & $10$ & $6$  \\
        $\Sigma_{\rm CB}^\ast$ & $\gamma_i$ & $3/2$ & $10$ & $6$ \\ 
        \hline  \hline
    \end{tabular}
\end{table}

Following the notations and conventions of Ref.~\cite{Bennett:2022yfa},  we write the  chimera baryon operators in the general form:
\begin{align} \label{eq:baryon_ops}
    \mathcal O_{\rm CB, \alpha}^{\Gamma_1 \Gamma_2}(x) = \left( Q_1^{a,\beta_1}(x) \left(  \mathcal{C} \, \Gamma_1\right)_{\beta_1 \beta_2} Q_2^{b,\beta_2}(x) \right) \Omega^{ad} \Omega^{bc} \Gamma_{2, \alpha \beta_3} \Psi^{cd,\beta_3}(x)\,,
\end{align}
where $\Omega$ is the symplectic matrix and $\mathcal{C}$ is the charge-conjugation matrix. Latin letters are used for color indices, and Greek letters for spinor indices. While $\Gamma_{1,2}$ could, in principle, denote any product of gamma matrices, in this paper
we set $\Gamma_2 = \mathbbm{1}$, while  $\Gamma_1 = \gamma_5$ or $\Gamma_1 = \gamma_i$. Hence, throughout this paper,  we denote the baryon operators as $\mathcal O_{\rm CB, \alpha}^{ \Gamma}$, with $\Gamma=\Gamma_1$---we occasionally omit an index, to indicate that the relations we write apply to all operators that differ only by that index.


We expect the chimera baryon states to have definite parity; hence we project the correlator,
$C_{\rm {CB}, \alpha \beta}(t) \equiv \langle \mathcal{O}_{\rm CB, \alpha} (t) \mathcal{O}_{\rm CB, \beta} (0)  \rangle$,  defined in analogy with Eq.~(\ref{eq:two-point-correlator}),
 to its parity-even and parity-odd components using the projectors $P_\pm = (1 \pm \gamma_0)/2$:
\begin{equation}
\label{eq:parity_projection}
    C_{\rm CB, \alpha \beta}^\pm(t) \equiv P_{\pm , \alpha \alpha_1} C_{\rm CB , \alpha_1 \beta}(t)\,.
\end{equation}
At large Euclidean times, on a lattice with anti-periodic boundary conditions for the fermions in the time direction, the projected correlation functions for chimera baryons behave  as
\begin{align}\label{eq:large_t_baryon}
    C_{\rm CB}^\pm(t) \approx (A_\pm e^{-m^\pm t} - A_\mp e^{-m^\mp(T-t)}) P_{\pm}\,,
\end{align}
where we understand spinorial indices, $A_\pm$ are  proportional to the vacuum-to-hadron matrix elements, for the parity-even and parity-odd state, respectively, and $m_\pm$ are the ground state masses of even and odd states.




Since the baryon operators defined with $\Gamma_1 = \gamma_i$ source both spin-$1/2$ and spin-$3/2$ states, we decompose the correlation functions involving such baryon operators by projecting them onto components with definite spin. Starting from  the zero-momentum correlation function
\begin{align}
    C^{ij}_{\rm CB , \alpha \beta}(t) \equiv& \frac{1}{N_s^3}\sum_{\vec x} \langle  \mathcal{O}_{\rm CB , \alpha}^{\gamma_i}(t,\vec x) \bar{\mathcal{O}}_{\rm CB ,  \beta}^{\gamma_j}(0,0) \rangle\,,
\end{align}
we project to states with a definite spin quantum number with the following definitions:
\begin{align}
    C_{\rm CB, \alpha \beta}^{(1/2)}(t) \equiv& P_{ij}^{(1/2)} C^{ij}_{\rm CB, \alpha \beta}(t) = \frac{1}{3} \gamma_i \gamma_j C^{ij}_{\rm CB , \alpha \beta}(t)\,, \\ 
    C_{\rm CB , \alpha \beta}^{(3/2)}(t) \equiv& P_{ij}^{(3/2)} C^{ij}_{\rm CB, \alpha \beta}(t) = \left(\delta_{ij} - \frac{1}{3} \gamma_i \gamma_j \right) C^{ij}_{\rm CB , \alpha \beta}(t)\,.
\end{align}
We report  the quantum numbers of the three operators of interest  in Tab.~\ref{tab:operators_baryons}. By analogy with hadrons in QCD, we denote the state sourced with $\Gamma_1=\gamma_5$ as $\Lambda_{\rm CB}$, the spin-$1/2$ projection of the state interpolated by $\Gamma_1=\gamma_i$ as $\Sigma_{\rm CB}$, and its spin-$3/2$ partner as $\Sigma_{\rm CB}^\ast$.



