\subsection*{Continuum renormalization (\(\overline{\text{MS}}\) scheme)}
We report here our  result for the perturbative calculation performed in the continuum theory. We adopt dimensional regularization, and  the $\overline{\text{MS}}$ renormalization scheme.\footnote{The finite parts of the one-loop integrals for the local operator are scheme dependent. Here, we chose the dimensional regularization with $\overline{\text{MS}}$ scheme. Other choices are possible. One is the Breitenlohner–Maison–'t Hooft–Veltman (BMHV)~\cite{Breitenlohner:1975hg,Breitenlohner:1977hr,tHooft:1972tcz} renormalization scheme, which prescribes a non-standard definition of $\gamma_5$ while operating in generic $d$ dimensions.} 
Assuming the external momenta of the two $({\rm f})$-type fermions to approach the null value $p_1, p_2 \to 0$, the sum of the Feynman integrals for the vertex functions corresponding to the Feynman diagrams in Fig.~\ref{fig:combined_diagrams} is given by the following expressions, for $\Gamma_1 = \gamma_5$:
\begin{comment}
\begin{equation}
\begin{aligned}
\mathcal{I}[ \gamma_5 ] = \frac{g^2}{16\pi^2}   \gamma_5 \Bigg\{ &C^{\rm f} \left[ 6 + 4 \log\frac{\mu^2}{(p_1+p_2)^2} + \dfrac{2p_1 \cdot p_2}{p_1^2 - p_2^2} \Delta^{\text{IR}} (p_1, p_2) + 4 \delta_{\overline{\text{MS}}} \right] \\
+ &C^{\rm f} (2-N_c) \left[ 12 + 4 \log\frac{\mu^2}{p_1^2} + 4 \log\frac{\mu^2}{p_2^2} - 2 \Delta^{\text{IR}} (p_1, p_2)+8 \delta_{\overline{\text{MS}}}  \right] \Bigg\} \,,
\end{aligned}
\end{equation}
\end{comment}
\begin{equation}
\begin{aligned}
\mathcal{I}[ \gamma_5 ] = \frac{g^2}{16\pi^2}   \gamma_5 \Bigg\{ &C^{\rm f} \left[ 6 + 4 \log\frac{\mu^2}{\Lambda^2}  + 4 \delta_{\overline{\text{MS}}} \right] \\
+ &C^{\rm f} (2-N_c) \left[ 12 + 8 \log\frac{\mu^2}{\Lambda^2} + 8 \delta_{\overline{\text{MS}}}  \right] \Bigg\} \,,
\end{aligned}
\end{equation}

where
\begin{equation}
    \delta_{\overline{\text{MS}}} = \dfrac{1}{\epsilon} +\log 4\pi - \gamma_E \,.
\end{equation}
For the chimera baryon operator with  $\Gamma_1 = \gamma_i$, we find
\begin{comment}
\begin{equation}
\begin{aligned}
\mathcal{I}[ \gamma_i ] = \frac{g^2}{16\pi^2}   \gamma_i \Bigg\{ &C^{\rm f} \left[ -\frac{1}{2} - \log\frac{\mu^2}{(p_1+p_2)^2} + \dfrac{2p_1 \cdot p_2}{p_1^2 - p_2^2} \Delta^{\text{IR}} (p_1, p_2) - \delta_{\overline{\text{MS}}}\right] \\
+ &C^{\rm f}(2-N_c) \left[ 1 + \log\frac{\mu^2}{p_1^2} + \log\frac{\mu^2}{p_2^2} + \Delta^{\text{IR}} (p_1, p_2) + 2 \delta_{\overline{\text{MS}}} \right] \Bigg\} \, .
\end{aligned}
\end{equation}
\end{comment}
\begin{equation}
\begin{aligned}
\mathcal{I}[ \gamma_i ] = \frac{g^2}{16\pi^2}   \gamma_i \Bigg\{ &C^{\rm f} \left[ -\frac{1}{2} - \log\frac{\mu^2}{\Lambda^2}  - \delta_{\overline{\text{MS}}}\right] \\
+ &C^{\rm f}(2-N_c) \left[ 1 + 2\log\frac{\mu^2}{\Lambda^2} + 2 \delta_{\overline{\text{MS}}} \right] \Bigg\} \, .
\end{aligned}
\end{equation}

