\SetKwInOut{Input}{input}
\SetKwInOut{Output}{output}
\SetKw{KwMin}{minimise}
\SetKw{KwSubjTo}{subject to}
\Input{Estimated (diagonalisable) transfer matrix $E$; max branch number $m_{\text{max}}$}
\Output{Closest Lindbladian generator $L_{\text{est}}$ to all checked branches of logarithm}
\caption{Convex Solve Method}\label{alg:convexsolve}
Compute (some) set of eigenvalues $\{\mu_j\}_j$ and right $\{\Ket{r_j}\}_j$ and left  $\{\Bra{l_j}\}_j$ eigenvectors of $E$

\For{$ j = 1$ \KwTo $d^2$}{$\lambda_j \gets$ principal log of $\mu_j$}

\For { $m \in \{-m_{\text{max}},\ldots,0,\ldots, m_{\text{max}} \}^{d^2}$}{
