\noindent We conclude that, under the Palatini variation, the connection is metric-compatible \emph{if and only if} it is torsion-free.



\subsection{Noether's Variation Yields the Einstein Tensor}
\subsubsection{Review on Vielbein Formalism}

\noindent In the previous section, we derived the variation of the Lie algebra-valued gauge 1-form (gauge connection) $\mathbf{A}_\nu$ on a principal bundle in local coordinates as:
\begin{align} \label{eq:varaition_gauge}
\Delta A^a_{\nu} = \delta A^a_{\nu} + \underbrace{ A^a_{\nu,\gamma} \delta x^\gamma + A^a_{\gamma} \delta {x^\gamma}_{,\nu} }_{\hat{\mathcal{L}}_{\delta x} \mathbf{A}}
\end{align}

\noindent However, the situation is subtler when considering connections on the tangent bundle (see footnote 9 of \cite{yang1996symmetry}). Unlike gauge connections, which take values in internal symmetry groups, the affine connection $\Gamma^\alpha_{\mu\nu}$ takes values in the tangent space itself. Directly applying the Lie derivative to this tangent-space-valued object gives\cite{yano2020theory}:
\begin{align*}
\left(\hat{\mathcal{L}}_{\delta x} \Gamma\right)^\alpha_{\mu\nu} = {\delta x}^\varepsilon \Gamma^\alpha_{\mu\nu,\varepsilon} + \Gamma^\alpha_{\mu\varepsilon}{\delta x}^\varepsilon_{,\nu} + \underbracket[0.4pt][0pt]{{{\delta x}^\alpha_{,\mu\nu}} - \Gamma^\varepsilon_{\mu\nu}\delta x^\alpha_{,\varepsilon} + \Gamma^\alpha_{\varepsilon\nu}{\delta x}^\varepsilon_{,\mu}}_{\text{Due to tangent-space index structure}}
\end{align*}

\noindent To handle this properly, we adopt the vielbein formalism\cite{eguchi1980gravitation}. In this framework, the affine connection $\Gamma^\varepsilon_{\mu\nu}$ is replaced by the spin connection $\omega^a_{b\sigma}$, a $\mathfrak{gl}(4)$-valued 1-form on the frame bundle. The local basis $\{ \partial_\mu \}$ is replaced by orthonormal frames $\{ \hat{e}_a \}$ with the transformation:
\begin{align*}
\partial_\mu &= e^a_\mu \hat{e}_a \\
g_{\mu\nu} &= e^a_\mu e^b_\nu \eta_{ab} \\
e^\mu_a e^a_\nu &= \delta^\mu_\nu, \quad e^\mu_a e^b_\mu = \delta^b_a
\end{align*}

\noindent The spin connection $\omega^a_{b\sigma}$ is related to the affine connection by:
\begin{align*}
\omega^a_{b\sigma} = e^a_\varepsilon e^\kappa_b \Gamma^\varepsilon_{\kappa\sigma} + e^a_\mu \partial_\sigma e^\mu_b
\end{align*}

\noindent The curvature of the frame bundle, denoted $\mathscr{R}^a_{b\omega\sigma}$, is given by:
\begin{align*}
\mathscr{R}^a_{b\omega\sigma} = \omega^a_{b\sigma,\omega} - \omega^a_{b\omega,\sigma} + \omega^a_{c\omega} \omega^c_{b\sigma} - \omega^a_{c\sigma} \omega^c_{b\omega} = e^a_\varepsilon e^\kappa_b R^\varepsilon_{\kappa\omega\sigma}
\end{align*}

\noindent With these preparations, the Einstein-Hilbert action takes the form:
\begin{align} \label{eq:action_G}
S = \frac{1}{2\kappa} \int d^4x \sqrt{-g} \, g^{\kappa\sigma} \delta^\omega_\varepsilon R^\varepsilon_{\kappa\omega\sigma}
= \frac{1}{2\kappa} \int d^4x \, e \, \eta^{ae} e^\sigma_e e^\omega_c \mathscr{R}^c_{a\omega\sigma}
\end{align}
where \( e = \det(e^a_\mu) = \sqrt{-g} \) is the determinant of the vielbein.

\noindent The variation of this action follows a pattern analogous to Eq.~\eqref{eq:Action_g}:
\begin{align} \label{eq:Action_e}
\delta S &= \int \left( \frac{\partial \mathscr{L}_{GR}}{\partial e^a_\mu} \delta e^a_\mu 
+ \frac{\partial \mathscr{L}_{GR}}{\partial \omega^b_{c\nu}} \delta \omega^b_{c\nu} 
+ \frac{\partial \mathscr{L}_{GR}}{\partial (\omega^b_{c\nu,\gamma})} \delta \omega^b_{c\nu,\gamma} \right) d^4x \nonumber \\
&= \int \underbracket[0.4pt][0pt]{\frac{\partial \mathscr{L}_{GR}}{\partial e^a_\mu}}_{\text{EoM \#3}} \delta e^a_\mu \, d^4x 
+ \int \underbracket[0.4pt][0pt]{\left( \frac{\partial \mathscr{L}_{GR}}{\partial \omega^b_{c\nu}} - \left( \frac{\partial \mathscr{L}_{GR}}{\partial \omega^b_{c\nu,\gamma}} \right)_{,\gamma} \right)}_{\text{EoM \#4}} \delta \omega^b_{c\nu} \, d^4x 
+ \int \left[ \frac{\partial \mathscr{L}_{GR}}{\partial (\omega^b_{c\nu,\gamma})} \delta \omega^b_{c\nu} \right]_{,\gamma} d^4x
\end{align}

\noindent Since the metric is given by \( g_{\mu\nu} = \eta_{ab} e^a_\mu e^b_\nu \), its variation yields \( \delta g_{\mu\nu} = 2 \eta_{ab} e^a_\mu \delta e^b_\nu \). Therefore, the equation of motion from varying the vielbein (EoM~\#3) reproduces the Einstein field equation (EoM~\#1), while the equation of motion from varying the spin connection (EoM~\#4) corresponds to the condition for metric compatibility, analogous to EoM~\#2.

\subsubsection{Einstein Tensor Derived from Noether's Theorem}

\noindent We now apply Noether’s variation principle to the gravitational action:
\begin{align*} 
    \Delta S = \int \left[ \text{EoM terms} \right] d^4 x 
    + \int \left[ 
        \partial_\mu\left(
            \frac{\partial \mathscr{L}_{GR}}{\partial \omega^b_{c\nu,\mu}} \delta\omega^b_{c\nu}
        \right) 
        + (\mathscr{L}_{GR} \delta x^\gamma)_{,\gamma}
    \right] d^4 x 
\end{align*}

\noindent The spin connection \( \omega^b_{c\nu} \), being a $\mathfrak{gl}$-valued 1-form, transforms under infinitesimal diffeomorphisms according to the general Lie derivative rule, as in the gauge theory case [cf.~Eq.~\eqref{eq:varaition_gauge}]:
\begin{align} 
\Delta \omega^b_{c\nu} 
= \delta \omega^b_{c\nu} + 
\underbrace{
    \delta x^\varepsilon \partial_\varepsilon \omega^b_{c\nu} 
    + \omega^b_{c\varepsilon} \partial_\nu \delta x^\varepsilon
}_{\hat{\mathcal{L}}_{\delta x} \boldsymbol{\omega}} 
\end{align}

\noindent Consequently, the Noether current associated with spacetime translation is given by:
\begin{align*} 
\partial_\mu \mathcal{J}^\mu_{\delta x\text{-GR}} 
= \partial_\mu \left[ 
    -\frac{\partial \mathscr{L}_{GR}}{\partial \omega^b_{c\nu,\mu}} \omega^b_{c\nu,\gamma} \delta x^\gamma  
    - \underbracket[0.4pt][0pt]{\frac{\partial \mathscr{L}_{GR}}{\partial \omega^b_{c\nu,\mu}} \omega^b_{c\gamma} \delta {x^\gamma}_{,\nu}}_{(*)}
    + \delta^\mu_\gamma \mathscr{L}_{GR} \delta x^\gamma 
\right]
\end{align*}

\noindent We now compute the term marked by \((*)\):
\begin{align*}
\underbracket[0.4pt][0pt]{ \partial_\mu \left[ 
    \frac{\partial \mathscr{L}_{GR}}{\partial \omega^b_{c\nu,\mu}} \omega^b_{c\gamma} \delta {x^\gamma}_{,\nu}
\right]}_{(*)}
= 
\underbracket[0.4pt][0pt]{\left[
    \frac{\partial \mathscr{L}_{GR}}{\partial \omega^b_{c\nu,\mu}} \omega^b_{c\gamma} \delta x^\gamma 
\right]_{,\mu\nu}}_{(*1)}
- \partial_\mu \left[
    \underbracket[0.4pt][0pt]{\left(
        \frac{\partial \mathscr{L}_{GR}}{\partial \omega^b_{c\nu,\mu}}
    \right)_{,\nu} \omega^b_{c\gamma} \delta x^\gamma}_{(*2)}
\right]
- \partial_\mu \left[
    \underbracket[0.4pt][0pt]{\frac{\partial \mathscr{L}_{GR}}{\partial \omega^b_{c\nu,\mu}} \omega^b_{c\gamma,\nu} \delta x^\gamma}_{(*3)}
\right]
\end{align*}

\noindent The term \((*1)\) vanishes by analogy with Eq.~\eqref{eq:anti_ab} in the Abelian case and Eq.~\eqref{eq:1_YM} in the non-Abelian case:
\begin{align*}
\underbracket[0.4pt][0pt]{\left[
    \frac{\partial \mathscr{L}_{GR}}{\partial \omega^b_{c\nu,\mu}} \omega^b_{c\gamma} \delta x^\gamma 
\right]_{,\mu\nu}}_{(*1)}
= \left[
    \frac{1}{2\kappa} e\, \eta^{ce} 
    \left( e^\nu_e e^\mu_b - e^\mu_e e^\nu_b \right) 
    \omega^b_{c\gamma} \delta x^\gamma
\right]_{,\mu\nu} = 0
\end{align*}

\noindent Term \((*2)\) can be rewritten using EoM\#4:
\begin{align*}
\underbracket[0.4pt][0pt]{\left(
        \frac{\partial \mathscr{L}_{GR}}{\partial \omega^b_{c\nu,\mu}}
    \right)_{,\nu} \omega^b_{c\gamma} \delta x^\gamma}_{(*2)}
    = \left(
    -\frac{\partial \mathscr{L}_{GR}}{\partial \omega^b_{c\mu,\nu}}
\right)_{,\nu} \omega^b_{c\gamma} \delta x^\gamma 
\underbracket{=}_{EoM\#4}
-\frac{\partial \mathscr{L}_{GR}}{\partial \omega^b_{c\mu}} \omega^b_{c\gamma} \delta x^\gamma 
= -\frac{\partial \mathscr{L}_{GR}}{\partial \omega^b_{c\nu,\mu}} 
\left(
    \omega^b_{d\gamma} \omega^d_{c\nu}
    - \omega^b_{d\nu} \omega^d_{c\gamma}
\right) \delta x^\gamma
\end{align*}

\noindent Gathering all terms, we obtain:
\begin{align*} 
\partial_\mu \mathcal{J}^\mu_{\delta x\text{-GR}} 
&= \partial_\mu \left[
    -\frac{\partial \mathscr{L}_{GR}}{\partial \omega^b_{c\nu,\mu}} \omega^b_{c\nu,\gamma} \delta x^\gamma  
    + \underbracket[0.4pt][0pt]{\frac{\partial \mathscr{L}_{GR}}{\partial \omega^b_{c\nu,\mu}} \omega^b_{c\gamma,\nu} \delta x^\gamma}_{(*3)}
    - \underbracket[0.4pt][0pt]{\frac{\partial \mathscr{L}_{GR}}{\partial \omega^b_{c\nu,\mu}} 
    \left( 
        \omega^b_{d\gamma} \omega^d_{c\nu} 
        - \omega^b_{d\nu} \omega^d_{c\gamma}
    \right) \delta x^\gamma}_{(*2)}
    + \delta^\mu_\gamma \mathscr{L}_{GR} \delta x^\gamma
\right] \\
&= \partial_\mu \left[
    \left(
        -\frac{\partial \mathscr{L}_{GR}}{\partial \omega^b_{c\nu,\mu}} 
        \left(
            \omega^b_{c\nu,\gamma} 
            - \omega^b_{c\gamma,\nu} 
            + \omega^b_{d\gamma} \omega^d_{c\nu} 
            - \omega^b_{d\nu} \omega^d_{c\gamma}
        \right) 
        + \delta^\mu_\gamma \mathscr{L}_{GR}
    \right) \delta x^\gamma
\right] \\
&= \partial_\mu \left[
    \underbracket[0.4pt][0pt]{
        \left(
            -\frac{\partial \mathscr{L}_{GR}}{\partial \omega^b_{c\nu,\mu}} 
            \mathscr{R}^b_{c\gamma\nu} 
            + \delta^\mu_\gamma \mathscr{L}_{GR}
        \right)
    }_{(t_{GR})^\mu_\gamma}
    \delta x^\gamma
\right]
\end{align*}

\noindent Therefore, the canonical energy-momentum tensor density for gravity reads:
\begin{align} 
\left(t_{GR}\right)^\mu_\gamma 
&= -\frac{\partial \mathscr{L}_{GR}}{\partial \omega^b_{c\nu,\mu}} \mathscr{R}^b_{c\gamma\nu} 
+ \delta^\mu_\gamma \mathscr{L}_{GR} \nonumber \\
&=- \frac{1}{2\kappa} e\, \eta^{ce} \left( e^\mu_e e^\nu_b - e^\nu_e e^\mu_b \right) \mathscr{R}^b_{c\gamma\nu} 
+ \delta^\mu_\gamma \mathscr{L}_{GR} \nonumber
\end{align}

\noindent Using the identity between spin curvature and Riemann curvature, this is 
\begin{align} 
\left(t_{GR}\right)^\mu_\gamma 
&= \frac{1}{2\kappa} 
\left(
    -g^{\beta\nu} R^\mu_{\beta\gamma\nu} 
    -g^{\alpha\mu} R_{\alpha\gamma} 
    + \delta^\mu_\gamma R 
\right) \sqrt{-g} \label{eq:Noether_t}
\end{align}
Furthermore, the well-known symmetry of the Riemann curvature tensor can be used, since the metric-compatible connection must be torsion-free indicated by EoM\#2, 
\begin{align*}
g^{\beta\nu} R^\mu_{\beta\gamma\nu}
= g^{\beta\nu} g^{\alpha\mu} R_{\alpha\beta\gamma\nu}
= g^{\beta\nu} g^{\alpha\mu} R_{\beta\alpha\nu\gamma}
= g^{\alpha\mu} R^\nu_{\alpha\nu\gamma}
= g^{\alpha\mu} R_{\alpha\gamma}
\end{align*}

\noindent Substituting into Eq.~\eqref{eq:Noether_t} gives:
\begin{align} \label{eq:Einstein=t}
\left(t_{GR}\right)^\mu_\gamma 
= \frac{1}{\kappa} 
\underbracket[0.4pt][0pt]{
    \left( 
        -g^{\alpha\mu} R_{\alpha\gamma} 
        + \frac{1}{2} \delta^\mu_\gamma R 
    \right)
}_{-g^{\mu\alpha} \mathbb{G}_{\alpha\gamma}} 
\sqrt{-g}
\end{align}

\noindent Thus, the canonical energy-momentum tensor density derived from Noether's theorem coincides with the Einstein tensor multiplied by the volume element \(\sqrt{-g}\). It satisfies the following key properties:
\begin{itemize}
    \item[\textbf{1.}] It is symmetric in indices \((\mu, \gamma)\).
    \item[\textbf{2.}] It is manifestly covariant: constructed solely from tensorial quantities.
    \item[\textbf{3.}] It vanishes in vacuum: \( R_{\mu\nu} = 0 \Rightarrow (t_{GR})^\mu_\gamma = 0 \), irrespective of coordinate or connection choices.
\end{itemize}



\section{Equivalence of Einstein-Hilbert and Noether Canonical Energy-Momentum Tensors}
\label{sec:Equivalence EMT}

\noindent In the previous sections, we derived the canonical energy-momentum tensor (EMT) using Noether's theorem. The result was a symmetric, gauge-invariant expression. In this section, we demonstrate that the Hilbert EMT—defined via the variation of the action with respect to the metric—and the canonical EMT are naturally equivalent. 

\medskip

\noindent The Lie derivative of the metric tensor \( g^{\gamma\alpha} \) with respect to the infinitesimal coordinate variation \( \delta x^\mu \) is given by:
\begin{align*}
\left( \hat{\mathcal{L}}_{\delta x} g \right)^{\gamma\alpha}
= -g^{\mu\alpha} {\delta x^\gamma}_{;\mu} - g^{\gamma\mu} {\delta x^\alpha}_{;\mu}
\end{align*}

\noindent Consider the action with Lagrangian density \( \mathscr{L} = \mathscr{L}[g^{\gamma\mu}, A_\nu, A_{\nu,\mu}, x^\gamma] \). Its total variation reads:
\begin{align*}
\Delta S &=
\int \frac{\delta \mathscr{L}}{\delta g^{\gamma\alpha}}\, \delta g^{\gamma\alpha} \, d^4x 
+ \int \cancelto{0}{\left[\text{EoM of } \delta A_\nu \right]} \delta A_\nu \, d^4x 
+ \int \partial_\mu \left[  
    \frac{\partial \mathscr{L}}{\partial(\partial_\mu A_\nu)} \Delta A_\nu
    + \underbracket[0.4pt][0pt]{\left( 
        -\frac{\partial \mathscr{L}}{\partial(\partial_\mu A_\nu)} F_{\gamma\nu} 
        + \delta^\mu_\gamma \mathscr{L} 
    \right)}_{t^\mu_\gamma} \delta x^\gamma  
\right] d^4x
\end{align*}

\noindent To study symmetry under spacetime translations \( \delta x^\mu \), we set \( \delta g = -\hat{\mathcal{L}}_{\delta x} g \) and \( \delta A = -\hat{\mathcal{L}}_{\delta x} A \Rightarrow \Delta A = 0 \). The variation becomes:
\begin{align*}
\Delta S &=
\int -\frac{\delta \mathscr{L}}{\delta g^{\gamma\alpha}} \left( \hat{\mathcal{L}}_{\delta x} g \right)^{\gamma\alpha} \, d^4x 
+ \int \partial_\mu \left[ t^\mu_\gamma \delta x^\gamma \right] d^4x \\
&=
\int 2 \frac{\delta \mathscr{L}}{\delta g^{\gamma\alpha}} g^{\mu\alpha} {\delta x^\gamma}_{;\mu} \, d^4x
+ \int \partial_\mu \left( \sqrt{-g} \, T^\mu_\gamma \delta x^\gamma \right) d^4x \\
&=
\int 2 \frac{\delta \mathscr{L}}{\delta g^{\gamma\alpha}} g^{\mu\alpha} {\delta x^\gamma}_{;\mu} \, d^4x
+ \int \sqrt{-g} \, \nabla_\mu \left( T^\mu_\gamma \delta x^\gamma \right) d^4x \\
&=
\int 2 \frac{\delta \mathscr{L}}{\delta g^{\gamma\alpha}} g^{\mu\alpha} {\delta x^\gamma}_{;\mu} \, d^4x
+ \int \sqrt{-g} \left( \nabla_\mu T^\mu_\gamma \right) \delta x^\gamma \, d^4x
+ \int \sqrt{-g} \, T^\mu_\gamma {\delta x^\gamma}_{;\mu} \, d^4x
\end{align*}
. Here \(\nabla_\mu\) is the Levi-Civita covariant derivative.
\noindent The first and the third terms combine into:
\begin{align*}
\Delta S =
\int \left[
    2 \frac{\delta \mathscr{L}}{\delta g^{\gamma\alpha}} g^{\mu\alpha}
    + \sqrt{-g} \, T^\mu_\gamma
\right] {\delta x^\gamma}_{;\mu} \, d^4x
+ \int \sqrt{-g} \left( \nabla_\mu T^\mu_\gamma \right) \delta x^\gamma \, d^4x
\end{align*}

\noindent If the action is invariant under translations, then \( \Delta S = 0 \), then $\nabla_\mu T^\mu_\gamma=0$ is the conservation law of energy momentum in the curved spacetime. This leads to the first term must be 0:

\begin{align*}
\underbracket[0.4pt][0pt]{T^\mu_\gamma}_{\text{Canonical EMT}}
= g^{\mu\alpha} 
\underbracket[0.4pt][0pt]{\left( -\frac{2}{\sqrt{-g}} \frac{\delta \mathscr{L}}{\delta g^{\gamma\alpha}} \right)}_{\text{Hilbert EMT}}
\end{align*}

\noindent This identity shows that the canonical energy-momentum tensor derived via Noether’s theorem is equivalent to the Hilbert EMT defined via metric variation. This demonstrates their natural equivalence within a diffeomorphism-invariant Lagrangian field theory.



\section{Alternative Derivation of the Einstein Field Equations}
\label{sec:Einstein eq}

\noindent Since the canonical energy-momentum tensor (EMT) and the Hilbert EMT are equivalent, we may derive the Einstein field equations directly from Noether’s theorem, without resorting to metric variation. Consider the total action composed of gravitational and electromagnetic contributions:
\begin{align*} 
S = \int d^4x \left( \mathscr{L}_{GR} + \mathscr{L}_{EM} \right)
\end{align*}

\noindent The total variation under infinitesimal spacetime translation \( x^\gamma \rightarrow x^\gamma + \delta x^\gamma \) induces the following field transformations:
\begin{align*} 
A_\nu &\rightarrow A_\nu + \underbracket[0.4pt][0pt]{\delta A_\nu + \left(\hat{\mathcal{L}}_{\delta x} A\right)_\nu}_{\Delta A_\nu} \\
\omega^b_{c\nu} &\rightarrow \omega^b_{c\nu} + \underbracket[0.4pt][0pt]{\delta \omega^b_{c\nu} + \left(\hat{\mathcal{L}}_{\delta x} \omega\right)^b_{c\nu}}_{\Delta \omega^b_{c\nu}}
\end{align*}

\noindent Plugging these into the variation of the action yields:
\begin{adjustwidth}{-2.3cm}{-1cm}
\begin{align*} 
\Delta S = \int d^4x \Bigg\{ 
& \left[ 
    \frac{\partial \mathscr{L}_{GR}}{\partial \omega^b_{c\nu}} 
    - \left( \frac{\partial \mathscr{L}_{GR}}{\partial \omega^b_{c\nu,\mu}} \right)_{,\mu} 
\right] \delta \omega^b_{c\nu}
+ \left[ 
    \frac{\partial \mathscr{L}_{EM}}{\partial A_\nu} 
    - \left( \frac{\partial \mathscr{L}_{EM}}{\partial A_{\nu,\mu}} \right)_{,\mu} 
\right] \delta A_\nu \\
& + \partial_\mu \left[ 
    \frac{\partial \mathscr{L}_{GR}}{\partial \omega^b_{c\nu,\mu}} \Delta \omega^b_{c\nu} 
    + \frac{\partial \mathscr{L}_{EM}}{\partial A_{\nu,\mu}} \Delta A_\nu 
    + \left( (t_{GR})^\mu_\gamma + (t_{EM})^\mu_\gamma \right) \delta x^\gamma 
\right] 
\Bigg\}
\end{align*}
\end{adjustwidth}

\noindent The last surface term encodes spacetime symmetry under translations. Using the known identity for divergence in curved space, we write:
\begin{align*} 
\partial_\mu \left\{\left[ \left( t_{GR} \right)^\mu_\gamma + \left( t_{EM} \right)^\mu_\gamma \right] \delta x^\gamma \right\} = 0 
\quad \Rightarrow \quad 
\sqrt{-g}\,\nabla_\mu \left\{\left[ \left( T_{GR} \right)^\mu_\gamma + \left( T_{EM} \right)^\mu_\gamma \right] \delta x^\gamma \right\}  = 0
\end{align*}

\noindent If the translation is global, meaning \( \nabla_\mu \delta x^\gamma = 0 \), then the conservation law reduces to:
\begin{align*} 
\nabla_\mu \left[ \left( T_{GR} \right)^\mu_\gamma + \left( T_{EM} \right)^\mu_\gamma \right] = 0
\end{align*}

\noindent Therefore, the total energy-momentum tensor must be conserved. By the structure of conserved symmetric tensors in general relativity, we have:
\begin{align*} 
\left( T_{GR} \right)^\mu_\gamma + \left( T_{EM} \right)^\mu_\gamma = \delta^\mu_\gamma \Lambda
\end{align*}
where \( \Lambda \) is an integration constant, interpreted as the cosmological constant. Substituting the explicit form of the gravitational energy-momentum tensor from Eq.~\eqref{eq:Einstein=t}, we obtain:
\begin{align*} 
\mathbb{G}_{\alpha\gamma} + g_{\alpha\gamma} \Lambda = \kappa g_{\mu\alpha} \left( T_{EM} \right)^\mu_\gamma
\end{align*}

\noindent This is the Einstein field equation with cosmological constant, derived purely from Noether’s theorem applied to translation symmetry, without invoking the variation of the metric tensor.

\section{Summary}

\noindent
In this work, we systematically explored the derivation of the energy-momentum tensor (EMT) from Noether’s theorem within both gauge theory and general relativity. The analysis began by emphasizing that the gauge potential should be treated as a 1-form field rather than a vector field. This differential geometric perspective ensures that the total variation under spacetime translations correctly produces a symmetric, gauge-invariant canonical EMT—without requiring any artificial symmetrization. This construction remains valid on arbitrary curved manifolds.

We then extended this framework to the gravitational case using the vielbein formalism. In this approach, the spin connection plays the role of a gauge field valued in the local Lorentz group, and the Hilbert–Einstein action becomes analogous to a gauge-theoretic Lagrangian. Applying Noether’s theorem to local spacetime transformations, we derived a canonical energy-momentum tensor that matches, up to a factor of the volume form, the Einstein tensor. This derivation demonstrates that the tensor is not only symmetric and generally covariant, but also vanishes in vacuum, making it physically meaningful.

The equivalence between the canonical EMT derived via Noether’s theorem and the Hilbert EMT obtained through metric variation was then established explicitly. This result highlights that energy-momentum conservation in curved spacetime naturally arises from the variational principle associated with coordinate invariance.

Finally, we presented an alternative route to the Einstein field equations that avoids varying the metric altogether. By considering the total variation of the full action under spacetime translation symmetry and requiring the conservation of the total Noether current, we recovered the Einstein equation with a cosmological constant term.


In conclusion, this unified treatment demonstrates how Noether’s theorem serves as a principle for constructing and interpreting the dynamics of gauge fields and spacetime geometry on equal footing.


