\subsection*{A.1 Universal Embedding and Linear Approximation Theorem (UELAT)}

\begin{theorem}[Universal Embedding \& Linear Approximation, Sobolev Version]\label{thm:UELAT-Sobolev}
Let $\Omega\subset\mathbb{R}^n$ be a bounded Lipschitz domain, let $k\in\mathbb{N}$ and $1\le p<\infty$, and set 
\[
   F \;=\; W^{k,p}(\Omega).
\]
Let $(b_j)_{j\in\mathbb{N}}$ be a computable, explicit basis for $F$ (e.g.\ wavelets or B-splines).  Then for every \emph{computable} $f\in F$ and every $\varepsilon>0$ there exist
\begin{enumerate}[label=(\roman*),leftmargin=1.5em]
  \item a finite index set $J\subset\mathbb{N}$,
  \item computable coefficients $(a_j)_{j\in J}\subset\mathbb{Q}$,
  \item and a finite, algorithmically verifiable \emph{certificate} $\mathcal{C}$
\end{enumerate}
such that the approximant
\[
  f_\varepsilon(x)\;=\;\sum_{j\in J}a_j\,b_j(x)
\]
satisfies
\[
   \big\lVert f - f_\varepsilon\big\rVert_{W^{k,p}(\Omega)} 
   \;<\;\varepsilon,
\]
and $\mathcal{C}$ records:
\begin{itemize}[leftmargin=1.5em]
  \item the extraction of each $a_j$ via local probes (inner products or projections),
  \item the choice of a finite open cover $\{U_i\}$ of~$\Omega$,
  \item the explicit compatibility checks on overlaps $U_i\cap U_{i'}$,
  \item and the bound $\|f - f_\varepsilon\|<\varepsilon$ with all numerical parameters.
\end{itemize}

\noindent\textbf{Remark.}  If $f$ is given only by local data on a cover $\{U_i\}$, any family of \emph{compatible} local certificates $\{a_j^{(i)}\}$ glues uniquely to a global $\mathcal{C}$ and $f_\varepsilon$.  Moreover, when $f$ is computable, all steps—including basis evaluation, coefficient computation, overlap reconciliation, and error‐bound verification—are themselves computable.  In proof assistants (Lean/Coq), one obtains program extraction of the certificate algorithm (see Appendix B).

\noindent\textbf{Banach‐Space Caveat.}  In Banach spaces lacking an unconditional basis or strict convexity, one may need to specify an optimization routine to select a best approximant; the certificate must then include the algorithmic description of that routine.  See Appendix B for those subtleties.
\end{theorem}
\subsection*{A.2 Contextual Choice Principle (CCP)}

\begin{definition}[Contextual Choice Principle]\label{def:CCP}
Let $\mathcal{E}$ be a Grothendieck topos (or constructive universe) equipped with a Lawvere–Tierney modality $\Box$.  We say $\mathcal{E}$ satisfies the \emph{Contextual Choice Principle (CCP)} if:
\[
  x\in X \;\text{global}\;
  \quad\Longleftrightarrow\quad
  \begin{minipage}[t]{0.75\linewidth}
    there exists a finite cover $\{U_i\}$ and local sections $x_i\in X(U_i)$ such that
    \[
      x_i|_{U_i\cap U_j} \;=\; x_j|_{U_i\cap U_j}
      \quad\forall\,i,j,
    \]
    and this gluing is \emph{algorithmically effective} and \emph{unique up to certificate}.
  \end{minipage}
\]
\end{definition}

\noindent\textbf{Remark.}
\begin{itemize}[leftmargin=1.5em]
  \item Every existence theorem in $\mathcal{E}$ is thus a \emph{gluing theorem}, and the gluing is by construction effective and unique once one fixes the finite certificate of local data and compatibilities.
  \item In concrete toposes (smooth, realizability, etc.), the form of CCP may vary in presentation but always enforces explicit local-to-global assembly.  See Appendix C for models.
\end{itemize}

