\section{Formal Constructive Proof in Sobolev Spaces}
\renewcommand{\theequation}{\thesection.\arabic{equation}}
\setcounter{equation}{0}

\subsection*{B.1. Setting}

Let $\Omega = (0,1)\subset\mathbb{R}$ and consider the Sobolev space
\[
  F \;=\; W^{k,2}(\Omega)\,.
\]
Fix an explicitly computable basis $(b_j)_{j\ge1}$ for $F$, e.g.\ a Daubechies wavelet basis or a compact B‐spline family \cite{CohenDeVore,DeVoreLorentz}.

\begin{remark}[Alternative Bases]
The same construction applies equally well to Legendre or Chebyshev polynomial bases, trigonometric systems, or other spline families, provided one has an explicit algorithm for basis evaluation and inner‐product computation.
\end{remark}

We prove: for every $f\in F$ and $\varepsilon>0$ there is a finite set $J\subset\mathbb{N}$, coefficients $(a_j)_{j\in J}$, and a finite certificate $\mathcal{C}$ such that
\[
  f_\varepsilon(x)\;=\;\sum_{j\in J}a_j\,b_j(x),
  \quad
  \|f - f_\varepsilon\|_{W^{k,2}(\Omega)} < \varepsilon,
\]
and $\mathcal{C}$ records the local approximations, overlap constraints, and error bounds in a fully constructive manner.

\subsection*{B.2. Step-by-Step Construction}

\paragraph{Step 1: Local Certificate Extraction.}
\begin{itemize}[leftmargin=1.5em]
  \item Choose $M\in\mathbb{N}$ so that $h=1/M$ is sufficiently small.
  \item Cover $\Omega$ by intervals 
    \[
      U_i = (i h,\,(i+1)h),
      \quad i=0,1,\dots,M-1.
    \]
  \item On each $U_i$, select a finite index set $J_i\subset\mathbb{N}$ and compute
    \[
      a_j^{(i)}
      = \langle f,\,b_j\rangle_{W^{k,2}(U_i)},
      \quad j\in J_i,
    \]
    by explicit quadrature or least‐squares, so that
    \[
      \big\lVert f|_{U_i}
      - \sum_{j\in J_i}a_j^{(i)}\,b_j\big\rVert_{W^{k,2}(U_i)}
      < \frac{\varepsilon}{2}\,.
    \]
\end{itemize}

\paragraph{Step 2: Compatibility on Overlaps.}
\begin{itemize}[leftmargin=1.5em]
  \item For each adjacent pair $U_i,U_{i+1}$, restrict both local expansions to $U_i\cap U_{i+1}$.
  \item \emph{Reconciliation:} if the two sums differ by more than $\delta = \varepsilon/(2M)$, solve the small least‐squares problem
    \[
      \min_{(c_j)}\big\lVert
        \sum_{j\in J_i}a_j^{(i)}b_j
        - \sum_{j\in J_{i+1}}c_j\,b_j
      \big\rVert_{W^{k,2}(U_i\cap U_{i+1})},
    \]
    to adjust one coefficient vector so that the mismatch on the overlap is $<\delta$.  Record the linear constraints
    \[
      a_j^{(i+1)} \;\mapsto\; c_j,
      \quad
      |a_j^{(i+1)}-c_j| < \delta,
      \quad j\in J_{i+1},
    \]
    as part of $\mathcal{C}$.
  \item \emph{Remark.}  In practice the mismatch decays rapidly as $h\to0$, so only minor adjustments are needed.
\end{itemize}

\paragraph{Step 3: Global Gluing via Partition of Unity.}
\begin{itemize}[leftmargin=1.5em]
  \item Choose a smooth partition of unity $(\psi_i)_{i=0}^{M-1}$ subordinate to $\{U_i\}$.
  \item Define
    \[
      f_\varepsilon(x)
      = \sum_{i=0}^{M-1}
        \psi_i(x)\,
        \Bigl(\sum_{j\in J_i}a_j^{(i)}\,b_j(x)\Bigr).
    \]
\end{itemize}

\paragraph{Step 4: Error Estimate.}
By standard partition‐of‐unity estimates in Sobolev norms (see \cite[Prop.~4.1]{CohenDeVore}),
\[
  \|f - f_\varepsilon\|_{W^{k,2}(\Omega)}
  \;\le\;
  \max_i
    \big\lVert f|_{U_i}
      - \sum_{j\in J_i}a_j^{(i)}b_j\big\rVert_{W^{k,2}(U_i)}
  \;+\;
  C_{\rm PU}\,\frac{\varepsilon}{2}
  \;<\;\varepsilon,
\]
where $C_{\rm PU}$ is an explicit constant depending only on $k$ and the overlap pattern.

\paragraph{Step 5: Certificate Assembly.}
The full certificate is
\[
  \mathcal{C}
  = \Bigl\{
      \bigl(U_i,\;\{(b_j,a_j^{(i)})\}_{j\in J_i},\;
      \{\,\delta\text{-mismatch constraints}\}\bigr)
    \Bigr\}_{i=0}^{M-1},
\]
together with numerical bounds verifying each inequality.  By construction, $\mathcal{C}$ is finite, explicit, and algorithmically verifiable.

\subsection*{B.3. Constructivity and Formalization}

All steps—basis evaluation, quadrature, least‐squares, partition‐of‐unity assembly, and norm estimates—are implemented by explicit algorithms.  Hence if $f$ is a \emph{computable} function, then both $f_\varepsilon$ and $\mathcal{C}$ are computable.

\begin{remark}[Proof-Assistant Encoding]
In Lean or Coq one encodes this as a dependent type, for example:
\begin{verbatim}
def sobolev_certificate
  (f : Omega -> R) (eps : Rpos) :
  Sigma (M : nat) (J : finset nat) (a : J -> Q)
    (C : certificate_data M J a),
    norm(f - f_eps(M,J,a), W^{k,2}) < eps
\end{verbatim}
guaranteeing both constructivity and machine-checkable verifiability.
\end{remark}


