\section{Zip-Shift space}%\label{sec:zshift}
%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%
For natural numbers $k,m$ with $k\leq m$, consider two finite sets of alphabets $\z = \{a_1,\ldots,\,a_k\}$ and $\s= \{0,\ldots,\,m-1\}$.  
Let  $\Sigma_{\s}\subseteq \{(x_i)_{i\in \Z},\, x_i\in \s\}$ be a shift space (for details on shift space see for instance \cite{3}).
For any integer $\ell \geq k$, a finite sequence 
\[\omega_{[k,\ell]}=(x_k\, x_{k+1}\, \ldots\, x_{\ell}),\]
 which occurs in some point $(x_i)_{i\in \Z}\in \Sigma_{\s}$
is called a \textit{word} or \textit{block} of length $\left|\omega_{[k,\ell]}\right|=\ell-k+1$.
Now, for every $n\geq 1$, assume that $B_n^{\s}:=B_n^{\s}(\Sigma_{\s})$ be  
the set of all admissible words of length $n$ and also 
\[B^{\s}:=B^{\s}(\Sigma_{\s})=\bigcup_{n\geq 1}B_n^{\s}.\]
Note that obviously, $B_1^{\s}=\s$.
\begin{definition}%\label{def:zip}
Using notations stated above, let  $\tau: \s\longrightarrow \z$ be a surjective transition map, which is not necessarily invertible. 
Also, let $Y=\{y=(y_i)_{i\in \Z},\, y_i\in \s\}$ be a two-sided shift space with its associated shift map $\sigma$. For any point $y\in Y$, we correspond a 
point $x=(x_i)_{i\in \Z}=(\ldots,x_{-2},x_{-1};\,x_0,\,x_1,\,x_2,\ldots)$ such that
\begin{equation}\label{def:zip}
x_i=\left\{\begin{tabular}{ll}
$y_i\in \s$ & $i\geq 0$\\
$\tau (y_i)\in \z$& $i<0$. 
\end{tabular}\right.
\end{equation}
Then consider the following space which:
\[
\Sigma_{\z,\s}:= \{x=(x_i)_{i\in \Z}\ : x_i \textrm{\ satisfies} \,(\ref{def:zip})\}.
\]
The space $\Sigma_{\z,\s}$ is so called the ``zip-shift space". 

If $Y$ is a full shift space (i.e., contains all possible admissible words on $\s$), then $\Sigma_{\z,\s}$  will be called  \textit{full zip-shift space}.
\end{definition} 
One important property that a new space should have is invariance under a certain kind of maps, which we define as zip-shift maps. The following definition addresses this concept.

\begin{definition}\label{def:zip shift map}
Following notations stated above, we define the zip-shift map 
\begin{eqnarray*}
\sigma_{\tau} : \Sigma_{\z,\s}&\to& \Sigma_{\z,\s} \\
x=(x_i) &\mapsto& \left(\sigma_{\tau}(x)\right),
\end{eqnarray*}
where for every $i\in\Z$,
\[
\left(\sigma_{\tau}(x)\right)_i = \begin{cases}
\tau(x_{0}) &  i= -1\\
x_{i+1} & i \ne -1,
\end{cases}
\]
which is obviously  well-defined.

\end{definition}
It is well-known that the shift map is homeomorphism. In the case of zip-shift map we have the following affirmation.
\begin{theorem}\label{teo:local homo}
The zip shift map, defined in Definition \ref{def:zip shift map}, is a local homeomorphism which is a generalization of a two-sided shift homeomorphism.
\end{theorem}
To prove this theorem, we first need to establish a topology on the zip-shift space. For this purpose, we provide the following definitions and statements:

1) When $\z=\s$ and $\tau(x)=id(x) =x$, then the zip-shift map represents the known two-sided shift map.  As cellular automaton is usually defined on full shift spaces, so we assume that the zip-shift spaces are full zip-shift spaces.  The interested reader can find more details on these concepts in \cite{L}. 
\begin{remark}\label{rmk:1}
Note that by Definition \ref{def:zip}, a full zip-shift map with transition function $\tau$ looks like a shift map for all $i\neq-1$ (i.e., $[\sigma_{\tau}(x)]_i=x_{i+1}$) and  $x_{-1}=\tau(x_0)$.
\end{remark}
2) Now, we equip $\Sigma_{\z,\s}$ with the following metric:\\
First, consider the map 
\[D:\Sigma_{\z,\s}\times \Sigma_{\z,\s}\rightarrow\mathbb{N}\cup \{0\}\]
given by, 
\begin{equation*}
D(x,y)=\begin{cases}
\infty & x=y, \\
\min\{\vert i\vert;\,(x_{i})\neq (y_{i}) \} & x\neq y.
\end{cases}
\end{equation*}

For any $x,y\in\Sigma_{\z,\s}$ the positive function
\begin{equation}\label{def:met}
\bar{d}(x,y):=\frac{1}{2^{D(x,y)}},
\end{equation}
defines a metric on $\Sigma_{\z,\s}$. This metric induces a topology on $\Sigma_{\z,\s}$ which is equivalent to the product topology (known also as Cantor topology). From now on, we consider the metric space $(\Sigma_{\z,\s}, \bar{d})$ with the induced metric topology. 
\begin{definition}
    \item (I) Any closed subset, $\Sigma$, of $\Sigma_{\z,\s}$ which is invariant under $\sigma$ (i.e., $\sigma_{\tau}^{\pm}(\Sigma)=\Sigma$) is called a \textit{sub zip-shift space} of $\Sigma_{\z,\s}$. From now on, $\Sigma$ denotes sub zip-shift space.
    \item (II) The set of all words of length $n$ in $\Sigma_{\z,\s}$, denoted by $B_n^{\z,\s}=B^{\z,\s}_n(\Sigma)$ is defined similar to the shift case. 
Indeed, the set $B^{\z,\s}=\bigcup_{n\geq 1}B^{\z,\s}_n(\Sigma)$
represents all \textit{admissible} words (in some texts it called the \textit{language}) of $\Sigma$.
    \item (III) A shift of finite type, or $SFT$, is a shift space whose set of forbidden words is finite.
\end{definition}
\begin{remark}\label{rem:tau}
Once working with admissible words of an $SFT$ space, we may need to extend the transition map $\tau:\s\to \z$ to a new map $\tilde{\tau}: \s\cup \z \to \z$, where 
\[
\tilde{\tau}(x)= \begin{cases}
\tau(x) & x\in \s,\\
x & x\in \z.
\end{cases}
\]
 In this way we define
 \[
 \tilde{\tau}(x_{[i-k,i+k]}):=\tilde{\tau}(x_{i-k})\tilde{\tau}(x_{i-k+1})\dots \tilde{\tau}(x_{i+k}).
\]
%Note that as $\tilde{\tau}(x_{[i-k,i+k]})$ is a word which entries that belong to $\z$, whenever $i>0$, we exchange it to $i<0$. 
\end{remark}
An important concept that we use frequently in study of zip-shift spaces is cylinder set.  The definition of these sets is similar to the shift space. More precisely,
for a zip-shift space $(\Sigma, \overline{d})$ the basic cylinder sets are 
\begin{equation*}%\label{B-C}
C_i^{s_i}=\{x\in\Sigma\,|\,x_{i}=s_{i}, i\in\mathbb{Z}\}.
\end{equation*}
Basically, $C_i^{s_i}$ represents the set of all points in $\Sigma$, that have $s_{i}$ in their $i^{th}$ entry. Obviously,  basic cylinders are open subsets (in fact they are clopen sets) in the product topology of zip-shift spaces.  
Also, \textit{general cylinder sets} are given by 
\[
C_{i_1,\dots,i_k}^{s_{1},\dots,s_{k}}=\{ x=(x_i)\in \Sigma\,|\,x_{i_1}=s_1,\dots,x_{i_k}=s_k; i_1,\dots,i_k\in \mathbb{Z}^d\},
\]
where, for $1\leq j\leq k$, the element $s_j\in \z$ if $i_j<0$, and $s_j\in \s$ when $i_j\geq 0$.

As cylinder sets are defined independently, so we have 
\[
C_{i_1,\dots,i_k}^{s_{1},\dots,s_{k}}=C_{i_1}^{s_{i_1}}\cap C_{i_2}^{s_{i_2}}\cdots \cap C_{i_k}^{s_{i_k}}.
\] 
\begin{remark}
The set of all cylinder sets forms a basis for the topology. Moreover, $\Sigma$ is a compact subset of $\Sigma_{\z,\s}$ (Tychonoff Theorem \cite{M}).
\end{remark}
Now we are ready to prove Theorem \ref{teo:local homo}:
\begin{proof}[\textbf{Proof of Theorem \ref{teo:local homo}}]
Since the image and pre-image of the basic and general cylinder sets are cylinder sets, one concludes that $\sigma_{\tau}$ is a continuous and open map. 

Let $\bar{x}=(\cdots x_{-1};x_0x_ 1\cdots)$ be an arbitrary element of $\Sigma_{\z,\s}$. There exists a cylinder set $C=C_{-1\,0\,1}^{x_{-1}\,x_{0}\,x_1}$ such that $\bar{x}\in C$. We claim that the restriction of $\sigma_{\tau}$ to $C$ is injective.
In fact, if $\sigma_{\tau}(x)=\sigma_{\tau}(y)$ for some $\bar{y}=(\cdots y_{-2}\,x_{-1};x_0\,x_ 1\,y_2\cdots)\in C,$  then, 
\[(\cdots x_{-2}\,x_{-1}\,\tau(x_0); x_1\,x_2\cdots)=(\cdots y_{-2}x_{-1} \tau(x_0); x_1\,y_2 \cdots).\]
Therefore $x_i=y_i$ for all $i\in\mathbb{Z}.$ This means that $\bar{x}=\bar{y}$. Therefore, $\sigma_{\tau}$ is injective on $C$ and hence is a local homeomorphism. 
\end{proof}
\begin{remark}\label{rmk:2}
 Note that:
In general, the zip-shift maps defined on two sets of finite alphabets, represent finite-to-1 local homeomorphisms,  i.e., the pre-images of elements of the zip-shift space over the zip-shift map are finite. In particular, for zip-shift space $\Sigma_{\z,\s}$ with transition map $\tau: \s\to \z$, when the cardinality of the pre-images over $\sigma_{\tau}$ is equal to some fixed $n$ for all $x\in \Sigma_{\z,\s}$ we say that it is an n-to-1 zip shift map. 
%with pre-image degree ($Pdeg(\sigma_{\tau})$) equal $n$ 
%and when exists points $x,y\in \Sigma_{\z,\s}$ with different cardinality of pre-images, we call it a finite-to-1 zip shift map.
%\item 2) If $\s=\z$ and $\tau: \s\to \z$ the identity map, then the associated zip-shift map is a full shift on $\s$.
\end{remark}
 In what follows we give the example of a 2-to-1 full zip shift map.
\begin{example}
Let $\s=\{0,1,2,3\}$, $\z=\{a,b\}$ and assume that the corresponded transition map $\tau:\s\to \z$ is defined as 
\[
\begin{cases}
\tau(0)=\tau(3)=a, & \\
\tau(1)=\tau(2)=b. &
\end{cases}
\]
Then for $\bar{x}=(x_i)_{i\in\mathbb{Z}}=(\cdots a\,b\,b\,b\,a\,\textbf{;}1\,0\,3\,0\,2\,\cdots)\in \Sigma$,  one can verify that 
\[\sigma_{\tau}(\bar{x})=(\cdots a\,b\,b\,b\,a\,b\,\textbf{;}\,0\,3\,0\,2\,\cdots),\] 
and 
\[\sigma_{\tau}^{-1}(\bar{x})=\{(\cdots a\,b\,b\,b\,\textbf{;}0\,1\,0\,3\,0\,2\,\cdots),(\cdots a\,b\,b\,b\,\textbf{;}3\,1\,0\,3\,0\,2\,\cdots)\}.\]
In fact for any $\bar{x}\in \Sigma_{\z,\s}$ the cardinality of $\sigma_{\tau}^{-1}(\bar{x})$, i.e. $\#(\sigma_{\tau}^{-1}(\bar{x}))=2$ 
%(i.e. $Pdeg(\sigma_{\tau})=2$) 
and $\sigma_{\tau}$ is a 2-to-1 map.
\end{example} 
