\section{Extended Curtis-Hedlund-Lyndon Theorem}\label{sec:Curtis theorem}
One of the fundamental results in symbolic dynamics is the Curtis–Hedlund–Lyndon Theorem. This theorem is a mathematical characterization of cellular automata in terms of their symbolic dynamics. 
In what follows first in Theorem \ref{teo:CHL_CA}, we present the classic Curtis–Hedlund–Lyndon theorem (see \cite{H}) for classic Cellular Automata and then in Theorem \ref{teo:extended curtis} we demonstrate an extended version of this theorem for generalized Cellular Automata. It is worth mentioning that,  an even more general definition of extended sliding block codes based on zip-shift spaces (not necessarily full) and a general Extended Curtis–Hedlund–Lyndon are given in \cite{L}.

\begin{definition}[Shift Based-Sliding Block Codes]\label{SBC_classic} 
   For a given pair of natural numbers $n$ and $m$, let $\s$ and $\mathcal{T}$ be two finite alphabet sets (state spaces). Assume that $X\subseteq \s^{\Z}$ is a shift space and $N=m+n+1$ (usually, $m$ is called the memory and  $n$ is called the anticipation of the dynamic). A continuous map $\phi: X\to {\mathcal{T}}^{\mathbb{Z}}$ is called a \textit{Sliding Block Code (simply denoted by} $SBC$) if there exists  a code map (i.e., a local rule) $\Phi:B_N(X)\to {\mathcal{T}}$ such that, for all $i\in\mathbb{Z}$ and every $\bar{x}=(x_i)_{i\in\mathbb{Z}}\in X$, we have:
	\begin{itemize}
		\item[($1$)] $\big[\phi(\bar{x})\big]_i=\Phi\big(x_{[i-m,i+n]}\big)$,
		\item[($2$)] $\phi$ commutes with shift maps. 
		(i.e., $\forall k\in \mathbb{Z}, \sigma^k\circ\phi = \phi\circ \sigma^k$).
	\end{itemize}
	Furthermore, we call $\phi$ a \textit{ Cellular Automaton} (or simply a CA), when $\s=\mathcal{T}$ and $X=\s^{\mathbb{Z}}$.
\end{definition}
\begin{theorem}[Curtis–Hedlund–Lyndon \cite{BS}] \label{teo:CHL_CA}
 Let $\s$ be a finite symbolic set. Then $G: \s^{\mathbb{Z}}\to \s^{\mathbb{Z}}$ is a cellular automaton if, and only if, it is continuous and commutes with the shifts.
\end{theorem}
In the following, with the aim of extending this theorem, we first present the definition of zip-cellular automata.
\begin{definition}[Zip-shift Based Sliding Block Codes (Z-SBC)]\label{SBC_zip} 
Let $(\z,\s)$  and $(\q,\p)$ be two pairs of finite alphabet sets (state spaces). Assume that $(\Sigma_{\z,\s},\sigma_{\tau})$ and $(\Sigma_{\q,\p},\sigma_{\kappa})$ represent full zip-shift spaces. Set two natural numbers $n$  and $m$. Put $N=m+n+1$. A continuous map $R: \Sigma_{\z,\s}\to \Sigma_{\q,\p}$, is a \textit{zip-shift-sliding block code} (simply denoted by Z-SBC) if there exists a code map (local rule) $\phi_{R}:B_{N}(\Sigma_{\z,\s})\to \q\cup \p$ such that for every $\bar{x}=(x_i)_{i\in\Z}\in \Sigma_{\z,\s}:$
\begin{itemize}

\item[($1$)] For all $i\in\Z$,  $[R(\bar{x})]_i=\phi_{R}(x_{[i-m,i+n]});$
\item[($2$)] For $i\geq 0$, $\tilde{\kappa}(\phi_{R}(x_{[i-m,i+n]}))=\phi_{R}(\tilde{\tau}(x_{[i-m,i+n]}))$.  
\item[($3$)]  $R$ locally ``commutes" with zip-shift maps, 
    i.e., for $i\geq 0$, both \textit{``function composition equality"}:$R\circ\sigma_{\tau}^i=\sigma_{\kappa}^i\circ R$ and \textit{``set theoretic equality"}: $R(\sigma_{\tau}^{-i}(\bar{x}))=\sigma_{\kappa}^{-i}(R(\bar{x}))$ hold. 
\end{itemize} 
Diagram \eqref{R1} demonstrates these mentioned properties.
\begin{equation}\label{R1}
\begin{tikzcd}
[row sep=tiny,column sep=tiny]& & & \\ \Sigma_{\mathcal{Z},\mathcal{S}} \arrow{rr}{\sigma_{\tau}}\arrow{dd}{R} & & \Sigma_{\mathcal{Z},\mathcal{S}}\arrow{dd}{R} \\& \circlearrowright &  & \\ \Sigma_{\q,\p}\arrow{rr}{\sigma_{\kappa}} & & \Sigma_{\q,\p}.\\
\end{tikzcd}
\end{equation}
Moreover, we call $R$ a  \textit{Zip-Cellular Automaton} (simply denoted by Zip-CA) when $\z=\q$, $\s=\p$, $\sigma_{\tau}=\sigma_{\kappa}$ and consequently $(\Sigma_{\z,\s},\sigma_{\tau})=(\Sigma_{\q,\p}, \sigma_{\kappa})$. Note that in this case, the second condition given above, simplifies to $\tau(\phi_{R}(x_{[i-m,i+n]}))=\phi_{R}(\tau(x_{[i-m,i+n]}))$ for $i\geq 0.$
\end{definition}
Just to emphasize, it is worth noting that  $\sigma_{\tau}^{-i}(\bar{x})$ (Resp. $\sigma_{\kappa}^{-i}(R(\bar{x}))$) is a set in $\Sigma_{\z,\s}$ (Resp. $\Sigma_{\q,\p}$) and $R(\sigma_{\tau}^{-i}(\bar{x}))$ is simply the image of this set under $R$.
\begin{remark}
It is noteworthy that if for given integers $m$ and $n$ and element $\bar x=(x_i)_{i\in\mathbb{Z}}\in \Sigma_{\mathcal{Z},\mathcal{S}}$ one defines,
\begin{equation}\label{def:phi}
\phi_{R}(x_{[i-m,i+n]}):=\begin{cases}
x_{i+1}\in \s \quad\quad &  i\geq 0\\
\tau(x_{0})\in \z\quad\quad &\, i=-1,\\ 
x_{i+1}\in \z\quad\quad &  i<-1. 
\end{cases}
\end{equation} 
Then $R(\bar x)=\sigma_{\tau}(\bar x)$ is a Zip-CA.
\end{remark}
%\[[R(\bar x)]_{i}=
%\begin{cases}
%[R_1(\bar{x})]_i \quad\quad \quad& i\geq 0 \\
%\tau(x) \quad\quad \quad& i=-1 \\[R_2(\bar{x})]_i \quad\quad \quad& i<0.
%\end{cases}\]
%Then the zip-CA $R$ is a zip shift map and in particular this shows that zip shift maps are Zip-CA.
In what follows the Extended Curtis–Hedlund–Lyndon theorem is demonstrated.
\begin{theorem}[Extended Curtis–Hedlund–Lyndon]\label{teo:extended curtis}
 Let $\z,\s$ be two  finite alphabet sets (state spaces). Then $R: (\Sigma_{\z,\s},\tau)\to (\Sigma_{\z,\s},\tau)$ is a zip Cellular Automaton if, and only if, it is continuous and locally ``commutes" (in the sense of Definition \ref{SBC_zip})  with zip-shift maps.
\end{theorem}
\begin{proof}
($\Rightarrow$) A Zip-CA by definition is a zip-shift sliding block code (Definition \ref{SBC_classic}) which is continuous and locally ``commutes" with zip-shift maps. 

($\Leftarrow$) Let $R: (\Sigma_{\z,\s},\tau)\to (\Sigma_{\z,\s},\tau)$  be continuous and locally ``commutes" with zip-shift map $\sigma_{\tau}$. We aim to show that there exists some $m,n\in\mathbb{N}$ and a local rule  $\phi_R: B_{N}(\Sigma_{\z,\s})\to \z\cup \s$ associated with $R$, which satisfies the properties given in Definition \ref{SBC_zip} where $N=m+n+1$. Put $\bar{x}=(x_i)\in \Sigma_{\z,\s}$.

As $(\Sigma_{\z,\s},\bar d)$ is compact (see \eqref{def:met} and Remark \ref{rmk:1}), so $R$ is uniformly continuous. Therefore, for all $\epsilon>0$ there exists  $0<\delta\leq \epsilon$ such that for $\bar{y}=(y_i)\in\Sigma_{\z,\s}$ when $\bar{d}(\bar{x},\bar{y})<\delta$, then $\bar{d}(R(\bar{x}),R(\bar{y}))<\epsilon$. Let $k\in\mathbb{N}$ such that $\frac{1}{2^k}<\delta$. In particular for every $-k\leq i\leq k$, we have $[R(\bar{x})]_i=[R(\bar{y})]_i$. Therefore, we can say that $R$ depends only on $x_{-k},\dots,x_{0},\dots,x_{k}$. Let $n=m=k$ so $N=2k+1$. Define the local rule, $\phi_R: B_{N}(\Sigma_{\z,\s})\to \z\cup \s$, as 

\begin{equation}\label{Eq:LR}
\phi_R(x_{[i-k,i+k]}) = \begin{cases}
    [R(\sigma_{\tau}^i(\bar{x}))]_0 & x_{[i-k,i+k]}\in \s^{N}, \\
    %\tilde{\tau}\left([R\left(\sigma^i_{\tau}(\bar{x})\right)]_0\right) & x_{[i-k,i+k]}\in \z^{N},\\
    \tilde{\tau}\left([R\left(\sigma^i_{\tau}(\bar{x})\right)]_0\right) & \text{otherwise}.
\end{cases}
\end{equation}
Note that as by hypothesis, $R(\sigma_{\tau}^i(\bar{x})) = \sigma_{\tau}^i(R(\bar{x}))$ so $\phi_R$ is well-defined map. To be more precise, let $\bar{x}=(x_i)$ and $\bar{y}=(y_i)$ be two elements of $\Sigma_{\z,\s}$ for which $x_{[i-k,i+k]} = y_{[i-k,i+k]}$. %Three possibilities may happen when all the elements of these blocks belong to $\s$ or to $\z$ or both of them. 
Due to the facts that $R$ is a uniformly continuous map and the way that we choose $k$, we know that $[R(\bar{x})]_i = [R(\bar{y})]_i$ for for every $-k\leq i\leq k$ with $k>1$, in particular it is true at the position $0$. 

To complete the proof, we should demonstrate that $\phi_R$ satisfies the conditions of Definition \ref{SBC_zip}. This means that, we should prove that:
\begin{enumerate}
\item For all $i\in\Z$,  $[R(\bar{x})]_i=\phi_{R}(x_{[i-k,i+k]});$
\item For $i\geq 0$, $\tilde{\tau}(\phi_{R}(x_{[i-k,i+k]}))=\phi_{R}(\tilde{\tau}(x_{[i-k,i+k]}))$.  
\item $R$ locally ``commutes" with zip-shift maps. 
\end{enumerate} 
The first and third above conditions happen obviously. For the second condition, note that using \eqref{Eq:LR} and Remark \ref{rem:tau}, when $i\geq 0$, we have
 \[\phi_R(\tilde{\tau}(x_{[i-k,i+k]}))=\tilde{\tau}([R(\sigma_{\tau}^i(\bar x))]_0) = \tilde{\tau}(\phi_{R}(x_{[i-k,i+k]})).\] 
% This implies that $\phi_R(x_{[i-k,i+k]})=\tilde{\tau}([R(\{\sigma_{\tau}^{-i}(\bar{x})\})]_0)$ for $i<0$. 
Therefore $R$ is a Zip-CA.

\end{proof}
