\section{Formulation of Problem}

Assume there is one riskless asset (bond) and $n$ risky assets (stocks) available for investment. 
Let the planning investment horizon $[0,T]$ be fixed.
The riskless asset has a constant interest rate $r$.
$\{B_t^{(1)},\dots,B_t^{(n)},0 \leqslant t \leqslant T\}$ is the standard $n$-dimensional Brownian motion defined on a filtered probability space $(\Omega,\mathcal{F},\mathbb{P};\{\mathcal{F}_t\}_{0 \leqslant t \leqslant T})$.
The price of the $i$-th risky asset is observable, whose discounted value can be governed by the stochastic differential equation:
\begin{align}\label{equ:S}
	dS^{(i)}_t = 
	(\mu^{(i)}(t)-r) S^{(i)}_t dt 
	+ \sigma^{(i)}(t) S^{(i)}_t dB^{(i)}_t,
	\qquad i=1,\dots,n,
\end{align}
where the return rate $\mu^{(i)}(t)$ and volatility $\sigma^{(i)}(t)$ are time-dependent.
$dB^{(i)}_t \cdot dB^{(j)}_t=\rho^{(ij)} dt$,
in which $\rho^{(ij)}\in[-1,1]$ is constant and describes the correlation between the return of the $i$-th and the $j$-th risky asset, $i, j\in\{1,\dots,n\}$.
Throughout this paper, we denote the excess expected return vector and the covariance matrix of $n$ risky assets by
\begin{align}\label{equ:DLD}
\mu-r=
\begin{bmatrix}
	\mu^{(1)}(t)-r &\cdots &\mu^{(n)}(t)-r
\end{bmatrix}^\top
\quad\text{and}\quad
\Sigma=DLD^\top,
\end{align}
respectively, where
\begin{align}\label{equ:L}
D=\text{diag}\{\sigma^{(1)}(t),\cdots,\sigma^{(n)}(t)\},
\qquad
L=
\begin{bmatrix}
	\rho^{(11)} &\cdots &\rho^{(1n)}\\
	\rho^{(21)} &\cdots &\rho^{(2n)}\\
	\vdots	    &\vdots &\vdots\\
	\rho^{(n1)} &\cdots &\rho^{(nn)}
\end{bmatrix}.
\end{align}


\subsection{Classical continuous-time MV model}\label{se:classical_model}

We first recall the classical continuous-time mean-variance (MV) model.
The analytic expression of the multi-asset optimal MV portfolio selection is shown in Lemma \ref{th:theta_cl}.

In financial market \eqref{equ:S}, the investor rebalances the portfolio selection dynamically with an allocation $\Theta_t= \begin{bmatrix} \theta^{(1)}_t &\cdots &\theta^{(n)}_t \end{bmatrix}^\top$, $\forall t\in[0,T]$, in which $\theta_t^{(i)}$ is the discounted amount put in the $i$-th risky asset at time $t$.
%Denote by $W_t$ the discounted wealth at moment $t$.
Under the self-financing condition, the discounted wealth process $W_t$ follows:
\begin{align*}%\label{equ:W_CL}
	dW_t
	= \sum_{i=1}^n \dfrac{\theta_t^{(i)}}{S_t^{(i)}} dS^{(i)}_t
	= \Theta_t^\top \Big( (\mu-r) dt + D dB_t \Big),
\end{align*}
with initial wealth $w^o>0$, where $dB_t = \begin{bmatrix} dB^{(1)}_t &\cdots &dB^{(n)}_t \end{bmatrix}^\top$.
The classical continuous-time MV model aims to consider the portfolio selection which maximizes the trade-off between the expectation and variance of terminal wealth $W_T$:
\begin{equation}\label{model_cl}
	\max_{\{\Theta_t\}} {\rm E}\Big(W_T\Big)-\gamma {\rm Var}\Big(W_T\Big),
\end{equation}
%subject to the dynamics \eqref{equ:W_CL},
where $\gamma>0$ is the risk aversion coefficient.

Because the variance operator in \eqref{model_cl} is non-smooth, i.e.,
\begin{equation*}
	{\rm Var}_s \Big({\rm Var}_t \Big(\cdot\Big)\Big)\neq {\rm Var}_s\Big(\cdot\Big), \qquad 0\leqslant s<t\leqslant T,
\end{equation*}
the principle of dynamic programming \citep{Bellman1957Dynamic} fails.
In order to obtain the optimal MV portfolio selection,
following \cite{Zhou2000Continuous}, the classical continuous-time MV model \eqref{model_cl} is transformed into a tractable stochastic linear-quadratic problem:
\begin{equation}\label{model_cl_aux}
	\max_{\{\Theta_t\}} {\rm E}\Big(-\gamma W_T^2+\tau W_T\Big),
\end{equation}
%subject to the dynamics \eqref{equ:W_CL},
with $\tau=1+2\gamma {\rm E}\Big(W_T^*\Big)$, where $\{W_t^*\}_{0\leqslant t \leqslant T}$ is the discounted wealth with the optimal portfolio selection.
Model \eqref{model_cl_aux} can be solved analytically, whose optimal portfolio selection $\{\Theta_t^*\}_{0\leqslant t \leqslant T}$ is shown in Lemma \ref{th:theta_cl}.

\begin{lemma}[\cite{Zhou2000Continuous}]\label{th:theta_cl}
The optimal portfolio selection of model \eqref{model_cl_aux} is given by
\begin{align}\label{equ:theta_n_cl}
\Theta_t^{*}
%=(-w+w^o+\dfrac{e^{K(0,T)\cdot T}}{2\gamma}){\comm \Sigma^{-1}}(\mu-r),
=( \dfrac{\tau}{2\gamma}-w)\Sigma^{-1}(\mu-r),
\qquad
\forall t\in[0,T],
\end{align}
with $\tau=e^{K(0,T)\cdot T}+2\gamma w^o$, 
where $w$ and $w^o$ are respectively the discounted amount of $t$-time wealth and initial wealth,
and
\begin{align*}
	K(0,T)
	=\dfrac{1}{T}\int_0^T (\mu-r)^\top \Sigma^{-1} (\mu-r)ds.
\end{align*}
\end{lemma}
%\begin{proof}
%The proof is omitted which is a degradation of that in Theorem \ref{th:v_theta_n}.
%\end{proof}

In Lemma \ref{th:theta_cl}, the optimal portfolio selection \eqref{equ:theta_n_cl} is related to three parts of parameters: $\mu-r$, $\Sigma^{-1}$ and $K(0,T)$.
Specifically, $\mu-r\in\mathbb{R}^{n\times 1}$ and $\Sigma^{-1}\in\mathbb{R}^{n\times n}$ are time-dependent representing the excess expected return vector and the inverse covariance matrix of the $n$ risky assets, respectively.
A change in the value of an element of $\mu-r$ or $\Sigma^{-1}$ exclusively influence the allocation associated with the corresponding risky assets \citep{Best1991sensitivity}.
In contrast, $K(0, T)\in\mathbb{R}$ remains constant during the whole planning investment horizon representing the average of squared Sharpe ratio of $n$ risky assets.
As the value of $K(0,T)$ increases, the amount invested in each risky asset is increased proportionally.
We will further explain the economic implications of $K(0,T)$ in Section \ref{se:K} later.


The optimal portfolio selection \eqref{equ:theta_n_cl}
in Lemma \ref{th:theta_cl} is the well-known pre-commitment portfolio selection \citep{Zhou2000Continuous, Li2000Optimal, Wang2010Numerical},
which shows superior performance within stable economic regimes \citep{Forsyth2020Multiperiod,Vigna2020time}.
When $T\to0$, the optimal portfolio selection at time 0 degenerates into
$\frac{1}{2\gamma}\Sigma^{-1}(\mu-r)$,
which is consistent with the static portfolio selection in single-period MV model \citep{Markowitz1956Optimization, Merton1972Analytical}.



\subsection{The average profitability of risky assets}\label{se:K}

In this subsection, we take a closer look at $K(0, T)$.
We explain the economic implications and then analyze the properties for it. 


For the $i$-th risky asset, $\frac{\mu^{(i)}(t)-r}{\sigma^{(i)}(t)}$ is the Sharpe ratio of it at time $t$, $i=1,\dots,n$.
If $\frac{\mu^{(i)}(t)-r}{\sigma^{(i)}(t)}\neq0$, the investor can profit from buying or shorting the risky asset. 
The further $\frac{\mu^{(i)}(t)-r}{\sigma^{(i)}(t)}$ is from zero, the more the investor can earn with a share of the risky asset.
We define the square of $\frac{\mu^{(i)}(t)-r}{\sigma^{(i)}(t)}$ as $A^{(i)}(t)$, i.e.,
\begin{align*}%\label{equ:Si}
	A^{(i)}(t)=\Big(\dfrac{\mu^{(i)}(t)-r}{\sigma^{(i)}(t)}\Big)^2,
\end{align*}
which represents the current profitability of the $i$-th risky asset.
And, the average of $A^{(i)}(s)$ over the planning investment horizon $[t,T]$ is defined as $K^{(i)}(t,T)$,
\begin{align*}%\label{equ:Ki}
	K^{(i)}(t,T)=\dfrac{1}{T-t}\int_t^T A^{(i)}(s) ds,
\end{align*}
which represents the average profitability of the $i$-th risky asset from $t$ to $T$. 

Similarly, in multi-asset financial market, $(\mu-r)^\top\Sigma^{-1} (\mu-r)$ is the squared Sharpe ratio of the $n$ risky assets.
We define $A(t)$ and $K(t,T)$ as 
\begin{equation}\label{equ:K}
\begin{split}
	A(t)=(\mu-r)^\top\Sigma^{-1} (\mu-r),
	\qquad
	K(t,T)=\dfrac{1}{T-t}\int_t^T A(s) ds,
\end{split}
\end{equation}
which represent the current and average profitability of $n$ risky assets, respectively.
In fact, when the financial market is stable, the average profitability of the $n$ risky assets $K(t,T)$ can be represented by the average profitability of each risky asset $K^{(i)}(t)$, $i=1,\dots,n$. 
We summarize this property into Theorem \ref{th:K_k}.

\begin{theorem}\label{th:K_k}
When the financial market is stable, i.e., model parameters $\mu, \Sigma$ are time-independent,
we have the following relation between the average profitability of $n$ risky assets and that of each risky asset, $\forall t\in[0,T)$,
\begin{align}\label{equ:K_k}
	K(t,T)
	=
\begin{bmatrix}
	\sqrt{K^{(1)}(t,T)} &\cdots &\sqrt{K^{(n)}(t,T)}~
\end{bmatrix}
L^{-1}
\begin{bmatrix}
	\sqrt{K^{(1)}(t,T)}~\\ \vdots\\ \sqrt{K^{(n)}(t,T)}
\end{bmatrix},
\end{align}
where the correlation coefficient matrix $L$ is defined in \eqref{equ:L}.
\end{theorem}
\begin{proof}
See Appendix \ref{app:K_k}.
\end{proof}


\section{The Exploratory Portfolio Selection}\label{se:exploratory_model}


Due to the lack of information about the parameters $\mu-r$, $\Sigma^{-1}$ and $K(0,T)$, the RL agent explores the financial market with a exploratory portfolio selection.
%, through which the agent can gather more information and lead to better portfolio performance.
In Section \ref{se:3.1}, following \cite{Wang2020Continuous}, we develop an exploratory formulation for the continuous-time multi-asset MV problem \eqref{model_cl}.
In Section \ref{se:multi}, we derive the optimal probability density function of the exploratory portfolio selection, whose expectation is the optimal MV portfolio selection in Lemma \ref{th:theta_cl}.
In Section \ref{se:alg_convergence}, we develop a policy iteration process to learn 
this optimal exploratory portfolio selection.



\subsection{Exploratory continuous-time MV model}\label{se:3.1}


The key idea of the exploratory formulation is to consider the randomness of the portfolio selection.
The RL agent chooses its $t$-time action (portfolio) by sampling from a multivariate probability density function $P(t,\cdot)$, which is called an exploratory portfolio selection, with the constraint
\begin{align*}%\label{equ:constraint}
\int_{\mathbb{R}^n}P(t,\theta) d\theta=1.
\end{align*}

We first describe the discounted wealth process under the exploratory portfolio selection $P(t,\theta)$.
Let $\widetilde{W}_t$ denote the $t$-time discounted wealth.
Following \cite{Wang2019Exploration}, $\{\widetilde{W}_t\}_{0 \leqslant t \leqslant T}$ is the ``average'' of infinitely many wealth processes generated 
under the portfolios that are repeatedly sampled from the probability density function $\{P(t,\cdot)\}_{0 \leqslant t \leqslant T}$.
The discounted wealth process under the exploratory formulation is described by:
\begin{equation}\label{equ:wealth_RL}
	d\widetilde{W}_t 
	= \int_{\mathbb{R}^n}\theta^\top (\mu-r) P(t,\theta) d\theta \cdot dt 
	+\sqrt{\int_{\mathbb{R}^n}\theta^\top\Sigma\theta P(t,\theta) d\theta} \cdot d\widetilde{B}_t,
\end{equation}
in which $\{\widetilde{B}_t\}_{0 \leqslant t \leqslant T}$ is the standard one-dimensional Brownian motion.
%The derivation of \eqref{equ:wealth_RL} is provided in Appendix \ref{app:wealth_RL}.


Next, we describe the objective function in the exploratory continuous-time MV model.
To regulate the level of exploration, the information entropy $h(P(t,\cdot))$ \citep{Cover1991Elements,Mnih2016Asynchronous, Nachum2017Improving} is introduced:
\begin{align}\label{equ:entropy}
	h(P(t,\cdot)):=\int_{\mathbb{R}^n}-P(t,\theta)\ln{P(t,\theta)}d\theta.
\end{align}
More uncertainty of the exploratory portfolio selection corresponds to a larger value of information entropy.
When we are on the realm of classical continuous-time MV model, the probability density function $P(t,\cdot)$ is the Dirac measure, and the information entropy $h(P(t,\cdot))$ tends to $-\infty$.
In the exploratory formulation, we encourage the exploration and incorporate the accumulative information entropy $\mathcal{H}(P(\cdot,\cdot)):=\int_0^T h(P(t,\cdot))dt$ into the objective function of the classical continuous-time MV model \eqref{model_cl}.
In fact, the accumulative information entropy $\mathcal{H}(P(\cdot,\cdot))$ has already been used by \cite{Wang2020Continuous} and \cite{Dai2023Learninga} to regularize exploration for a continuous-time single-asset MV portfolio selection problem.
Then, the entropy-regularized optimization problem 
for the continuous-time multi-asset MV model
is formulated as:
\begin{equation}\label{model_rl}
	\max_{\{P(t,\cdot)\}} {\rm E}\Big(\widetilde{W}_T\Big)-\gamma {\rm Var}\Big(\widetilde{W}_T\Big)+\lambda \mathcal{H}(P(\cdot,\cdot)),
\end{equation}
where $\lambda~(\lambda>0)$ is the exploration weight,
and 
the discounted terminal wealth $\widetilde{W}_T$
is defined in \eqref{equ:wealth_RL}
under the exploratory portfolio selection 
$\{P(t,\cdot)\}_{0 \leqslant t \leqslant T}$.


\subsection{The gaussian exploration}\label{se:multi}


In order to solve the exploratory continuous-time MV model \eqref{model_rl}, the stochastic linear-quadratic optimal control model \eqref{model_cl_aux} is also transformed into the exploratory formulation:
\begin{equation}\label{model_rl_aux}
	\max_{\{P(t,\cdot)\}} {\rm E}\Big(-\gamma \widetilde{W}_T^2+\tau \widetilde{W}_T\Big)
	+\lambda \mathcal{H}(P(\cdot,\cdot))
\end{equation}
with $\tau=1+2\gamma {\rm E}\Big(\widetilde{W}_T^*\Big)$,
where $\{\widetilde{W}_t\}_{0\leqslant t \leqslant T}$ subjects to the process \eqref{equ:wealth_RL}
and $\widetilde{W}_T^*$ is the discounted wealth at terminal time $T$ with the optimal exploratory portfolio selection.
Now, we prove the equivalence of problem \eqref{model_rl} and \eqref{model_rl_aux} in Lemma \ref{le:rl_aux}.


\begin{lemma}\label{le:rl_aux}
For $t\in[0,T]$, suppose $P^*(t,\cdot)$ is the optimal exploratory portfolio selection for original problem \eqref{model_rl}. 
Then, $P^*(t,\cdot)$ is also optimal for auxiliary problem \eqref{model_rl_aux} with $\tau=1+2\gamma {\rm E}\Big(\widetilde{W}_T^*\Big)$.
\end{lemma}

\begin{proof}
See Appendix \ref{app:rl_aux}.
\end{proof}


According to Lemma \ref{le:rl_aux}, any optimal solution of model \eqref{model_rl} can be found via solving the stochastic linear-quadratic model \eqref{model_rl_aux}.
Hence, in the following of this paper, we focus on model \eqref{model_rl_aux}.
%we focus on the stochastic linear-quadratic problem \eqref{model_rl_aux}.
For $\forall(t,w)\in[0,T]\times \mathbb{R}$, we define the optimal value function
\begin{equation}\label{model_rl_aux_subproblem}
\begin{split}
	V^{*}(t,w)&=\max_{\{P(s,\cdot)\}}{\rm E}\Big(-\gamma \widetilde{W}_T^2+\tau \widetilde{W}_T\Big)
	+\lambda\int_t^T h(P(s,\cdot))ds
	%\\
	%s.t.\quad &
	%d\widetilde{W}_s = \int_{\mathbb{R}^n}\theta^\top (\mu-r) P(s,\theta) d\theta \cdot ds 
  	%+\sqrt{\int_{\mathbb{R}^n}\theta^\top\Sigma\theta P(s,\theta) d\theta} \cdot d\widetilde{B}_s\\
	%&\widetilde{W}_t=w
\end{split}
\end{equation}
with $h(P(s,\cdot))$, $s\in[t,T]$, defined in \eqref{equ:entropy}.
Following the principle of dynamic programming, we deduce that $V^*(t,w)$ satisfies the Hamilton-Jacobi-Bellman (HJB) equation
\begin{equation}\label{equ:HJB}
\begin{split}
  -\dfrac{\partial V^*}{\partial t}(t,w)
	=&\max_{P(t,\cdot)}\Big\{ \lambda  h(P(t,\cdot))\\
	&+\dfrac{\partial V^*}{\partial w}(t,w)\int_{\mathbb{R}^n}\theta^\top (\mu-r) P(t,\theta) d\theta
  +\dfrac{1}{2}\dfrac{\partial^2 V^*}{\partial w^2}(t,w)\int_{\mathbb{R}^n}\theta^\top\Sigma\theta P(t,\theta) d\theta\Big\}
\end{split}
\end{equation}
with the terminal condition $V^*(T,w)=-\gamma w^2+\tau w$.
Then, applying the high dimensional Euler-Lagrange equation \citep{Liberzon2012Calculus} to HJB equation \eqref{equ:HJB}, the optimal exploratory portfolio selection $P^*(t,\theta)$ can be obtained in Theorem \ref{th:v_theta_n}.

\begin{theorem}\label{th:v_theta_n}
For $\forall(t,w) \in [0,T] \times \mathbb{R}$, the optimal exploratory portfolio selection of model \eqref{model_rl_aux} is Gaussian, whose density function is
\begin{equation}\label{equ:theta_n}
	P^*(t,\cdot)
	=\mathcal{N}\Big((\dfrac{\tau}{2\gamma}-w)\Sigma^{-1}(\mu-r),\dfrac{\lambda}{2}\dfrac{e^{K(t,T)\cdot (T-t)}}{\gamma}\Sigma^{-1}\Big).
\end{equation}
The corresponding optimal value function is given by
\begin{equation}\label{equ:V_n}
\begin{split}
	V^*(t,w)
	&=-\gamma e^{-K(t,T)\cdot (T-t)}\left(w - \frac{\tau}{2\gamma}\right)^2
	+\frac{\tau^2}{4\gamma}\\
	&+\frac{\lambda n}{2}\int_{t}^{T}\left[\ln\left(\frac{\pi\lambda}{\gamma}\right)+\frac{1}{n}\ln(|\Sigma^{-1}|)+K(s,T)\cdot(T-s)\right]ds
	%&=-\gamma e^{-K(t,T)\cdot (T-t)}(w-\dfrac{e^{K(0,T)\cdot T}+2\gamma w^o}{2\gamma})^2
	%+\gamma(\dfrac{e^{K(0,T)\cdot T}+2\gamma w^o}{2\gamma})^2\\
	%&+\dfrac{\lambda n}{2}\int_t^T [\ln(\dfrac{\pi\lambda}{\gamma})
	%+\dfrac{1}{n}\ln(|\Sigma^{-1}|)+K(s,T)\cdot(T-s)] ds
\end{split}
\end{equation}
with $K(t,T)$ and $K(s,T)$ defined in \eqref{equ:K}.
Moreover, $\tau=e^{K(0,T)\cdot T}+2\gamma w^o$.
\end{theorem}
\begin{proof}
	See Appendix \ref{app:v_theta_n}.
\end{proof}


