In the common practice within the field of RL algorithm, the (exploratory) portfolio selection is usually parameterized with (deep) neural networks \citep{Coache2024Reinforcement, Duarte2024Machine}.
Thanks to Theorem \ref{th:v_theta_n} and Theorem \ref{th:sac}, 
at time $t$, we can parameterize the one-dimensional exploratory portfolio selection, which only consists of the riskless asset and the $i$-th risky asset, with the explicit expression:
\begin{equation}
\label{equ:para_p_i}
	p(t,\theta;\phi^{(i)})
	=\mathcal{N}\Big((\dfrac{\phi_1^{(i)}}{2\gamma}-w)
		\phi_4^{(i)}
	\phi_3^{(i)},\dfrac{\lambda}{2}\dfrac{e^{\phi_2^{(i)}\cdot(T-t)}}{\gamma}
	\phi_4^{(i)}
\Big),
\end{equation}
where $\phi^{(i)}=\{\phi_1^{(i)},\phi_2^{(i)},\phi_3^{(i)},\phi_4^{(i)}\}$.
Comparing the expression of $p(t,\theta;\phi^{(i)})$ with the optimal exploratory portfolio selection $P^*(t,\cdot)$ in Theorem \ref{th:v_theta_n}, 
we conclude that,
$\phi_1^{(i)}$, $\phi_2^{(i)}$, $\phi_3^{(i)}$ and $\phi_4^{(i)}$ 
are introduced to learn
$K^{(i)}(0,T)$, $K^{(i)}(t,T)$, $\mu^{(i)}-r$ and $(\sigma^{(i)})^2$, i.e.,
\begin{align}\label{equ:phi_ki}
	\phi_1^{(i)} = e^{K^{(i)}(0,T)\cdot T}+2\gamma w^o,\quad
	\phi_2^{(i)} = K^{(i)}(t,T),\quad
	\phi_3^{(i)} = \mu^{(i)}-r,\quad
	\phi_4^{(i)} = \frac{1}{{(\sigma^{(i)})^2}}.
\end{align}
%\begin{align*}
%%	K^{(i)}(0,T) = 
%	\dfrac{\ln( \phi_1^{(i)}-2\gamma w^o)}{T},\quad
%%	K^{(i)}(t,T) = 
%	\phi_2^{(i)},\quad
%%	\mu^{(i)}-r = 
%	\phi_3^{(i)},\quad
%%	(\sigma^{(i)})^2 = 
%	\frac{1}{{\phi_4^{(i)}}}.
%\end{align*}
respectively. And, $\phi_3^{(i)}$ is what we need to obtain.

%In this one-dimensional policy evaluation and policy improvement procedures, 
%we start from some initialized values for $\phi^{(i)}$ and then update them iteratively.

%\begin{itemize}
%\item
%$K^{(i)}(0,T)$ can be estimated by $\dfrac{\ln( \phi_1^{(i)}-2\gamma w^o)}{T}$.
%\item
%$K^{(i)}(t,T)$ can be estimated by $\phi_2^{(i)}$.
