As known in Section \ref{se:alg_convergence}, the learning process consists of the iterative procedures of policy evaluation and policy improvement.
We start from some initialized values for $\phi^{(i)}$ and then update them iteratively.
For the policy evaluation, given $\phi^{(i)}$, according to Lemma \ref{le:policy_evaluation}, 
the corresponding value function $v^p(t,w)$ is not only related to $p(t,\theta;\phi^{(i)})$ but also to the true value of return rate $\mu^{(i)}(t)$ and volatility $\sigma^{(i)}(t)$ which cannot be obtained directly.
In order to implement the policy evaluation, at time $t$,
according to the form of \eqref{equ:V_n},
we parameterize the corresponding value functions $v^p(t,w)$ as
\begin{equation}
\label{equ:para_v_i}
	v(t,w;\psi^{(i)})
	=-\gamma e^{-\psi_2^{(i)}\cdot(T-t)}(w-\dfrac{\psi_1^{(i)}}{2\gamma})^2+\psi_3^{(i)}+\dfrac{\lambda}{2}\psi_4^{(i)},
\end{equation}
and choose $\psi^{(i)} = \{\psi_1^{(i)},\psi_2^{(i)},\psi_3^{(i)},\psi_4^{(i)}\}$
such that $v(t,w;\psi^{(i)})$ could approximate $v^p(t,w)$ with the available data of the $i$-th risky asset prices.

It is noticed that the value function $v^p(t,w)$
satisfies the dynamic programming
\begin{equation}\label{equ:bellman}
	{\rm E}_{t}\Big(\dfrac{v^p(t+\Delta t,\widetilde{W}_{t+\Delta t})-v^p(t,\widetilde{W}_{t})}{\Delta t}\Big)+\lambda h(p(t,\theta;\phi^{(i)})) = 0
\end{equation}
By collecting $M$ samples for the time-series data of the return rate of the $i$-th risky asset
\begin{equation*}
\{R^{(i,1)},\dots,R^{(i,M)}\},
\end{equation*}
the left-hand side of the dynamic programming \eqref{equ:bellman} can be calculated numerically.
Specifically, for the $k$-th sample, we generate an allocation $\theta_{t}^{(i,k)}$ under the given exploratory portfolio selection $p(t,\theta;\phi^{(i)})$.
%In financial market \eqref{equ:S}, the return rate of risky asset is assumed to be independent identically distributed.
The discounted wealth at $t+\Delta t$ time can be simulated by
\begin{align}\label{equ:dW_i}
	W_{t+\Delta t}^{(i,k)}=W_{t}^{(i)}+R^{(i,k)}\theta_{t}^{(i,k)}.
\end{align}
Then, the left-hand side of the dynamic programming \eqref{equ:bellman}
is approximated by
\begin{align*}%\label{equ:loss_app_i}
	\delta_t:=
	\dfrac{1}{M}\sum_{k=1}^M \dfrac{v(t+\Delta t,W_{t+\Delta t}^{(i,k)};\psi^{(i)})-v(t,W_{t};\bar{\psi}^{(i)})}{\Delta t}
	+\lambda h(p(t,\theta;\phi^{(i)})),
\end{align*}
where $\bar{\psi}^{(i)}$ is the set of parameters in value function \eqref{equ:para_v_i} learned at last time point.
Hence, we define the loss function
\begin{align*}%\label{equ:loss}
	L_{t}(\psi^{(i)},\bar{\psi}^{(i)},\phi^{(i)})
	=\dfrac{\Delta t}{2}\delta_{t}^2,
\end{align*}
and update the parameterized value function by
\begin{align}\label{equ:min}
	\psi^{(i)}\leftarrow\arg\min_{\psi^{(i)}} ~L_{t}(\psi^{(i)},\bar{\psi}^{(i)},\phi^{(i)}).
\end{align}


When it comes to the policy improvement, we update the exploratory portfolio selection $p(t,\theta;\phi^{(i)})$ under given updated parameters in $\psi^{(i)}$.
At time $t$, according to Lemma \ref{le:policy_improvement}, the exploratory portfolio selection can be improved into
\begin{align}\label{equ:policy_improvement_i}
	\mathcal{N}\Big((\dfrac{\psi_1^{(i)}}{2\gamma}-w)\dfrac{\mu^{(i)}(t)-r}{(\sigma^{(i)}(t))^2},\dfrac{\lambda}{2}\dfrac{e^{\psi_2^{(i)}(T-t)}}{\gamma}\dfrac{1}{(\sigma^{(i)}(t))^2}\Big).
\end{align}
Comparing \eqref{equ:policy_improvement_i} with 
the parametric form of the exploratory portfolio selection \eqref{equ:para_p_i}, we conduct that the parameters in $p(t,\theta;\phi^{(i)})$ are updated by
\begin{equation}\label{equ:update_phi12_i}
\begin{split}
	\phi_1^{(i)}\leftarrow\psi_1^{(i)},\qquad
	\phi_2^{(i)}\leftarrow\psi_2^{(i)},\qquad
	\phi_4^{(i)}\leftarrow\dfrac{1}{(\widehat{\sigma}^{(i)}(t))^2},
\end{split}
\end{equation}
in which $\widehat{\sigma}^{(i)}(t)$ is obtained by maximum likelihood estimation (MLE) \citep{Campbell1996Econometrics}.
%And $\phi_3^{(i)},\phi_4^{(i)}$ can not be updated according to the policy improvement theorem directly.
What's more, following \cite{Wang2020Continuous}, 
when given $\phi_1^{(i)}$, $\phi_2^{(i)}$ and $\phi_4^{(i)}$,
the parameter $\phi_3^{(i)}$ can be updated by
\begin{equation}\label{equ:update_phi3_i}
	\phi_3^{(i)}\leftarrow\arg\max_{\phi_3^{(i)}} L_{t}(\psi^{(i)},\bar{\psi}^{(i)},\phi^{(i)}).
\end{equation}
The pseudocode of iterative learning procedure for $\mu^{(i)}-r$ is summarized in Algorithm \ref{alg:mu_r}.
After learned $\mu^{(i)}-r$ for each risky asset,
the excess expected return vector is assembled by
\begin{equation}\label{equ:phi3_combine}
	\mu-r\leftarrow\begin{bmatrix} \phi_3^{(1)},\dots,\phi_3^{(n)} \end{bmatrix}^\top.
\end{equation}

\renewcommand{\algorithmicrequire}{\textbf{Input:}}
\renewcommand{\algorithmicensure}{\textbf{Output:}}
\begin{breakablealgorithm}\label{alg:mu_r}
\caption{The Learning Process of $\mu^{(i)}-r$}
\begin{algorithmic}[1]
\REQUIRE 
The initialized parameters $\phi^{(i)}$ in exploratory portfolio selection;
The initialized parameters $\psi^{(i)}$ in the value function;
The $t$ time discounted wealth $W_{t}$;
The time-series data of return rates of the $i$-th risky asset $\{R^{(i,1)},\dots,R^{(i,M)}\}$.
\ENSURE 
The learned parameter $\mu^{(i)}-r=\phi_3^{(i)}$.
\renewcommand{\algorithmicensure}{\textbf{Procedure:}}
\ENSURE  
%\STATE{Set the number of iterations $N_{iter}$.}
%\FOR {$iter=1:N_{iter}$}
\FOR {$k=1:M$}
	\STATE{Sample an allocation $\theta_{t}^{(i,k)}\sim p(t,W_{t},\theta;\phi^{(i)})$.}
	%\STATE{Simulate the next time return rate of the $j$-th risky asset with $R_{t+\Delta t}^{(j,k)}=R^{(j,k)}$.}
	\STATE{Simulate the discounted wealth $W_{t+\Delta t}^{(i,k)}$ using $R^{(i,k)}$ with \eqref{equ:dW_i}.}
\ENDFOR
\STATE{Update the parameters $\psi^{(i)}$ in the value function with \eqref{equ:min}.}
\STATE{Update the parameters $\phi^{(i)}$ in the exploratory portfolio selection with \eqref{equ:update_phi12_i} and \eqref{equ:update_phi3_i}.}
%\ENDFOR
\end{algorithmic}
\end{breakablealgorithm}


\subsection{Learning the average profitability of risky assets}\label{se:alg}


After obtained the estimation of excess expected return vector $\widehat{\mu}-r$ and inverse covariance matrix $\widehat{\Sigma}^{-1}$, in this section, we focus on the learning process of $K(0,T)$ to complete the multi-asset MV optimization framework.
And, a $n$-dimensional algorithm, which operates through the iterative process of policy evaluation and policy improvement presented in Section \ref{se:alg_convergence} with $n$ risky assets, is designed.


At time $t$, we parameterize the multi-asset exploratory portfolio selection with an explicit expression:
\begin{equation}\label{equ:para_p}
	p(t,\theta;\phi)
	=\mathcal{N}\Big((\dfrac{\phi_1}{2\gamma}-w)
		\widehat{\Sigma}^{-1}(\widehat{\mu}-r),
	\dfrac{\lambda}{2}\dfrac{e^{\phi_2\cdot(T-t)}}{\gamma}\widehat{\Sigma}^{-1}\Big),
\end{equation}
{\comm where $\phi=\{\phi_1,\phi_2\}$.}
Comparing the expression of $p(t,\theta;\phi)$ with the optimal multi-asset exploratory portfolio selection $P^*(t,\cdot)$ in Theorem \ref{th:v_theta_n}, 
we conclude that, $\phi_1$ is introduced to learn $K(0,T)$, and $\phi_2$ is introduced to learn $K(t,T)$
\begin{align}\label{equ:phi_k}
	\phi_1 = e^{K(0,T)\cdot T}+2\gamma w^o,\quad
	\phi_2 = K(t,T).
\end{align}
%, which does not affect the optimal multi-asset MV portfolio selection \eqref{equ:theta_n_cl} and only plays a role in the $n$-dimensional algorithm.


For the policy evaluation, similar to the approach in Section \ref{se:mu_r}, we approximate the value function of the multi-asset exploratory portfolio selection \eqref{equ:para_p} with
\begin{equation}\label{equ:para_v}
	v(t,w;\psi)
	=-\gamma e^{-\psi_2\cdot(T-t)}(w-\dfrac{\psi_1}{2\gamma})^2+\psi_3+\dfrac{\lambda}{2}\psi_4,
\end{equation}
where $\psi=\{\psi_1,\psi_2,\psi_3,\psi_4\}$.
As the historical data of risky asset prices can be reused,
we collect $M$ samples for time-series data of the return rate of $n$ risky assets
\begin{align*}
	\{R^1,\dots,R^M\},
\end{align*}
in which $R^k=\begin{bmatrix} R^{(1,k)} &\cdots &R^{(n,k)} \end{bmatrix}^\top\in\mathbb{R}^{n\times 1}, k=1,\dots,M$.
For the $k$-th sample, we generate an allocation $\Theta_{t}^k\in\mathbb{R}^{n\times 1}$ under the given multi-asset exploratory portfolio selection $p(t,\theta;\phi)$, and simulate the discounted wealth at $t+\Delta t$ time with
\begin{equation}\label{equ:dW}
	W_{t+\Delta t}^k=W_{t}+(R^k)^\top\Theta_{t}^{k}.
\end{equation}
By defining
\begin{equation*}
	\delta_{t}(\psi,\bar{\psi},\phi)
	=\dfrac{1}{M}\sum_{k=1}^M \dfrac{v(t+\Delta t,W_{t+\Delta t}^k;\psi)-v(t,W_{t};\bar{\psi})}{\Delta t}
	+\lambda h(p(t,\theta;\phi))
\end{equation*}
and the loss function
\begin{equation*}
	L_{t}(\psi,\bar{\psi},\phi)
	=\dfrac{\Delta t}{2}
	\delta_t^2,
\end{equation*}
in which $\bar{\psi}$ is the set of parameters in value function \eqref{equ:para_v} learned at last time point,
the parameterized value function can be updated by
\begin{align}\label{equ:multi_min}
	\psi\leftarrow\arg\min_{\psi} ~L_{t}(\psi,\bar{\psi},\phi).
\end{align}



For the policy improvement in the $n$-dimensional algorithm, under given updated parameters in $\psi$, according to Lemma \ref{le:policy_improvement}, the multi-asset exploratory portfolio selection can be improved into
\begin{align}\label{equ:policy_improvement}
	\mathcal{N}\Big((\dfrac{\psi_1}{2\gamma}-w)
		\widehat{\Sigma}^{-1}(\widehat{\mu}-r),
	\dfrac{\lambda}{2}\dfrac{e^{\psi_2(T-t)}}{\gamma}\widehat{\Sigma}^{-1}\Big).
\end{align}
Comparing \eqref{equ:policy_improvement} with 
the parametric form in \eqref{equ:para_p}, we conduct that the parameters in multi-asset exploratory portfolio selection $p(t,\theta;\phi)$ are updated by
\begin{align}\label{equ:update_phi}
	\phi_1\leftarrow\psi_1,
	\qquad
	\phi_2\leftarrow\psi_2.
\end{align}
Thus, at time $t$, the pseudocode of iterative learning procedure for $K(0,T)$ can be summarized in Algorithm \ref{alg:K}.
%We stress that the average profitability of the $n$ risky assets $K(0,T)$ is learned by $\phi_1$ in Algorithm \ref{alg:K}.
%After completing the learning process of $\phi_1$, the optimal multi-asset MV portfolio selection \eqref{equ:theta_n_cl} can be implement, which is the expectation of the exploratory portfolio selection \eqref{equ:para_p}.
\renewcommand{\algorithmicrequire}{\textbf{Input:}}
\renewcommand{\algorithmicensure}{\textbf{Output:}}
\begin{breakablealgorithm}\label{alg:K}
\caption{The Learning Process of $K(0,T)$}
\begin{algorithmic}[1]
\REQUIRE 
The values of $\widehat{\mu}-r$ and $\widehat{\Sigma}^{-1}$;
The initialized parameters $\phi_1,\phi_2$;
The initialized parameters $\psi_1,\psi_2,\psi_3,\psi_4$;
The $t$ time discounted wealth $W_{t}$;
The time-series data of returns rates $\{R^1,\cdots,R^M\}$.
\ENSURE 
The learned parameter $K(0,T) = \frac{1}{T}\ln( \phi_1-2\gamma w^o)$.
\renewcommand{\algorithmicensure}{\textbf{Procedure:}}
\ENSURE  
%\STATE{Set $\psi=(\psi_1,\psi_2,\psi_3,\psi_4)$.}
%\STATE{Set the number of iterations $N_{iter}$.}
%\FOR {$iter=1:N_{iter}$}
\FOR {$k=1:M$}
	\STATE{Sample an allocation $\Theta_{t}^k\sim p(t,W_{t},\theta;\phi)$.}
	%\STATE{Simulate the next time return rate $R_{t+\Delta t}^k$ with \eqref{equ:simulate_S}.}
	\STATE{Simulate the next time discounted wealth $W_{t+\Delta t}^k$ using $R^k$ with \eqref{equ:dW}.}
\ENDFOR
\STATE{Update the parameters $\psi$ in the value function with \eqref{equ:multi_min}.}
\STATE{Update the parameters $\phi$ in the exploratory portfolio selection with \eqref{equ:update_phi}.}
%\ENDFOR
\end{algorithmic}
\end{breakablealgorithm}



Finally, we can develop the online SAC algorithm, Algorithm \ref{alg:online}, for learning the continuous-time multi-asset MV portfolio selection in a discrete-time setting. 
We divide the investment horizon $[0,T]$ into $N$ time intervals $[t_j,t_{j+1})$, $j = 0, 1, \dots, N-1$, where $t_0 = 0$ and $t_N = T$.
At each time point, the portfolio selection is implemented with the currently learned parameters, and the wealth at the next time point is obtained.
We reiterate that the exploratory portfolio selections are used for learning, and the mean of the learned multi-asset exploratory portfolio selection is used when implementing.


In Algorithm \ref{alg:online}, parameters are updated every $m$ time points.
When performing the updates,
we use the values obtained from the previous update as the initial values for the current update.
For the $i$-th risky asset, Algorithm \ref{alg:mu_r} is called to learn $\mu^{(i)}-r$.
Subsequently, $\widehat{\mu}-r$ is obtained by \eqref{equ:phi3_combine},
and $\widehat{\Sigma}^{-1}$ is obtained by the shrinking technique in \cite{Shi2020Improving}. 
Thereafter, $\widehat{\mu}-r$ and $\widehat{\Sigma}^{-1}$ are then used as inputs for Algorithm \ref{alg:K},
and all the parameters in optimal multi-asset MV portfolio selection \eqref{equ:theta_n_cl} can be learned.



\renewcommand{\algorithmicrequire}{\textbf{Input:}}
\renewcommand{\algorithmicensure}{\textbf{Output:}}
\begin{breakablealgorithm}\label{alg:online}
\caption{The Optimal multi-asset MV Portfolio Selection with Online SAC Algorithm}
\begin{algorithmic}[1]
\REQUIRE 
Investment horizon $T$;
Time intervals $[t_j,t_{j+1})$, $j = 0, 1, \dots, N-1$;
Initial Wealth $w^{o}$. %$W_{t_0}$.
\ENSURE 
The optimal multi-asset MV portfolio selection process $\{\Theta_{t_j}^*\}_{j=0}^{N-1}$;
The corresponding wealth process $\{W_{t_j}\}_{j=0}^N$.
\renewcommand{\algorithmicensure}{\textbf{Procedure:}}
\ENSURE 
%\STATE{Initialize parameters $\phi=\{\phi_1,\phi_2,{\bm \phi_3},{\bm \Phi_4}\}$.}
%\STATE{Initialize parameters $\psi=\{\psi_1,\psi_2,\psi_3,\psi_4\}$.}
\STATE{Set the learning cycle $m$.}
\FOR {$j=0:(N-1)$}
\IF {$j \equiv 0 \pmod{m}$}
\FOR {$i=1:n$}
	\STATE{Update $\phi_3^{(i)}$ by Algorithm \ref{alg:mu_r}.}
\ENDFOR
	\STATE{Set $\widehat{\mu}-r\leftarrow\begin{bmatrix} \phi_3^{(1)},\dots,\phi_3^{(n)} \end{bmatrix}^\top$.}
	\STATE{Estimate $\widehat{\Sigma}^{-1}$ by the shrinking technique in \cite{Shi2020Improving}.}
	\STATE{Update $\phi_1$ by Algorithm \ref{alg:K} with $\widehat{\mu}-r$ and $\widehat{\Sigma}^{-1}$.}
\ENDIF
\STATE{Implement the optimal multi-asset MV portfolio selection at $t_j$ time by
\vspace{-.5em}
\begin{equation*}
	\Theta_{t_j}^*=(\dfrac{\phi_1}{2\gamma}-W_{t_j})\widehat{\Sigma}^{-1}(\widehat{\mu}-r).
\end{equation*}
\vspace{-1em}}
\STATE{Observe the discounted wealth $W_{t_{j+1}}$ at time $t_{j+1}$ from the financial market.}
\ENDFOR
\end{algorithmic}
\end{breakablealgorithm}


