\section{The discounted wealth process under the exploratory MV problem}\label{app:wealth_RL}

Following \cite{Wang2019Exploration}, the theoretical framework for exploratory is same inspired by repetitive learning. %, however, there are differences when consider the portfolio selection with $n$ risky assets.
From the law of large numbers, $N$ independent copies of wealth processes $\{W_t^k\}^{k=1,\dots,N}_{0 \leqslant t \leqslant T}$ are considered simultaneously.
At each $k$, ($k=1,\dots,N$), portfolio selection $\{\Theta_t^k\}_{0 \leqslant t \leqslant T}$ is sampled under the probability density function $\{P(t,\cdot)\}_{0 \leqslant t \leqslant T}$
and is executed to obtain its corresponding copy of wealth processes $\{W_t^k\}_{0 \leqslant t \leqslant T}$ by \eqref{equ:W_CL}.
Then, at time $t$, the drift term and the diffusion term in $\{\widetilde{W}_t\}_{0 \leqslant t \leqslant T}$ are calculated by
\begin{align*}
&{\rm E}\Big(\Delta \widetilde{W}_t\Big)
=\lim\limits_{N\to+\infty}\dfrac{1}{N}\sum_{k=1}^N\Big(\Delta  W_t^k\Big)
=\lim\limits_{N\to+\infty}\dfrac{1}{N}\sum_{k=1}^N\Big((\Theta_t^k)^\top(\mu-r) \cdot \Delta t 
+(\Theta_t^k)^\top D \Delta B_t^k \Big),\\
&{\rm E}\Big((\Delta \widetilde{W}_t)^2\Big)
=\lim\limits_{N\to+\infty}\dfrac{1}{N}\sum_{k=1}^N\Big( (\Delta  W_t^k)^2 \Big)
=\lim\limits_{N\to+\infty}\dfrac{1}{N}\sum_{k=1}^N\Big( (\Theta_t^k)^\top D \Delta B_t^k (\Delta B_t^k)^\top D^\top \Theta_t^k \Big),
\end{align*}
in which $\Delta B_t^k\in\mathbb{R}^{n\times 1}$ is the random increment of $n$ risky assets in \eqref{equ:S}.
Because of
\begin{align*}
&\lim\limits_{N\to+\infty}\dfrac{1}{N}\sum_{k=1}^N\Big( \Delta B_t^k \Big)
={\rm E}\Big(\Delta B_t\Big)
=0,\\
&\lim\limits_{N\to+\infty}\dfrac{1}{N}\sum_{k=1}^N\Big( B_t^k (\Delta B_t^k)^\top \Big)
=L\cdot\Delta t,
\end{align*}
we have
\begin{align*}
&{\rm E}\Big(\Delta \widetilde{W}_t\Big)
=\int_{\mathbb{R}^n}\theta^\top (\mu-r) P(t,\theta) d\theta \cdot \Delta t
+\int_{\mathbb{R}^n}\theta^\top D P(t,\theta) d\theta {\rm E}(\Delta B_t)
=\int_{\mathbb{R}^n}\theta^\top (\mu-r) P(t,\theta) d\theta \cdot \Delta t,\\
&{\rm E}\Big((\Delta \widetilde{W}_t)^2\Big)
=\int_{\mathbb{R}^n}\theta^\top D L D^\top \theta P(t,\theta) d\theta \cdot \Delta t
=\int_{\mathbb{R}^n}\theta^\top\Sigma\theta P(t,\theta) d\theta \cdot \Delta t.
\end{align*}
In this way, the discounted wealth process in the exploratory MV problem can be define as
\begin{equation*}
	d\widetilde{W}_t 
	= \int_{\mathbb{R}^n}\theta^\top (\mu-r) P(t,\theta) d\theta \cdot dt 
	+\sqrt{\int_{\mathbb{R}^n}\theta^\top\Sigma\theta P(t,\theta) d\theta} \cdot d\widetilde{B}_t
\end{equation*}
in which $\{\widetilde{B}_t\}_{0 \leqslant t \leqslant T}$ is the standard one-dimensional Brownian motion.
\fi

\section{The Proof of Theorem \ref{th:K_k}}\label{app:K_k}

When model parameters $\mu$ and $\Sigma$ are time-independent, the average (current) profitability of $n$ risky assets remains constant, i.e., 
	$K(t,T)=A(t)=K$.
Similarly, the average (current) profitability of the $i$-th risky asset is also constant, i.e., 
\begin{align*}
	K^{(i)}(t,T)=A^{(i)}(t)=K^{(i)}, \qquad i=1,\dots,n.
\end{align*}
According to the definition of average profitability of $n$ risky assets in \eqref{equ:K}, we have
\begin{equation*}%\label{equ:K_A}
	K=(\mu-r)^\top\Sigma^{-1}(\mu-r)
	=(\mu-r)^\top (D L D^\top)^{-1} (\mu-r).
\end{equation*}
On the other hand, we have 
	$\mu^{(i)}-r=\sqrt{K^{(i)}}\sigma^{(i)}$
then the Equation \eqref{equ:K_k} in Theorem \ref{th:K_k} can be obtained.



\section{The Proof of Lemma \ref{le:rl_aux}}\label{app:rl_aux}

We proof Lemma \ref{le:rl_aux} by contradiction.
We assume that $\{P^*(t,\cdot)\}_{0\leqslant t\leqslant T}$, is the optimal exploratory portfolio selection in problem \eqref{model_rl} but not the optimal one in auxiliary problem \eqref{model_rl_aux}.
Then, there exists $\{P(t,\theta)\}_{0\leqslant t\leqslant T}$ such that
\begin{equation}\label{equ:con}
\begin{split}
	{\rm E}\Big(-\gamma (\widetilde{W}_T^*)^2+\tau \widetilde{W}_T^*+\lambda \mathcal{H}(P^*(\cdot,\cdot))\Big)
	<{\rm E}\Big(-\gamma \widetilde{W}_T^2+\tau \widetilde{W}_T+\lambda \mathcal{H}(P(\cdot,\cdot))\Big).
\end{split}
\end{equation}
Next, we will proof that the objective function in \eqref{model_rl_aux} with $\{P(t,\theta)\}_{0\leqslant t\leqslant T}$ will become larger than that with $P^*(t,\theta)_{0\leqslant t\leqslant T}$.

It is observed that
\begin{align*}
	f(x,y)=-\gamma x+\gamma y^2+y, \quad \mbox{ with }\gamma>0,
\end{align*}
is a convex function, i.e., 
\begin{align*}
  f(x,y)\geqslant f(x_0,y_0)+f_x(x_0,y_0)\cdot(x-x_0)+f_y(x_0,y_0)\cdot(y-y_0).
\end{align*}
Setting $x={\rm E}(\widetilde{W}_T^2), y={\rm E}(\widetilde{W}_T), x_0={\rm E}(\widetilde{W}_T^*)^2, y_0={\rm E}(\widetilde{W}_T^*)$, 
we have 
\begin{equation*}%\label{equ:inequ}
\begin{split}
	&f({\rm E}(\widetilde{W}_T^2),{\rm E}(\widetilde{W}_T))\\
  	\geqslant &f({\rm E}((\widetilde{W}_T^*)^2),{\rm E}(\widetilde{W}_T^*))-\gamma({\rm E}(\widetilde{W}_T^2)-{\rm E}((\widetilde{W}_T^*)^2))+(2\gamma {\rm E}(\widetilde{W}_T^*)+1)({\rm E}(\widetilde{W}_T)-{\rm E}(\widetilde{W}_T^*)).
\end{split}
\end{equation*}
Because of $f({\rm E}(\widetilde{W}_T^2),{\rm E}(\widetilde{W}_T))={\rm E}(\widetilde{W}_T)-\gamma {\rm Var}(\widetilde{W}_T)$,
we have %the inequation \eqref{equ:inequ} becomes
\begin{equation*}%\label{equ:inequ2}
\begin{split}
  	&{\rm E}(\widetilde{W}_T)-\gamma {\rm Var}(\widetilde{W}_T) \\
	\geqslant &{\rm E}(\widetilde{W}_T^*)-\gamma {\rm Var}(\widetilde{W}_T^*)-\gamma {\rm E}(\widetilde{W}_T^2)+\gamma {\rm E}((\widetilde{W}_T^*)^2)
	+\tau {\rm E}(\widetilde{W}_T)-\tau {\rm E}(\widetilde{W}_T^*)
\end{split}
\end{equation*}
with $\tau=2\gamma {\rm E}(\widetilde{W}_T^*)+1$.
Thus, 
%according to \eqref{equ:con} and \eqref{equ:inequ2}, 
we can derive that
\begin{align*}
  	&{\rm E}(\widetilde{W}_T)-\gamma {\rm Var}(\widetilde{W}_T)
	+\lambda \mathcal{H}(P(\cdot,\cdot))\\
	\geqslant &{\rm E}(\widetilde{W}_T^*)-\gamma {\rm Var}(\widetilde{W}_T^*)-\gamma {\rm E}(\widetilde{W}_T^2)+\tau {\rm E}(\widetilde{W}_T)
	+\gamma {\rm E}((\widetilde{W}_T^*)^2)-\tau {\rm E}(\widetilde{W}_T^*)
	+\lambda \mathcal{H}(P(\cdot,\cdot))\\
  	> &{\rm E}(\widetilde{W}_T^*)-\gamma {\rm Var}(\widetilde{W}_T^*)
	+\lambda \mathcal{H}(P^*(\cdot,\cdot))
\end{align*}
which is contradictory to our assumptions that $P^*(t,\theta)$ is the optimal exploratory portfolio selection in problem \eqref{model_rl}.



\section{The Proof of Theorem \ref{th:v_theta_n}}\label{app:v_theta_n}

The derivation is divided into two parts:

1.
We first apply the high dimensional Euler-Lagrange theorem \citep{Kot2014First} to HJB equation \eqref{equ:HJB},
and derive the relationship between the optimal exploratory portfolio selection and parameter $\tau$.

According to HJB equation \eqref{equ:HJB}, the optimal exploratory portfolio selection $P^*(t,\theta)$ can be obtained by solving a constrained optimization problem:
\begin{align*}
  &\max_{P(t,\cdot)} \int_{\mathbb{R}^n} \Big(
  -\lambda \ln{P(t,\theta)}
  +\dfrac{\partial V}{\partial w}(t,w)\theta^\top (\mu-r)
  +\dfrac{1}{2}\dfrac{\partial^2 V}{\partial w^2}(t,w)\theta^\top\Sigma\theta\Big)P(t,\theta) d\theta\\
	&s.t. ~\int_{\mathbb{R}^n}P(t,\theta) d\theta=1.
\end{align*}
Thus, $P^*(t,\theta)$ satisfies
\begin{align*}
  -\lambda \ln{P^*(t,\theta)}
  +\dfrac{\partial V}{\partial w}(t,w)\theta^\top (\mu-r)
  +\dfrac{1}{2}\dfrac{\partial^2 V}{\partial w^2}(t,w)\theta^\top\Sigma\theta -k
  -\lambda =0,
\end{align*}
where $k$ is the Lagrange multiplier.
And, it follows that
\begin{align*}
	P^*(t,\theta)
	=\dfrac{{\rm exp}\Big(\frac{1}{\lambda}\Big(\frac{\partial V}{\partial w}(t,w)\theta^\top (\mu-r) +\frac{1}{2}\frac{\partial^2 V}{\partial w^2}(t,w)\theta^\top\Sigma\theta\Big)\Big)}
	{\int_{\mathbb{R}^n}{\rm exp}\Big(\frac{1}{\lambda }\Big(\frac{\partial V}{\partial w}(t,w)\theta^\top (\mu-r) +\frac{1}{2}\frac{\partial^2 V}{\partial w^2}(t,w)\theta^\top\Sigma\theta\Big)\Big) d\theta}.
\end{align*}


We conjecture the value function in the form $V(t,w)=-I(t)w^2+H(t)w+G(t)$.
Then, $P^*(t,\theta)$ is the exploratory portfolio selection with multivariate normal distribution 
\begin{align}\label{equ:multi_normal_distribution}
	\mathcal{N}\Big((\dfrac{H(t)}{2I(t)}-w)\Sigma^{-1}(\mu-r),\dfrac{\lambda}{2I(t)}\Sigma^{-1}\Big).
\end{align}
%and
%\begin{align*}
%	&h(P^*(t,\cdot))
%	=\dfrac{n}{2}\ln{(2\pi e)}+\dfrac{n}{2}\ln{\dfrac{\lambda}{2I(t)}}+\dfrac{1}{2}\ln{|\Sigma^{-1}|}\\
%	&\int_{\mathbb{R}^n}\theta^\top (\mu-r) P^*(t,\theta) d\theta
%	=-(w-\dfrac{H(t)}{2I(t)})(\mu-r)^\top\Sigma^{-1} (\mu-r)\\
%	&\hspace{+4.3cm}
%	=-(w-\dfrac{H(t)}{2I(t)})A(t)\\
%	&\int_{\mathbb{R}^n}\theta^\top\Sigma\theta P^*(t,\theta) d\theta
%	=(w-\dfrac{H(t)}{2I(t)})^2(\mu-r)^\top\Sigma^{-1} \Sigma \Sigma^{-1}(\mu-r)+{\rm tr}(\dfrac{\lambda}{2I(t)}\Sigma\Sigma^{-1})\\
%	&\hspace{+3.5cm}
%	=(w-\dfrac{H(t)}{2I(t)})^2A(t)+\dfrac{\lambda n}{-2I(t)}
%\end{align*}
%with $A(t)$ defined in \eqref{equ:K}.
%
%
By substituting the above value function and exploratory portfolio selection back into the HJB equation \eqref{equ:HJB}, it is obtained that $I(t),H(t),G(t)$ should satisfy the ordinary differential equations
\begin{equation*}
\begin{cases}
	I^{'}(t)=-I(t)A(t)\\
	H^{'}(t)=H(t)A(t)\\
	G^{'}(t)=-\dfrac{H^2(t)}{4I(t)}A(t)-\dfrac{\lambda n}{2}\ln{\dfrac{\pi}{\lambda}}+\dfrac{\lambda n}{2}\ln(I(t))+\dfrac{\lambda}{2}\ln(|\Sigma|)
\end{cases}
\end{equation*}
with boundary conditions $I(T)=\gamma,H(T)=\tau,G(T)=0$.
Then, we calculate that
\begin{equation}\label{equ:I_H_G}
\begin{cases}
	I(t)=\gamma e^{\int_t^T -A(s) ds}\\
	H(t)=\tau e^{\int_t^T -A(s) ds}\\
	G(t)
	=\dfrac{\tau^2}{4\gamma}(1-e^{\int_t^T -A(s) ds})
	+\dfrac{\lambda n}{2}\int_t^T [\ln(\dfrac{\pi\lambda}{\gamma})
	-\dfrac{1}{n}\ln(|\Sigma|)+\int_s^T A(r)dr]ds,
\end{cases}
\end{equation}
and $H(t)$ is related to parameter $\tau$.

2.
Next, we focus on the calculation of $\tau$ with the condition $\tau=1+2\gamma {\rm E}\Big(\widetilde{W}_T^*\Big)$.

Under the exploratory portfolio selection \eqref{equ:multi_normal_distribution}, the wealth process \eqref{equ:wealth_RL} evolves as
\begin{align*}
	d\widetilde{W}_s^*
	=-\dfrac{(H(s)+2I(s)\widetilde{W}_s^*)}{2I(s)}A(s) \cdot ds
	+\sqrt{ -\dfrac{\lambda n}{2I(s)}+\dfrac{(H(s)+2I(s)\widetilde{W}_s^*)^2}{4I^2(s)}A(s)}\cdot d\widetilde{B}_s.
\end{align*}
Taking expectations on both sides of the above equation, we conclude that ${\rm E}(\widetilde{W}_s)$ satisfies the nonhomogeneous linear ordinary differential equation
\begin{align*}
	d{\rm E}(\widetilde{W}_s^*)
	={\rm E}(d\widetilde{W}_s^*)=-\dfrac{(H(s)+2I(s){\rm E}(\widetilde{W}_s^*))}{2I(s)}A(s)\cdot ds
	=\Big(-{\rm E}(\widetilde{W}_s^*)A(s)+\dfrac{\tau}{2\gamma}A(s)\Big)\cdot ds
\end{align*}
with the initial condition ${\rm E}(\widetilde{W}_0^*)=w^o$.
Thus, ${\rm E}(\widetilde{W}_s^*)$ can be expressed as
\begin{equation*}
	{\rm E}(\widetilde{W}_s^*)=e^{\int_0^s -A(t)dt}\Big( \dfrac{\tau}{2\gamma}\int_0^s A(t)e^{\int_0^t A(k)dk }dt+w^o \Big).
\end{equation*}
And, we have
\begin{equation}\label{equ:E_WT}
\begin{split}
	{\rm E}(\widetilde{W}_T^*)
	&=e^{\int_0^T -A(t)dt}\Big( \dfrac{\tau}{2\gamma}\int_0^T A(t)e^{\int_0^t A(k)dk }dt+w^o \Big)\\
	&=\dfrac{\tau}{2\gamma}
	(1-e^{\int_0^T -A(t)dt})
	+w^o e^{\int_0^T -A(t)dt}
\end{split}
\end{equation}

Substituting \eqref{equ:E_WT} back into the condition $\tau=1+2\gamma {\rm E}\Big(\widetilde{W}_T^*\Big)$, $\tau$ can be calculated as
\begin{align*}
  	\tau=e^{K(0,T)\cdot T}+2\gamma w^o
\end{align*}
with $K(0,T)$ defined in \eqref{equ:K}.
Thus, according to the above expression of $\tau$, the optimal exploratory portfolio selection \eqref{equ:multi_normal_distribution} is Gaussian with
\begin{align*}
	\mathcal{N}\Big(-(w-\dfrac{e^{K(0,T)\cdot T}+2\gamma w^o}{2\gamma})\Sigma^{-1}(\mu-r),\dfrac{\lambda}{2}\dfrac{e^{K(t,T)\cdot (T-t)}}{\gamma}\Sigma^{-1}\Big),
\end{align*}
and the corresponding value function can be expressed as
\begin{align*}
	V^*(t,w)
	&=-\gamma e^{-K(t,T)\cdot (T-t)}(w-\dfrac{e^{K(0,T)\cdot T}+2\gamma w^o}{2\gamma})^2
	+\gamma(\dfrac{e^{K(0,T)\cdot T}+2\gamma w^o}{2\gamma})^2\\
	&+\dfrac{\lambda n}{2}\int_t^T [\ln(\dfrac{\pi\lambda}{\gamma})
	-\dfrac{1}{n}\ln(|\Sigma|)+K(s,T)\cdot(T-s)] ds.
\end{align*}



