According to the Feynman-Kac formulate \citep{Oksendal2010Stochastic}, the value function $V^P(t,w)$ satisfies
\begin{equation}\label{equ:F_K}
\begin{split}
	&\dfrac{\partial V^{P}}{\partial t}(t,w)
	+\lambda h(P(t,\cdot))\\
	&+\dfrac{\partial V^{P}}{\partial w}(t,w)\int_{\mathbb{R}^n}\theta^\top (\mu-r) P(t,\theta) d\theta
	+\dfrac{1}{2}\dfrac{\partial^2 V^{P}}{\partial w^2}(t,w)\int_{\mathbb{R}^n}\theta^\top\Sigma\theta P(t,\theta) d\theta
	=0.
\end{split}
\end{equation}
When $P(t,\cdot)=\mathcal{N}\Big((a_0-w){\bm a_1},e^{a_2}{\bm A_3}\Big)$,
the PDE \eqref{equ:F_K} becomes
\begin{equation}\label{equ:FK}
\begin{split}
	&\dfrac{\partial V^{P}}{\partial t}(t,w)
	+\dfrac{\lambda n}{2}\ln{(2\pi e)}+\dfrac{\lambda}{2}\ln{|e^{a_2}{\bm A_3}|}\\
	&+\dfrac{\partial V^{P}}{\partial w}(t,w) (a_0-w){\bm a_1}^{\top}(\mu-r)
	+\dfrac{1}{2}\dfrac{\partial^2 V^{P}}{\partial w^2}(t,w)((a_0-w)^2{\bm a_1}^{\top}\Sigma{\bm a_1}+{\rm tr}(e^{a_2}{\bm A_3}\Sigma))
	=0.
\end{split}
\end{equation}
We conjecture the value function in the form $V^P(t,w)=-I^P(t)w^2+H^P(t)w+G^P(t)$.
The coefficients of the quadratic, primary and constant terms of $w$ in equation \eqref{equ:FK} are all zero,
%\begin{align*}
%	&I^{'}(t)w^2+H^{'}(t)w+G^{'}(t)
%	+\dfrac{\lambda n}{2}\ln{(2\pi e)}+\dfrac{\lambda}{2}\ln{|e^{a_2}{\bm A_3}|}\\
%	&+(2I(t)w+H(t)) (a_0-w){\bm a_1}^{\top}(\mu-r)
%	+I(t)((a_0-w)^2{\bm a_1}^{\top}\Sigma{\bm a_1}+tr(e^{a_2}{\bm A_3}\Sigma))
%	=0.
%\end{align*}
i.e.,
\begin{equation*}
\begin{cases}
	I^{'}(t)-2I(t){\bm a_1}^{\top}(\mu-r)+I(t){\bm a_1}^{\top}\Sigma{\bm a_1}=0\\
	H^{'}(t)-2I(t)a_0{\bm a_1}^{\top}(\mu-r)+2I(t)a_0{\bm a_1}^{\top}\Sigma{\bm a_1}-H(t){\bm a_1}^{\top}(\mu-r)=0\\
	G^{'}(t)+\dfrac{\lambda n}{2}\ln{(2\pi e)}+\dfrac{\lambda}{2}\ln{|e^{a_2}{\bm A_3}|}-I(t)a_0^2{\bm a_1}^{\top}\Sigma{\bm a_1}-I(t){\rm tr}(e^{a_2}{\bm A_3}\Sigma)+H(t)a_0{\bm a_1}^{\top}(\mu-r)=0
\end{cases}
\end{equation*}
with the terminal condition %$V^P(T,w)=-\gamma w^2+\tau^P w$ means 
$I^P(T)=\gamma, H^P(T)=\tau^P, G^P(T)=0$.
Solving the above PDEs, we have
\begin{equation*}
\begin{cases}
	I(t)=\gamma e^{\int_{t}^T-\left(2{\bm a_1}^{\top}(\mu - r)-{\bm a_1}^{\top}\Sigma{\bm a_1}\right)ds}\\
	H(t)=e^{\int_{t}^T-{\bm a_1}^{\top}(\mu - r)ds}\left[\tau^P-2\gamma\int_{t}^T a_0\left({\bm a_1}^{\top}\Sigma{\bm a_1}-{\bm a_1}^{\top}(\mu - r)\right)e^{\int_{s}^T-\left({\bm a_1}^{\top}(\mu - r)-{\bm a_1}^{\top}\Sigma{\bm a_1}\right)du}ds\right]
\\
	G^P(t)
	=\int_t^T
	\Big[H^P(s)a_0{\bm a_1}^\top(\mu-r)-I^P(s)a_0^2{\bm a_1}^\top\Sigma{\bm a_1}\\
	\hspace{+2cm}
	+\dfrac{\lambda n}{2}\ln{(2\pi e)}+\dfrac{\lambda n}{2}a_2+\dfrac{\lambda}{2}\ln{|{\bm A_3}|}-I^P(s) e^{a_2}{\rm tr}(\Sigma {\bm A_3})
	\Big] ds
\end{cases}
\end{equation*}


\section{The Proof of Lemma \ref{le:policy_improvement}}\label{app:policy_improvement}

For any arbitrarily given exploratory portfolio selection $P(t,\cdot)$ and another exploratory portfolio selection $\widetilde{P}(t,\cdot)$, we first calculate the difference between $V^{\widetilde{P}}(t,W_{t})$ and $V^{P}(t,W_{t})$.
Define $\{\widetilde{W}_s\}_{t<s<T}$ to be the exploratory wealth process \eqref{equ:wealth_RL} generated with the portfolio selection $\{\widetilde{P}(s,\cdot)\}_{t<s<T}$.
Under the assumption in Lemma \ref{le:policy_improvement} that $V^P(T,w)=V^{\widetilde{P}}(T,w)$, we have
\begin{align*}
	&V^{\widetilde{P}}(t,W_{t})-V^{P}(t,W_{t})
	={\rm E}_t\Big(V^{\widetilde{P}}(T,\widetilde{W}_{T})\Big)
	-V^{P}(t,W_{t})\\
	=&{\rm E}_t\Big(V^{P}(T,\widetilde{W}_{T})\Big)
	-V^{P}(t,W_{t})
	={\rm E}_t\Big(V^{P}(T,\widetilde{W}_{T})
	-V^{P}(t,W_{t})\Big)\\
	=&
	\int_t^T
	[\dfrac{\partial V^{P}}{\partial s}(s,w)
	+\dfrac{\partial V^{P}}{\partial w}(s,w)\int_{\mathbb{R}^n}\theta^\top (\mu-r) \widetilde{P}(s,\theta) d\theta\\
	&\quad+\dfrac{1}{2}\dfrac{\partial^2 V^{P}}{\partial w^2}(s,w)\int_{\mathbb{R}^n}\theta^\top\Sigma\theta \widetilde{P}(s,\theta) d\theta]ds
	+\lambda \int_t^T h(\widetilde{P}(s,\cdot)) ds.
\end{align*}
When $\widetilde{P}(t,\theta)$ is the extremum of the optimization problem
\begin{equation}\label{equ:wide_P}
\begin{split}
  &\max_{P(t,\cdot)} \int_{\mathbb{R}^n} \Big(
  -\lambda \ln{P(t,\theta)}
  +\dfrac{\partial V^{P}}{\partial w}(t,w)\theta^\top (\mu-r)
  +\dfrac{1}{2}\dfrac{\partial^2 V^{P}}{\partial w^2}(t,w)\theta^\top\Sigma\theta\Big)P(t,\theta) d\theta,\\
	&s.t. ~\int_{\mathbb{R}^n}P(t,\theta) d\theta=1,
\end{split}
\end{equation}
$\widetilde{P}(t,\theta)$ is given by the Gaussian distribution in \eqref{equ:tilde_P}.
Then, $V^{\widetilde{P}}(t,W_{t})-V^{P}(t,W_{t})$ becomes
\begin{align*}
	V^{\widetilde{P}}(t,W_{t})-V^{P}(t,W_{t})
	=& \int_t^T
	\Big[\dfrac{\partial V^{P}}{\partial s}(s,w)
	+\dfrac{\partial V^{P}}{\partial w}(s,w)\int_{\mathbb{R}^n}\theta^\top (\mu-r) \widetilde{P}(s,\theta) d\theta\\
	&+\dfrac{1}{2}\dfrac{\partial^2 V^{P}}{\partial w^2}(s,w)\int_{\mathbb{R}^n}\theta^\top\Sigma\theta \widetilde{P}(s,\theta) d\theta
	+\lambda h(\widetilde{P}(s,\cdot)\Big] ds\\
	=& \int_t^T
	\Big[\dfrac{\partial V^{P}}{\partial s}(s,w)
	+\max_{P(s,\cdot)}\Big\{\dfrac{\partial V^{P}}{\partial w}(s,w)\int_{\mathbb{R}^n}\theta^\top (\mu-r) P(s,\theta) d\theta\\
	&+\dfrac{1}{2}\dfrac{\partial^2 V^{P}}{\partial w^2}(s,w)\int_{\mathbb{R}^n}\theta^\top\Sigma\theta P(s,\theta) d\theta
	+\lambda h(P(s,\cdot)\Big\}\Big] ds.
\end{align*}
On the other hand, according to Feynman-Kac formulate, the value function $V^P(s,w)$ satisfies
\begin{align*}
	&\dfrac{\partial V^{P}}{\partial s}(s,w)
	+\dfrac{\partial V^{P}}{\partial w}(s,w)\int_{\mathbb{R}^n}\theta^\top (\mu-r) P(s,\theta) d\theta\\
	&+\dfrac{1}{2}\dfrac{\partial^2 V^{P}}{\partial w^2}(s,w)\int_{\mathbb{R}^n}\theta^\top\Sigma\theta P(s,\theta) d\theta+\lambda  h(P(s,\cdot))=0,
\end{align*}
for $s\in[t,T]$.
Thus, we have
\begin{align*}
	V^{\widetilde{P}}(t,W_{t})-V^{P}(t,W_{t})
	\geq0.
\end{align*}



\section{The Proof of Theorem \ref{th:sac}}\label{app:sac}

For any arbitrarily given initial exploratory portfolio selection $P_0(t,\theta)$ with 
\begin{equation*}
	\mathcal{N}\Big((a_0-w){\bm a_1},e^{a_2(T-t)}{\bm A_3}\Big),
\end{equation*}
%the expectation of terminal wealth is
%\begin{equation*}
%	{\rm E}(\widetilde{W}_T)
%	=e^{\int_0^T -{\bm a_1}^\top (\mu-r)ds}
%	\Big(\int_0^T a_0{\bm a_1}^\top(\mu-r)e^{\int_0^s {\bm a_1}^\top (\mu-r)dk }ds+w^o \Big).
%\end{equation*}
according to Lemma \ref{le:policy_evaluation}, $\tau^{P_0}$ can be given as
\begin{equation*}
	\tau^{P_0}
	=1+2\gamma e^{\int_0^T -{\bm a_1}^\top (\mu-r)ds}
	\Big(\int_0^T a_0{\bm a_1}^\top(\mu-r)e^{\int_0^s {\bm a_1}^\top (\mu-r)dk }ds+w^o \Big).
\end{equation*}
The initial value function $V^{P_0}(t,w)$ with boundary condition $V^{P_0}(T,w)=-\gamma w^2+\tau_0 w$ can be shown as
\begin{align*}
	V^{P_0}(t,w)=I^{P_0}(t)w^2+H^{P_0}(t)w+G^{P_0}(t)
\end{align*}
in which
\begin{align*}
	&I^{P_0}(t)=-\gamma e^{\int_t^T -b_1(s)-b_2(s) ds},\\
	&H^{P_0}(t)
	=\tau_0 e^{\int_t^T -b_2(s) ds}
	-2\gamma e^{\int_t^T -b_2(s) ds}
	\int_t^T a_0e^{\int_s^T -b_1(r) dr}b_1(s)ds
	%&G^{P_0}(t)
	%=\int_t^T
	%[\dfrac{\lambda n}{2}\ln{(2\pi e)}+\dfrac{\lambda n}{2}a_2+\dfrac{\lambda}{2}\ln{|{\bm A_3}|}
	%+H^Pa_0b_2(s)+I^P(a_0^2(b_2(s)-b_1(s)) +e^{a_2}\text{tr}(\Sigma {\bm A_3}))] ds
\end{align*}
with
$b_1(s)={\bm a_1}^\top(\mu-r)-{\bm a_1}^\top\Sigma{\bm a_1}$ and 
$b_2(s)={\bm a_1}^\top(\mu-r)$.

Then, according to Lemma \ref{le:policy_improvement}, the exploratory portfolio selection is updated into $P_1(t,\theta)$ which is the probability density function of multivariate normal distribution
\begin{align*}
	P_1(t,\theta)
	=&\mathcal{N}\Big(\dfrac{\frac{\partial V^{P_0}}{\partial w}(t,w)}{-\frac{\partial^2 V^{P_0}}{\partial w^2}(t,w)}\Sigma^{-1}(\mu-r),\dfrac{\lambda}{-\frac{\partial^2 V^{P_0}}{\partial w^2}(t,w)}\Sigma^{-1}\Big)\\
	=&\mathcal{N}\Big((\dfrac{\tau_0-2\gamma \int_t^T a_0e^{\int_s^T -b_1(r) dr}b_1(s)ds}{2\gamma e^{\int_t^T -b_1(s) ds}}-w)\Sigma^{-1}(\mu-r),
	\dfrac{\lambda}{2}\dfrac{e^{\int_t^T b_1(s)+b_2(s) ds}}{\gamma}\Sigma^{-1}\Big).
\end{align*}
Again, according to Lemma \ref{le:policy_evaluation}, $\tau^{P_1}$ can be given as
\begin{equation*}
	\tau^{P_1}
	=1+2\gamma e^{\int_0^T -A(s)ds}
	\Big(\int_0^T \dfrac{\tau^{P_0}-2\gamma \int_s^T a_0e^{\int_k^T -b_1(r) dr}b_1(k)dk}{2\gamma e^{\int_s^T -b_1(k) dk}}A(s)e^{\int_0^s A(k)dk }ds+w^o \Big).
\end{equation*}
The value function $V^{P_1}(t,w)$ with boundary condition $V^{P_1}(T,w)=-\gamma w^2+\tau^{P_1} w$ becomes
\begin{align*}
	V^{P_1}(t,w)=I^{P_1}(t)w^2+H^{P_1}(t)w+G^{P_1}(t)
\end{align*}
in which
	$I^{P_1}(t)
	=-\gamma e^{\int_t^T -A(s) ds}$ and 
	$H^{P_1}(t)
	=\tau^{P_1} e^{\int_t^T -A(s) ds}$.
	%&G^{P_1}(t)
	%=\int_t^T
	%[\dfrac{\lambda n}{2}\ln{(2\pi e)}+\dfrac{\lambda n}{2}a_2(T-t)+\dfrac{\lambda}{2}\ln{|{\bm A_3}|}\\
	%&\qquad+H^{P_1}\dfrac{\tau-2\gamma \int_t^T a_0e^{\int_s^T -b_1(r) dr}b_1(s)ds}{2\gamma e^{\int_t^T -b_1(s) ds}}(\mu-r)^\top\Sigma^{-1} (\mu-r)\\
	%&\qquad+I^{P_1}((\dfrac{\tau-2\gamma \int_t^T a_0e^{\int_s^T -b_1(r) dr}b_1(s)ds}{2\gamma e^{\int_t^T -b_1(s) ds}})^2(\mu-r)^\top\Sigma^{-1}(\mu-r)
	%+\dfrac{\lambda n}{2\gamma})] ds.

Again, according to Lemma \ref{le:policy_improvement}, the exploratory portfolio selection is updated to $P_2(t,\theta)$ which is the probability density function of multivariate normal distribution
\begin{align*}
	P_2(t,\theta)
	=&\mathcal{N}\Big(\dfrac{\frac{\partial V^{P_1}}{\partial w}(t,w)}{-\frac{\partial^2 V^{P_1}}{\partial w^2}(t,w)}\Sigma^{-1}(\mu-r),\dfrac{\lambda}{-\frac{\partial^2 V^{P_1}}{\partial w^2}(t,w)}\Sigma^{-1}\Big)\\
	=&\mathcal{N}\Big((\dfrac{\tau^{P_1}}{2\gamma}-w)\Sigma^{-1}(\mu-r),\dfrac{\lambda}{2}\dfrac{e^{K(t,T)\cdot(T-t)}}{\gamma}\Sigma^{-1}\Big).
\end{align*}

Then, we will prove that, for $n\geqslant2$,
\begin{align}\label{equ:tau_iter}
	\tau^{P_n}
	=1+2\gamma e^{\int_0^T -A(s)ds}
	\Big(\int_0^T \dfrac{\tau^{P_{n-1}}}{2\gamma}A(s)e^{\int_0^s A(k)dk }ds+w^o \Big)
\end{align}
and
\begin{align}\label{equ:theta_iter}
	P_{n+1}(t,\theta)
	=\mathcal{N}\Big((\dfrac{\tau^{P_{n}}}{2\gamma}-w)\Sigma^{-1}(\mu-r),\dfrac{\lambda}{2}\dfrac{e^{K(t,T)\cdot(T-t)}}{\gamma}\Sigma^{-1}\Big).
\end{align}
In fact, for $\forall k$, if
\begin{equation*}
	P_k(t,\theta)
	=\mathcal{N}\Big((\dfrac{\tau^{P_{k-1}}}{2\gamma}-w)\Sigma^{-1}(\mu-r),\dfrac{\lambda}{2}\dfrac{e^{K(t,T)\cdot(T-t)}}{\gamma}\Sigma^{-1}\Big),
\end{equation*}
$\tau^{P_k}$ can be given as
\begin{equation*}
	\tau^{P_k}
	=1+2\gamma e^{\int_0^T -A(s)ds}
	\Big(\int_0^T \dfrac{\tau^{P_{k-1}}}{2\gamma}A(s)e^{\int_0^s A(k)dk }ds+w^o \Big).
\end{equation*}
According to Lemma \ref{le:policy_evaluation}, the value function $V^{P_k}(t,w)$ with boundary condition $V^{P_k}(T,w)=-\gamma w^2+\tau^{P_k} w$ can be shown as
\begin{align*}
	V^{P_k}(t,w)=I^{P_k}(t)w^2+H^{P_k}(t)w+G^{P_k}(t),
\end{align*}
in which
	$I^{P_k}(t)
	=-\gamma e^{\int_t^T -A(s) ds}$ and
	$H^{P_k}(t)
	=\tau^{P_k} e^{\int_t^T -A(s) ds}$.
Applying Lemma \ref{le:policy_improvement}, the $k+1$-th iteration of the exploratory portfolio selection is updated to
\begin{align*}
	P_{k+1}(t,\theta)
	=&\mathcal{N}\Big(\dfrac{\frac{\partial V^{P_k}}{\partial w}(t,w)}{-\frac{\partial^2 V^{P_k}}{\partial w^2}(t,w)}\Sigma^{-1}(\mu-r),\dfrac{\lambda}{-\frac{\partial^2 V^{P_k}}{\partial w^2}(t,w)}\Sigma^{-1}\Big)\\
	=&\mathcal{N}\Big((\dfrac{\tau^{P_k}}{2\gamma}-w)\Sigma^{-1}(\mu-r),\dfrac{\lambda}{2}\dfrac{e^{K(t,T)\cdot(T-t)}}{\gamma}\Sigma^{-1}\Big).
\end{align*}
By mathematical induction, \eqref{equ:tau_iter} and \eqref{equ:theta_iter} is obtained.


Equation \eqref{equ:tau_iter} gives the recursion sequence of $\{\tau^{P_n}\}$.
Thus,
\begin{equation*}
	\lim_{n\to+\infty}\tau^{P_n}
	=\dfrac{1+2\gamma w^o e^{\int_0^T -A(s)ds}}{e^{\int_0^T -A(s)ds}}
	=e^{\int_0^T A(s)ds}+2\gamma w^o.
\end{equation*}
In this way, we draw the conclusion that
\begin{equation*}
\begin{split}
	\lim_{n\to+\infty}P_{n}(t,\theta)
	&=\lim_{n\to+\infty}
	\mathcal{N}\Big((\dfrac{\tau^{P_n}}{2\gamma}-w)\Sigma^{-1}(\mu-r),\dfrac{\lambda}{2}\dfrac{e^{K(t,T)\cdot(T-t)}}{\gamma}\Sigma^{-1}\Big)\\
	&=\mathcal{N}\Big((\dfrac{e^{\int_0^T A(s)ds}+2\gamma w^o}{2\gamma}-w)\Sigma^{-1}(\mu-r),\dfrac{\lambda}{2}\dfrac{e^{K(t,T)\cdot(T-t)}}{\gamma}\Sigma^{-1}\Big),
\end{split}
\end{equation*}
and $\lim\limits_{n\to+\infty}V^{P_n}(t,w)$ becomes the optimal value function in \eqref{equ:V_n}.


