\section{Preliminaries}\label{sec3}

In this section, we aim at defining the quasi-periodic Green's function of Lam\'{e} system with Dirichlet boundary condition on $\mathbb{R}^2_+:=\{(x_1,0):x_1\in\mathbb{R}\}$. We derive the explicit expression of the Green's function and separate the evanescent and propagating parts. Based on the aforementioned Green's function we define quasi-periodic layer potential operators and introduce some important properties, which will be very useful in subsequent discussions.

Throughout the whole paper, we consider unitary Fourier transform,i.e.
$$
    \hat{f}(\xi):=\frac{1}{2\pi}\int f(x) e^{-\ii x\cdot\xi}{\rm{d}} x
$$
for $x,\xi\in\mathbb{R}^2$.



\subsection{Quasi-periodic-Dirichlet Green's function}\label{sec3-1}

Firstly we give the definition and properties of quasi-periodic-Dirichlet Green's function for the Lam\'{e} system. We first introduce the quasi-periodic Green's function $\bm{G}^{\alpha,\omega}$ satisfying
\begin{equation}\label{eq:quasi-p-Green}
\begin{split}
(\mathcal{L}^{\lambda, \mu} +\rho\omega^2\bm{I})\bm{G}^{\alpha,\omega}(\bm{x},\bm{y})&=\sum_{n \in \mathbb{Z}} \delta(x_1 - y_1 - n) \delta(x_2 - y_2) {\rm{e}}^{{\rm{i}} n\alpha}\bm{I}\\
&=\delta(x_2 - y_2)\left(\sum_{n \in \mathbb{Z}} \delta(x_1 - y_1 - n){\rm{e}}^{{\rm{i}} n\alpha} \right)\bm{I}.
\end{split}
\end{equation}

Here $\bm{I}$ is $2\times 2$ identity matrix, and $\bm{G}^{\alpha,\omega}(\bm{x},\bm{y})$ is $2\times 2$ matrix-valued function. It is straightforward that $\bm{G}^{\alpha,\omega}(\bm{x},\bm{y}) = \bm{G}^{\alpha,\omega}(\bm{x}-\bm{y})$. Define $\overline{\bm{G}}^{\alpha,\omega}(\bm{x}):= e^{-\ii \alpha x_1}\bm{G}^{\alpha,\omega}(\bm{x})$. $\tgao(\bm{x})$ is then a periodic function of $x_1$ with periodicity 1. Substituting $e^{\ii \alpha x_1}\overline{\bm{G}}$ into \eqref{eq:quasi-p-Green} we get the following result.

\begin{lemma}
    \begin{equation}
        \begin{aligned}
            &e^{-\ii\alpha x_1}(\llm(e^{\ii\alpha x_1} \tgao))_{1j} = \\&\mu(-\alpha^2+2\ii\alpha\partial_1 + \Delta)\tgaop{1j}+(\lambda+\mu)(-\alpha^2+2\ii\alpha\partial_1+\partial_{11})\tgaop{1j} + (\lambda+\mu)(\ii\alpha\partial_2+\partial_{12})\tgaop{2j}, \\
            &e^{-\ii\alpha x_1}(\llm(e^{\ii\alpha x_1}\tgao))_{2j} = \\
            &\mu(-\alpha^2+2\ii\alpha\partial_1+\Delta)\tgaop{2j}+(\lambda+\mu)(\ii\alpha\partial_2+\partial_{12})\tgaop{1j} +(\lambda+\mu)\partial_{22}\tgaop{2j}.
        \end{aligned}
    \end{equation}
    Here $j=1,2$, and $\partial_if$ is short for $\frac{\partial f}{\partial x_i}$.
\end{lemma}

Define
$$
    \overline{\mathcal{L}}^{\lambda,\mu}:=\begin{pmatrix}
        \mu\partial_{22}+(\lambda+2\mu)(-\alpha^2+2\ii\alpha\partial_1+\partial_{11}) & (\lambda+\mu)(\ii\alpha\partial_2+\partial_{12}) \\
        (\lambda+\mu)(\ii\alpha\partial_2+\partial_{12}) & (\lambda+2\mu)\partial_{22}+\mu(-\alpha^2+2\ii\alpha\partial_1+\partial_{11})
    \end{pmatrix},
$$
then
\begin{equation}\label{eq:tgao1}
    (\overline{\mathcal{L}}^{\lambda,\mu}+\rho\omega^2\bm{I})\tgao(\bm{x}) = \sum\limits_{n\in\mathbb{Z}}\delta(x_1-n)\delta(x_2)\bm{I}.
\end{equation}
Consider the Fourier expansion of $\tgao(\bm{x})$ with respect to $x_1$ in the form of
\begin{equation}\label{eq:tgaopij}
    \tgaop{ij}(x_1,x_2) = \sum\limits_{l\in 2\pi\mathbb{Z}} c_{l,ij}(x_2)e^{\ii lx_1}.
\end{equation}
To get rid of $x_1$ dependency in the equation, we take advantage of Poisson summation formula
$$
    \sum\limits_{n\in\mathbb{Z}}\delta(x_1-n) = \frac{1}{2\pi}\sum\limits_{l\in 2\pi\mathbb{Z}}e^{\ii lx_1}
$$
Plugging Fourier expansion and Poisson summation formula into \eqref{eq:tgao1} leads to an ordinary differential equation system of $\bm{c}_l(x_2):=(c_{l,ij}(x_2))_{2\times 2}$.The expressions are shown below.

\begin{lemma}\label{eq:cl}
    $\bm{c}_l$ satisfies
    \begin{equation}\label{eq:clode}
        \begin{aligned}
            (-(\lambda+2\mu)(\alpha+l)^2+\rho\omega^2)c_{l,1j} + \mu c_{l,1j}'' + \ii(\lambda+\mu)(\alpha+l)c_{l,2j}' &= \frac{1}{2\pi}\delta_0\delta_{1j} \\
            (-\mu(\alpha+l)^2+\rho\omega^2)c_{l,2j} + (\lambda+2\mu)c_{l,2j}'' + \ii(\lambda+\mu)(\alpha+l)c_{l,1j}' &= \frac{1}{2\pi}\delta_0\delta_{2j}
        \end{aligned}
    \end{equation}
    for $j=1,2$.
\end{lemma}

Notice that $c_{l,11}$, $c_{l,21}$ (as well as $c_{l,12}$, $c_{l,22}$) are paired in the equation system. For brevity we only demonstrate the calculation details of $c_{l,11}$ and $c_{l,21}$, and directly give the final expressions of $c_{l,12}$ and $c_{l,22}$.

Applying Fourier transform to \eqref{eq:clode}, we get
\begin{equation*}\label{eq:clft}
    \begin{aligned}
        (\rho\omega^2-\mu(\alpha+l)^2-(\lambda+2\mu)\xi^2)\hat{c}_{l,21} - (\lambda+\mu)(\alpha+l)\xi\hat{c}_{l,11} &= 0 \\
        (\rho\omega^2-(\lambda+2\mu)(\alpha+l)^2-\mu\xi^2)\hat{c}_{l,11} - (\lambda+\mu)(\alpha+l)\xi\hat{c}_{l,21} &= (2\pi)^{-\frac{3}{2}}.
    \end{aligned}
\end{equation*}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
Define
\begin{align*}
D &= (\rho\omega^2-(\lambda+2\mu)(\alpha+l)^2-\mu\xi^2)(\rho\omega^2-\mu(\alpha+l)^2-(\lambda+2\mu)\xi^2)-(\lambda+\mu)^2(\alpha+l)^2\xi^2. \\
&= \mu(\lambda+2\mu)(\xi^2+(\alpha+l)^2-\frac{\rho\omega^2}{\lambda+2\mu})(\xi^2+(\alpha+l)^2-\frac{\rho\omega^2}{\mu}).
\end{align*}

Calculation shows that
\begin{equation*}
\begin{aligned}
\hat{c}_{l,11}(\xi) &= (2\pi)^{-3/2}  \frac{\rho\omega^2-\mu(\alpha+l)^2-(\lambda+2\mu)\xi^2}{D}, \\
\hat{c}_{l,21}(\xi)
&= (2\pi)^{-3/2}\frac{(\lambda+\mu)(\alpha+l)\xi}{D}.
\end{aligned}
\end{equation*}

$\alpha$ here is exactly the first element of wave vector $\bm{k}$, so $\alpha<k_p$ and $\alpha<k_s$.

We define
\begin{align*}
l_{p,+}:= k_p-\alpha, && l_{p,-}:=-k_p-\alpha, \\
l_{s,+}:= k_s-\alpha, && l_{s,-}:=-k_s-\alpha.
\end{align*}
It is obvious that $l_{p,+}<l_{s,+}$ and $l_{p,-}>l_{s,-}$ since $k_p<k_s$. Define $\gamma_{l,s} := \sqrt{|(\alpha+l)^2-\frac{\rho\omega^2}{\mu}|}, \gamma_{l,p} := \sqrt{|(\alpha+l)^2-\frac{\rho\omega^2}{\lambda+2\mu}|}$. The following calculation is divided into three different cases:
\begin{itemize}
\item \textbf{Case I: $l\geq l_{s,+}$ or $l\leq l_{s,-}$.}

In this case $(\alpha+l)^2\geq k_s^2>k_p^2$. To calculate the inverse Fourier transform of $\hat{c}_{l,ij}$, we need the following result.
\begin{lemma}
    \begin{equation*}
    \begin{aligned}
        \int_{-\infty}^{+\infty} \frac{e^{\ii\xi x}}{\xi^2+a^2}\mathrm{d}\xi &= \pi\frac{e^{-|ax|}}{a}, \\
        \int_{-\infty}^{+\infty} \frac{\xi e^{\ii\xi x}}{\xi^2+a^2}\mathrm{d}\xi &= \ii\pi\mathrm{sgn}(x)e^{-|ax|}.
    \end{aligned}
    \end{equation*}
\end{lemma}

With the help of lemma above we conclude that
\begin{align}\label{eq:cl1121}
    c_{l,11}(x) &= \frac{\lambda+\mu}{4\pi\mu(\lambda+2\mu)(\gamma_{l,p}^2-\gamma_{l,s}^2)}\left[\gamma_{l,s}e^{-\gamma_{l,s}|x|} - \frac{(\alpha+l)^2}{\gamma_{l,p}}e^{-\gamma_{l,p}|x|}\right],\\
    c_{l,21}(x) &= \frac{\ii(\lambda+\mu)(\alpha+l)}{4\pi\mu(\lambda+2\mu)(\gamma_{l,p}^2-\gamma_{l,s}^2)}\mathrm{sgn}(x)(e^{-\gamma_{l,s}|x|} - e^{-\gamma_{l,p}|x|}).
\end{align}

Similarly, we can solve the other two Fourier coefficients $c_{l,12}, c_{l,22}$ satisfying
\begin{equation*}
    \begin{aligned}
        (\rho\omega^2-\mu(\alpha+l)^2-(\lambda+2\mu)\xi^2)\hat{c}_{l,22} - (\lambda+\mu)(\alpha+l)\xi\hat{c}_{l,12} &= (2\pi)^{-\frac{3}{2}} \\
        (\rho\omega^2-(\lambda+2\mu)(\alpha+l)^2-\mu\xi^2)\hat{c}_{l,12} - (\lambda+\mu)(\alpha+l)\xi\hat{c}_{l,22} &= 0 .
    \end{aligned}
\end{equation*}

as follows
\begin{align}\label{eq:cl1222}
c_{l,12}(x) &= \frac{\ii(\lambda+\mu)(\alpha+l)}{4\pi\mu(\lambda+2\mu)(\gamma_{l,p}^2-\gamma_{l,s}^2)}\mathrm{sgn}(x)(e^{-\gamma_{l,s}|x|}-e^{-\gamma_{l,p}|x|}) \\
c_{l,22}(x) &= \frac{\lambda+\mu}{4\pi\mu(\lambda+2\mu)(\gamma_{l,p}^2-\gamma_{l,s}^2)}\left[\gamma_{l,p}e^{-\gamma_{l,p}|x|} - \frac{(\alpha+l)^2}{\gamma_{l,s}}e^{-\gamma_{l,s}|x|}\right]
\end{align}

We can see that all $c_{l,ij}$ are decaying exponentially with the increasing $|x|$. This implies that the corresponding part in Green's function generate an evanescent wave. As a result, all modes with $l\geq l_{s,+}$ or $l\leq l_{s,-}$ are evanescent modes.

\item \textbf{Case II: $l_{p,+}\leq l<l_{s,+}$ or $l_{s,-}< l \leq l_{p,-}$.}

In this case $k_s^2>(\alpha+l)^2\geq k_p^2$. To calculate the inverse Fourier transform of $c_{l,ij}$ we need two additional results from Sommerfeld integrals.
\begin{lemma}\label{lem:feymann}
    With Feymann prescription, the following identities hold.
    \begin{align*}
       \int_{-\infty}^{+\infty} \frac{e^{ix\xi}}{\xi^2-k^2}\mathrm{d}\xi &= \frac{\ii\pi}{k}e^{\ii k|x|} \\
       \int_{-\infty}^{+\infty} \frac{\xi e^{ix\xi}}{\xi^2-k^2}\mathrm{d}\xi &= \ii\pi\mathrm{sgn}(x)e^{\ii k|x|}.
    \end{align*}
\end{lemma}
Then with a bit calculation we conclude that
\begin{equation}\label{eq:lplls}
\begin{aligned}
    c_{l,11}(x) &= \frac{-(\lambda+\mu)}{4\pi(\lambda+2\mu)\mu(\gamma_{l,s}^2+\gamma_{l,p}^2)}\left[\frac{\alpha^2}{\gamma_{l,p}}e^{-\gamma_{l,p}|x|} + \ii\gamma_{l,s}e^{\ii\gamma_{l,s}|x|}\right] \\
    c_{l,21}(x) &= c_{l,12}(x) =  \frac{-\ii(\alpha+l)(\lambda+\mu)\mathrm{sgn}(x)}{4\pi(\lambda+2\mu)\mu(\gamma_{l,s}^2+\gamma_{l,p}^2)}(e^{-\gamma_{l,p}|x|} - e^{\ii\gamma_{l,s}|x|}) \\
    c_{l,22}(x) &= \frac{-(\lambda+\mu)}{4\pi(\lambda+2\mu)\mu(\gamma_{l,s}^2+\gamma_{l,p}^2)}\left[-\gamma_{l,p}e^{-\gamma_{l,p}|x|} + \frac{\ii(\alpha+l)^2}{\gamma_{l,s}}e^{\ii\gamma_{l,s}|x|}\right]
\end{aligned}
\end{equation}

We can see that the p-wave part in the Green's function is exponentially decreasing, while the s-wave part propagates. Therefore when $l_{p,+}\leq l<l_{s,+}$ or $l_{s,-}< l \leq l_{p,-}$, only s-wave contributes to the propagating solution, and p-wave stays evanescent.

\item \textbf{Case III: $l_{p,-}<l<l_{p,+}$.}
When $l_{p,-}<l<l_{p,+}$, the term $\rho\omega^2-\mu\alpha^2>0$ and $\rho\omega^2-(\lambda+2\mu)\alpha^2>0$. With the help of Lemma \ref{lem:feymann}
we can get that
\begin{equation}\label{eq:c0}
\begin{aligned}
    c_{l,11}(x) &= \frac{\ii(\lambda+\mu)}{4\pi\mu(\lambda+2\mu)(\gamma_{l,p}^2-\gamma_{l,s}^2)}\left[\gamma_{l,s}e^{i\gamma_{l,s}|x|} + \frac{(\alpha+l)^2}{\gamma_{l,p}}e^{i\gamma_{l,p}|x|}\right] \\
    c_{l,12}(x) &= c_{l,21}(x) = \frac{\ii(\lambda+\mu)(\alpha+l)}{4\pi\mu(\lambda+2\mu)(\gamma_{l,p}^2-\gamma_{l,s}^2)}\mathrm{sgn}(x)(e^{\ii \gamma_{l,p}|x|} - e^{\ii \gamma_{l,s}|x|}) \\
    c_{l,22}(x) &=
    \frac{\ii(\lambda+\mu)}{4\pi\mu(\lambda+2\mu)(\gamma_{l,p}^2-\gamma_{l,s}^2)}\left[\gamma_{l,p}e^{\ii\gamma_{l,p}|x|} + \frac{(\alpha+l)^2}{\gamma_{l,s}}e^{\ii\gamma_{l,s}|x|}\right]
\end{aligned}
\end{equation}
This leads to a propagating solution for both p-wave and s-wave instead of an evanescent one.
\end{itemize}

To conclude, with \eqref{eq:cl1121}, \eqref{eq:cl1222}, \eqref{eq:lplls}, \eqref{eq:c0}, we achieved the full expression of $\tgao(\bm{x})$. The desired quasi-periodic Green's function satisfying \eqref{eq:quasi-p-Green} could be calculated by $\gao(\bm{x}) = e^{\ii\alpha x_1}\tgao(\bm{x})$. Since in our discussion, there is a Dirichlet boundary condition imposed on $\partial\mathbb{R}^2_+$, to facilitate our discussion we define $\gpao(\bm{x},\bm{y}):= \gao((x_1-y_1,x_2-y_2))-\gao((x_1-y_1,x_2+y_2))$. With this definition $\gpao(\bm{x},\bm{y})$ takes the following form
\begin{equation}\label{eq:quasiperiodicgreen}
    \gpao(\bm{x},\bm{y}) = \sum\limits_{l\in 2\pi\mathbb{Z}}(\bm{c}_l(x_2-y_2)-\bm{c}_l(x_2+y_2))e^{\ii(\alpha+l)(x_1-y_1)}
\end{equation}
and $\gpao(\bm{x},\bm{y}) = 0$ when $\bm{x}\in\mathbb{R}_+^2$ and $\bm{y}\in\partial\mathbb{R}_+^2$. Notice that unlike $\gao$, $\gpao$ is no longer translation invariant, i.e. $\gpao(\bm{x},\bm{y})\neq \gpao(\bm{x}-\bm{y},0)$.

\subsection{Quasi-periodic-Dirichlet layer potentials}\label{sec3-2}

Now, we are ready to introduce the quasi-periodic-Dirichlet layer potential operators. For $\bm{\psi}\in (L^2(\partial D))^2$, we define the following layer potential operators with quasi-periodic Green's function defined in \eqref{eq:quasiperiodicgreen}.
\begin{equation}\label{eq:layer-potential-D}
\begin{split}
\mathcal{S}^{\alpha,\omega}_+[\bm{\psi}](\bm{x}):=&\int_{\partial D} \bm{G}_{+}^{\alpha,\omega} (\bm{x},\bm{y})\bm{\psi}(\bm{y}){\rm{d}}\sigma(\bm{y}), \ \bm{x}\in \mathbb{R}_+^2,\\
\mathcal{K}^{\alpha,\omega}_+[\bm{\psi}](\bm{x}):=&\mathrm{p.v.}\int_{\partial D} \frac{\partial\bm{G}_{+}^{\alpha,\omega} }{\partial \bm{\nu_x}}(\bm{x},\bm{y})\bm{\psi}(\bm{y}){\rm{d}}\sigma(\bm{y}),\  \bm{x}\in \partial D,\\
\widetilde{\mathcal{S}}^{\alpha,\omega}_+[\bm{\psi}](\bm{x}):=&\int_{\partial D} \widetilde{\bm{G}}_{+}^{\alpha,\omega} (\bm{x},\bm{y})\bm{\psi}(\bm{y}){\rm{d}}\sigma(\bm{y}), \ \bm{x}\in \mathbb{R}^2_+,\\
\widetilde{\mathcal{K}}^{\alpha,\omega}_+[\bm{\psi}](\bm{x}):=&\mathrm{p.v.}\int_{\partial D} \frac{\partial\widetilde{\bm{G}}_{+}^{\alpha,\omega} }{\partial \bm{\nu_x}}(\bm{x},\bm{y})\bm{\psi}(\bm{y}){\rm{d}}\sigma(\bm{y}),\  \bm{x}\in \partial D.\\
\end{split}
\end{equation}
Here $\widetilde{\bm{G}}^{\alpha,\omega}_+$ denotes the $\alpha$-quasi-periodic Dirichlet Green's function corresponding to Lam\'{e} system with Lam\'{e} constants $\tilde{\lambda}, \tilde{\mu}$. $\partial/\partial{\bm{\nu}_x}$ means taking normal derivative with respect to $\bm{x}$.

The following properties of $\mathcal{S}^{\alpha,\omega}_+$ and $\mathcal{K}^{\alpha,\omega}_+$ could be proved with similar methods as in \cite{HabibElastic}.
\begin{proposition}\label{prop:layerpotentialproperty}
Single layer potential $\mathcal{S}^{\alpha,\omega}_+[\bm{\psi}]$ is continuous across $\partial D$, i.e.
$$
    \left.\mathcal{S}^{\alpha,\omega}_+[\bm{\psi}]\right\vert_- = \left.\mathcal{S}^{\alpha,\omega}_+[\bm{\psi}]\right\vert_+ \quad \mathrm{on}~\partial D.
$$
When regarding as operator from $L^2(\partial D)$ to $L^2(\partial D)$, the $L^2$ adjoint of $\mathcal{K}^{\alpha,\omega}_+$ is
$$
    (\mathcal{K}^{\alpha,\omega}_+)^*[\bm{\psi}](\bm{x}) := \mathrm{p.v.}\int_{\partial D} \frac{\partial\bm{G}_{+}^{\alpha,\omega} }{\partial \bm{\nu_y}}(\bm{x},\bm{y})\bm{\psi}(\bm{y}){\rm{d}}\sigma(\bm{y}),\  \bm{x}\in \partial D.
$$
The normal derivative of the single layer potential satisfies the following jump relation
\begin{equation*}
\left.\frac{\partial}{\partial\bm{\nu}} \mathcal{S}_+^{\alpha,\omega}[\bm{\psi}]\right\vert_{\pm}(\bm{x})=\Big(\pm\frac{1}{2}\bm{I}+(\mathcal{K}_+^{\alpha,\omega})^{\ast} \Big)\bm{\psi}(\bm{x})\quad {\rm{a.e.}}\ \bm{x}\in \partial D.
\end{equation*}
\end{proposition}
With the help of \eqref{eq:layer-potential-D} and Proposition \ref{prop:layerpotentialproperty}, we could write the solution to problem \eqref{eq:elas_sys} in the following integral representation formula
\begin{equation}\label{eq:int_repre}
\bm{u}(\bm{x}):=\left\{
	\begin{array}{ll}
		\bm{u}^{{\rm{in}}}_+(\bm{x})+\mathcal{S}^{\alpha,\omega}_+[\bm{\psi}](\bm{x}),  &  \bm{x} \in  \mathbb{R}^2\setminus\bar{\Omega}, \medskip \\
                 \displaystyle  \widetilde{\mathcal{S}}^{\alpha,\omega}_+[\bm{\phi}](\bm{x}) ,   &\bm{x} \in  \Omega ,
	\end{array}
	\right.
\end{equation}
The boundary potentials $\bm{\phi}, \bm{\psi}\in (L^2(\partial D))^2$ are determined by
\begin{equation*}\label{eq:A_F}
\mathcal{A}\left(
\begin{array}{c}
     \bm{\phi} \\
      \bm{\psi}
\end{array}
\right)=\bm{F},
\end{equation*}
where
\begin{equation*}%\label{eq:int_repre}
\mathcal{A}:=\left(
\begin{array}{cc}
\widetilde{\mathcal{S}}^{\alpha,\omega}_+ & -\mathcal{S}^{\alpha,\omega}_+\\
-\frac{1}{2}\bm{I}+(\widetilde{\mathcal{K}}_+^{\alpha,\omega})^{\ast} &-\big(\frac{1}{2}\bm{I}+(\mathcal{K}_+^{\alpha,\omega})^{\ast} \big)
\end{array}
\right)
\end{equation*}
and
\begin{equation}\label{eq:Fdefinition}
\bm{F}:=\left(
\begin{array}{c}
    \bm{u}^{{\rm{in}}}_+  \\
      \frac{\partial}{\partial\bm{\nu}}\bm{u}^{{\rm{in}}}_+
\end{array}
\right).
\end{equation}

\section{Elastic metascreen with $\widetilde{\mu}\rightarrow +\infty$}

In this section, we will study the behaviour of elastic metascreen when the shear modulus $\widetilde{\mu}$ of inclusions goes to infinity. We would like to prove that the scattered field from metascreen will be significantly amplified at some specific frequencies $\omega$ very close to 0, which are called subwavelength resonant frequencies. It is obvious that when $\omega$ is very close to the characteristic value of $\mathcal{A}$ (See Appendix \ref{sec:appa}), $\mathcal{A}$ will become ill-posed which leads to the blow-up of $\bm{\phi}$ and $\bm{\psi}$. Therefore we will begin with calculating the characteristic values of $\mathcal{A}$, prove the existence of subwavelength resonances, and then calculate the expression of $\bm{\phi}, \bm{\psi}$ followed by approximated expressions of fields in $\Omega$ and at far-field.

\subsection{Asymptotic analysis of Green's function and layer potential operators}\label{sec:asymptoticgreen}

Due to the complexity of problem \eqref{eq:int_repre}, it is impossible to obtain the explicit expression of $\bm{\phi}$ and $\bm{\psi}$ for an arbitrary inclusion $D$. Here we expand $\gpao$ asymptotically with respect to $\widetilde{\mu}$, use the leading order terms of Green's function to approximate the layer potential operators, and solve the original problem with approximated operators.

Recall that as quasi-periodicity, $\alpha$ must always be smaller than $k_p$ and $k_s$, which means in the subwavelength scenario $\alpha$ must converge to 0 with $\omega$. We assume here that $\alpha = \delta\omega\mu^{-1/2}$ with $0<\delta<\rho$ a constant. %Then $\gamma_{0,s} = \sqrt{(\rho-\delta^2)\frac{\omega^2}{\mu}}$, $\gamma_{0,p} = \sqrt{(\rho C_{\lambda,\mu} - \delta^2)\frac{\omega^2}{\mu}}$, $\gamma_{l,s} = \sqrt{(\delta\omega\mu^{-1/2}+l)^2-\rho\omega^2\mu^{-1}}$, $\gamma_{l,p} = \sqrt{(\delta\omega\mu^{-1/2}+l)^2-\rho\omega^2\mu^{-1}C_{\lambda,\mu}}$.
We define a few variables which will be used in equations followed.
\begin{align*}
C_{\lambda,\mu} = \frac{\mu}{\lambda+2\mu}, && \alpha_s = \sqrt{\rho-\delta^2}, && \alpha_p = \sqrt{\rho C_{\lambda,\mu} - \delta^2}, \\
b_{l,s} = -\frac{\rho}{2l}, && b_{l,p} = -\frac{\rho C_{\lambda,\mu}}{2l}.
\end{align*}
By direct calculation, we could verify that $\gpao$ could be expanded in the form of
\begin{equation}\label{eq:muinfiexpansion}
    \gpao(\bm{x},\bm{y}) =: \sum\limits_{k=1}^{+\infty}\frac{1}{\omega^2}\frac{\omega^{2k}}{\mu^k}\bm{G}^{\alpha}_{+,k}(\bm{x},\bm{y}) =:  \sum\limits_{k=1}^{+\infty}\frac{1}{\omega^2}\frac{\omega^{2k}}{\mu^k}\sum\limits_{l\in 2\pi\mathbb{Z}}\bm{G}_{+,k,l}^{\alpha}(\bm{x},\bm{y}),
\end{equation}
where
\begin{equation}\label{eq:g0}
    \begin{aligned}
    &\bm{G}^{\alpha}_{+,1,0}(\bm{x},\bm{y}) \\
    &= \frac{1}{4\pi\rho}\begin{pmatrix}
        \rho(|x_2-y_2|-|x_2+y_2|) & -2\delta y_2(\alpha_p-\alpha_s) \\
        -2\delta y_2(\alpha_p-\alpha_s) & \rho C_{\lambda,\mu}(|x_2-y_2|-|x_2+y_2|)
    \end{pmatrix}e^{\ii\alpha (x_1-y_1)}, \\
    &\bm{G}^{\alpha}_{+,1,l}(\bm{x},\bm{y})  \\
    &= \frac{e^{-l|x_2-y_2|}}{4\pi\rho}e^{\ii(\alpha+l)(x_1-y_1)}\\&\begin{pmatrix}
    b_{l,s}(1-l|x_2-y_2|) -\frac{2\delta^2}{l} + b_{l,p}(1+l|x_2-y_2|) & \ii l(b_{l,p}-b_{l,s})(x_2-y_2) \\
    \ii l(b_{l,p}-b_{l,s})(x_2-y_2) & b_{l,p}(1-l|x_2-y_2|) + b_{l,s}(1+l|x_2-y_2|) - \frac{2\delta^2}{l}
    \end{pmatrix} \\&- \frac{e^{-l|x_2+y_2|}}{4\pi\rho}e^{\ii(\alpha+l)(x_1-y_1)}\\&\begin{pmatrix}
    b_{l,s}(1-l|x_2+y_2|) -\frac{2\delta^2}{l} + b_{l,p}(1+l|x_2+y_2|) & \ii l(b_{l,p}-b_{l,s})(x_2+y_2) \\
    \ii l(b_{l,p}-b_{l,s})(x_2+y_2) & b_{l,p}(1-l|x_2+y_2|) + b_{l,s}(1+l|x_2+y_2|) - \frac{2\delta^2}{l}
    \end{pmatrix}.
    \end{aligned}
\end{equation}
When restricting points $x,y$ inside one periodical cell, the dirac comb summation on the right-hand side of \eqref{eq:quasi-p-Green} degenerates to $\delta(x_1-y_1)\delta(x_2-y_2)\bm{I}$. Substituting \eqref{eq:muinfiexpansion} into \eqref{eq:quasi-p-Green} we get the following expansion in one periodic cell $S$ as follows
\begin{equation}\label{eq:recursiverelation}
\begin{aligned}
    &(\Delta + \nabla\nabla\cdot)\bm{G}_{+,1}^{\alpha} = \delta(x_2-y_2)\delta(x_1-y_1)\bm{I}, \\
    &\omega^2(\Delta + \nabla\nabla\cdot)\bm{G}_{+,k+1}^{\alpha} + \lambda\nabla\nabla\cdot\bm{G}_{+,k}^{\alpha} + \rho\omega^2\bm{G}_{+,k}^{\alpha} = 0,\quad k>1
\end{aligned}
\end{equation}
\begin{remark}\label{rmk:1}
We should notice that the exact expansion of $\bm{G}_+^{\alpha,\omega}$ with respect to $\mu$ should be
$$
    \gpao = \sum\limits_{p=1}^{+\infty} \mu^{-p/2}\bm{G}'_p + \mu^{-(p+1)/2}\bm{G}_p.
$$
Combining this expansion with \eqref{eq:quasi-p-Green} we have the following recursive relations
\begin{equation*}
\begin{aligned}
    &\bm{G}'_1=0,\\
    &(\Delta + \nabla\nabla\cdot)\bm{G}_1 = \delta(x_2-y_2)\sum\limits_{n\in\mathbb{Z}}\delta(x_1-y_1-n)\bm{I}, \\
    &(\Delta + \nabla\nabla\cdot)\bm{G}_{k+2} + \lambda\nabla\nabla\cdot\bm{G}_k + \rho\omega^2\bm{G}_k = \delta(x_2-y_2)\sum\limits_{n\in\mathbb{Z}}\delta(x_1-y_1-n)e(k)\bm{I},\quad k>0,
\end{aligned}
\end{equation*}
where $e(k):= (\ii n\delta\omega\mu^{-1/2})^k/k!$ is the $k$-th term in expansion of $e^{\ii n\alpha}$. The last recursive equation also holds for $\bm{G}'_k, k>0$. The reason for the disappearance of $\mu^{-p/2}$ terms in \eqref{eq:muinfiexpansion} is that each $\bm{G}_{+,k}^{\alpha}$ there still depends on $\mu$ because of the existence of $C_{\lambda,\mu}$ in $\gamma_{l,p}, l\in\mathbb{N}$. The $\mu^{-p/2}$ terms merge into different $\bm{G}_{+,k}^{\alpha}$ in this way. It is obvious that $C_{\lambda,\mu}$ is bounded when $\mu\rightarrow\infty$, and the expansion \eqref{eq:muinfiexpansion} benefits our discussion by clarifying the $\omega$ and $\mu$ terms simultaneously.
\end{remark}
\begin{remark}
When calculating the recursive relation \eqref{eq:recursiverelation} we specifically assume $x$ and $y$ both lies inside one periodic cell, since this expansion will only be applied to the calculation of integrations on $\partial D$ and in $D$. It is worth mentioning that when $x,y\in\mathbb{R}^2$ are two arbitrary points, we have to use the expansion in Remark \ref{rmk:1} instead, since the $e^{\ii n\alpha}$ term in the dirac comb summation will contribute to $\mu^{-p/2}$ term when we assume $\alpha = \delta\omega\mu^{-1/2}$.
\end{remark}


We use $\bm{G}_+^{\alpha,\omega}$ to define $\mathcal{S}^{\alpha,\omega}_+$ and $(\mathcal{K}^{\alpha,\omega}_+)^{\ast}$. Notice that in $\mathcal{A}$, the left column $\widetilde{\mathcal{S}}^{\alpha,\omega}_+$ and $-\frac{1}{2}\bm{I}+(\widetilde{\mathcal{K}}_+^{\alpha,\omega})^*$ depends on asymptotic variables $\widetilde{\mu}$ and $\omega$, while the right column $-\mathcal{S}^{\alpha,\omega}_+$ and $-(\frac{1}{2}\bm{I}+(\mathcal{K}_+^{\alpha,\omega})^*)$ only depends on $\omega$. Following the decomposition of $\bm{G}_+^{\alpha,\omega}$ we have
\begin{align*}
    \widetilde{\mathcal{S}}^{\alpha,\omega}_+ = \sum\limits_{p=1}^{+\infty} \frac{\omega^{2p-2}}{\widetilde{\mu}^p}\widetilde{\mathcal{S}}^{\alpha}_{+,p}, \quad \widetilde{\mathcal{K}}^{\alpha,\omega}_+ = \sum\limits_{p=1}^{+\infty} \frac{\omega^{2p-2}}{\widetilde{\mu}^p}\widetilde{\mathcal{K}}^{\alpha}_{+,p}.
\end{align*}
Since $\widetilde{\mu}\widetilde{\bm{G}}_+^{\alpha,0} = \widetilde{\bm{G}}_{+,1}^{\alpha}$, we also have $\widetilde{\mathcal{S}}_{+,1}^{\alpha} = \widetilde{\mu}\widetilde{\mathcal{S}}_+^{\alpha,0}$ and $\widetilde{\mathcal{K}}_{+,1}^{\alpha} = \widetilde{\mu}\widetilde{\mathcal{K}}_+^{\alpha,0}$. Similar results also hold for $\bm{G}_+^{\alpha,\omega}, \mathcal{S}_+^{\alpha,\omega}$ and $\mathcal{K}_+^{\alpha,\omega}$. Furthermore, it is important to notice that $\bm{G}_{+,1}^\alpha$ is independent of choice of $\lambda,\mu$ and $\rho$, which implies that $\bm{G}_{+,1}^\alpha = \widetilde{\bm{G}}_{+,1}^\alpha$. We briefly summarize some additional useful results in the following lemma.
\begin{lemma}
    $\bm{G}_{+,1}^\alpha$ as well as $\mathcal{S}_{+,1}^\alpha$, $\mathcal{K}_{+,1}^\alpha$ are independent of $\lambda,\mu,\rho$. When regarding as operator from $L^2(\partial D)$ to $L^2(\partial D)$, the operator norm $\|\mathcal{S}_{+,1}^\alpha\|$ is of order $\mathcal{O}(1)$, while $\|\mathcal{S}_+^{\alpha,0}\| = \mathcal{O}(\mu^{-1})$, $\|\widetilde{\mathcal{S}}_+^{\alpha,0}\| = \mathcal{O}(\widetilde{\mu}^{-1})$, $\|\widetilde{\mathcal{K}}_+^{\alpha,0}\| = \mathcal{O}(1)$, $\|\mathcal{K}_+^{\alpha,0}\| = \mathcal{O}(1)$.
\end{lemma}
We can then decompose $\mathcal{A}$ as
\begin{equation}\label{eq:decomposeA}
\mathcal{A} = \mathcal{A}_0+\sum\limits_{p=1}^{+\infty}\omega^{2p-2} (\frac{1}{\widetilde{\mu}^{p}}\mathcal{A}_{p,in} + \frac{\omega^2}{\mu^{p+1}}\mathcal{A}_{p,ex}) =: \mathcal{A}_0+\sum\limits_{p=1}^{+\infty}\omega^{2p-2}\mathcal{A}_p =: \mathcal{A}_0 + \mathcal{B},
\end{equation}
where $\mathcal{A}_{p,in}$, $\mathcal{A}_{p,ex}$ is the expansion of left and right column of $\mathcal{A}$, correspondingly, in the following expressions
\begin{equation}\label{eq:adecompose}
\begin{aligned}
    \mathcal{A}_0 &= \begin{pmatrix}
    0 & -\mathcal{S}^{\alpha,0}_+ \\ -\frac{1}{2}\bm{I} + (\widetilde{\mathcal{K}}^{\alpha,0}_+)^* & -(\frac{1}{2}\bm{I}+(\mathcal{K}^{\alpha,0}_+)^*)
    \end{pmatrix}, \\
    \mathcal{A}_{p,in} &= \begin{pmatrix}
    \widetilde{\mathcal{S}}^\alpha_{+,p} & 0 \\ \frac{\omega^2}{\widetilde{\mu}}(\widetilde{\mathcal{K}}^\alpha_{+,p+1})^* & 0
    \end{pmatrix}, \qquad
    \mathcal{A}_{p,ex} = \begin{pmatrix}
    0 & -\mathcal{S}^{\alpha}_{+,p+1} \\ 0 & -(\mathcal{K}^\alpha_{+,p+1})^*
    \end{pmatrix}, \quad \mathrm{for~} p>0.
\end{aligned}
\end{equation}

  According to the discussion below Lemma 2.127 in \cite{HabibElastic}, $\mathcal{S}_+^{\alpha,0}$ might not be invertible in 2-dimensional space. As a result we impose the following assumption in this paper.
 \begin{assumption}\label{asump:invertibility}
 The shape of $D$ is chosen so that $\mathcal{S}_+^{\alpha,0}$ is invertible.
 \end{assumption}
  Although $\widetilde{\mathcal{K}}_+^{\alpha,0}$ and $\mathcal{S}_+^{\alpha,0}$ are defined with $\alpha$-quasi-periodic Green's function with Dirichlet boundary condition, we still can follow similar arguments in Section 2.15.8 of \cite{HabibElastic} to illustrate properties of interest of $\widetilde{\mathcal{K}}^{\alpha,0}_+$ and its adjoint. Define
  $$
  \Psi :=\{\bm{p}+\bm{Q}\bm{x}, \bm{p}\in\mathbb{R}^2, \bm{Q} \mathrm{~is~antisymmetric~} 2\times 2 \mathrm{~matrix}\}
  $$
  as the set of rigid motions in $\mathbb{R}^2$. We can prove in a similar way as Lemma 2.128 of \cite{HabibElastic} that $\Psi$ is the eigenspace of $\mathcal{K}^{\alpha,0}_+$ on $L^2(\partial D)$ corresponding to $\frac{1}{2}$. Since $\Psi$ is independent of $\lambda$ and $\mu$, it is immediate that $\Psi$ is also the eigenspace of $\widetilde{\mathcal{K}}^{\alpha,0}_+$.

  Let $(\cdot,\cdot)$ denote the inner product of $L^2(\partial D)\times L^2(\partial D)=:(L^2(\partial D))^2$, and $(\cdot,\cdot)_{\mathcal{H}}$ denote the inner product of $(L^2(\partial D))^2\times (L^2(\partial D))^2=:\mathcal{H}$.

It is observed that $\mathrm{dim}\Psi = 3$ since $\bm{p}$ and $\bm{Q}$ contributes two and one degrees of freedom, correspondingly. Define
$$
\bm{f}^{(1)} := \frac{1}{|\partial D|}\begin{pmatrix} 1 \\ 0\end{pmatrix}, \quad \bm{f}^{(2)} := \frac{1}{|\partial D|}\begin{pmatrix} 0 \\ 1\end{pmatrix}, \quad \bm{f}^{(3)} := \frac{1}{C_0}\begin{pmatrix}-x_2 \\ x_1\end{pmatrix}
$$
where $C_0:=\int_{\partial D} x_1^2+x_2^2 \mathrm{d}\sigma(x)$. $\bm{f}^{(i)}\in (L^2(\partial D))^2$, $i=1,2,3$ then satisfies $(\bm{f}^{(i)},\bm{f}^{(j)})=\delta_{ij}$.
Define
$$
    H_\Psi(\partial D):=\{\bm{\varphi}\in (L^2(\partial D))^2:(\bm{\psi},\bm{\varphi}) = 0, \forall\bm{\psi}\in\Psi\}.
$$
 From Proposition \ref{prop:layerpotentialproperty} and the invertibility of $\frac{1}{2}\bm{I}-(\widetilde{\mathcal{K}}_+^{\alpha,0})^*$ on $H_\Psi(\partial D)$ from Lemma 2.127 of \cite{HabibElastic}, there exists a unique $\widetilde{\bm{\psi}}^{(i)}\in H_\Psi(\partial D)$ such that
$$
    (\frac{1}{2}\bm{I}-(\widetilde{\mathcal{K}}^{\alpha,0}_+)^*)[\widetilde{\bm{\psi}}^{(i)}] = \frac{\partial}{\partial\widetilde{\bm{\nu}}}\widetilde{S}_+^{\alpha,0}[\bm{f}^{(i)}]|_- = (-\frac{1}{2}\bm{I} + (\widetilde{\mathcal{K}}_+^{\alpha,0})^*)[\bm{f}^{(i)}].
$$
We define $\bm{\psi}^{(i)} := \widetilde{\bm{\psi}}^{(i)} + \bm{f}^{(i)}$, then it follows that $(\widetilde{\mathcal{K}}_+^{\alpha,0})^*[\bm{\psi}^{(i)}] = \frac{1}{2}\bm{\psi}^{(i)}$ and
$$
    (\bm{f}^{(i)}, \bm{\psi}^{(j)})= (\bm{f}^{(i)}, \widetilde{\bm{\psi}}^{(j)}) + (\bm{f}^{(i)}, \bm{f}^{(j)}) = \delta_{ij}.
$$

  Define $W:=\mathrm{span}\{\bm{\psi}^{(i)}\in (L^2(\partial D))^2, i=1,2,3\}$. Let
  $$
    H_W :=\{ \bm{f}\in (L^2(\partial D))^2: (\bm{f},\bm{\varphi})=0~\mathrm{for}~\mathrm{all}~\bm{\varphi}\in W\}.
  $$
  We have the following decomposition from Lemma 2.129 of \cite{HabibPhoto}.
  \begin{lemma}\label{lem:decompose}
    The following results hold.
    \begin{enumerate}
        \item Each $\bm{\varphi}\in (L^2(\partial D))^2$ is uniquely decomposed as
            $$
                \bm{\varphi} = \bm{\varphi}'+\bm{\varphi}'':=\bm{\varphi}'+\sum\limits_{j=1}^3( \bm{f}^{(j)},\bm{\varphi})\bm{\psi}^{(j)},
            $$
            and $\bm{\varphi}'\in H_\Psi$.
        \item Each $\bm{f}\in (L^2(\partial D))^2$ is uniquely decomposed as
            $$
                \bm{f} = \bm{f}' + \bm{f}'' := \bm{f}' + \sum\limits_{j=1}^3(\bm{f},\bm{\psi}^{(j)})\bm{f}^{(j)},
            $$
            and $\bm{f}'\in H_W$.
        \item $\widetilde{\mathcal{S}}_+^{\alpha,0}$ maps $W$ into $\Psi$, and $H_\Psi$ into $H_W$.
        \item $W$ is the eigenspace of $(\widetilde{\mathcal{K}}_+^{\alpha,0})^*$ corresponding to the eigenvalue $1/2$.
    \end{enumerate}
  \end{lemma}

  Due to previous discussions, we know that $\mathcal{A}_0$ is not invertible. In fact, we have
  \begin{align*}
    \mathrm{Ker}\mathcal{A}_0 &= \{(\bm{f}_1,\bm{f}_2)^\top: \bm{f}_1\in\mathrm{Ker}(-\frac{1}{2}\bm{I}+(\widetilde{\mathcal{K}}^{\alpha,0}_+)^*), \bm{f}_2=0\} \\
    &= \mathrm{span}\{\Psi_i:=(\bm{\psi}^{(i)},0)^\top, i=1,2,3\}. \\
    \mathrm{Ker}\mathcal{A}_0^* &= \{(\bm{g}_1,\bm{g}_2)^\top: \bm{g}_2\in\mathrm{Ker}(-\frac{1}{2}\bm{I}+\widetilde{\mathcal{K}}^{\alpha,0}_+), \bm{g}_1 = (\mathcal{S}_+^{\alpha,0})^{*,-1}[\bm{g}_2]\} \\
    &= \mathrm{span}\{((\mathcal{S}_+^{\alpha,0})^{*,-1}[\bm{f}^{(i)}], \bm{f}^{(i)})^\top, i=1,2,3\}.
  \end{align*}
  Define $\Psi_i^*:=((\mathcal{S}_+^{\alpha,0})^{*,-1}[\bm{f}^{(i)}], \bm{f}^{(i)})^\top/C^*_i, i=1,2,3$ where $C^*_i$ are the constants such that $(\Psi_i^*, \Psi_j^*)_{\mathcal{H}} = \delta_{ij}$.

  Therefore, similar to Lemma \ref{lem:decompose}, we can orthogonally decompose $\mathcal{H}$ using $\mathrm{Ker}\mathcal{A}_0$ as well as $\mathrm{Ker}\mathcal{A}_0^*$. We define operator $\mathcal{P}:\mathcal{H}\rightarrow \mathcal{H}$ as
  $$
  \mathcal{P}\bigg[\begin{pmatrix} \bm{f}_1 \\ \bm{f}_2 \end{pmatrix}\bigg] = \sum\limits_{i=1}^3\bigg(\begin{pmatrix} \bm{f}_1 \\ \bm{f}_2 \end{pmatrix}, \begin{pmatrix} \bm{\psi}^{(i)} \\ 0 \end{pmatrix}\bigg)_{\mathcal{H}}\Psi_i^*.
  $$
  It is immediate that $\mathcal{P}[\bm{f}] = 0$ if and only if $\bm{f}\perp \mathrm{Ker}\mathcal{A}_0$. Therefore we can construct a modified version of $\mathcal{A}_0$ which is invertible.

  \begin{lemma}\label{lem:ainvertibility}
    $\widetilde{\mathcal{A}}_0 := \mathcal{A}_0 + \mathcal{P}: \mathcal{H}\rightarrow \mathcal{H}$ is invertible. Furthermore, $\widetilde{\mathcal{A}}_0[\Psi_i]=\Psi_i^*$, $\widetilde{\mathcal{A}}_0^*[\Psi_i^*]=\Psi_i, i=1,2,3$.
  \end{lemma}

\subsection{Calculation of resonant frequencies}\label{sec:resonantfrequency}

  When regarding $\mathcal{A}$ as an operator-valued function with independent variable $\omega$, the resonant frequencies are exactly the characteristic values (defined in Appendix \ref{sec:appa}) of $\mathcal{A}$. Unfortunately, the direct calculation of characteristic values of $\mathcal{A}$ is too complicated. \cite{HabibARMA} introduced a complete method to deal with such problem, which could be summarized as follows:
  \begin{itemize}
  \item Do asymptotic expansion of $\mathcal{A}(\omega)$ to find out leading order term $\mathcal{A}_0(\omega)$;
  \item Using Rouch\'{e}'s theorem (Theorem \ref{thm:rouche}), prove that for any characteristic value $\omega$ of $\mathcal{A}$, there exists a small neighborhood $V$ of $\omega$ such that $\mathcal{A}_0$ has characteristic value $\omega_0$ in $V$ with the same multiplicity as $\omega$ (Lemma 3.8 in \cite{HabibARMA});
  \item Calculate the difference between $\omega_0$ and $\omega$ with results in Theorem 3.9 in \cite{HabibARMA}.
  \end{itemize}
  We will apply this method here. The asymptotic expansion has been done in Section \ref{sec:asymptoticgreen}. Since the steps in \cite{HabibARMA} could be directly applied here to prove the relationship between characteristic values of $\mathcal{A}$ and $\mathcal{A}_0$ without much modification, we will not repeat them for brevity. Our goal of this section is to calculate the an approximation to the characteristic value $\omega$ of $\mathcal{A}$. We will not demonstrate the differences between $\omega$ and $\omega_0$, which could still be done by following the steps in Theorem 3.9 in \cite{HabibARMA}.


  Now we suppose for the characteristic value $\omega$, $\Phi\in \mathcal{H}$ is the non-trivial solution of equation $\mathcal{A}[\Phi] = 0$. We then decompose $\Phi$ as $\Phi = \Phi_0 + \Phi_\perp$, where
  $$
  \Phi_0:=\sum_{i=1}^3 \tau_i(\bm{\psi}^{(i)},0)^\top\in\mathrm{Ker}\mathcal{A}_0, \quad \Phi_\perp \perp \mathrm{Ker}\mathcal{A}_0.
  $$
  Here $\tau_i (i=1,2,3)$ are constants to be determined. An immediate result is that $P[\Phi_\perp]=0$.

Lemma \ref{lem:ainvertibility} ensured the invertibility of $\widetilde{\mathcal{A}}_0$, and due to the fact that $\widetilde{\mu}\rightarrow\infty$ and $\omega$ is very small, Rouch\'{e}'s theorem (Chapter 1 in \cite{HabibLayer}) guarantees the invertiblity of $\widetilde{\mathcal{A}}_0+\mathcal{B}$. We have the following asymptotic expansion
\begin{equation}\label{eq:a0pbexpansion}
    (\widetilde{\mathcal{A}}_0+\mathcal{B})^{-1} = (I+\sum\limits_{p=1}^{+\infty}(-1)^p(\widetilde{\mathcal{A}}_0^{-1}\mathcal{B})^p)\widetilde{\mathcal{A}}_0^{-1}
\end{equation}
Applying it to equation $\mathcal{A}[\Phi]=0$ leads to
\begin{equation}\label{eq:omegafreq1}
    (\widetilde{\mathcal{A}}_0+\mathcal{B})^{-1}(\widetilde{\mathcal{A}}_0+\mathcal{B}-\mathcal{P})[\Phi] = 0.
\end{equation}
Since $\mathcal{P}[\Phi] = \mathcal{P}[\Phi_0] + \mathcal{P}[\Phi_\perp] = \sum_{i=1}^3\tau_i\Psi_i^*$, \eqref{eq:omegafreq1} is equivalent to
$$
    \Phi_0 + \Phi_\perp - (\widetilde{\mathcal{A}}_0+\mathcal{B})^{-1}[\sum_{i=1}^3\tau_i\Psi_i^*] = 0
$$
Taking inner product with $\Phi_0$ on both sides of \eqref{eq:omegafreq1} gets rid of $\Phi_\perp$ term and transforms the equation above to
$$
    \left(\sum\limits_{i=1}^3\tau_i\Psi_i,\sum\limits_{j=1}^3\tau_j\Psi_j\right)_\mathcal{H} - \left((I+\sum\limits_{p=1}^{+\infty}(-1)^p(\widetilde{\mathcal{A}}_0^{-1}\mathcal{B})^p)\widetilde{\mathcal{A}}_0^{-1}[\sum\limits_{i=1}^3\tau_i\Psi_i^*], \sum\limits_{j=1}^3\tau_j\Psi_j\right)_\mathcal{H} = 0.
$$
Lemma \ref{lem:ainvertibility} tells us that $\widetilde{\mathcal{A}}_0^{-1}[\Psi_i^*] = \Psi_i$, which implies that
\begin{equation}\label{eq:cal1}
    \bigg((\widetilde{\mathcal{A}}_0^{-1}\mathcal{B}-(\widetilde{\mathcal{A}}_0^{-1}\mathcal{B})^2 + \cdots)\sum\limits_{i=1}^3\tau_i\Psi_i, \sum\limits_{j=1}^3\tau_j\Psi_j\bigg)_\mathcal{H} = 0.
\end{equation}
From \eqref{eq:adecompose}, we could see that $\mathcal{A}_{k,ex}\Psi_i = 0$ holds for any $k$, therefore we only need to focus on the contribution of $\mathcal{A}_{k,in}$ when calculating \eqref{eq:cal1}. From definition of $\mathcal{B}$ (Equation \eqref{eq:decomposeA}), $((\widetilde{\mathcal{A}}_0^{-1}\mathcal{B})^k\Psi_i, \Psi_j)_\mathcal{H} = O(\widetilde{\mu}^{-2})$ holds for $k\geq 2$, therefore we can neglect all the other higher-order terms. For the leading order term of $\widetilde{\mathcal{A}}_0^{-1}\mathcal{B}$, recalling that $\mathcal{A}_1 = \frac{1}{\widetilde{\mu}}\mathcal{A}_{1,in} + \frac{\omega^2}{\mu^2}\mathcal{A}_{1,ex}$ and $(\widetilde{\mathcal{A}}_0^{-1})^*[\Psi_j] = \Psi_j^*$, we then have
$$
    (\widetilde{\mathcal{A}}_0^{-1}\mathcal{B}\Psi_i, \Psi_j)_\mathcal{H} = \frac{1}{\widetilde{\mu}}(\widetilde{\mathcal{A}}_0^{-1}\mathcal{A}_{1,in}\Psi_i, \Psi_j)_\mathcal{H}+\mathcal{O}(\frac{1}{\widetilde{\mu}^2}) = \frac{1}{\widetilde{\mu}}(\mathcal{A}_{1,in}\Psi_i, \Psi_j^*)_\mathcal{H}+\mathcal{O}(\frac{1}{\widetilde{\mu}^2}).
$$
Since
$$
    \mathcal{A}_{1,in}\Psi_i = \begin{pmatrix} \widetilde{\mathcal{S}}_{+,1}^\alpha[\bm{\psi}^{(i)}] \\ \frac{\omega^2}{\widetilde{\mu}}(\widetilde{\mathcal{K}}_{+,2}^\alpha)^*[\bm{\psi}^{(i)}]\end{pmatrix},
$$
the leading order term in the last equation takes the following form
\begin{equation}\label{eq:a1inleadingorder}
\begin{aligned}
 \frac{1}{\widetilde{\mu}}(\mathcal{A}_{1,in}\Psi_i, \Psi_j^*)_\mathcal{H} = \frac{1}{\widetilde{\mu}C^*_j}\bigg\{\left(\widetilde{\mathcal{S}}_{+,1}^\alpha[\bm{\psi}^{(i)}], (\mathcal{S}_+^{\alpha,0})^{*,-1}[\bm{f}^{(j)}]\right) + \frac{\omega^2}{\widetilde{\mu}}\left((\widetilde{\mathcal{K}}^\alpha_{+,2})^*[\bm{\psi}^{(i)}], \bm{f}^{(j)}\right)\bigg\}.
\end{aligned}
\end{equation}
Since $\widetilde{\mathcal{S}}_{+,1}^\alpha=\mathcal{S}_{+,1}^\alpha = \mu\mathcal{S}_+^{\alpha,0}$, the first term in \eqref{eq:a1inleadingorder} is
$$
    \left(\widetilde{\mathcal{S}}_{+,1}^\alpha[\bm{\psi}^{(i)}], (\mathcal{S}_+^{\alpha,0})^{*,-1}[\bm{f}^{(j)}]\right) = (\mu\bm{\psi}^{(i)}, \bm{f}^{(j)}) = \mu\delta_{ij}.
$$
Now we calculate the second term $\frac{\omega^2}{\widetilde{\mu}}((\widetilde{\mathcal{K}}^\alpha_{+,2})^*[\bm{\psi}^{(i)}], \bm{f}^{(j)})$ in \eqref{eq:a1inleadingorder}. From recursive relations \eqref{eq:recursiverelation} we know that
$$
    \frac{1}{\widetilde{\mu}}\mathcal{L}^{\widetilde{\lambda},\widetilde{\mu}}\widetilde{\bm{G}}_{+,2}^\alpha = (\Delta + \nabla\nabla\cdot + \frac{\widetilde{\lambda}}{\widetilde{\mu}}\nabla\nabla\cdot)\widetilde{\bm{G}}_{+,2}^\alpha = -(\frac{\widetilde{\lambda}}{\omega^2}\nabla\nabla\cdot + \widetilde{\rho})\widetilde{\bm{G}}_{+,1}^\alpha + O(\frac{1}{\widetilde{\mu}}).
$$
Notice that $\bm{f}^{(j)}$ satisfies
\begin{equation*}
\left\{
\begin{aligned}
&\mathcal{L}^{\lambda,\mu}\bm{f}^{(j)}=0 \quad \mathrm{in~} D, \\
&\frac{\partial \bm{f}^{(j)}}{\partial \bm{\nu}}=0 \quad \mathrm{on~} \partial D,
\end{aligned}
\right.
\end{equation*}
for any $(\lambda,\mu)$ pair. We then have
\begin{align*}
    \frac{1}{\widetilde{\mu}}\widetilde{\mathcal{K}}_{+,2}^\alpha[\bm{f}^{(j)}] &= \frac{1}{\widetilde{\mu}}\int_{\partial D}\frac{\partial \widetilde{\bm{G}}_{+,2}^\alpha(x,y)}{\partial\bm{\widetilde{\nu}}_y}\bm{f}^{(j)}(y)\mathrm{d}\sigma(y) = \frac{1}{\widetilde{\mu}}\int_D \mathcal{L}^{\widetilde{\lambda},\widetilde{\mu}}\widetilde{\bm{G}}_{+,2}^\alpha(x,y)\bm{f}^{(j)}(y)\mathrm{d}y\\
    & = -\int_D \left(\frac{\widetilde{\lambda}}{\omega^2}\nabla_y\nabla_y\cdot\widetilde{\bm{G}}_{+,1}^\alpha(x,y)+\widetilde{\rho}\widetilde{\bm{G}}_{+,1}^\alpha(x,y)\right)\bm{f}^{(j)}(y)\mathrm{d}y + O(\frac{1}{\widetilde{\mu}}) \\
    &= \int_D \frac{\widetilde{\lambda}}{\omega^2}\Delta_y\widetilde{\bm{G}}_{+,1}^\alpha(x,y) \bm{f}^{(j)}(y)\mathrm{d}y -\widetilde{\rho}\int_D\widetilde{\bm{G}}_{+,1}^\alpha(x,y)\bm{f}^{(j)}(y)\mathrm{d}y + O(\frac{1}{\widetilde{\mu}})
\end{align*}
Notice that $\widetilde{\bm{G}}_{+,1}^\alpha$ satisfies homogeneous Lam\'{e} system with $\lambda = 0, \mu = 1,\omega=0$, which means the corresponding boundary contraction is
$$
\frac{\partial\widetilde{\bm{G}}_{+,1}^\alpha}{\partial\bm{\nu}_{1,0,y}} = (\nabla_y\widetilde{\bm{G}}_{+,1}^\alpha + \nabla_y(\widetilde{\bm{G}}_{+,1}^\alpha)^\top)\bm{\nu}_y = \partial_{\bm{\nu}_y}\widetilde{\bm{G}}_{+,1}^\alpha + \partial_{\bm{\nu}_y}(\widetilde{\bm{G}}_{+,1}^\alpha)^\top = 2\partial_{\bm{\nu}_y}\widetilde{\bm{G}}_{+,1}^\alpha.
$$
Since $x\in\partial D$, calculation then follows
\begin{align*}
    \int_D \Delta_y \widetilde{\bm{G}}_{+,1}^\alpha(x,y)\bm{f}^{(j)}(y)\mathrm{d}y &= \int_{\partial D}\partial_{\bm{\nu}_y}\widetilde{\bm{G}}_{+,1}^\alpha(x,y)\bm{f}^{(j)}(y)\mathrm{d}\sigma(y) = \frac{1}{2}\int_{\partial D}\frac{\partial \widetilde{\bm{G}}_{+,1}^\alpha(x,y)}{\partial \bm{\nu}_{1,0,y}}\bm{f}^{(j)}(y)\mathrm{d}\sigma(y)\\
     &= \frac{1}{2}\int_D \mathcal{L}^{1,0}\widetilde{\bm{G}}_{+,1}^\alpha(x,y)\bm{f}^{(j)}(y)\mathrm{d}\sigma(y)=0.
\end{align*}
Therefore the second term in $(\mathcal{A}_{1,in}\Psi_i,\Psi_j^*)_\mathcal{H}$ is
\begin{align*}
    \frac{\omega^2}{\widetilde{\mu}}((\widetilde{\mathcal{K}}_{+,2}^\alpha)^*[\bm{\psi}^{(i)}],\bm{f}^{(j)}) &= \frac{\omega^2}{\widetilde{\mu}}(\bm{\psi}^{(i)}, \widetilde{\mathcal{K}}_{+,2}^\alpha[\bm{f}^{(j)}]) \\
    &= -\widetilde{\rho}\omega^2\int_{\partial D}\bm{\psi}^{(i)}(x)\int_D\widetilde{\bm{G}}_{+,1}^\alpha(x,y)\bm{f}^{(j)}(y)\mathrm{d}y\mathrm{d}\sigma(x) + O(\frac{1}{\widetilde{\mu}}) \\
    &= -\widetilde{\rho}\omega^2\int_D \widetilde{\mathcal{S}}_{+,1}^\alpha[\bm{\psi}^{(i)}](y)\bm{f}^{(j)}(y)\mathrm{d}y + O(\frac{1}{\widetilde{\mu}}).
\end{align*}
Define
\begin{equation*}
\mathcal{C} = \begin{pmatrix}\frac{1}{C_1^*} & & \\ & \frac{1}{C_2^*} & \\ & & \frac{1}{C_3^*}\end{pmatrix}, \quad \mathcal{M} = \begin{pmatrix} m_{11} & m_{12} & m_{13} \\ m_{21} & m_{22} & m_{23} \\ m_{31} & m_{32} & m_{33} \end{pmatrix}
\end{equation*}
where $m_{ij} := \int_D \widetilde{\mathcal{S}}_{+,1}^{\alpha}[\bm{\psi}^{(i)}](y)\bm{f}^{(j)}(y)\mathrm{d}y$. We can then summarize the calculation above as
\begin{equation}\label{eq:a0inva1}
    (\widetilde{\mathcal{A}}_0^{-1}\mathcal{A}_1\sum\limits_{i=1}^3\tau_i\Psi_i, \sum\limits_{i=1}^3\tau_j\Psi_j)_\mathcal{H} = \bm{\tau}^\top(\mu\bm{I}-\widetilde{\rho}\omega^2\mathcal{M}+O(\frac{1}{\widetilde{\mu}^2}))\mathcal{C}\bm{\tau},
\end{equation}
The characteristic value of $\mathcal{A}$ can then be approximated by the eigenvalue of $\mu\bm{I} - \widetilde{\rho}\omega^2\mathcal{M}$. To conclude,
\begin{theorem}\label{thm:resonantfrequency}
    Let $m_i, i=1,2,3$ be the eigenvalue of $\mathcal{M}$. Then the resonant frequencies are
    $$
    \omega_i = \sqrt{\frac{\mu}{\widetilde{\rho} m_i}} + O(\widetilde{\mu}^{-1}).
    $$
    Since $m_i$ only depends on the shape of $D$, it is immediate that the subwavelength resonance occurs \emph{if and only if} $\mu/\widetilde{\rho}\rightarrow 0$.
    %The corresponding wavenumber of P-wave and S-wave is
    %$$
    %    k_P = \sqrt{\frac{1}{m_i(\lambda+2\widetilde{\mu})}} + O(\widetilde{\mu}^{-1}), k_S = \sqrt{\frac{1}{m_i\widetilde{\mu}}} + O(\widetilde{\mu}^{-1}).
    %$$
    %It is obvious that $k_P, k_S$ is of order $O(\widetilde{\mu}^{-1/2})$. \textcolor{red}{This is not the subwavelength resonance.}
\end{theorem}
