\subsection{Near-field and far-field calculation}
In the scenario of sub-wavelength resonance, i.e. $\omega\rightarrow 0$ and $\widetilde{\mu}\rightarrow \infty$, we are able to carry out further calculations of approximated near field and far field based on asymptotic expansions of $\omega$ and $\widetilde{\mu}$. Assuming now the incident wave is P-wave, we want to solve
\begin{equation}\label{eq:psimain}
(\widetilde{\mathcal{A}}_0+\mathcal{B}-\mathcal{P})\Phi = \bm{F}.
\end{equation}
$\bm{F}$ is defined in \eqref{eq:Fdefinition}. Same as previous subsection, we decompose $\Phi = \Phi_0 + \Phi_\perp$, where $\Phi_0 = \sum_{i=1}^3\tau_i\Psi_i$. The first goal of this subsection is to determine $\tau_i$ and $\Phi_\perp$.

\subsubsection{Determine $\tau_i$.}

By applying $(\widetilde{\mathcal{A}}_0+\mathcal{B})^{-1}$ to both sides of \eqref{eq:psimain} we get
\begin{equation}\label{eq:psimain1}
    \Phi_0 + \Phi_\perp - (\widetilde{\mathcal{A}}_0+\mathcal{B})^{-1}\mathcal{P}\Phi = (\widetilde{\mathcal{A}}_0+\mathcal{B})^{-1}\bm{F}.
\end{equation}
where $\bm{F} = (\bm{u}_P^+, \partial\bm{u}_P^+/\partial\bm{\nu})^\top$. The contraction $\partial\bm{\nu}$ is taking on the outward boundary of $\partial D$, hence is independent of $\widetilde{\mu}$. Taking inner product with $\Psi_j$ on both sides and following the same calculation steps as \eqref{eq:omegafreq1}-\eqref{eq:cal1}, we get
\begin{equation}\label{eq:psijinnerproduct}
    \bigg((\widetilde{\mathcal{A}}_0^{-1}\mathcal{B}-(\widetilde{\mathcal{A}}_0^{-1}\mathcal{B})^2 + \cdots)\sum\limits_{i=1}^3\tau_i\Psi_i, \Psi_j\bigg)_\mathcal{H} = ((\widetilde{\mathcal{A}}_0+\mathcal{B})^{-1}\bm{F}, \Psi_j)_\mathcal{H}.
\end{equation}
The right-hand side of \eqref{eq:psijinnerproduct} can be expanded as
\begin{equation}\label{eq:a0binv1}
    ((\widetilde{\mathcal{A}}_0+\mathcal{B})^{-1}\bm{F}, \Psi_j)_\mathcal{H} = (\widetilde{\mathcal{A}}_0^{-1}\bm{F}-\widetilde{\mathcal{A}}_0^{-1}\mathcal{A}_1\widetilde{\mathcal{A}}_0^{-1}\bm{F}, \Psi_j)_\mathcal{H} + \mathcal{O}(\omega^2)+\mathcal{O}(\frac{1}{\widetilde{\mu}^2}).
\end{equation}
By carefully checking the definition of $\mathcal{A}_1$, we notice that
\begin{equation}\label{eq:a1expansion}
    \mathcal{A}_1 = \frac{1}{\widetilde{\mu}}\begin{pmatrix}\widetilde{\mathcal{S}}_{+,1}^\alpha & 0 \\ 0 & 0\end{pmatrix} + \frac{\omega^2}{\widetilde{\mu}^2}\begin{pmatrix}0 & 0 \\ (\widetilde{\mathcal{K}}_{+,2}^\alpha)^* & 0\end{pmatrix} - \frac{\omega^2}{\mu^2}\begin{pmatrix} 0 & \mathcal{S}_{+,2}^\alpha \\ 0 & (\mathcal{K}_{+,2}^\alpha)^*\end{pmatrix} = \frac{1}{\widetilde{\mu}}\begin{pmatrix}\widetilde{\mathcal{S}}_{+,1}^\alpha & 0 \\ 0 & 0\end{pmatrix} + \mathcal{O}(\omega^2).
\end{equation}
Therefore, the leading order term of $(\widetilde{\mathcal{A}}_0^{-1}\mathcal{A}_1\widetilde{\mathcal{A}}_0^{-1}\bm{F},\Psi_j)$ is
$$
    \frac{1}{\widetilde{\mu}}\left(\begin{pmatrix}\widetilde{\mathcal{S}}_{+,1}^\alpha & 0 \\ 0 & 0\end{pmatrix}\widetilde{\mathcal{A}}_0^{-1}\bm{F}, \Psi_j^*\right)_\mathcal{H} = \frac{1}{\widetilde{\mu}}\left(\widetilde{\mathcal{A}}_0^{-1}\bm{F}, \begin{pmatrix}(\widetilde{\mathcal{S}}_{+,1}^\alpha)^* & 0 \\ 0 & 0\end{pmatrix}\begin{pmatrix} (\mathcal{S}_+^{\alpha,0})^{*,-1}[\bm{f}^{(j)}] \\ \bm{f}^{(j)}\end{pmatrix}\right)_\mathcal{H}= \frac{\mu}{\widetilde{\mu}}(\widetilde{\mathcal{A}}_0^{-1}\bm{F}, \Psi_j)_\mathcal{H}.
$$
\eqref{eq:a0binv1} could then be reformulated as
\begin{equation}\label{eq:a0binv2}
    ((\widetilde{\mathcal{A}}_0+B)^{-1}\bm{F}, \Psi_j)_\mathcal{H} = \left(1-\frac{\mu}{\widetilde{\mu}}\right)(\widetilde{\mathcal{A}}_0^{-1}\bm{F}, \Psi_j) + \mathcal{O}(\omega^2)+\mathcal{O}(\frac{1}{\widetilde{\mu}^2}) =: \left(1-\frac{\mu}{\widetilde{\mu}}\right)\mathcal{K}_j + \mathcal{O}(\omega^2)+\mathcal{O}(\frac{1}{\widetilde{\mu}^2}).
\end{equation}
Define $\mathcal{K}:=(\mathcal{K}_1, \mathcal{K}_2, \mathcal{K}_3)^\top$. Equation \eqref{eq:a0inva1} tells us that
$$
((\widetilde{\mathcal{A}}_0+B)^{-1}[\sum\tau_i\Psi_i^*], \Psi_j) = \mathcal{C}(\mu\bm{I}-\widetilde{\rho}\omega^2\mathcal{M})\bm{\tau} + O(\frac{1}{\widetilde{\mu}^2}).
$$
Plugging \eqref{eq:a0binv2} and this equation into \eqref{eq:psijinnerproduct}
$$
\bm{\tau} = (1-\frac{\mu}{\widetilde{\mu}})(\mu\bm{I}-\widetilde{\rho}\omega^2\mathcal{M})^{-1}\mathcal{C}^{-1}\mathcal{K}+\mathcal{O}(\omega^2)+\mathcal{O}(\widetilde{\mu}^{-2}).
$$
To achieve an estimation of $\mathcal{K}_j$, we need to calculate
$$
(\widetilde{\mathcal{A}}_0^{-1}F, \Psi_j)_\mathcal{H} = (F, \Psi_j^*)_\mathcal{H} = \left(\begin{pmatrix}\bm{u}_+^P \\ \frac{\partial \bm{u}_+^P}{\partial \bm{\nu}}\end{pmatrix}, \begin{pmatrix}(\mathcal{S}^{\alpha,0}_+)^{*,-1}[\bm{f}^{(j)}] \\ \bm{f}^{(j)}\end{pmatrix}\right)_\mathcal{H}.
$$
It then suffices to calculate $(\bm{u}_+^P, (\mathcal{S}^{\alpha,0}_+)^{*,-1}[\bm{f}^{(j)}])$ and $(\partial \bm{u}_+^P/\partial\bm{\nu}, \bm{f}^{(j)})$.
\begin{itemize}
\item \emph{$(\bm{u}_+^P, (\mathcal{S}^{\alpha,0}_+)^{*,-1}[\bm{f}^{(j)}])$ term}.

Since $\omega\rightarrow 0$, we could expand definition equation \eqref{eq:upp} of $\bm{u}_P^+$ and get that
$$
    \bm{u}_+^P(\bm{x}) = 2\ii\omega\sqrt{\frac{\rho}{\lambda+2\mu}}\theta_2x_2\bm{\theta} + \mathcal{O}(\omega^2).
$$
Hence
$$
    (\bm{u}_+^P, (\mathcal{S}_+^{\alpha,0})^{*,-1}[\bm{f}^{(j)}]) = 2\ii\omega\sqrt{\frac{\rho}{\lambda+2\mu}}\theta_2((\mathcal{S}_+^{\alpha,0})^{-1}[x_2\bm{\theta}], \bm{f}^{(j)}) + \mathcal{O}(\omega^2).
$$
To proceed, we need the following lemma.
\begin{lemma}\label{lem:htheta}
Define
$$
\bm{h}(\bm{\theta}):=\frac{\partial (x_2\bm{\theta})}{\partial\bm{\nu}} = \theta_2(\lambda\nu_1, (\lambda+2\mu)\nu_2)^\top.
$$
Then
    $$
    (\mathcal{S}_+^{\alpha,0})^{-1}[x_2\bm{\theta}] = (-\frac{1}{2}\bm{I}+(\mathcal{K}^{\alpha,0}_+)^*)^{-1}[\bm{h}(\bm{\theta})] + \sum\limits_{i=1}^3 ( x_2\bm{\theta},\bm{\psi}^{(i)})(\mathcal{S}_+^{\alpha,0})^{-1}[\bm{f}^{(i)}].
    $$
\end{lemma}
\begin{proof}
Define $\bm{f}_\theta=x_2\bm{\theta} - \sum_{i=1}^3(x_2\bm{\theta}, \bm{\psi}^{(i)}) \bm{f}^{(i)}$. The construction of $\bm{f}_\theta$ immediately implies that $\bm{f}_\theta\in H_W(\partial D)$. Recalling that $\bm{f}^{(i)}\in\Psi$ are solutions of inner Neumann problem, we can then observe that
\begin{equation*}
\left\{
\begin{aligned}
&\mathcal{L}^{\lambda,\mu}\bm{f}_\theta=0 \quad \mathrm{in}~D, \\
&\frac{\partial \bm{f}_\theta}{\partial\bm{\nu}}|_- = \bm{h}(\bm{\theta}) \quad\mathrm{on}~\partial D.
\end{aligned}
\right.
\end{equation*}
It follows that $\bm{h}(\bm{\theta})\in H_\Psi(\partial D)$, which means $\bm{h}(\bm{\theta})\in\mathrm{Im}(-\bm{I}/2+(\mathcal{K}_+^{\alpha,0})^*)$. Define $\bm{\eta}_-:=(-\bm{I}/2+(\mathcal{K}^{\alpha,0}_+)^*)^{-1}[\bm{h}(\bm{\theta})]$. Then $\bm{\eta}_-\in H_\Psi(\partial D)$, and $\mathcal{S}_+^{\alpha,0}[\bm{\eta}_-] = \bm{f}_\theta$ holds since we have already ensured that $\bm{f}_\theta\in H_W(\partial D)$. The result the follows by applying $(\mathcal{S}_+^{\alpha,0})^{-1}$ on both sides of definition equation of $\bm{f}_\theta$.
\end{proof}
From Lemma \ref{lem:decompose} we know that $\mathcal{S}_+^{\alpha,0}$ maps $W$ into $\Psi$. Recall that $\widetilde{\mathcal{S}}_{+,1}^\alpha$ is independent of $\lambda,\mu$ and satisfies $\widetilde{\mathcal{S}}_{+,1}^\alpha = \mu\mathcal{S}_+^{\alpha,0}$. We assume
$$
\widetilde{\mathcal{S}}_{+,1}^\alpha[\bm{\psi}^{(i)}] =: \sum_{j=1}^3 s_{ij}\bm{f}^{(j)}
$$
and define $\bm{S}=(s_{ij})_{3\times 3}$. The invertibility of $\widetilde{\mathcal{S}}_{+,1}^{\alpha}$ indicates $\bm{S}$ is invertible. Denote $\bm{S}^{-1} = (s_{ij}^{-1})_{3\times 3}$, where $\sum_{j=1}^3 s_{ij}^{-1}s_{jk} = \delta_{ik}$. Then $(\widetilde{\mathcal{S}}_{+,1}^\alpha)^{-1}[\bm{f}^{(i)}] = \sum_{j=1}^3 s_{ij}^{-1}\bm{\psi}^{(j)}$. As a result,
\begin{align*}
    \left((\mathcal{S}_+^{\alpha,0})^{-1}[x_2\bm{\theta}], \bm{f}^{(i)}\right) =& \left((\mathcal{S}_+^{\alpha,0})^{-1}[\bm{f}_\theta] + \sum\limits_{j=1}^3( x_2\bm{\theta},\bm{\psi}^{(j)})(\mathcal{S}_+^{\alpha,0})^{-1}[\bm{f}^{(j)}], \bm{f}^{(i)}\right) \\
    =& \sum\limits_{j=1}^3 (x_2\bm{\theta},\bm{\psi}^{(j)})\sum\limits_{k=1}^3 (\mu s_{jk}^{-1}\bm{\psi}^{(k)}, \bm{f}^{(i)}) = \sum\limits_{j=1}^3(x_2\bm{\theta}, \bm{\psi}^{(j)})\mu s_{ji}^{-1},
\end{align*}
The second equality holds because $(\mathcal{S}_+^{\alpha,0})^{-1}[\bm{f}_\theta]\in H_\Psi(\partial D)$. We then have
\begin{align*}
\left(\bm{u}_+^P, (\mathcal{S}_+^{\alpha,0})^{*,-1}[\bm{f}^{(j)}]\right) = 2\ii\omega\sqrt{\frac{\rho}{\lambda+2\mu}}\theta_2 \sum\limits_{i=1}^3(x_2\bm{\theta}, \bm{\psi}^{(i)})\mu s_{ij}^{-1} + \mathcal{O}(\omega^2).
\end{align*}
\item \emph{$(\partial \bm{u}_+^P/\partial\bm{\nu}, \bm{f}^{(i)})$ term.}

By expanding \eqref{eq:upnu1}, \eqref{eq:upnu21} and \eqref{eq:upnu22} with respect to $\omega$, we know that
\begin{align*}
    \left(\frac{\partial \bm{u}_+^P}{\partial \bm{\nu}}\right)_1 &= 2\lambda\omega\sqrt{\frac{\rho}{\lambda+2\mu}}\nu_1 + 2\ii\mu\omega\sqrt{\frac{\rho}{\lambda+2\mu}}\theta_1\theta_2\nu_2+ \mathcal{O}(\omega^2), \\
    \left(\frac{\partial\bm{u}_+^P}{\partial\bm{\nu}}\right) &= 2\lambda\omega\sqrt{\frac{\rho}{\lambda+2\mu}}\nu_2 + 2\ii\mu\omega\sqrt{\frac{\rho}{\lambda+2\mu}}\theta_1\theta_2\nu_1 + 4\ii\mu\omega\sqrt{\frac{\rho}{\lambda+2\mu}}\theta_2^2\nu_2+\mathcal{O}(\omega^2).
\end{align*}
So
\begin{align*}
    \left(\frac{\partial \bm{u}_+^P}{\partial \bm{\nu}}, \bm{f}^{(i)}\right)=& 2\lambda\omega\sqrt{\frac{\rho}{\lambda+2\mu}}(\bm{\nu}, \bm{f}^{(i)}) + 2\ii\mu\omega\sqrt{\frac{\rho}{\lambda+2\mu}}\theta_1\theta_2((\nu_2,\nu_1)^\top, \bm{f}^{(i)}) \\
    &+ 4\ii\mu\omega\sqrt{\frac{\rho}{\lambda+2\mu}}\theta_2^2((0,\nu_2)^\top, \bm{f}^{(i)})+ \mathcal{O}(\omega^2) .
\end{align*}
From definition of $\bm{f}^{(i)}$ we could verify that $\nabla\cdot \bm{f}^{(i)}=0$, hence by divergence theorem we have $(\bm{\nu}, \bm{f}^{(i)}) = 0, i=1,2,3$. Similarly,
\begin{align*}
    \int_{\partial D}\begin{pmatrix}\nu_2 \\ \nu_1 \end{pmatrix}\cdot\begin{pmatrix}\bm{f}^{(i)}_1 \\ \bm{f}^{(i)}_2 \end{pmatrix}\mathrm{d}\sigma = \int_D\nabla\cdot\begin{pmatrix}\bm{f}^{(i)}_2 \\ \bm{f}^{(i)}_1\end{pmatrix}\mathrm{d}x = 0, \\
    \int_{\partial D}\begin{pmatrix}0 \\ \nu_2 \end{pmatrix}\cdot\begin{pmatrix}\bm{f}^{(i)}_1 \\ \bm{f}^{(i)}_2 \end{pmatrix}\mathrm{d}\sigma = \int_D\nabla\cdot\begin{pmatrix}0 \\ \bm{f}^{(i)}_2\end{pmatrix}\mathrm{d}x = 0.
\end{align*}
This implies $(\partial \bm{u}_+^P/\partial\bm{\nu}, \bm{f}^{(i)})=\mathcal{O}(\omega^2)$.
\end{itemize}
To conclude, the coefficient vector $\bm{\tau}$ takes the following form:
\begin{equation}\label{eq:alphaexpression}
\begin{aligned}
   \bm{\tau} =& 2\ii\omega\sqrt{\frac{\rho}{\lambda+2\mu}}\mu(1-\frac{\mu}{\widetilde{\mu}})\theta_2(\mu\bm{I}-\widetilde{\rho}\omega^2\mathcal{M})^{-1}\sum\limits_{j=1}^3(x_2\bm{\theta}, \bm{\psi}^{(j)})\begin{pmatrix}c_1s_{j1}^{-1} \\ c_2s_{j2}^{-1} \\ c_3s_{j3}^{-1}\end{pmatrix}\\&+\mathcal{O}(\omega^2)+\mathcal{O}(\widetilde{\mu}^{-2}).
\end{aligned}
\end{equation}
\begin{remark}\label{rmk:order}
Here we would like to estimate the order of $\bm{\alpha}$. From previous discussions we know that
$$
    \mathcal{C}(\mu\bm{I}-\widetilde{\rho}\omega^2\mathcal{M})\bm{\tau} = (1-\frac{\mu}{\widetilde{\mu}})\mathcal{K} + \mathcal{O}(\omega^2) + \mathcal{O}(\frac{1}{\widetilde{\mu}^2}).
$$
From definitions it is obvious that $\mathcal{C} = \mathcal{O}(1)$, $\mathcal{K} = \mathcal{O}(1)$, so the right-hand side is $\mathcal{O}(1)$. We can then conclude that $\bm{\tau} = \mathcal{O}(\mu^{-1})$. In case that $\mu = \mathcal{O}(\widetilde{\mu}^{-1})$, we then have $\bm{\tau} = \mathcal{O}(\widetilde{\mu})$.
\end{remark}

\subsubsection{Determining $\Phi_\perp$.}

Now we start the calculation of $\Phi_\perp$. Similar asymptotic analysis of \eqref{eq:psimain1} leads to
\begin{equation}\label{eq:psiperp}
\Phi_\perp = \widetilde{\mathcal{A}}_0^{-1}\bm{F} - \widetilde{\mathcal{A}}_0^{-1}\mathcal{A}_1\widetilde{\mathcal{A}}_0^{-1}\bm{F} - \sum\limits_{i=1}^3\tau_i\widetilde{\mathcal{A}}_0^{-1}\mathcal{A}_1[\Psi_i] + \mathcal{O}(\omega^2) + \mathcal{O}(\frac{1}{\widetilde{\mu}^2}).
\end{equation}
\begin{itemize}
  \item \emph{$\widetilde{\mathcal{A}}_0^{-1}\bm{F}$ term}.

  Recall that $\widetilde{\mathcal{A}}_0 = \mathcal{A}_0+\mathcal{P}$. Denote $\beta_i:= (\bm{F},\Psi_i^*)_\mathcal{H}$ and $\bm{F}_\perp:= \bm{F}-\sum_{i=1}^3\beta_i\Psi_i^*$, then $\bm{F}_\perp$ is orthogonal to $\mathrm{Ker}\mathcal{A}_0^*$, and therefore belongs to $\mathrm{Im}\mathcal{A}_0$. We then have
  $$
    \widetilde{\mathcal{A}}_0^{-1}\bm{F} = \mathcal{A}_0^{-1}\bm{F}_\perp + \sum\limits_{i=1}^3\beta_i\Psi_i.
  $$
  From the asymptotic expansion of $\bm{F}$, we can estimate $\beta_i$ by
  \begin{align*}
    \beta_i &= (\bm{F},\Psi_i^*)_\mathcal{H} = \left(\begin{pmatrix}2\ii\omega\sqrt{\frac{\rho}{\lambda+2\mu}}\theta_2x_2\bm{\theta}+\mathcal{O}(\omega^2)\\ \partial \bm{u}_+^P/\partial\bm{\nu} \end{pmatrix}, \begin{pmatrix}(\mathcal{S}_+^{\alpha,0})^{*,-1}[\bm{f}^{(i)}] \\ \bm{f}^{(i)}\end{pmatrix}\right)_\mathcal{H} \\
    &= \left(2\ii\omega\sqrt{\frac{\rho}{\lambda+2\mu}}\theta_2x_2\bm{\theta}, (\mathcal{S}_+^{\alpha,0})^{*,-1}[\bm{f}^{(i)}]\right) + \left(\frac{\partial\bm{u}_+^P}{\partial\bm{\nu}}, \bm{f}^{(i)}\right) +\mathcal{O}(\omega^2\mu) \\
    &= 2\ii\omega\sqrt{\frac{\rho}{\lambda+2\mu}}\theta_2((\mathcal{S}_+^{\alpha,0})^{-1}[x_2\bm{\theta}], \bm{f}^{(i)}) +\mathcal{O}(\omega^2) + \mathcal{O}(\omega^2\mu) \\&= 2\ii\omega\mu\theta_2\sqrt{\frac{\rho}{\lambda+2\mu}}\sum\limits_{j=1}^3(x_2\bm{\theta}, \bm{\psi}^{(j)})s_{ji}^{-1}+\mathcal{O}(\omega^2) + \mathcal{O}(\omega^2\mu).
  \end{align*}
  The second last equality holds because of results in last section. The last equality holds because of Lemma \ref{lem:htheta} and the fact that $(-\frac{1}{2}\bm{I}+(\mathcal{K}^{\alpha,0}_+)^*)^{-1}[\bm{h}(\bm{\theta})]\in H_\Psi(\partial D)$.

  Denote $\bm{F}_\perp =: (\bm{F}_{\perp,1}, \bm{F}_{\perp,2})^\top$, then
  \begin{align*}
    \bm{F}_{\perp,1} &= 2\ii\omega\sqrt{\frac{\rho}{\lambda+2\mu}}\theta_2\left(x_2\bm{\theta} - \mu\sum\limits_{i=1}^3(x_2\bm{\theta}, \bm{\psi}^{(j)})\sum\limits_{j=1}^3 s_{ji}^{-1}(\mathcal{S}_+^{\alpha,0})^{*,-1}[\bm{f}^{(i)}]\right)+\mathcal{O}(\omega^2) +\mathcal{O}(\omega^2\mu),\\
    \bm{F}_{\perp,2} &= 2\lambda\omega\sqrt{\frac{\rho}{\lambda+2\mu}}\bm{\nu} + 4\ii\mu\omega\sqrt{\frac{\rho}{\lambda+2\mu}}\theta_2^2\begin{pmatrix}0 \\ \nu_2\end{pmatrix} \\&+ 2\ii\omega\mu\sqrt{\frac{\rho}{\lambda+2\mu}}\theta_2\left(\theta_1\begin{pmatrix}\nu_2 \\ \nu_1\end{pmatrix} - \sum\limits_{i=1}^3\sum\limits_{j=1}^3(x_2\bm{\theta}, \bm{\psi}^{(j)})s_{ji}^{-1}\bm{f}^{(i)}\right) + \mathcal{O}(\omega^2) + \mathcal{O}(\omega^2\mu).
  \end{align*}
  For $\mathcal{A}_0^{-1}\bm{F}_\perp$, we estimate each item separately. We know that
  $$
    \mathcal{A}_0^{-1} = \begin{pmatrix}
    -(-\frac{1}{2}\bm{I} + (\widetilde{\mathcal{K}}_+^{\alpha,0})^*)^{-1}(\frac{1}{2}\bm{I} + (\mathcal{K}_+^{\alpha,0})^*)(\mathcal{S}_+^{\alpha,0})^{-1} & (-\frac{1}{2}\bm{I}+(\widetilde{\mathcal{K}}_+^{\alpha,0})^*)^{-1} \\ -(\mathcal{S}_+^{\alpha,0})^{-1} & 0
    \end{pmatrix}.
  $$
  So
  \begin{align*}
    (\mathcal{A}_0^{-1}\bm{F}_\perp)_1 &= -(-\frac{1}{2}\bm{I} + (\widetilde{\mathcal{K}}_+^{\alpha,0})^*)^{-1}(\frac{1}{2}\bm{I} + (\mathcal{K}_+^{\alpha,0})^*)(\mathcal{S}_+^{\alpha,0})^{-1}[\bm{F}_{\perp,1}] + (-\frac{1}{2}\bm{I}+(\widetilde{\mathcal{K}}_+^{\alpha,0})^*)^{-1}[\bm{F}_{\perp,2}], \\
    (\mathcal{A}_0^{-1}\bm{F}_\perp)_2 &= -(\mathcal{S}_+^{\alpha,0})^{-1}[\bm{F}_{\perp,1}].
  \end{align*}
  Use the definition and result in Lemma \ref{lem:htheta}, we have
  \begin{align*}
    &(\mathcal{A}_0^{-1}\bm{F}_\perp)_1 = -(-\frac{1}{2}\bm{I} + (\widetilde{\mathcal{K}}_+^{\alpha,0})^*)^{-1}(\frac{1}{2}\bm{I}+(\mathcal{K}_+^{\alpha,0})^*)(\mathcal{S}_+^{\alpha,0})^{-1}\bm{F}_{\perp,1} \\&+ 2\lambda\omega\sqrt{\frac{\rho}{\lambda+2\mu}}(-\frac{1}{2}\bm{I}+(\widetilde{\mathcal{K}}_+^{\alpha,0})^*)^{-1}[\bm{\nu}] +\mathcal{O}(\omega\mu) + \mathcal{O}(\omega^2) \\&= -2\ii\omega\sqrt{\frac{\rho}{\lambda+2\mu}}\theta_2(-\frac{1}{2}\bm{I} + (\widetilde{\mathcal{K}}_+^{\alpha,0})^*)^{-1}
    \\&\left((-\frac{1}{2}\bm{I}+(\mathcal{K}_+^{\alpha,0})^*)^{-1}[\bm{h(\theta)}] - \bm{h(\theta)} - (\frac{1}{2}\bm{I}+(\mathcal{K}_+^{\alpha,0})^*)(\mathcal{S}_+^{\alpha,0})^{-1}\sum\limits_{i=1}^3(x_2\bm{\theta},\bm{\psi}^{(i)})[\bm{f}^{(i)}]\right)\\ &+ 2\lambda\omega\sqrt{\frac{\rho}{\lambda+2\mu}}(-\frac{1}{2}\bm{I}+(\widetilde{\mathcal{K}}_+^{\alpha,0})^*)^{-1}[\bm{\nu}]+ \mathcal{O}(\omega\mu) \\
    &= -2\ii\omega\sqrt{\frac{\rho}{\lambda+2\mu}}\theta_2(-\frac{1}{2}\bm{I} + (\widetilde{\mathcal{K}}_+^{\alpha,0})^*)^{-1}\left((-\frac{1}{2}\bm{I}+(\mathcal{K}_+^{\alpha,0})^*)^{-1}[\bm{h(\theta)}] - \bm{h(\theta)} - \sum\limits_{i=1}^3 (x_2\bm{\theta}, \bm{\psi}^{(i)})\bm{f}^{(i)}\right)\\&+ 2\lambda\omega\sqrt{\frac{\rho}{\lambda+2\mu}}(-\frac{1}{2}\bm{I}+(\widetilde{\mathcal{K}}_+^{\alpha,0})^*)^{-1}[\bm{\nu}]+\mathcal{O}(\omega\mu).
  \end{align*}
  The third equality holds because
  $$
    (-\frac{1}{2}\bm{I} + (\mathcal{K}_+^{\alpha,0})^*)(\mathcal{S}_+^{\alpha,0})^{-1}[\bm{f}^{(i)}] = 0.
  $$
  For the sake of brevity, we define
  \begin{align*}
    &\mathscr{F}_{\perp,1} := \\&-2\ii\omega\sqrt{\frac{\rho}{\lambda+2\mu}}\theta_2\left((-\frac{1}{2}\bm{I}+(\mathcal{K}_+^{\alpha,0})^*)^{-1}[\bm{h(\theta)}] - \bm{h(\theta)} - \sum\limits_{i=1}^3 (x_2\bm{\theta}, \bm{\psi}^{(i)})\bm{f}^{(i)}\right)+2\lambda\omega\sqrt{\frac{\rho}{\lambda+2\mu}}\bm{\nu},
  \end{align*}
  then
  $$
    (\mathcal{A}_0^{-1}\bm{F}_\perp)_1 = (-\frac{1}{2}\bm{I} + (\widetilde{\mathcal{K}}_+^{\alpha,0})^*)^{-1}[\mathscr{F}_{\perp,1}] + \mathcal{O}(\omega\mu).
  $$
  Similarly, we have
  \begin{align*}
    (\mathcal{A}_0^{-1}\bm{F}_\perp)_2 = -(\mathcal{S}_+^{\alpha,0})^{-1}[\bm{F}_{\perp, 1}] = -2\ii\omega\sqrt{\frac{\rho}{\lambda+2\mu}}\theta_2(\mathcal{S}_+^{\alpha,0})^{-1}[x_2\bm{\theta}] +\mathcal{O}(\omega\mu^2).
  \end{align*}
  \item \emph{$\tau_i\widetilde{\mathcal{A}}_0^{-1}\mathcal{A}_1[\Psi_i]$ term}.

  From \eqref{eq:a1expansion} we know that the leading order term of $\widetilde{\mathcal{A}}_0^{-1}\mathcal{A}_1[\Psi_i]$ is $\mathcal{O}(\omega^2) + \mathcal{O}(\widetilde{\mu}^{-1})$, therefore the contribution of this term in $\phi$ is minor compared to $\tau_i\bm{\psi}^{(i)}$ from $\Phi_0$. Nevertheless, the contribution to $\bm{\psi}$ should not be neglected, since the blowing $\bm{\tau}$ will cancel the decaying $\widetilde{\mu}^{-1}$. We have
  \begin{align*}
    (\widetilde{\mathcal{A}}_0^{-1}\mathcal{A}_1[\Psi_i])_2 = \frac{1}{\widetilde{\mu}}\sum\limits_{i=1}^3\sum\limits_{j=1}^3\tau_is_{ij}(-\mathcal{S}_+^{\alpha,0})^{-1}[\bm{f}^{(j)}] + \mathcal{O}(\omega^2\mu)= -\frac{\mu}{\widetilde{\mu}}\sum\limits_{i=1}^3\tau_i\bm{\psi}^{(i)} + \mathcal{O}(\omega^2\mu).
  \end{align*}

  \item \emph{$\widetilde{\mathcal{A}}_0^{-1}\mathcal{A}_1\widetilde{\mathcal{A}}_0^{-1}[F]$ term.}

  From \eqref{eq:a1expansion} we know that the leading order term of $\widetilde{\mathcal{A}}_0^{-1}\mathcal{A}_1\widetilde{\mathcal{A}}_0^{-1}[F]$ is even higher order terms compared to $\tau_i\widetilde{\mathcal{A}}_0^{-1}\mathcal{A}_1[\Psi_i]$. Hence we neglect the contribution of this term in both $\bm{\phi}$ and $\bm{\psi}$.
\end{itemize}
\subsubsection{Near-field and far-field estimation}

By summarizing all the results we have got in the previous section, we can conclude that
\begin{align*}
    \begin{pmatrix}\bm{\phi} \\ \bm{\psi}\end{pmatrix} &= \Phi = \Phi_\perp + \sum\limits_{i=1}^3\tau_i\Psi_i \\
    &=\begin{pmatrix}(-\frac{1}{2}\bm{I}+(\widetilde{\mathcal{K}}_+^{\alpha,0})^*)^{-1}[\mathscr{F}_{\perp,1}]+\sum\limits_{i=1}^3\tau_i\bm{\psi}^{(i)}+ \mathcal{O}(\omega^2) + \mathcal{O}(\omega\mu) + \mathcal{O}(\frac{1}{\widetilde{\mu}^2}) \\ -2\ii\omega\sqrt{\frac{\rho}{\lambda+2\mu}}\theta_2(\mathcal{S}_+^{\alpha,0})^{-1}[x_2\bm{\theta}]-\frac{\mu}{\widetilde{\mu}}\sum\limits_{i=1}^3\tau_i\bm{\psi}^{(i)} + \mathcal{O}(\omega^2\mu)+\mathcal{O}(\omega\mu^2) \end{pmatrix} ,
\end{align*}
where $\alpha_i$ are defined in \eqref{eq:alphaexpression}.

To conclude, from \eqref{eq:int_repre} we observe that, under the assumption that $\widetilde{\mu}\rightarrow +\infty$, $\mu\rightarrow 0$, the sub-wavelength resonance frequency $\omega\rightarrow 0$, and the field inside scatterer is determined by
\begin{equation}\label{eq:innerfield}
\begin{aligned}
     \widetilde{\mathcal{S}}_+^{\alpha,\omega}[\bm{\phi}] = -2\ii\omega\sqrt{\frac{\rho}{\lambda+2\mu}}\theta_2u_{int} + \sum\limits_{i=1}^3\tau_i\widetilde{\mathcal{S}}_+^{\alpha,\omega}[\bm{\psi}^{(i)}] + \mathcal{O}(\frac{\omega\mu}{\widetilde{\mu}}) + \mathcal{O}(\frac{\omega^2}{\widetilde{\mu}}) + \mathcal{O}(\frac{1}{\widetilde{\mu}^3}).
\end{aligned}
\end{equation}
where $\bm{u}_{int} := \widetilde{\mathcal{S}}_+^{\alpha,0}(-\bm{I}/2+(\widetilde{\mathcal{K}}_+^{\alpha,0})^*)^{-1}[\mathscr{F}_{\perp,1}]$ satisfying the following equation system
\begin{equation*}
\left\{
\begin{aligned}
    &\mathcal{L}^{\widetilde{\lambda}, \widetilde{\mu}}\bm{u}_{int} = 0 \quad \mathrm{in}~D \\
    &\frac{\partial \bm{u}_{int}}{\partial\widetilde{\bm{\nu}}}|_- = \mathscr{F}_{\perp, 1} \quad \mathrm{on}~\partial D.
\end{aligned}
\right.
\end{equation*}

We observe that the field inside scatterer blows up due to the blow up of $\tau_i$ when $\omega$ goes to resonance frequency in Theorem \ref{thm:resonantfrequency}.

From expansion of $\bm{G}_+^{\alpha,\omega}$ and definition of $\mathcal{S}_+^{\alpha,\omega}$, we have $\|\mathcal{S}_+^{\alpha,\omega} - \mathcal{S}_+^{\alpha,0}\| = \mathcal{O}(\omega)$, where the norm is taken in space of bounded operators from $(L^2(\partial D))^2$ to $(L^2(\partial D))^2$. The scattered field outside scatterer is determined by
\begin{equation}\label{eq:outerfield}
\begin{aligned}
    \mathcal{S}_+^{\alpha,\omega}[\bm{\psi}] = -2\ii\omega\sqrt{\frac{\rho}{\lambda+2\mu}}\theta_2x_2\bm{\theta} -\frac{\mu}{\widetilde{\mu}}\sum\limits_{i=1}^3\tau_i\mathcal{S}_+^{\alpha,0}[\bm{\psi}^{(i)}]+ \mathcal{O}(\omega\mu\widetilde{\mu}^{-1})+ \mathcal{O}(\omega^2\mu)+\mathcal{O}(\omega\mu^2).
\end{aligned}
\end{equation}

Now we calculate the far-field approximation of $\mathcal{S}_+^{\alpha,\omega}[\bm{\psi}]$. In the limiting case when $\omega\rightarrow 0$, $l_p=l_s=1$. $l_p$ and $l_s$ can never be $0$ since $\alpha<\mathrm{min}(k_p,k_s)$. As a result, $l=0$ is the only one propagating mode when $\omega\rightarrow 0$. In the far-field scenario, $x_2\rightarrow +\infty$, so $x_2-y_2>0$ and $x_2+y_2>0$. The corresponding leading order term of propagating Green's function is
$$
    \bm{G}^\alpha_{+,1,0}(\bm{x},\bm{y}) = -\frac{y_2}{2\pi\rho}\begin{pmatrix}
    \rho & \delta(\alpha_p-\alpha_s) \\
    \delta(\alpha_p-\alpha_s) & \rho\frac{\mu}{\lambda+2\mu}
    \end{pmatrix}e^{\ii \alpha x_1}.
$$
When $x_2\rightarrow +\infty$, the evanescent part in $\mathcal{S}_+^{\alpha,0}[\bm{\psi}^{(i)}]\rightarrow 0$, so at far-field
\begin{equation*}
\begin{aligned}
    \mathcal{S}_+^{\alpha,\omega}[\bm{\psi}]&\approx \bm{u}_{sc,\infty}^{\alpha,\omega}:= -2\ii\omega\sqrt{\frac{\rho}{\lambda+2\mu}}\theta_2x_2\bm{\theta} \\&+ \frac{1}{\widetilde{\mu}}\sum\limits_{i=1}^3\tau_i\int_{\partial D}\frac{y_2}{2\pi\rho}\begin{pmatrix}
    \rho & \delta(\alpha_p-\alpha_s) \\
    \delta(\alpha_p-\alpha_s) & \rho\frac{\mu}{\lambda+2\mu}
    \end{pmatrix}e^{\ii \alpha x_1}\bm{\psi}^{(i)}(y)\mathrm{d}\sigma(y)+ \mathcal{O}(\omega^2\mu)+\mathcal{O}(\omega\mu^2).
\end{aligned}
\end{equation*}
As discussed in Remark \ref{rmk:order}, when $\mu = \mathcal{O}(\widetilde{\mu}^{-1})$, we have $\bm{\tau} = \mathcal{O}(\widetilde{\mu})$, and the scattered wave varies greatly when $\omega$ goes to resonant frequency. The main results of this subsection is summarized in the following theorem.
\begin{theorem}
    Under the assumption that $\widetilde{\mu}\rightarrow +\infty$ and $\mu\rightarrow 0$, as the frequency $\omega$ of incident wave approaches sub-wavelength resonance frequency, the field inside each scatterer of elastic metascreen blows up in the order of $\mathcal{O}(\mu^{-1})$. When $\mu = \mathcal{O}(\widetilde{\mu}^{-1})$, the blow-up rate is of order $\mathcal{O}(\widetilde{\mu})$. Furthermore, when subwavelength resonance occurs, the far-field approximation of scattering wave differs greatly when $\mu=\mathcal{O}(\widetilde{\mu}^{-1})$ compared to the non-resonating case.
\end{theorem}

